window.WORDS={"adults":[["herald","HER-uhld","verb","To announce, or to be a sign of something coming.","Crocuses herald the end of winter.",""],["melancholy","MEL-uhn-kol-ee","noun","A quiet, gentle sadness.","Rainy Sundays fill him with a sweet melancholy.","From Greek melas, “black,” and khole, “bile.”"],["vagabond","VAG-uh-bond","noun","A person who wanders from place to place.","He spent a summer as a happy vagabond, hiking from town to town.","From Latin vagari, “to wander.”"],["odious","OH-dee-uhs","adjective","Very unpleasant.","Cleaning the oven is an odious chore.","From Latin odium, “hatred.”"],["nestle","NES-uhl","verb","To settle in snugly and comfortably.","The kitten nestled into the blanket.",""],["audacious","aw-DAY-shuhs","adjective","Bold and daring, sometimes surprisingly so.","The squirrel made an audacious leap onto the bird feeder.","From Latin audax, “bold.”"],["dour","DOOR","adjective","Stern and gloomy.","The dour guard finally cracked a smile.",""],["disparate","DIS-per-it","adjective","Very different from each other.","The club brings together disparate people who love books.",""],["abeyance","uh-BAY-uhns","noun","A state of being paused or put on hold for a while.","The plan to paint the kitchen is in abeyance until spring.",""],["humdrum","HUM-drum","adjective","Dull and boring.","A surprise picnic livened up our humdrum Tuesday.",""],["gourmand","goor-MAHND","noun","A person who loves good food, and lots of it.","My little brother, a true gourmand, asked for thirds.","From French gourmand."],["extemporize","ik-STEM-puh-ryz","verb","To speak or perform without planning.","When the lights went out, the actor had to extemporize.","From Latin ex tempore, “out of the time.”"],["lenient","LEE-nee-uhnt","adjective","Gentle and not strict.","The lenient librarian forgave our late fees.","From Latin lenis, “soft, mild.”"],["wayward","WAY-werd","adjective","Going off in an unexpected or unruly way.","A wayward balloon drifted over the rooftops.",""],["bulwark","BUL-werk","noun","A strong wall or a strong source of protection.","Good friends are a bulwark against hard times.",""],["cahoots","kuh-HOOTS","noun","Secret teamwork, usually for mischief.","The cousins were in cahoots to surprise Grandma.",""],["onomatopoeia","on-uh-mat-uh-PEE-uh","noun","A word that sounds like the thing it names, like buzz or pop.","“Sizzle” is a tasty bit of onomatopoeia.","From Greek onoma, “name,” and poiein, “to make.”"],["muse","MYOOZ","noun","Someone or something that inspires you to create.","The ocean is the muse for many of his songs.",""],["acclimate","AK-luh-mayt","verb","To get used to a new place or situation.","It took the family a week to acclimate to the mountain air.",""],["orator","OR-uh-ter","noun","A skilled public speaker.","The young orator held the crowd's attention.","From Latin orare, “to speak.”"],["cacophony","kuh-KOF-uh-nee","noun","A loud mix of harsh, clashing sounds.","The kitchen was a cacophony of pots, pans and laughter.","From Greek kakophonia, “bad sound.”"],["prowess","PROU-is","noun","Great skill at something.","Her prowess at chess surprised everyone.",""],["woolgathering","WOOL-gath-er-ing","noun","Idle daydreaming.","Stop woolgathering and help me set the table.",""],["pique","PEEK","verb","To stir up interest or curiosity.","The mystery box piqued the children's curiosity.","From French piquer, “to prick.”"],["valiant","VAL-yuhnt","adjective","Brave and bold.","The valiant firefighter saved the kitten from the tree.",""],["fastidious","fa-STID-ee-uhs","adjective","Very careful about small details and cleanliness.","My fastidious uncle folds his socks in neat squares.","From Latin fastidium, “loathing.”"],["tinker","TING-ker","verb","To try fixing or improving something in small ways.","Dad loves to tinker with the old radio in the garage.",""],["wily","WY-lee","adjective","Clever and sneaky.","The wily raccoon opened the trash can lid.",""],["capricious","kuh-PRISH-uhs","adjective","Likely to change suddenly for no clear reason.","Spring weather here is capricious, so bring a jacket.",""],["perseverance","pur-suh-VEER-uhns","noun","Sticking with something even when it is hard.","With perseverance, she finished the thousand-piece puzzle.",""],["upheaval","uhp-HEE-vuhl","noun","A big, sudden change or disturbance.","Moving to a new city was an upheaval, but a happy one.",""],["idiosyncrasy","id-ee-uh-SING-kruh-see","noun","An odd habit special to one person.","One of my dad's idiosyncrasies is eating cereal at night.","From Greek idiosynkrasia, “one's own mixture.”"],["wheedle","WEED-l","verb","To coax someone with sweet talk.","The kids wheedled an extra story out of Grandma.",""],["drab","DRAB","adjective","Dull and lacking color.","A few bright pillows cheered up the drab room.",""],["hamlet","HAM-lit","noun","A very small village.","We stopped for pie in a tiny hamlet.",""],["whimsical","WIM-zi-kuhl","adjective","Playful and fanciful in an unusual way.","The garden had whimsical gnome statues and fairy doors.",""],["epitome","ih-PIT-uh-mee","noun","A perfect example of something.","Her warm kitchen is the epitome of comfort.","From Greek epitome, “a cutting short.”"],["pellucid","puh-LOO-sid","adjective","Very clear, like clean water or simple writing.","The lake was pellucid, and we could see the fish.","From Latin pellucidus, “transparent.”"],["demarcate","dih-MAR-kayt","verb","To mark the limits of something.","Stones demarcate the edge of the garden.",""],["mosey","MOH-zee","verb","To walk in a slow, easy way.","Let's mosey down to the pond after lunch.",""],["preen","PREEN","verb","To clean feathers, or to fuss over how you look.","The swan preened on the riverbank.",""],["candelabra","kan-dl-AH-bruh","noun","A fancy holder for several candles.","A silver candelabra lit the dinner table.","From Latin candela, “candle.”"],["glean","GLEEN","verb","To gather bits of information slowly.","I gleaned a few tips from watching the chef.",""],["shambolic","sham-BOL-ik","adjective","Messy and badly organized.","Our first try at a family band was shambolic but fun.",""],["whiff","WIF","noun","A quick, light smell.","I caught a whiff of lilacs on the breeze.",""],["bedraggled","bih-DRAG-uhld","adjective","Wet, dirty and messy.","The bedraggled puppy came in from the rain.",""],["vicissitude","vi-SIS-i-tood","noun","A change in luck or life, often unwelcome.","Their friendship lasted through all of life’s vicissitudes.","From Latin vicissitudo, “change.”"],["palimpsest","PAL-imp-sest","noun","Something with old layers still showing under new ones.","The old wall was a palimpsest of faded posters.","From Greek palin, “again,” and psestos, “scraped.”"],["laconic","luh-KON-ik","adjective","Using very few words.","Our laconic neighbor just said, “Nice day.”","From Greek Lakonikos, “Spartan.”"],["impresario","im-pruh-SAR-ee-oh","noun","A person who organizes shows or concerts.","My niece is the impresario of our backyard talent show.","From Italian impresario, “one who undertakes.”"],["mannerism","MAN-uh-riz-uhm","noun","A small habit in how someone moves or talks.","Tapping her pen is one of my sister's mannerisms.",""],["vista","VIS-tuh","noun","A wide, beautiful view.","The vista from the hilltop took our breath away.","From Italian vista, “view.”"],["placate","PLAY-kayt","verb","To calm someone and make them less upset.","A hug placated the crying child.","From Latin placare, “to calm.”"],["jiffy","JIF-ee","noun","A very short time.","I'll be back in a jiffy.",""],["honorific","on-uh-RIF-ik","noun","A title or word that shows respect.","“Sir” and “Madam” are honorifics.",""],["bayou","BY-oo","noun","A slow-moving, marshy stream or creek.","Frogs croaked along the bayou at dusk.","From Choctaw bayuk, “a small stream.”"],["silhouette","sil-oo-ET","noun","A dark outline seen against a light background.","We saw the silhouette of a deer against the sunset.",""],["cumulative","KYOO-myuh-luh-tiv","adjective","Growing by adding up over time.","Small daily walks have a cumulative effect on health.","From Latin cumulus, “heap.”"],["nigh","NY","adverb","Near, or almost.","The holidays are nigh, so we are baking.",""],["abacus","AB-uh-kuhs","noun","A frame with beads on rods, used for counting.","My grandmother still adds up the grocery bill on her old wooden abacus.","From Greek abax, “a counting board.”"],["forte","FORT","noun","Something a person is very good at.","Baking is not my forte, but I love trying.","From French fort, “strong.”"],["akimbo","uh-KIM-boh","adverb","With hands on hips and elbows pointing out.","Mom stood arms akimbo, waiting for an answer.",""],["perennial","puh-REN-ee-uhl","adjective","Lasting for a very long time, or coming back each year.","Pumpkin pie is a perennial favorite in our house.","From Latin perennis, “lasting through the years.”"],["adulation","aj-uh-LAY-shuhn","noun","Very great praise or admiration, often more than is deserved.","The young singer enjoyed the adulation of the crowd.",""],["pedestrian","puh-DES-tree-uhn","adjective","Dull and ordinary.","The plot was pedestrian, but the songs were great.","From Latin pedester, “on foot.”"],["cleave","KLEEV","verb","To split apart, or to cling closely to.","The ship cleaved through the waves.",""],["vintage","VIN-tij","adjective","Old but of high quality.","She found a vintage dress at the thrift store.",""],["defray","dih-FRAY","verb","To help pay for costs.","The bake sale helped defray the cost of the trip.",""],["natter","NAT-er","verb","To chat in a light, easy way for a long time.","The two friends nattered over tea all afternoon.",""],["kinetic","ki-NET-ik","adjective","Having to do with motion.","The kids had so much kinetic energy after lunch.","From Greek kinein, “to move.”"],["deliberate","dih-LIB-er-it","adjective","Done on purpose and with care.","She took slow, deliberate steps across the ice.","From Latin librare, “to weigh.”"],["trepidation","trep-i-DAY-shuhn","noun","A nervous feeling about what might happen.","I opened the envelope with some trepidation.","From Latin trepidare, “to tremble.”"],["blanch","BLANCH","verb","To turn pale; also to dip food quickly in boiling water.","She blanched the green beans before freezing them.","From French blanc, “white.”"],["strident","STRY-duhnt","adjective","Loud, harsh and hard to ignore.","The strident car alarm woke the whole street.","From Latin stridere, “to creak.”"],["gobsmacked","GOB-smakt","adjective","Totally amazed.","I was gobsmacked when my kids cleaned the whole house.",""],["robust","roh-BUST","adjective","Strong, healthy and hard to break.","The robust old tree has stood for two hundred years.","From Latin robustus, “strong as oak.”"],["orb","ORB","noun","A round ball or sphere.","The moon hung like a silver orb.","From Latin orbis, “circle.”"],["apex","AY-peks","noun","The very top or highest point.","We cheered when we reached the apex of the hill.","From Latin apex, “a peak.”"],["dormant","DOR-muhnt","adjective","Asleep or inactive for a time.","The tulip bulbs lie dormant all winter.","From French dormir, “to sleep.”"],["philanthropy","fih-LAN-thruh-pee","noun","Giving money or time to help others.","Her philanthropy built a new playground.","From Greek philos, “loving,” and anthropos, “human.”"],["torpor","TOR-per","noun","A state of being sluggish and inactive.","After the big lunch, a lazy torpor settled over us.","From Latin torpere, “to be numb.”"],["bevy","BEV-ee","noun","A large group of people or things.","A bevy of ducks waddled across the path.",""],["irascible","ih-RAS-uh-buhl","adjective","Easily made angry.","The irascible goose chased us across the farm.","From Latin ira, “anger.”"],["conflate","kuhn-FLAYT","verb","To mix two different ideas up as if they were one.","Don’t conflate being quiet with being shy.",""],["aghast","uh-GAST","adjective","Shocked and upset.","She was aghast to find the dog had eaten the cake.",""],["resolute","REZ-uh-loot","adjective","Firm and set on doing something.","She was resolute about finishing the race.",""],["innate","ih-NAYT","adjective","Something you are born with.","Our cat has an innate love of boxes.","From Latin innatus, “inborn.”"],["delve","DELV","verb","To dig deep into a subject.","We delved into old photo albums all afternoon.",""],["annotate","AN-oh-tayt","verb","To add notes to a book or text to explain it.","She annotated her cookbook with tips in the margins.","From Latin nota, “a mark.”"],["utopia","yoo-TOH-pee-uh","noun","An imagined perfect place.","To my son, a utopia is a world made of candy.","Coined in 1516 from Greek ou, “not,” and topos, “place.”"],["relish","REL-ish","verb","To enjoy something very much.","I relish quiet Sunday mornings with a good book.",""],["caustic","KAW-stik","adjective","Sharp and biting, like harsh words.","His caustic joke hurt more than he meant it to.","From Greek kaustikos, “burning.”"],["befitting","bih-FIT-ing","adjective","Right and suitable for a person or moment.","They gave the retiring teacher a party befitting her long service.",""],["umbrage","UHM-brij","noun","A feeling of being hurt or offended.","The cat took umbrage when we moved her bed.","From Latin umbra, “shadow.”"],["punctilious","punk-TIL-ee-uhs","adjective","Very careful about rules and good manners.","The punctilious host wrote thank-you notes to every guest.",""],["dub","DUHB","verb","To give someone a nickname.","We dubbed our new kitten “Captain.”",""],["latent","LAY-tuhnt","adjective","Hidden but able to grow later.","Her latent talent for drawing showed up at age forty.","From Latin latere, “to lie hidden.”"],["decadent","DEK-uh-duhnt","adjective","Richly indulgent, often in a fun way.","We shared a decadent chocolate cake.",""],["nomenclature","NOH-muhn-klay-cher","noun","A system of names used in a subject.","Bird watchers learn a whole nomenclature of species.","From Latin nomen, “name.”"],["quotidian","kwoh-TID-ee-uhn","adjective","Ordinary and part of every day.","She found joy in quotidian things like folding warm laundry.","From Latin quotidie, “every day.”"],["apogee","AP-uh-jee","noun","The highest or best point of something.","Her career reached its apogee when she opened her own bakery.","From Greek apogaion, “away from the earth.”"],["taciturn","TAS-i-turn","adjective","Quiet and not inclined to talk much.","The taciturn fisherman just nodded and smiled.","From Latin tacitus, “silent.”"],["skedaddle","ski-DAD-l","verb","To run away fast.","The squirrels skedaddled when the dog came outside.",""],["ordeal","or-DEEL","noun","A hard and painful experience.","Getting the cat into the carrier was an ordeal.",""],["arboreal","ar-BOR-ee-uhl","adjective","Living in trees, or having to do with trees.","Koalas are arboreal animals.","From Latin arbor, “tree.”"],["assuage","uh-SWAYJ","verb","To ease or soothe a feeling or need.","A cup of cocoa assuaged our chill after sledding.",""],["adorn","uh-DORN","verb","To decorate something to make it prettier.","We adorned the table with flowers from the yard.","From Latin adornare, “to furnish.”"],["glade","GLAYD","noun","An open, grassy space in a forest.","We had a picnic in a sunny glade.",""],["homage","OM-ij","noun","Something done to show respect or honor.","The mural pays homage to the town's first farmers.","From French hommage."],["convoluted","KON-vuh-loo-tid","adjective","Twisted and hard to follow.","The movie’s plot was so convoluted we got lost.","From Latin convolvere, “to roll together.”"],["saunter","SAWN-ter","verb","To walk in a slow, relaxed way.","We sauntered along the boardwalk eating ice cream.",""],["apparition","ap-uh-RISH-uhn","noun","A ghostly figure, or something that appears suddenly.","In the fog, the lighthouse looked like an apparition.","From Latin apparere, “to appear.”"],["posit","POZ-it","verb","To put forward an idea as true.","The scientist posited that the birds follow the river.",""],["capacious","kuh-PAY-shuhs","adjective","Roomy and able to hold a lot.","Her capacious bag held snacks for the whole family.","From Latin capax, “able to hold much.”"],["fallow","FAL-oh","adjective","Left unplanted for a while to rest.","The farmer let the field lie fallow for a year.",""],["mishmash","MISH-mash","noun","A messy mix of things.","Dinner was a mishmash of leftovers, and it was great.",""],["xenial","ZEE-nee-uhl","adjective","Friendly and welcoming to guests.","Our xenial hosts set out snacks the moment we arrived.","From Greek xenos, “guest, stranger.”"],["remorse","ri-MORS","noun","A deep feeling of being sorry for something you did.","He felt remorse for snapping at his little brother.","From Latin remordere, “to bite again.”"],["journeyman","JUR-nee-muhn","noun","A skilled worker who has fully learned a trade.","A journeyman carpenter built our sturdy table.",""],["enchant","en-CHANT","verb","To fill with delight, as if by magic.","The puppet show enchanted the little ones.","From Latin incantare, “to chant a spell over.”"],["apprentice","uh-PREN-tis","noun","A person learning a trade by working with a skilled worker.","He spent a year as an apprentice to a carpenter.",""],["billow","BIL-oh","verb","To swell and move in large waves.","The sails billowed in the strong breeze.",""],["devotee","dev-uh-TEE","noun","A big fan of something.","He is a devotee of morning walks.",""],["bagatelle","bag-uh-TEL","noun","Something small and unimportant; a trifle.","To her, the extra chore was a mere bagatelle.","From Italian bagatella, “a trifle.”"],["owlish","OW-lish","adjective","Looking wise or serious, like an owl, often with glasses.","The owlish librarian peered over her spectacles.",""],["doldrums","DOHL-druhmz","noun","A state of dullness or low spirits.","A new puzzle pulled us out of the winter doldrums.",""],["neophyte","NEE-uh-fyt","noun","A beginner at something.","As a neophyte baker, I burned the first batch.","From Greek neophytos, “newly planted.”"],["candor","KAN-der","noun","The quality of being open and honest.","We thanked her for her candor about the plan.","From Latin candor, “whiteness, brightness.”"],["xeriscape","ZEER-uh-skayp","noun","A garden designed to need very little water.","Our desert neighbors made a lovely xeriscape of cactus and stones.","From Greek xēros, “dry.”"],["estuary","ES-choo-er-ee","noun","The wide mouth of a river where it meets the sea.","We watched herons wade in the estuary.","From Latin aestuarium, “tidal place.”"],["pathos","PAY-thos","noun","A quality that makes people feel pity or sadness.","The movie's ending had real pathos.","From Greek pathos, “suffering.”"],["amicable","AM-i-kuh-buhl","adjective","Friendly and peaceful, without arguing.","The brothers reached an amicable deal about the last slice.","From Latin amicus, “friend.”"],["offhand","OF-hand","adjective","Said casually, without much thought.","Her offhand comment gave me a great idea.",""],["adept","uh-DEPT","adjective","Very skilled at something.","My sister is adept at fixing bicycle chains.","From Latin adeptus, “having attained.”"],["unkempt","uhn-KEMPT","adjective","Messy and not cared for.","After camping, our hair was wild and unkempt.","From Old English cemban, “to comb.”"],["affable","AF-uh-buhl","adjective","Friendly and easy to talk to.","Our affable mail carrier always stops to chat.","From Latin affabilis, “easy to speak to.”"],["belittle","bih-LIT-l","verb","To make someone or something seem unimportant.","Never belittle a small act of kindness.",""],["acrimony","AK-ruh-moh-nee","noun","Bitter and angry feelings between people.","The two friends settled their quarrel without any acrimony.",""],["aroma","uh-ROH-muh","noun","A pleasant smell.","The aroma of fresh bread filled the house.","From Greek aroma, “a spice.”"],["brook","BRUK","noun","A small stream.","We skipped stones across the brook.",""],["daydream","DAY-dreem","verb","To let your mind drift to happy thoughts.","She daydreams about the beach during math class.",""],["keen","KEEN","adjective","Eager, or sharp.","She has a keen eye for birds.",""],["denizen","DEN-uh-zuhn","noun","A creature or person who lives in a certain place.","Frogs are the noisy denizens of our pond.",""],["bramble","BRAM-buhl","noun","A prickly bush, like a blackberry bush.","We picked berries carefully from the brambles.",""],["microcosm","MY-kruh-koz-uhm","noun","A small thing that shows what a bigger thing is like.","The school fair is a microcosm of our whole town.","From Greek mikros, “small,” and kosmos, “world.”"],["vespertine","VES-per-tin","adjective","Having to do with the evening.","The vespertine song of crickets filled the yard.","From Latin vesper, “evening.”"],["percolate","PUR-kuh-layt","verb","To slowly spread or filter through.","The idea percolated in her mind for days.","From Latin percolare, “to strain through.”"],["paucity","PAW-sih-tee","noun","A shortage of something.","There was a paucity of chairs, so we sat on the floor.","From Latin paucus, “few.”"],["thwart","THWORT","verb","To stop someone from doing what they planned.","The fence thwarted the rabbits’ plan to eat our lettuce.",""],["scintilla","sin-TIL-uh","noun","A tiny trace or spark of something.","There wasn’t a scintilla of doubt that he would help.","From Latin scintilla, “a spark.”"],["heft","HEFT","noun","Weight or heaviness.","I felt the heft of the big watermelon.",""],["brio","BREE-oh","noun","Lively energy and spirit.","The band played with great brio.","From Italian brio, “liveliness.”"],["divest","dy-VEST","verb","To get rid of something.","They divested themselves of clutter before the move.",""],["allot","uh-LOT","verb","To give out a share of something.","Each child was allotted one hour of screen time.",""],["octave","OK-tiv","noun","The gap between one musical note and the next note of the same name.","She can sing two octaves higher than me.","From Latin octavus, “eighth.”"],["belie","bih-LY","verb","To give a false picture of something; to hide what is true.","His calm face belied how nervous he felt.",""],["colossal","kuh-LOS-uhl","adjective","Very, very large.","We built a colossal sandcastle at the beach.","From Greek kolossos, “giant statue.”"],["maverick","MAV-er-ik","noun","A person who thinks and acts on their own, not like the crowd.","The maverick chef put berries on the pizza, and it worked.",""],["baleful","BAYL-fuhl","adjective","Looking threatening or unfriendly.","The cat gave the dog a baleful stare.",""],["acerbic","uh-SUR-bik","adjective","Sharp and biting in a way that can sting.","His acerbic jokes are funny, but sometimes they hurt feelings.","From Latin acerbus, “sour.”"],["ponder","PON-der","verb","To think about something carefully.","I pondered which book to read next.","From Latin ponderare, “to weigh.”"],["benign","bih-NYN","adjective","Gentle, kind and harmless.","The big dog has a benign nature and loves kids.","From Latin benignus, “kindly.”"],["scrupulous","SKROO-pyuh-luhs","adjective","Very careful to do things right and honestly.","She was scrupulous about returning every borrowed book.",""],["willowy","WIL-oh-ee","adjective","Tall, slim and graceful.","The willowy dancer seemed to float across the stage.",""],["fortuitous","for-TOO-i-tuhs","adjective","Happening by lucky chance.","Meeting my old friend at the bus stop was fortuitous.","From Latin fortuitus, “by chance.”"],["bevel","BEV-uhl","noun","A slanted edge on wood, glass or stone.","The mirror had a pretty beveled edge.",""],["unbeknownst","uhn-bi-NOHNST","adjective","Without someone knowing.","Unbeknownst to Dad, we had planned a surprise party.",""],["azure","AZH-er","adjective","Bright blue, like a clear sky.","We swam in the azure water of the bay.","From Persian lazhward, “lapis lazuli.”"],["elegy","EL-uh-jee","noun","A sad poem or song about someone or something lost.","She wrote a gentle elegy for her old dog.","From Greek elegeia, “a song of mourning.”"],["serenade","ser-uh-NAYD","verb","To sing or play music for someone you care about.","The kids serenaded Mom with a song on her birthday.",""],["sobriquet","SOH-bri-kay","noun","A nickname.","Her sobriquet in the family was “Sunny.”","From French sobriquet, “a nickname.”"],["biophilia","by-oh-FIL-ee-uh","noun","A natural love of living things and nature.","Her biophilia shows in the dozens of plants on her windowsill.","From Greek bios, “life,” and philia, “love.”"],["agape","uh-GAYP","adjective","Wide open, often in surprise.","The children stood with mouths agape at the fireworks.",""],["contrarian","kuhn-TRAIR-ee-uhn","noun","A person who likes to take the opposite view.","Our resident contrarian always argues that winter is best.",""],["bastion","BAS-chuhn","noun","A place or group that strongly protects an idea or way of life.","The corner bookshop is a bastion of quiet in a busy town.",""],["polyglot","POL-ee-glot","noun","A person who speaks many languages.","Our tour guide was a polyglot who spoke six languages.","From Greek polys, “many,” and glotta, “tongue.”"],["malleable","MAL-ee-uh-buhl","adjective","Easy to shape or change.","Young minds are malleable, so we read them good books.","From Latin malleus, “hammer.”"],["heuristic","hyoo-RIS-tik","noun","A simple rule of thumb that helps you decide.","My heuristic for packing: if in doubt, leave it out.","From Greek heuriskein, “to find.”"],["stymie","STY-mee","verb","To block or get in the way of progress.","A missing puzzle piece stymied our plan to finish tonight.",""],["invigorate","in-VIG-uh-rayt","verb","To fill with energy.","A cold swim invigorated us.","From Latin vigor, “liveliness.”"],["nincompoop","NIN-kuhm-poop","noun","A silly, foolish person (said kindly).","I felt like a nincompoop when I wore two different shoes.",""],["bemoan","bih-MOHN","verb","To complain or express sadness about something.","We bemoaned the end of summer vacation.",""],["bleak","BLEEK","adjective","Cold, bare and gloomy.","The beach looked bleak in the winter fog.",""],["verve","VURV","noun","Lively energy and spirit.","She danced with great verve at the wedding.",""],["chronicle","KRON-i-kuhl","noun","A record of events in the order they happened.","Her diary is a chronicle of our summer trips.","From Greek chronos, “time.”"],["bizarre","bih-ZAR","adjective","Very strange and unusual.","We saw a bizarre cloud shaped like a teapot.","From French bizarre, “odd.”"],["apropos","ap-ruh-POH","adjective","Fitting for the moment; related to what is being said.","Her joke about rain was apropos, since it had just started pouring.","From French à propos, “to the purpose.”"],["bolster","BOHL-ster","verb","To support or make stronger.","The coach's speech bolstered the team's spirits.",""],["proximity","prok-SIM-ih-tee","noun","Being near something.","We love our home's proximity to the park.","From Latin proximus, “nearest.”"],["fettle","FET-l","noun","Condition or shape, as in good health.","After a good night's sleep, Grandpa was in fine fettle.",""],["offbeat","OF-beet","adjective","Unusual in a fun way.","He has an offbeat sense of humor.",""],["mirth","MURTH","noun","Joy and laughter.","The room filled with mirth when the puppy sneezed.",""],["baffle","BAF-uhl","verb","To confuse someone completely.","The riddle baffled everyone at the table.",""],["wrought","RAWT","adjective","Made or shaped with care, often from metal.","The garden had a beautiful wrought iron gate.",""],["culinary","KUHL-uh-ner-ee","adjective","Having to do with cooking.","Her culinary skills turned leftovers into a feast.","From Latin culina, “kitchen.”"],["abscond","ab-SKOND","verb","To leave in a hurry and in secret, often with something not yours.","The puppy absconded with my sock and hid under the bed.","From Latin abscondere, “to hide away.”"],["dross","DRAWS","noun","Something worthless; junk.","We sorted the treasures from the dross at the yard sale.",""],["modulate","MOJ-uh-layt","verb","To adjust or change the level of something.","She modulated her voice to a whisper in the library.","From Latin modulari, “to measure.”"],["behest","bih-HEST","noun","A person's order or request.","At my mother's behest, I wrote thank-you notes.",""],["verbose","ver-BOHS","adjective","Using more words than needed.","His verbose email could have been one line.","From Latin verbum, “word.”"],["aglow","uh-GLOH","adjective","Glowing with light, warmth or happiness.","Her face was aglow when she opened the letter.",""],["halcyon","HAL-see-uhn","adjective","Calm, happy and peaceful, often about the past.","We remember the halcyon summers at the lake.","From Greek halkyon, “kingfisher.”"],["complicit","kuhm-PLIS-it","adjective","Helping with something wrong.","The twins were complicit in hiding the cookie jar.",""],["culminate","KUHL-muh-nayt","verb","To reach the high point or end.","The fair culminated in a fireworks show.","From Latin culmen, “summit.”"],["bibliophile","BIB-lee-uh-fyl","noun","A person who loves books.","A true bibliophile, she has books in every room.","From Greek biblion, “book,” and philos, “loving.”"],["opulent","OP-yuh-luhnt","adjective","Rich, fancy and full of costly things.","The hotel lobby was opulent with gold and velvet.","From Latin opulentus, “wealthy.”"],["banal","buh-NAL","adjective","So ordinary that it is boring.","The movie had a banal plot we guessed right away.","From French banal, “common.”"],["maestro","MY-stroh","noun","A great master of an art, especially music.","Grandpa is a maestro at the grill every summer.","From Italian maestro, “master.”"],["fulcrum","FUL-kruhm","noun","The point a lever rests on, or the key part of something.","The seesaw's fulcrum sits right in the middle.","From Latin fulcire, “to prop up.”"],["waft","WAFT","verb","To float gently through the air.","The smell of fresh bread wafted out of the bakery.",""],["solitude","SOL-i-tood","noun","Being alone in a peaceful way.","He enjoyed the solitude of fishing at dawn.","From Latin solus, “alone.”"],["repose","ri-POHZ","noun","A state of rest and calm.","The lake was in perfect repose at dawn.",""],["coterie","KOH-tuh-ree","noun","A small, close group of people with shared interests.","A coterie of bird lovers meets at the park each dawn.",""],["cajole","kuh-JOHL","verb","To gently coax someone into doing something.","He cajoled his sister into sharing the last cookie.","From French cajoler, “to coax.”"],["cavort","kuh-VORT","verb","To jump and play in a lively way.","The lambs cavorted in the spring meadow.",""],["sojourn","SOH-jern","noun","A short stay somewhere.","Our sojourn at the seaside lasted a happy week.",""],["kilter","KIL-ter","noun","Good balance or working order.","The time change threw my sleep out of kilter.",""],["constituent","kuhn-STICH-oo-uhnt","noun","One of the parts that make up a whole.","Flour is a key constituent of bread.",""],["plume","PLOOM","noun","A big feather, or a tall cloud of smoke or steam.","A plume of steam rose from the teapot.","From Latin pluma, “feather.”"],["plaintive","PLAYN-tiv","adjective","Sounding sad.","We heard the plaintive call of a dove.",""],["meridian","muh-RID-ee-uhn","noun","The highest point, or a line on a map from pole to pole.","At the meridian of her career, she trained dozens of new nurses.","From Latin meridies, “midday.”"],["leeway","LEE-way","noun","Extra room or freedom.","Leave some leeway in case traffic is bad.",""],["nutshell","NUT-shel","noun","A very short summary of something.","In a nutshell, the trip was wonderful.",""],["scamper","SKAM-per","verb","To run with quick, light steps.","The kittens scampered after the ball of yarn.",""],["genial","JEEN-yuhl","adjective","Friendly and cheerful.","Our genial host made everyone feel at home.",""],["uncanny","uhn-KAN-ee","adjective","Strange in a surprising, hard-to-explain way.","She has an uncanny knack for finding four-leaf clovers.",""],["bungle","BUHNG-guhl","verb","To do something clumsily and badly.","I bungled the knot, and the tent fell down.",""],["jitters","JIT-erz","noun","Nervous, shaky feelings.","I had the jitters before my piano recital.",""],["archipelago","ar-kuh-PEL-uh-goh","noun","A group of islands close together.","We sailed through an archipelago of tiny green islands.",""],["jape","JAYP","noun","A playful trick or joke.","The cousins planned a harmless jape for April Fools' Day.",""],["aloof","uh-LOOF","adjective","Distant and not friendly or involved.","The new cat stayed aloof for a week, then curled up on my lap.",""],["complement","KOM-pluh-ment","verb","To go well with something and make it better.","The lemon complements the fish perfectly.","From Latin complere, “to fill up.”"],["meld","MELD","verb","To blend together into one.","The flavors meld nicely if the soup sits overnight.",""],["perambulate","per-AM-byuh-layt","verb","To walk around in a slow, easy way.","We perambulated around the lake after supper.","From Latin per, “through,” and ambulare, “to walk.”"],["conversant","kuhn-VUR-suhnt","adjective","Familiar with and knowing about something.","She is conversant in three languages.",""],["diffident","DIF-i-duhnt","adjective","Shy and lacking confidence.","The diffident new student smiled when we waved her over.",""],["fortnight","FORT-nyt","noun","Two weeks.","Our cousins are visiting for a fortnight.","From Old English feowertiene niht, “fourteen nights.”"],["lethargy","LETH-er-jee","noun","A feeling of being slow and sleepy.","After the big lunch, lethargy set in.","From Greek lethargia, “forgetfulness.”"],["hermit","HUR-mit","noun","A person who lives alone, away from others.","The old hermit lived in a cabin by the lake.",""],["euphemism","YOO-fuh-miz-uhm","noun","A gentle word used in place of a harsh one.","“Pre-loved” is a kind euphemism for “used.”","From Greek euphemismos, “use of good words.”"],["vehement","VEE-uh-muhnt","adjective","Showing very strong feeling.","She made a vehement case for getting a dog.","From Latin vehemens, “eager, violent.”"],["matriarch","MAY-tree-ark","noun","A woman who leads a family or group.","Our grandmother is the matriarch who hosts every holiday.","From Latin mater, “mother,” and Greek archein, “to rule.”"],["warble","WOR-buhl","verb","To sing with trills, like a bird.","A wren warbled outside my window at dawn.",""],["pithy","PITH-ee","adjective","Short but full of meaning.","Her pithy advice was “Be kind, be brief.”",""],["fraught","FRAWT","adjective","Filled with something, usually worry or trouble.","The trip was fraught with small mishaps, but we laughed through them.",""],["tidings","TY-dingz","noun","News or messages.","The letter brought glad tidings of a new baby.","From Old English tīdung, “news.”"],["nautical","NAW-tih-kuhl","adjective","Having to do with ships, sailors or the sea.","The room had a nautical theme with ropes and anchors.","From Greek nautes, “sailor.”"],["analogy","uh-NAL-uh-jee","noun","A comparison that explains one thing by showing how it is like another.","She used an analogy: the heart works like a pump.","From Greek analogia, “proportion.”"],["panorama","pan-uh-RAM-uh","noun","A wide view of a whole area.","From the hilltop we saw a panorama of the valley.","From Greek pan, “all,” and horama, “view.”"],["acumen","AK-yuh-muhn","noun","The skill of making good, quick judgments.","Her business acumen helped the lemonade stand turn a profit.","From Latin acumen, “a point, sharpness.”"],["moniker","MON-ih-ker","noun","A name or nickname.","His moniker at the bakery is “Mister Muffin.”",""],["congruent","KONG-groo-uhnt","adjective","In agreement or matching.","His actions were congruent with his promises.",""],["unctuous","UHNGK-choo-uhs","adjective","Too smooth and flattering to be sincere.","The unctuous salesman praised every hat I tried on.","From Latin unctus, “oiled.”"],["forbearance","for-BAIR-uhns","noun","Patience and self-control.","The teacher showed great forbearance on the first day of school.",""],["drizzle","DRIZ-uhl","noun","Light, fine rain.","We walked through the drizzle without umbrellas.",""],["ardent","AR-duhnt","adjective","Full of strong, warm feeling; very eager.","She is an ardent fan of the local baseball team.","From Latin ardere, “to burn.”"],["workaday","WURK-uh-day","adjective","Ordinary and everyday.","Our workaday dinner turned into a fun picnic.",""],["newfangled","NOO-fang-guhld","adjective","New and a bit strange or fussy.","Grandma laughed at the newfangled toaster with ten buttons.",""],["knead","NEED","verb","To press and fold dough with your hands.","We kneaded the bread dough together.",""],["negligible","NEG-lih-juh-buhl","adjective","So small it hardly matters.","The cost of the extra stamp was negligible.",""],["mendacious","men-DAY-shuhs","adjective","Not telling the truth.","The mendacious note said the dog ate the homework.","From Latin mendax, “lying.”"],["solicitous","suh-LIS-i-tuhs","adjective","Showing caring concern for someone.","The solicitous nurse made sure I had an extra blanket.",""],["adage","AD-ij","noun","An old, well-known saying that holds some truth.","As the adage goes, many hands make light work.",""],["formidable","FOR-mi-duh-buhl","adjective","Impressive and hard to beat.","Our chess club faced a formidable rival.","From Latin formido, “fear.”"],["aperture","AP-er-cher","noun","An opening, hole or gap.","Light came in through a small aperture in the curtain.","From Latin apertura, “an opening.”"],["clamor","KLAM-er","noun","A loud, steady noise from many voices.","The clamor of the crowd rose as the parade began.","From Latin clamare, “to cry out.”"],["chasm","KAZ-uhm","noun","A deep crack in the earth, or a big gap between people.","A rope bridge hung across the chasm.","From Greek chasma, “gaping hollow.”"],["tenable","TEN-uh-buhl","adjective","Able to be defended or believed.","Her idea for a shorter school day seemed tenable.","From Latin tenere, “to hold.”"],["dichotomy","dy-KOT-uh-mee","noun","A split between two opposite things.","There’s a dichotomy between what we want and what we need.","From Greek dichotomia, “a cutting in two.”"],["unassuming","uhn-uh-SOO-ming","adjective","Modest and not showy.","The unassuming little café makes the best soup in town.",""],["mutable","MYOO-tuh-buhl","adjective","Able to change.","Plans are mutable when you travel with small kids.","From Latin mutare, “to change.”"],["bouquet","boo-KAY","noun","A bunch of flowers; also a pleasant smell.","She brought her teacher a bouquet of daisies.","From French bouquet, “a little wood.”"],["embellish","em-BEL-ish","verb","To add details or decoration to make something nicer.","Grandma likes to embellish her stories with funny details.","From Old French embellir, “to make beautiful.”"],["metamorphosis","met-uh-MOR-fuh-sis","noun","A big change in form, like a caterpillar to a butterfly.","The old shed went through a metamorphosis into an art studio.","From Greek meta, “change,” and morphe, “form.”"],["jot","JOT","verb","To write something down quickly.","I jotted the recipe on a napkin.",""],["catapult","KAT-uh-puhlt","verb","To throw or launch something with great force.","The good news catapulted him out of his chair.",""],["heyday","HAY-day","noun","The time of greatest success.","In its heyday, the diner was always full.",""],["marvel","MAR-vuhl","verb","To be filled with wonder at something.","We marveled at the stars far from the city lights.","From Latin mirabilia, “wonderful things.”"],["meticulous","muh-TIK-yuh-luhs","adjective","Very careful about every small detail.","She is meticulous when she wraps gifts.",""],["kestrel","KES-truhl","noun","A small falcon that hovers in the air.","A kestrel hovered over the field, looking for mice.",""],["needle","NEED-l","verb","To tease or annoy someone again and again.","My sister needles me about my messy room.",""],["didactic","dy-DAK-tik","adjective","Meant to teach a lesson.","The fable has a didactic message about patience.","From Greek didaskein, “to teach.”"],["truculent","TRUK-yuh-luhnt","adjective","Eager to argue or fight.","The truculent goose chased us across the yard.","From Latin trux, “fierce.”"],["kindle","KIN-duhl","verb","To start a fire, or to stir up a feeling.","The trip kindled her love of travel.",""],["languid","LANG-gwid","adjective","Slow and relaxed, without energy.","We spent a languid afternoon in the hammock.","From Latin languere, “to be faint.”"],["cursory","KUR-suh-ree","adjective","Quick and not very careful.","He gave the room a cursory glance and missed his keys.",""],["engender","en-JEN-der","verb","To cause or bring about a feeling or situation.","Kind words engender trust.","From Latin ingenerare, “to beget.”"],["mammoth","MAM-uhth","adjective","Huge in size or amount.","Cleaning the garage was a mammoth job.",""],["abhor","ab-HOR","verb","To hate something very much.","My uncle abhors cold coffee, so he drinks it fast.","From Latin abhorrere, “to shrink back from.”"],["jejune","ji-JOON","adjective","Dull, or naive and childish.","His jejune jokes made only the toddlers laugh.","From Latin jejunus, “fasting, dry.”"],["abound","uh-BOUND","verb","To be found in large numbers.","Wildflowers abound in the meadow every June.","From Latin abundare, “to overflow.”"],["winsome","WIN-suhm","adjective","Charming in a sweet, innocent way.","The toddler gave a winsome smile to everyone in line.","From Old English wynsum, “pleasant.”"],["buffoon","buh-FOON","noun","A person who acts silly to make others laugh.","Dad played the buffoon to cheer up the kids.","From Italian buffone, “a jester.”"],["susurrus","soo-SUR-uhs","noun","A soft whispering or rustling sound.","The susurrus of the leaves lulled me to sleep.","From Latin susurrus, “a whisper.”"],["gratuitous","gruh-TOO-i-tuhs","adjective","Not needed or not called for.","The movie had a gratuitous car chase.","From Latin gratuitus, “free, done without pay.”"],["vanguard","VAN-gard","noun","The front part of a group, leading the way.","Our school is in the vanguard of planting rooftop gardens.",""],["adrift","uh-DRIFT","adjective","Floating without being steered, or feeling lost and without aim.","The little toy boat was adrift in the pond.",""],["omniscient","om-NISH-uhnt","adjective","Knowing everything.","The story is told by an omniscient narrator.","From Latin omnis, “all,” and sciens, “knowing.”"],["hearth","HARTH","noun","The floor of a fireplace, or the home itself.","We warmed our hands by the hearth.",""],["din","DIN","noun","A loud, constant noise.","We could barely talk over the din of the fair.",""],["devolve","dih-VOLV","verb","To pass down to someone, or to slowly get worse.","The pillow fight devolved into a fit of giggles.",""],["rotund","roh-TUND","adjective","Round and plump.","The rotund little robin hopped across the lawn.","From Latin rotundus, “round.”"],["blasé","blah-ZAY","adjective","Not excited or impressed because you have seen it before.","The teenager was blasé about the roller coaster.","From French blasé, “tired of pleasure.”"],["neighborly","NAY-ber-lee","adjective","Friendly and helpful, like a good neighbor.","It was neighborly of them to shovel our walk.",""],["facetious","fuh-SEE-shuhs","adjective","Joking at a time when you should be serious.","He was being facetious when he said he would eat the whole cake.","From Latin facetia, “a jest.”"],["diplomacy","dih-PLOH-muh-see","noun","Skill in handling people kindly and wisely.","It took diplomacy to settle who got the window seat.",""],["lattice","LAT-is","noun","A crisscross pattern of strips.","Roses climbed the garden lattice.",""],["jumble","JUM-buhl","noun","A messy mix.","The drawer was a jumble of pens and string.",""],["indelible","in-DEL-uh-buhl","adjective","Impossible to remove or forget.","Our trip to the ocean left an indelible memory.","From Latin indelebilis, “not able to be wiped out.”"],["kvetch","KVECH","verb","To complain a lot.","He kvetched about the cold but stayed for the snowball fight.","From Yiddish kvetshn, “to squeeze.”"],["zinger","ZING-er","noun","A quick, clever, funny line.","Mom ended the debate with a friendly zinger.",""],["tacit","TAS-it","adjective","Understood without being said out loud.","We had a tacit agreement that Dad gets the last cookie.","From Latin tacitus, “silent.”"],["ablaze","uh-BLAYZ","adjective","Burning brightly or glowing with light or color.","The maple trees were ablaze with red and orange leaves.",""],["bustle","BUHS-uhl","noun","Busy, noisy activity.","We loved the bustle of the morning market.",""],["conundrum","kuh-NUHN-druhm","noun","A hard problem or puzzle.","Choosing just one dessert was a real conundrum.",""],["nocturnal","nok-TUR-nl","adjective","Active at night.","Owls are nocturnal birds.","From Latin nox, “night.”"],["fervent","FUR-vuhnt","adjective","Showing strong and warm feeling.","She is a fervent fan of her granddaughter's soccer team.","From Latin fervere, “to boil.”"],["desist","dih-ZIST","verb","To stop doing something.","Please desist from tapping your pencil.",""],["disquisition","dis-kwuh-ZISH-uhn","noun","A long, detailed talk or essay on a topic.","Dad gave a disquisition on the perfect grilled cheese.",""],["judder","JUD-er","verb","To shake hard and fast.","The old washing machine juddered across the floor.",""],["quell","KWEL","verb","To calm something down or put an end to it.","Grandpa’s soft song quelled the baby’s crying.","From Old English cwellan, “to kill.”"],["conjure","KON-jer","verb","To bring something to mind, as if by magic.","The smell of cinnamon conjures memories of winter.",""],["effusive","ih-FYOO-siv","adjective","Showing feelings in a big, gushing way.","He was effusive in his thanks after we fixed his fence.","From Latin effundere, “to pour out.”"],["bent","BENT","noun","A natural talent or liking for something.","She has an artistic bent and loves to paint.",""],["kiosk","KEE-osk","noun","A small stand that sells things or gives information.","We bought maps at the kiosk.","From Turkish köşk, “pavilion.”"],["defunct","dih-FUHNGKT","adjective","No longer existing or working.","The defunct train station is now a café.","From Latin defunctus, “finished.”"],["woebegone","WOH-bi-gon","adjective","Looking very sad.","The puppy gave a woebegone look when we left.",""],["disseminate","dih-SEM-uh-nayt","verb","To spread information widely.","The library disseminates news about free classes.","From Latin semen, “seed.”"],["toothsome","TOOTH-suhm","adjective","Tasty and pleasing to eat.","The bakery sells toothsome cinnamon rolls.",""],["jostle","JOS-uhl","verb","To push and bump in a crowd.","Fans jostled for a better view of the fireworks.",""],["headlong","HED-lawng","adverb","Head first, or in a rush without thinking.","The dog ran headlong into the lake.",""],["flit","FLIT","verb","To move quickly and lightly.","Hummingbirds flit from flower to flower.",""],["dudgeon","DUHJ-uhn","noun","A feeling of being offended, often called “high dudgeon” when strong.","He left in high dudgeon when we ate his fries.",""],["hummock","HUM-uhk","noun","A small, rounded hill or mound.","The rabbit hid behind a grassy hummock.",""],["latitude","LAT-i-tood","noun","Freedom to choose how to act.","Our teacher gives us latitude to pick our own topics.","From Latin latitudo, “breadth.”"],["mnemonic","nih-MON-ik","noun","A trick that helps you remember something.","We used a mnemonic to learn the planets in order.","From Greek mneme, “memory.”"],["blurt","BLURT","verb","To say something suddenly without thinking.","My little brother blurted out the surprise.",""],["raffish","RAF-ish","adjective","Carefree and a bit unconventional in a charming way.","The old sailor had a raffish smile and a striped scarf.",""],["minuscule","MIN-uh-skyool","adjective","Very, very small.","There was a minuscule crumb left on the plate.",""],["supercilious","soo-per-SIL-ee-uhs","adjective","Acting as if you are better than others.","The supercilious cat ignored everyone at the party.","From Latin supercilium, “eyebrow.”"],["befuddle","bih-FUHD-l","verb","To confuse someone.","The new remote control befuddled Grandpa.",""],["comely","KUHM-lee","adjective","Pleasant to look at.","The comely cottage had roses by the gate.",""],["outlier","OUT-ly-er","noun","Something very different from the rest of its group.","The one sunny day was an outlier in a rainy month.",""],["atone","uh-TOHN","verb","To make up for a mistake or wrong.","He atoned for forgetting her birthday by baking her a cake.","From the phrase at one, “in harmony.”"],["bonny","BON-ee","adjective","Pretty, healthy and pleasing to see.","What a bonny baby, the neighbor said.",""],["covert","KOH-vert","adjective","Secret or hidden.","The kids ran a covert mission to bake Dad a cake.",""],["tangential","tan-JEN-shuhl","adjective","Only loosely connected to the main topic.","His tangential story about his cat made us forget the question.","From Latin tangere, “to touch.”"],["banter","BAN-ter","noun","Friendly, playful joking talk.","The cooks kept up a cheerful banter in the kitchen.",""],["smitten","SMIT-n","adjective","Completely charmed by someone or something.","The whole family was smitten with the new puppy.",""],["prudent","PROOD-nt","adjective","Wise and careful about the future.","It's prudent to bring a jacket in the mountains.","From Latin prudens, “foreseeing.”"],["morass","muh-RAS","noun","A messy situation that is hard to get out of.","We got lost in a morass of paperwork.",""],["daub","DAWB","verb","To smear paint or something soft roughly on a surface.","The toddler daubed paint all over the paper.",""],["pragmatic","prag-MAT-ik","adjective","Practical and focused on what works.","A pragmatic packer brings only what she needs.","From Greek pragma, “a deed.”"],["discord","DIS-kord","noun","Disagreement or lack of harmony.","A little discord over the TV ended with a coin toss.","From Latin discors, “not of one heart.”"],["noggin","NOG-in","noun","A playful word for your head.","Use your noggin and wear a hat in the cold.",""],["vernacular","ver-NAK-yuh-ler","noun","The everyday language people speak in a place.","The guide spoke in the local vernacular.","From Latin vernaculus, “native.”"],["demystify","dee-MIS-tuh-fy","verb","To make something easier to understand.","Her class demystified baking bread.",""],["passé","pa-SAY","adjective","Out of date and no longer in fashion.","My teen says my jeans are passé.","From French passé, “past.”"],["quaint","KWAYNT","adjective","Charming in an old-fashioned way.","We stayed in a quaint little cottage with a bright blue door.","From Old French cointe, “clever, pretty.”"],["citadel","SIT-uh-dl","noun","A fortress on high ground protecting a city.","From the old citadel, we could see the whole town.",""],["ragamuffin","RAG-uh-muf-in","noun","A messy, scruffy child in old clothes.","The kids came home from the creek looking like ragamuffins.",""],["debilitate","dih-BIL-i-tayt","verb","To make someone or something weak.","The long heat wave debilitated the garden.","From Latin debilis, “weak.”"],["zest","ZEST","noun","Great enjoyment and energy, or the grated peel of a lemon or orange.","Grandpa still has a real zest for life.","From French zeste, “citrus peel.”"],["digress","dy-GRES","verb","To wander off the main topic.","Grandpa often digresses into stories about his farm.","From Latin digredi, “to step aside.”"],["spellbound","SPEL-bownd","adjective","So amazed you cannot look away.","The kids sat spellbound during the puppet show.",""],["avuncular","uh-VUHNG-kyuh-ler","adjective","Kind and friendly, like a favorite uncle.","The avuncular shopkeeper slipped us each a candy.","From Latin avunculus, “mother's brother.”"],["paradigm","PAIR-uh-dym","noun","A model or a usual way of thinking about something.","Working from home changed the paradigm of the office.","From Greek paradeigma, “pattern.”"],["blithe","BLYTH","adjective","Cheerful and carefree, sometimes too much so.","She hummed with blithe good spirits as she cooked.",""],["bookish","BOOK-ish","adjective","Fond of reading and study.","The bookish boy always carried a novel in his backpack.",""],["paradox","PAIR-uh-doks","noun","Something that seems to go against itself but may be true.","It's a paradox that the more I rest, the more energy I have.","From Greek para, “beyond,” and doxa, “opinion.”"],["deduce","dih-DOOS","verb","To figure something out from clues.","From the crumbs, we deduced who ate the cookies.","From Latin deducere, “to lead down.”"],["amiable","AY-mee-uh-buhl","adjective","Friendly and pleasant.","Our amiable neighbor waves every morning.",""],["chrysalis","KRIS-uh-lis","noun","The case a caterpillar forms before becoming a butterfly.","We watched the butterfly break free of its chrysalis.","From Greek chrysos, “gold.”"],["prolific","pruh-LIF-ik","adjective","Making a lot of something.","The prolific writer finished a book each year.",""],["berate","bih-RAYT","verb","To scold someone angrily.","The goose berated us loudly for walking near its nest.",""],["pseudonym","SOOD-n-im","noun","A made-up name an author uses.","She wrote mystery novels under a pseudonym.","From Greek pseudes, “false,” and onoma, “name.”"],["refulgent","ri-FUL-juhnt","adjective","Shining very brightly.","The refulgent moon lit up the whole lake.","From Latin refulgere, “to shine back.”"],["placid","PLAS-id","adjective","Calm and peaceful.","The lake was placid in the early morning.","From Latin placidus, “gentle.”"],["gilded","GIL-did","adjective","Covered with a thin layer of gold.","The old book had gilded edges.",""],["besotted","bih-SOT-id","adjective","Completely charmed or in love.","The whole family is besotted with the new kitten.",""],["makeshift","MAYK-shift","adjective","Made quickly from whatever is around, for now.","We built a makeshift tent from blankets and chairs.",""],["annals","AN-uhlz","noun","Records of events year by year; history.","That snowstorm went down in the annals of our town.","From Latin annus, “year.”"],["garner","GAR-ner","verb","To gather or collect.","Her pie garnered praise at the fair.",""],["commensurate","kuh-MEN-ser-it","adjective","Matching in size or amount.","Her reward was commensurate with her hard work.",""],["belabor","bih-LAY-ber","verb","To talk about something far too long.","Let's not belabor the point; we all agree.",""],["frugal","FROO-guhl","adjective","Careful not to waste money or things.","My frugal aunt saves every jar and ribbon.","From Latin frugalis, “thrifty.”"],["ludicrous","LOO-di-kruhs","adjective","So silly it is laughable.","The idea of a cat walking on a leash seemed ludicrous.","From Latin ludus, “play.”"],["durable","DOOR-uh-buhl","adjective","Able to last a long time.","These durable boots have lasted ten winters.","From Latin durare, “to last.”"],["voluble","VOL-yuh-buhl","adjective","Talking easily and a lot.","My voluble aunt can chat for hours.","From Latin volvere, “to roll.”"],["stalwart","STAWL-wert","adjective","Loyal, strong and reliable.","He has been a stalwart helper at the food bank for years.",""],["deride","dih-RYD","verb","To make fun of in a mean way.","Nobody should deride a beginner for trying.","From Latin deridere, “to laugh at.”"],["nadir","NAY-der","noun","The lowest point of something.","Losing the game was the nadir of the season, but we bounced back.","From Arabic nazir, “opposite.”"],["urbane","er-BAYN","adjective","Polished, polite and at ease with people.","The urbane host made every guest feel welcome.","From Latin urbanus, “of the city.”"],["vicarious","vy-KAIR-ee-uhs","adjective","Felt through someone else’s experience.","I got vicarious joy from watching my son learn to ride a bike.","From Latin vicarius, “substitute.”"],["mischievous","MIS-chuh-vuhs","adjective","Playful in a way that causes small trouble.","The mischievous kitten hid my socks.",""],["dogmatic","dawg-MAT-ik","adjective","Sure your opinions are right and unwilling to listen.","Don’t be so dogmatic about how to fold towels.",""],["embolden","em-BOHL-duhn","verb","To give someone courage.","Her kind words emboldened him to try again.",""],["alacrity","uh-LAK-ri-tee","noun","Cheerful eagerness and quickness.","The kids cleaned their rooms with alacrity when they heard about ice cream.","From Latin alacer, “lively.”"],["dewy","DOO-ee","adjective","Wet with dew; fresh.","We walked barefoot across the dewy grass.",""],["cognizant","KOG-nuh-zuhnt","adjective","Aware of something.","Be cognizant of the time so we don’t miss the bus.",""],["puckish","PUK-ish","adjective","Playful and full of harmless mischief.","He gave a puckish grin before the prank.",""],["yonder","YON-der","adverb","Over there, at a distance.","Look at the deer standing yonder by the trees.",""],["affluent","AF-loo-uhnt","adjective","Having a lot of money and comfort.","The affluent town built a beautiful new park.","From Latin affluere, “to flow toward.”"],["distill","dih-STIL","verb","To boil something down to its most important part.","She distilled the long report into three points.","From Latin destillare, “to drip down.”"],["iridescent","ir-i-DES-uhnt","adjective","Showing shifting rainbow colors.","The soap bubble was iridescent in the sunlight.","From Greek iris, “rainbow.”"],["exhilarate","ig-ZIL-uh-rayt","verb","To make someone feel very happy and full of energy.","The sled ride down the hill exhilarated the kids.","From Latin exhilarare, “to make cheerful.”"],["attune","uh-TOON","verb","To make aware of and in tune with something.","Over time she became attuned to her baby's moods.",""],["hubris","HYOO-bris","noun","Too much pride.","His hubris made him skip practice, and he lost.","From Greek hybris, “excess pride.”"],["disenchant","dis-en-CHANT","verb","To make someone lose a good feeling about something.","The long lines disenchanted us with the theme park.",""],["abode","uh-BOHD","noun","The place where someone lives; a home.","Welcome to my humble abode, said Dad with a bow.",""],["collegial","kuh-LEE-jee-uhl","adjective","Friendly and cooperative among coworkers.","The office had a collegial, helpful mood.",""],["aria","AR-ee-uh","noun","A song sung by one voice, often in an opera.","The singer's aria brought the audience to its feet.","From Italian aria, “air.”"],["obsequious","uhb-SEE-kwee-uhs","adjective","Too eager to please or obey.","The obsequious waiter refilled our water every minute.","From Latin obsequi, “to comply.”"],["brindle","BRIN-dl","adjective","Brownish or gray with darker streaks, used for animals.","Our brindle dog blends right into the fall leaves.",""],["meander","mee-AN-der","verb","To wander slowly with no set path.","We meandered through the market tasting fruit.","From Greek Maiandros, a winding river."],["delegate","DEL-i-gayt","verb","To give part of your work to someone else.","Mom delegated the dishes to us.",""],["duplicity","doo-PLIS-i-tee","noun","Deceiving people by saying one thing and doing another.","The villain’s duplicity was revealed in the last chapter.","From Latin duplex, “double.”"],["flux","FLUKS","noun","Constant change.","Our plans for the weekend are still in flux.","From Latin fluxus, “flowing.”"],["capstone","KAP-stohn","noun","The final, crowning achievement.","The trip to the coast was the capstone of our summer.",""],["verdant","VUR-dnt","adjective","Green with lots of growing plants.","The verdant hills glowed after the spring rain.",""],["askance","uh-SKANS","adverb","With doubt or distrust, often looking sideways.","The cat looked askance at the new vacuum cleaner.",""],["nudge","NUJ","verb","To push gently, or to remind softly.","She nudged me to call my grandmother.",""],["bohemian","boh-HEE-mee-uhn","adjective","Living in a free, artistic and unusual way.","The painter's bohemian apartment was full of plants and colorful rugs.",""],["gaffe","GAF","noun","A small, awkward social mistake.","Calling my teacher “Mom” was quite a gaffe.","From French gaffe, “blunder.”"],["compendium","kuhm-PEN-dee-uhm","noun","A collection of facts or works in one place.","Her recipe box is a compendium of family favorites.",""],["celestial","suh-LES-chuhl","adjective","Having to do with the sky or the stars.","We lay on the grass and watched the celestial show.","From Latin caelum, “sky.”"],["lament","luh-MENT","verb","To show sadness or regret.","We lamented the end of summer.","From Latin lamentum, “a wailing.”"],["burnish","BUR-nish","verb","To polish until shiny.","He burnished the old brass doorknob until it gleamed.",""],["zilch","ZILCH","noun","Nothing at all.","I looked for my keys and found zilch.",""],["desolate","DES-uh-lit","adjective","Empty, lonely and bare.","The beach felt desolate in the winter fog.",""],["anachronism","uh-NAK-ruh-niz-uhm","noun","Something that seems to belong to a different time.","A typewriter in a modern office feels like a charming anachronism.","From Greek ana, “back,” and chronos, “time.”"],["chastise","chas-TYZ","verb","To scold someone sharply.","The coach chastised us for being late.",""],["obscure","uhb-SKYOOR","adjective","Not well known, or hard to understand.","He loves obscure facts about bugs.","From Latin obscurus, “dark.”"],["pulchritude","PUL-krih-tood","noun","Physical beauty.","The garden in May is a sight of pure pulchritude.","From Latin pulcher, “beautiful.”"],["breadth","BREDTH","noun","Width; also wide range or scope.","Her breadth of knowledge about birds amazed us.",""],["peccadillo","pek-uh-DIL-oh","noun","A small, harmless fault.","Eating dessert first is my favorite peccadillo.","From Spanish pecadillo, “small fault.”"],["recalcitrant","ri-KAL-si-truhnt","adjective","Stubborn and hard to control.","The recalcitrant mule would not move one more step.","From Latin recalcitrare, “to kick back.”"],["carapace","KAR-uh-pays","noun","The hard shell on the back of a turtle or crab.","The turtle pulled its head inside its carapace.",""],["deign","DAYN","verb","To do something as if it were beneath you.","The cat finally deigned to sit on my lap.","From Latin dignari, “to think worthy.”"],["frivolous","FRIV-uh-luhs","adjective","Silly and not serious or important.","We spent a frivolous afternoon blowing bubbles.","From Latin frivolus, “silly.”"],["wrangle","RANG-guhl","verb","To argue, or to round up and control something.","It took ten minutes to wrangle the kids into the car.",""],["gravitas","GRAV-i-tahs","noun","A serious, dignified manner.","The class president spoke with gravitas.","From Latin gravitas, “weight.”"],["kibitz","KIB-its","verb","To give advice nobody asked for, especially while watching a game.","My uncle loves to kibitz during our card games.","From Yiddish kibitsen."],["polymath","POL-ee-math","noun","A person who knows a lot about many subjects.","The polymath next door can fix cars and play the cello.","From Greek polymathes, “having learned much.”"],["virtuoso","vur-choo-OH-soh","noun","A person with amazing skill, especially in music.","The young violin virtuoso played without any sheet music.","From Italian virtuoso, “skilled.”"],["paltry","PAWL-tree","adjective","Very small and not worth much.","He won a paltry prize of one sticker, but he was proud.",""],["impasse","IM-pas","noun","A point where no progress can be made.","We reached an impasse about the movie, so we played a game instead.","From French impasse, “dead end.”"],["perpetual","per-PECH-oo-uhl","adjective","Never ending or changing.","Our little brother is in perpetual motion.","From Latin perpetuus, “continuing.”"],["commiserate","kuh-MIZ-uh-rayt","verb","To share in someone’s sadness or trouble.","We commiserated over our soggy picnic.","From Latin miser, “wretched.”"],["coerce","koh-URS","verb","To force someone to do something.","You can’t coerce a cat into a bath.",""],["adjunct","AJ-uhngkt","noun","Something added to a main thing but not essential to it.","The garden club is an adjunct to the town library.",""],["dapper","DAP-er","adjective","Neat and stylish in dress.","Grandpa looked dapper in his bow tie.",""],["respite","RES-pit","noun","A short rest from something tiring.","The shady tree gave us a respite from the hot sun.",""],["brittle","BRIT-l","adjective","Hard but easily broken.","The old leaves were dry and brittle.",""],["perceptive","per-SEP-tiv","adjective","Quick to notice and understand things.","The perceptive teacher saw I was nervous.",""],["defiant","dih-FY-uhnt","adjective","Boldly refusing to obey.","The defiant toddler would not wear his hat.",""],["fracas","FRAY-kuhs","noun","A noisy quarrel or fuss.","There was a small fracas over the last slice of pie.",""],["reciprocate","ri-SIP-ruh-kayt","verb","To give back the same kind of thing you got.","When she helped me move, I reciprocated by cooking her dinner.","From Latin reciprocus, “moving back and forth.”"],["precarious","prih-KAIR-ee-uhs","adjective","Not safe or steady; likely to fall.","The stack of books was precarious.","From Latin precarius, “obtained by asking.”"],["emissary","EM-uh-ser-ee","noun","A person sent with a message or a job to do.","The kids sent their little sister as an emissary to ask for ice cream.","From Latin emissarius, “one sent out.”"],["bough","BOW","noun","A large branch of a tree.","A swing hung from the old oak's lowest bough.",""],["kernel","KUR-nuhl","noun","A seed, or the most important part of something.","There is a kernel of truth in every fairy tale.",""],["motif","moh-TEEF","noun","A pattern or idea that keeps showing up.","Birds are a motif in all of her paintings.","From French motif."],["scallywag","SKAL-ee-wag","noun","A playful rascal.","That little scallywag ate all the cherries.",""],["panacea","pan-uh-SEE-uh","noun","A cure for every problem.","A nap is not a panacea, but it helps a lot.","From Greek pan, “all,” and akos, “cure.”"],["mundane","mun-DAYN","adjective","Plain and ordinary.","Even mundane chores feel fun with good music.","From Latin mundus, “world.”"],["oomph","OOMF","noun","Energy and excitement.","A little hot sauce gives the soup some oomph.",""],["elucidate","ih-LOO-si-dayt","verb","To make something clear by explaining it.","The teacher drew a picture to elucidate the idea.","From Latin lucidus, “bright, clear.”"],["piecemeal","PEES-meel","adverb","Bit by bit, a little at a time.","We fixed up the old house piecemeal.",""],["docile","DOS-uhl","adjective","Calm and easy to handle.","The docile horse let the children brush its mane.","From Latin docilis, “easily taught.”"],["amass","uh-MAS","verb","To gather a large amount of something over time.","Over the years he amassed a huge collection of stamps.",""],["cairn","KAIRN","noun","A pile of stones used to mark a place or trail.","Hikers stacked a cairn to show the path.","From Scottish Gaelic carn, “heap of stones.”"],["luscious","LUSH-uhs","adjective","Rich and delicious.","We ate luscious ripe peaches.",""],["grimace","GRIM-uhs","noun","A twisted face showing dislike or pain.","He made a grimace at the sour lemon.",""],["miscellany","MIS-uh-lay-nee","noun","A mix of many different things.","The drawer held a miscellany of keys, string and stamps.","From Latin miscellanea, “mixed things.”"],["torrent","TOR-uhnt","noun","A fast, strong rush of water or other things.","A torrent of rain poured off the roof.","From Latin torrens, “rushing, boiling.”"],["desiccate","DES-i-kayt","verb","To dry out completely.","The hot sun desiccated the garden.","From Latin siccus, “dry.”"],["avid","AV-id","adjective","Very eager and keen.","My dad is an avid reader of mystery novels.","From Latin avidus, “eager.”"],["wry","RY","adjective","Dryly funny in a quiet, clever way.","She gave a wry smile when the cake fell.",""],["sheepish","SHEE-pish","adjective","A little embarrassed about something you did.","He gave a sheepish smile after tripping over the rug.",""],["impeccable","im-PEK-uh-buhl","adjective","Without any flaws.","He has impeccable table manners.",""],["quirky","KWUR-kee","adjective","Odd or unusual in a charming way.","Her quirky hat with a paper flower made people smile.",""],["goad","GOHD","verb","To push someone to do something.","His friends goaded him into trying the spicy pepper.",""],["morale","muh-RAL","noun","How cheerful and hopeful a group feels.","Pizza Friday is great for team morale.",""],["palpable","PAL-puh-buhl","adjective","So strong you can almost touch it.","The excitement before the show was palpable.","From Latin palpare, “to touch gently.”"],["rarefied","RAIR-uh-fyd","adjective","Thin, high or special, as if far above everyday life.","The climbers breathed the rarefied air at the top of the mountain.","From Latin rarus, “thin, rare.”"],["intrepid","in-TREP-id","adjective","Brave and fearless.","The intrepid kids explored the creek.","From Latin intrepidus, “not alarmed.”"],["dazzle","DAZ-uhl","verb","To amaze with brightness or skill.","The fireworks dazzled the crowd.",""],["murmuration","mur-myuh-RAY-shuhn","noun","A huge flock of birds swirling together in the sky.","We watched a murmuration of starlings at sunset.",""],["artisan","AR-tuh-zuhn","noun","A skilled worker who makes things by hand.","An artisan carved the wooden spoon we use every day.",""],["maelstrom","MAYL-struhm","noun","A wild, swirling mess of action or feeling.","The kitchen was a maelstrom of pots and flour before the big dinner.","From early Dutch maelstroom, “grinding stream.”"],["covet","KUHV-it","verb","To want something very much, often something that is someone else’s.","He coveted his friend’s shiny red bike.",""],["frisson","free-SOHN","noun","A sudden thrill or shiver of excitement.","A frisson ran through the crowd as the curtain rose.","From French frisson, “a shiver.”"],["putter","PUT-er","verb","To do small, easy tasks in a relaxed way.","Grandpa loves to putter in his workshop.",""],["harrowing","HAR-oh-ing","adjective","Very upsetting or frightening.","Watching the kitten's rescue from the tall tree was harrowing.",""],["kaput","kuh-POOT","adjective","Broken and no longer working.","The old toaster is kaput.","From German kaputt."],["parsimonious","par-suh-MOH-nee-uhs","adjective","Very unwilling to spend money.","The parsimonious man reused tea bags three times.","From Latin parcere, “to spare.”"],["myriad","MEER-ee-uhd","adjective","Too many to count.","The night sky held myriad stars.","From Greek myrias, “ten thousand.”"],["ruse","ROOZ","noun","A clever trick meant to fool someone.","The surprise party ruse worked perfectly.",""],["keepsake","KEEP-sayk","noun","A small thing kept to remember someone or something.","The seashell is a keepsake from our trip.",""],["buoyant","BOY-uhnt","adjective","Able to float; also cheerful and hopeful.","She was in a buoyant mood on the first day of spring.",""],["decoy","DEE-koy","noun","Something used to lure or distract.","The wooden duck was a decoy that fooled the real ducks.",""],["profuse","pruh-FYOOS","adjective","Given in large amounts.","He gave profuse thanks for the help.","From Latin profundere, “to pour forth.”"],["farrago","fuh-RAH-goh","noun","A confused mix of things.","His closet was a farrago of shoes, games and old kites.","From Latin farrago, “mixed feed for cattle.”"],["lagoon","luh-GOON","noun","A shallow body of water cut off from the sea.","We paddled across the calm lagoon.","From Italian laguna."],["oddball","OD-bawl","noun","A person who is fun and a little strange.","Every family has an oddball, and ours wears bright socks.",""],["bountiful","BOUN-tuh-fuhl","adjective","Plentiful, or giving freely.","We gave thanks for a bountiful harvest.",""],["concoct","kuhn-KOKT","verb","To make something by mixing things together.","The kids concocted a wild new smoothie.","From Latin concoquere, “to cook together.”"],["dynamo","DY-nuh-moh","noun","A very energetic person.","Our coach is a dynamo who never stops moving.","From Greek dynamis, “power.”"],["behold","bih-HOHLD","verb","To see or look at something special.","The sunset over the lake was a sight to behold.",""],["oblivion","uh-BLIV-ee-uhn","noun","The state of being forgotten or unaware.","The old song faded into oblivion until a band brought it back.","From Latin oblivisci, “to forget.”"],["minstrel","MIN-struhl","noun","A traveling singer or musician of long ago.","The fair had a minstrel who played the lute.",""],["discombobulate","dis-kuhm-BOB-yuh-layt","verb","To confuse or fluster someone.","The sudden change of plans discombobulated us.",""],["derelict","DER-uh-likt","adjective","Abandoned and run-down.","Volunteers turned the derelict lot into a garden.","From Latin derelinquere, “to abandon.”"],["renounce","ri-NOWNS","verb","To give something up formally or on purpose.","She renounced sweets for a month to see how she felt.",""],["auspicious","aw-SPISH-uhs","adjective","Showing signs of future success; a good start.","Sunshine on opening day was an auspicious sign.","From Latin auspicium, “a reading of birds.”"],["furtive","FUR-tiv","adjective","Sneaky, trying not to be seen.","The dog gave a furtive glance at the sandwich.","From Latin furtivus, “stolen.”"],["festoon","fe-STOON","verb","To decorate with chains of flowers, ribbons or lights.","We festooned the porch with paper lanterns.","From Italian festone, “festive garland.”"],["twilight","TWY-lyt","noun","The soft light just after sunset.","We caught fireflies in the twilight.",""],["deft","DEFT","adjective","Quick and skillful.","With a deft flick, she flipped the pancake.",""],["usher","UHSH-er","verb","To guide someone to a place.","The kind man ushered us to our seats.",""],["improvise","IM-pruh-vyz","verb","To make or do something without a plan, using what you have.","We forgot the tent poles, so we improvised with sticks.","From Latin improvisus, “unforeseen.”"],["fjord","fee-ORD","noun","A long, narrow arm of sea between tall cliffs.","The boat glided through the quiet fjord.","From Norwegian fjord."],["boffin","BOF-in","noun","A playful word for a scientist or expert.","The computer boffin fixed my laptop in a minute.",""],["gawk","GAWK","verb","To stare in a silly or rude way.","Visitors gawked at the giant pumpkin.",""],["tawdry","TAW-dree","adjective","Showy and cheap looking.","The shop was full of tawdry plastic souvenirs.",""],["meteoric","mee-tee-OR-ik","adjective","Very fast and bright, like a shooting star.","The bakery had a meteoric rise after one great review.",""],["poignant","POYN-yuhnt","adjective","Touching the heart in a sad or tender way.","The old photo was a poignant reminder of summer.","From French poindre, “to prick.”"],["diurnal","dy-UR-nl","adjective","Active in the daytime.","Squirrels are diurnal, while owls come out at night.","From Latin diurnus, “of the day.”"],["cerebral","suh-REE-bruhl","adjective","Thoughtful and focused on ideas more than feelings.","She enjoys cerebral puzzles that take all evening.","From Latin cerebrum, “brain.”"],["pungent","PUN-juhnt","adjective","Having a strong, sharp smell or taste.","The pungent garlic made our eyes water.","From Latin pungere, “to prick.”"],["dearth","DURTH","noun","A lack or shortage.","There is no dearth of love in this house.",""],["oaf","OHF","noun","A clumsy, awkward person.","I felt like an oaf when I tripped over the rug.",""],["opine","oh-PYN","verb","To give your opinion.","Uncle Joe likes to opine on the best way to grill corn.","From Latin opinari, “to think.”"],["ennui","on-WEE","noun","A tired, bored feeling of having nothing fun to do.","A rainy week of ennui ended when the sun came out.","From French ennui, “boredom.”"],["tenacious","tuh-NAY-shuhs","adjective","Not giving up; holding on firmly.","The tenacious puppy would not let go of the rope toy.","From Latin tenax, “holding fast.”"],["guffaw","guh-FAW","noun","A loud, hearty laugh.","Dad let out a guffaw at the cartoon.",""],["disabuse","dis-uh-BYOOZ","verb","To free someone from a wrong belief.","Let me disabuse you of the idea that cats like baths.",""],["whittle","WIT-l","verb","To carve wood by cutting off small bits.","Grandpa whittled a little bird from a stick.",""],["nomad","NOH-mad","noun","A person who moves from place to place.","After college he lived like a nomad, working in different towns.","From Greek nomas, “roaming.”"],["apothecary","uh-POTH-uh-ker-ee","noun","An old word for a shop or person that made and sold medicines.","The museum had a tiny apothecary with glass jars on the shelves.",""],["coax","KOHKS","verb","To gently persuade.","She coaxed the kitten out from under the bed.",""],["virga","VUR-guh","noun","Rain that falls from a cloud but dries up before reaching the ground.","We saw gray streaks of virga hanging over the desert.","From Latin virga, “rod, streak.”"],["devour","dih-VOUR","verb","To eat or read hungrily.","She devoured the whole book in one night.","From Latin devorare, “to swallow down.”"],["legible","LEJ-uh-buhl","adjective","Clear enough to read.","Please make your handwriting legible.","From Latin legere, “to read.”"],["germane","jer-MAYN","adjective","Related to the topic being discussed.","Please keep your questions germane to the lesson.",""],["vacillate","VAS-uh-layt","verb","To keep changing your mind.","I vacillated between the blue shirt and the green one.","From Latin vacillare, “to sway.”"],["awry","uh-RY","adverb","Away from the planned or right course.","Our picnic plans went awry when the ants arrived.",""],["outspoken","out-SPOH-kuhn","adjective","Saying what you think openly and boldly.","My outspoken aunt always tells us the truth.",""],["salient","SAY-lee-uhnt","adjective","Most important or easy to notice.","The salient point of her talk was to be kind.","From Latin salire, “to leap.”"],["brazen","BRAY-zuhn","adjective","Bold and without shame.","The brazen seagull stole a fry right from my hand.",""],["proliferate","pruh-LIF-uh-rayt","verb","To grow or spread quickly.","Dandelions proliferated across the lawn.",""],["noodle","NOO-dl","verb","To play around with an idea or tune in a relaxed way.","He noodled on the guitar while dinner cooked.",""],["echelon","ESH-uh-lon","noun","A level or rank in a group.","She rose to the top echelon of chess players in town.","From French échelon, “rung of a ladder.”"],["overcast","OH-ver-kast","adjective","Covered with gray clouds.","It was overcast, so we packed umbrellas.",""],["pertinent","PUR-tn-uhnt","adjective","Related to the subject at hand.","Please ask questions that are pertinent to the lesson.",""],["serene","suh-REEN","adjective","Calm and peaceful.","The lake looked serene in the early morning light.","From Latin serenus, “clear, calm.”"],["agog","uh-GOG","adjective","Very eager and excited to hear or see something.","The class was agog at the news of a snow day.",""],["transfix","trans-FIKS","verb","To hold someone still with wonder or surprise.","The kids were transfixed by the shooting stars.","From Latin transfigere, “to pierce through.”"],["astound","uh-STOUND","verb","To surprise someone very much.","The tiny dog's high jump astounded the crowd.",""],["delectable","dih-LEK-tuh-buhl","adjective","Delicious and delightful.","The delectable smell of fresh bread filled the house.","From Latin delectare, “to delight.”"],["moxie","MOK-see","noun","Courage and spunk.","It took moxie to sing on stage for the first time.",""],["limpid","LIM-pid","adjective","Clear and easy to see through.","We swam in a limpid mountain pool.","From Latin limpidus, “clear.”"],["brood","BROOD","verb","To think long and deeply about something that worries you.","Instead of brooding over the lost game, they went for ice cream.",""],["disinclined","dis-in-KLYND","adjective","Not wanting to do something.","On rainy days, I’m disinclined to leave my bed.",""],["haphazard","hap-HAZ-erd","adjective","Done without any plan or order.","Toys lay in a haphazard pile.",""],["banish","BAN-ish","verb","To send away or get rid of.","A warm bath banished my worries.",""],["malapropism","MAL-uh-prop-iz-uhm","noun","Using a wrong word that sounds like the right one, often by mistake.","Saying “for all intensive purposes” is a funny malapropism.",""],["quandary","KWON-dree","noun","A tricky spot where you are not sure what to do.","I was in a quandary about which birthday cake to pick.",""],["doodle","DOO-dl","verb","To draw little shapes without much thought.","He doodles stars in the margins of his notebook.",""],["jettison","JET-i-suhn","verb","To throw away something you no longer need.","We jettisoned the broken toys before the move.",""],["contagious","kuhn-TAY-juhs","adjective","Easily spread from one person to another.","Her laugh was so contagious the whole room joined in.",""],["finesse","fi-NES","noun","Skill and grace in handling something.","She folded the paper crane with great finesse.","From French fin, “fine.”"],["kismet","KIZ-met","noun","Fate or destiny.","Finding my lost ring in the sand felt like kismet.","From Turkish kismet, “fate.”"],["fledgling","FLEJ-ling","noun","A young bird just learning to fly, or a beginner.","The fledgling hopped from branch to branch.",""],["milieu","mil-YOO","noun","The setting or world around a person.","The cozy milieu of the bookshop made us stay for hours.","From French milieu, “middle.”"],["insatiable","in-SAY-shuh-buhl","adjective","Never satisfied; always wanting more.","She has an insatiable love of books.",""],["loquacious","loh-KWAY-shuhs","adjective","Very talkative.","Our loquacious parrot greets every visitor.","From Latin loqui, “to speak.”"],["trifle","TRY-fuhl","noun","Something small and unimportant, or a layered dessert.","Don’t worry about the spilled milk; it’s a trifle.",""],["bard","BARD","noun","A poet or storyteller, especially one who sings.","The camp counselor was our bard, telling tales by the fire.",""],["jeopardy","JEP-er-dee","noun","Danger of harm or loss.","The storm put our picnic in jeopardy.",""],["demur","dih-MUR","verb","To politely object or hesitate.","She demurred when asked to sing, then sang anyway.",""],["dilatory","DIL-uh-tor-ee","adjective","Slow and likely to delay.","His dilatory packing made us late again.",""],["muster","MUS-ter","verb","To gather up, like courage or people.","She mustered the nerve to ask a question in class.","From Latin monstrare, “to show.”"],["eclectic","ih-KLEK-tik","adjective","Made up of many different kinds of things.","Grandpa has an eclectic music collection, from jazz to folk songs.","From Greek eklektikos, “picking out.”"],["outstrip","out-STRIP","verb","To grow bigger or faster than something else.","Demand for her cookies outstripped her oven.",""],["dutiful","DOO-ti-fuhl","adjective","Doing what is expected, with care.","The dutiful dog waited by the door every evening.",""],["confection","kuhn-FEK-shuhn","noun","A sweet treat, like candy or fancy cake.","The bakery window was full of pink confections.",""],["allure","uh-LOOR","noun","A strong, attractive charm.","The allure of the beach pulled us out of bed early.",""],["inkling","INK-ling","noun","A slight idea or hint.","I had no inkling about the surprise party.",""],["delineate","dih-LIN-ee-ayt","verb","To describe or mark out clearly.","The map delineates each hiking trail.","From Latin linea, “line.”"],["larder","LAR-der","noun","A cool room or cupboard for storing food.","The larder was full of jams and pickles.",""],["jovial","JOH-vee-uhl","adjective","Cheerful and friendly.","The jovial baker gave us free cookies.",""],["redress","ri-DRES","verb","To set right something that was wrong or unfair.","The store redressed the mistake by sending a new lamp.",""],["lassitude","LAS-i-tood","noun","A tired, lazy feeling.","The summer heat brought a pleasant lassitude.","From Latin lassus, “weary.”"],["rubicund","ROO-bi-kuhnd","adjective","Having a healthy red color in the face.","The baker’s rubicund cheeks glowed by the warm oven.","From Latin rubicundus, “reddish.”"],["touchstone","TUCH-stohn","noun","Something used to judge the quality of other things.","Her mother’s kindness was the touchstone for how she treated others.",""],["alpenglow","AL-puhn-gloh","noun","The pink glow on mountain tops near sunrise or sunset.","We watched the alpenglow paint the snowy peaks.","From German Alpenglühen, “Alps glow.”"],["vitality","vy-TAL-i-tee","noun","Lively energy and strength.","The garden was full of vitality in May.","From Latin vita, “life.”"],["brink","BRINGK","noun","The edge of a steep place, or the point just before something happens.","The team was on the brink of winning the title.",""],["vertiginous","ver-TIJ-uh-nuhs","adjective","So high it makes you dizzy.","We peeked over the vertiginous cliff edge.","From Latin vertigo, “a whirling.”"],["redoubtable","ri-DOW-tuh-buhl","adjective","Strong and worthy of respect, even a little scary.","My grandmother is a redoubtable chess player.","From French redouter, “to fear.”"],["rapture","RAP-cher","noun","A feeling of great joy and delight.","The children watched the fireworks in pure rapture.","From Latin raptus, “carried off.”"],["parley","PAR-lee","noun","A talk between two sides to settle something.","The kids held a parley to share the swing.","From French parler, “to speak.”"],["spurious","SPYOOR-ee-uhs","adjective","False, even though it looks real.","The ad made spurious claims about the magic shoes.","From Latin spurius, “false.”"],["flamboyant","flam-BOY-uhnt","adjective","Bold, bright and showy.","He wore a flamboyant orange hat to the fair.","From French flamboyer, “to flame.”"],["unruly","uhn-ROO-lee","adjective","Hard to control or keep in order.","I tried to tame my unruly curls with a clip.",""],["gregarious","gri-GAIR-ee-uhs","adjective","Loving to be with other people.","Our gregarious dog greets everyone at the park.","From Latin grex, “flock.”"],["blatant","BLAYT-nt","adjective","Very obvious and done openly.","Leaving crumbs on his shirt was a blatant clue he ate the cookies.",""],["categorical","kat-i-GOR-i-kuhl","adjective","Clear and without any doubt.","Her answer was a categorical no to more cake.",""],["surmise","ser-MYZ","verb","To guess something based on clues.","From the muddy paws, I surmised the dog had been in the garden.",""],["wanderlust","WON-der-luhst","noun","A strong wish to travel and explore.","Her wanderlust took her to a new country every summer.","From German Wanderlust, “desire to wander.”"],["negate","nih-GAYT","verb","To cancel out or make useless.","Eating a whole cake can negate a long walk.","From Latin negare, “to deny.”"],["disheveled","dih-SHEV-uhld","adjective","Messy and untidy, especially hair or clothes.","He came home disheveled after the windy walk.",""],["cosset","KOS-it","verb","To pamper and care for someone.","We cosseted Mom with breakfast in bed.",""],["clemency","KLEM-uhn-see","noun","Mercy shown to someone who did wrong.","The teacher showed clemency and gave us one more day.","From Latin clemens, “mild.”"],["disposition","dis-puh-ZISH-uhn","noun","A person’s usual mood or nature.","Our dog has a sunny disposition.",""],["acclaim","uh-KLAYM","noun","Loud and public praise.","Her apple pie won wide acclaim at the county fair.","From Latin acclamare, “to shout at.”"],["tandem","TAN-duhm","noun","Two things working together, one behind the other.","The friends rode a tandem bike along the shore.","From Latin tandem, “at length.”"],["jocular","JOK-yuh-ler","adjective","Playful and joking.","Our jocular mail carrier always has a riddle for us.","From Latin jocus, “joke.”"],["alcove","AL-kohv","noun","A small space set back into a wall of a room.","She made a cozy reading nook in the alcove by the stairs.","From Arabic al-qubba, “the vault.”"],["widdershins","WID-er-shinz","adverb","In the opposite direction to the sun’s path; counterclockwise.","The children skipped widdershins around the maypole.",""],["kaleidoscope","kuh-LY-duh-skohp","noun","A tube of mirrors and colored bits that make changing patterns, or any bright, changing mix.","The garden was a kaleidoscope of color.","From Greek kalos, “beautiful,” and eidos, “form.”"],["monotony","muh-NOT-n-ee","noun","Boring sameness with no change.","Singing in the car broke the monotony of the long drive.","From Greek monos, “one,” and tonos, “tone.”"],["gallant","GAL-uhnt","adjective","Brave and polite, especially in a kind way.","The gallant boy held the door for everyone.","From French galant, “courtly.”"],["demure","dih-MYOOR","adjective","Quiet, modest and shy.","The demure puppy hid behind its mother.",""],["clairvoyant","klair-VOY-uhnt","adjective","Seeming to know things before they happen.","Mom seems clairvoyant about when we’ve skipped brushing.","From French clair, “clear,” and voyant, “seeing.”"],["misanthrope","MIS-uhn-throhp","noun","A person who does not like other people.","The grumpy neighbor seemed a misanthrope until he brought us soup.","From Greek misein, “to hate,” and anthropos, “human.”"],["choreograph","KOR-ee-uh-graf","verb","To plan the steps of a dance or event.","The kids choreographed a dance for the talent show.","From Greek choreia, “dance.”"],["apprise","uh-PRYZ","verb","To tell someone about something; to inform.","Please apprise me of any changes to the plan.","From French appris, “taught.”"],["proclivity","proh-KLIV-ih-tee","noun","A natural leaning toward something.","My dog has a proclivity for napping in sunbeams.","From Latin proclivis, “sloping forward.”"],["judicious","joo-DISH-uhs","adjective","Wise and careful in choosing.","She made a judicious choice to leave early and beat the traffic.","From Latin judicium, “judgment.”"],["cupidity","kyoo-PID-i-tee","noun","Strong greed, especially for money.","The story warns of a king whose cupidity cost him everything.",""],["conceit","kuhn-SEET","noun","Too much pride in yourself.","His conceit faded after he lost the spelling bee.",""],["outpace","out-PAYS","verb","To go faster or do better than.","The little dog outpaced the big one in the race.",""],["patina","puh-TEE-nuh","noun","A soft shine or color that comes with age.","The copper roof had a lovely green patina.",""],["enigma","ih-NIG-muh","noun","A puzzle or mystery that is hard to figure out.","How the cat got onto the roof was an enigma.","From Greek ainigma, “a riddle.”"],["bereft","bih-REFT","adjective","Sad and lonely because something is missing.","The town felt bereft when the old bakery closed.",""],["tumbleweed","TUM-buhl-weed","noun","A dry plant that breaks off and rolls in the wind.","A tumbleweed rolled across the empty desert road.",""],["antecedent","an-tuh-SEE-duhnt","noun","Something that came before and led to something else.","The horse cart was an antecedent of the car.","From Latin antecedere, “to go before.”"],["glacial","GLAY-shuhl","adjective","Very slow or very cold, like a glacier.","Traffic moved at a glacial pace.","From Latin glacies, “ice.”"],["exuberant","ig-ZOO-ber-uhnt","adjective","Full of joy, energy and excitement.","The exuberant puppy ran circles around the yard.","From Latin exuberare, “to be fruitful.”"],["abate","uh-BAYT","verb","To become less strong or less intense.","We waited on the porch until the rain began to abate.","From Old French abatre, “to beat down.”"],["maven","MAY-vuhn","noun","A person who knows a lot about something.","My neighbor is a coffee maven who can name every bean.","From Yiddish meyvn, “one who understands.”"],["humility","hyoo-MIL-i-tee","noun","Not thinking you are better than others.","She won the prize but accepted it with humility.","From Latin humilis, “low.”"],["disingenuous","dis-in-JEN-yoo-uhs","adjective","Not fully honest or sincere.","It was disingenuous to say he didn’t want dessert.",""],["opportune","op-er-TOON","adjective","Happening at just the right time.","The bus arrived at an opportune moment, right as it rained.","From Latin opportunus, “toward the harbor.”"],["hijinks","HY-jinks","noun","Playful, silly fun.","The cousins got up to hijinks at the sleepover.",""],["voluminous","vuh-LOO-muh-nuhs","adjective","Very large or full, holding a lot.","She wore a voluminous coat with deep pockets.",""],["drivel","DRIV-uhl","noun","Silly talk or nonsense.","The comic book was fun drivel for a rainy day.",""],["ornate","or-NAYT","adjective","Covered in fancy decoration.","The old theater had an ornate ceiling.","From Latin ornare, “to adorn.”"],["ambivalent","am-BIV-uh-luhnt","adjective","Having mixed feelings about something.","I feel ambivalent about moving, excited but a little sad.",""],["unscathed","uhn-SKAYTHD","adjective","Not hurt or harmed at all.","The vase fell off the shelf but landed unscathed.",""],["menagerie","muh-NAJ-uh-ree","noun","A mixed group of animals, or of odd things.","Their house is a menagerie of cats, fish and one parrot.","From French ménagerie."],["filigree","FIL-i-gree","noun","Delicate, lacy designs made of fine wire.","Her silver necklace had lovely filigree.",""],["tumult","TOO-muhlt","noun","A loud, confused noise or uproar.","The tumult of the crowd grew as the parade came near.","From Latin tumultus, “commotion.”"],["caveat","KAV-ee-aht","noun","A warning or condition to keep in mind.","You can borrow the car, with one caveat: fill the tank.","From Latin caveat, “let him beware.”"],["modicum","MOD-ih-kuhm","noun","A small amount.","With a modicum of practice, you can learn to juggle.","From Latin modicus, “moderate.”"],["unison","YOO-nuh-suhn","noun","Doing something together at the same time.","The class said “good morning” in unison.","From Latin unisonus, “having one sound.”"],["salubrious","suh-LOO-bree-uhs","adjective","Good for your health.","The salubrious mountain air made us all feel better.","From Latin salus, “health.”"],["outmoded","out-MOH-did","adjective","Out of date; no longer in style or use.","We traded the outmoded phone for a newer one.",""],["downcast","DOUN-kast","adjective","Sad and low in spirit.","He was downcast until his friend called.",""],["adamant","AD-uh-muhnt","adjective","Firm and refusing to change your mind.","Grandpa was adamant that we wear our coats in the snow.",""],["concede","kuhn-SEED","verb","To admit something is true, often unwillingly.","He conceded that her pie was better than his.","From Latin concedere, “to yield.”"],["narrative","NAR-uh-tiv","noun","A story, or the way a story is told.","Her travel narrative made us want to visit the coast.","From Latin narrare, “to tell.”"],["disembark","dis-em-BARK","verb","To get off a ship, plane or train.","We disembarked and headed to the beach.",""],["ravenous","RAV-uh-nuhs","adjective","Very, very hungry.","After a day at the beach, we were ravenous.",""],["propitious","pruh-PISH-uhs","adjective","Giving a good chance of success.","Sunny skies made it a propitious day for a picnic.","From Latin propitius, “favorable.”"],["begrudge","bih-GRUHJ","verb","To feel unhappy that someone has something, or to give unwillingly.","I don't begrudge my brother his win; he trained hard.",""],["lush","LUSH","adjective","Full of thick, green growth.","The lush garden was full of ferns.",""],["obdurate","OB-duh-rit","adjective","Very stubborn and hard to move.","The obdurate mule would not cross the bridge.","From Latin obdurare, “to harden.”"],["bonhomie","bon-uh-MEE","noun","Cheerful, friendly good nature.","The picnic was full of bonhomie and laughter.","From French bonhomie, “good nature.”"],["potpourri","poh-puh-REE","noun","A bowl of dried petals and spices, or a mix of things.","The show was a potpourri of songs, jokes and dances.","From French pot pourri, “rotten pot.”"],["tirade","TY-rayd","noun","A long, angry speech.","The chef went on a funny tirade about burnt toast.",""],["periphery","puh-RIF-uh-ree","noun","The outer edge of something.","A deer stood at the periphery of the field.","From Greek periphereia, “circumference.”"],["contrite","kuhn-TRYT","adjective","Feeling sorry for doing wrong.","The contrite puppy hid after chewing the shoe.",""],["quidnunc","KWID-nungk","noun","A person who always wants to know the latest news.","Our friendly quidnunc neighbor knew about the new bakery first.","From Latin quid nunc, “what now?”"],["sartorial","sar-TOR-ee-uhl","adjective","Having to do with clothes and how you dress.","His bright bow tie was a sartorial delight.","From Latin sartor, “tailor.”"],["sanguine","SANG-gwin","adjective","Cheerful and hopeful, even when things are hard.","Mom stayed sanguine even when the car broke down.","From Latin sanguis, “blood.”"],["avail","uh-VAYL","noun","Use or help, as in the phrase “to no avail” meaning without success.","We searched for the lost key, but to no avail.",""],["sibilant","SIB-uh-luhnt","adjective","Making a hissing “s” sound.","The sibilant whisper of the wind filled the tent.","From Latin sibilare, “to hiss.”"],["élan","ay-LAHN","noun","Style, energy and confidence.","She danced with such élan that everyone clapped.","From French élan, “dash, rush.”"],["alchemy","AL-kuh-mee","noun","A kind of magic that seems to turn ordinary things into something special.","By some kitchen alchemy, leftovers became a delicious soup.",""],["suffuse","suh-FYOOZ","verb","To spread slowly over or through something.","A warm glow suffused the sky at dusk.","From Latin suffundere, “to pour beneath.”"],["knotty","NOT-ee","adjective","Full of knots, or hard to solve.","We worked through a knotty math problem.",""],["savor","SAY-ver","verb","To enjoy something slowly so it lasts.","She savored every bite of the warm peach pie.","From Latin sapor, “taste.”"],["aerie","AIR-ee","noun","A high nest of an eagle or other large bird; also any high, safe spot.","From her attic aerie, she could see the whole town.",""],["cynosure","SY-nuh-shoor","noun","Someone or something everyone looks at.","The giant cake was the cynosure of the party.",""],["duress","doo-RES","noun","Pressure or threats used to make someone act.","He ate his broccoli only under duress.",""],["illustrious","ih-LUS-tree-uhs","adjective","Famous and admired for great deeds.","The illustrious author visited our book club.","From Latin illustris, “bright.”"],["fathom","FATH-uhm","verb","To understand something after thinking hard.","I can't fathom how bees find their way home.","From Old English fæthm, “outstretched arms.”"],["mystique","mih-STEEK","noun","A special air of mystery that draws you in.","The old lighthouse has a certain mystique.",""],["badinage","bad-n-AHZH","noun","Light, playful teasing talk.","The friends traded friendly badinage over breakfast.","From French badiner, “to joke.”"],["eminent","EM-uh-nuhnt","adjective","Famous and respected.","An eminent scientist visited our school.","From Latin eminere, “to stand out.”"],["mirage","mih-RAHZH","noun","Something that seems real but is not there.","The puddle on the hot road was only a mirage.","From French mirer, “to look at.”"],["foible","FOY-buhl","noun","A small, harmless weakness or odd habit.","Dad's foible is humming while he reads.","From old French foible, “weak.”"],["incognito","in-kog-NEE-toh","adverb","In disguise, so no one knows who you are.","Dad went to the costume party incognito.","From Italian incognito, “unknown.”"],["vigilant","VIJ-uh-luhnt","adjective","Watchful and alert.","The vigilant lifeguard kept an eye on every swimmer.","From Latin vigilare, “to keep watch.”"],["topsy-turvy","top-see-TUR-vee","adjective","Upside down or in a happy mess.","The house was topsy-turvy after the birthday party.",""],["cogent","KOH-juhnt","adjective","Clear and convincing.","She made a cogent case for a bigger garden.",""],["allay","uh-LAY","verb","To calm or ease a fear or worry.","The nurse's kind smile allayed my little brother's fears.",""],["altruism","AL-troo-iz-uhm","noun","Caring about others and helping them without wanting a reward.","Her altruism showed when she gave her lunch to a hungry classmate.","From French altruisme, from Latin alter, “other.”"],["captivate","KAP-tuh-vayt","verb","To hold someone’s attention with charm or wonder.","The puppet show captivated every child in the room.","From Latin captivus, “taken captive.”"],["beacon","BEE-kuhn","noun","A light or signal that guides or warns; also a source of hope.","The porch light was a beacon on the dark road home.",""],["panoply","PAN-uh-plee","noun","A big, impressive collection.","The market had a panoply of fresh fruits.",""],["atrium","AY-tree-uhm","noun","A large open space inside a building, often with a glass roof.","Plants filled the sunny atrium of the library.","From Latin atrium, “an entrance hall.”"],["jest","JEST","noun","A joke.","He said it in jest, and we all laughed.",""],["omnibus","OM-nih-buhs","noun","A book or collection with many works in one.","I borrowed an omnibus of short mystery stories.","From Latin omnibus, “for all.”"],["amplify","AM-pluh-fy","verb","To make louder or stronger.","The microphone amplified her small voice.","From Latin amplus, “large.”"],["maudlin","MAWD-lin","adjective","Too sad or teary in a silly way.","The old movie got a bit maudlin at the end.",""],["accolade","AK-uh-layd","noun","An award or words of high praise.","The volunteer received many accolades for her years of service.",""],["autodidact","aw-toh-DY-dakt","noun","A person who has taught themselves.","An autodidact, she learned to code from library books.","From Greek autodidaktos, “self-taught.”"],["illuminate","ih-LOO-muh-nayt","verb","To light up, or to make clear.","Lanterns illuminated the garden path.","From Latin lumen, “light.”"],["sundry","SUN-dree","adjective","Of many different kinds.","The drawer held sundry buttons, pens and keys.",""],["asunder","uh-SUHN-der","adverb","Into pieces or apart.","The old fence was torn asunder by the storm.",""],["uproarious","uhp-ROR-ee-uhs","adjective","Very funny, or full of loud laughter.","The play was uproarious from start to finish.",""],["calibrate","KAL-uh-brayt","verb","To adjust something so it works or measures just right.","Dad calibrated the oven so the bread would bake evenly.",""],["affinity","uh-FIN-i-tee","noun","A natural liking for something or someone.","He has an affinity for old jazz records.",""],["biennial","by-EN-ee-uhl","adjective","Happening every two years.","The town holds a biennial art fair.","From Latin bi, “two,” and annus, “year.”"],["astray","uh-STRAY","adverb","Off the right path or away from the right way.","The letter went astray and arrived a week late.",""],["hanker","HANG-ker","verb","To have a strong wish for something.","I always hanker for soup on rainy days.",""],["mettle","MET-l","noun","Courage and strength to keep going.","The long hike tested our mettle.",""],["dander","DAN-der","noun","Temper, as in getting angry.","Don’t get your dander up over a little spilled milk.",""],["circadian","ser-KAY-dee-uhn","adjective","Following a daily 24-hour cycle.","Morning sunlight helps keep your circadian rhythm on track.","From Latin circa, “about,” and dies, “day.”"],["belfry","BEL-free","noun","A tower or room where bells hang.","Pigeons nested high in the old belfry.",""],["benchmark","BENCH-mark","noun","A standard used to measure or compare things.","His grandmother's pie is the benchmark for all other pies.",""],["ambrosia","am-BROH-zhuh","noun","Something that tastes or smells wonderful.","Fresh peaches in July are pure ambrosia.","From Greek ambrosia, “food of the gods.”"],["restive","RES-tiv","adjective","Restless and hard to keep still.","The audience grew restive as the speech went on.",""],["impromptu","im-PROMP-too","adjective","Done without planning.","We had an impromptu dance party in the living room.","From Latin in promptu, “in readiness.”"],["felicity","fi-LIS-i-tee","noun","Great happiness, or a well-chosen way of saying something.","The family lived in quiet felicity by the lake.","From Latin felix, “happy.”"],["witticism","WIT-uh-siz-uhm","noun","A clever, funny remark.","His witticisms made the long car ride fly by.",""],["oasis","oh-AY-sis","noun","A green spot with water in a desert, or any peaceful place.","The little park is an oasis in the busy city.","From Greek oasis."],["beeline","BEE-lyn","noun","A straight, quick path to somewhere.","The kids made a beeline for the snack table.",""],["brisk","BRISK","adjective","Quick and lively; also cool and fresh.","We took a brisk walk in the autumn air.",""],["attire","uh-TYR","noun","Clothes, especially for a special event.","The invitation asked for festive attire.",""],["palatable","PAL-uh-tuh-buhl","adjective","Pleasant enough to taste or to accept.","Adding honey made the medicine palatable.",""],["zephyr","ZEF-er","noun","A soft, gentle breeze.","A cool zephyr drifted through the open window.","From Greek zephyros, “the west wind.”"],["travesty","TRAV-uh-stee","noun","A silly or shocking copy that misses the point.","Pineapple on that fancy cake was a travesty, Grandpa joked.",""],["deprecate","DEP-ri-kayt","verb","To express disapproval of something.","He deprecated his own cooking, but it was great.",""],["almanac","AWL-muh-nak","noun","A yearly book of facts, weather and calendars.","Grandpa checks the almanac before he plants his tomatoes.",""],["commodious","kuh-MOH-dee-uhs","adjective","Roomy and comfortable.","The cabin was commodious enough for all ten cousins.","From Latin commodus, “convenient.”"],["neologism","nee-OL-uh-jiz-uhm","noun","A brand new word or phrase.","Every year brings a few fun neologisms into the dictionary.","From Greek neos, “new,” and logos, “word.”"],["curtail","ker-TAYL","verb","To cut short or reduce.","Rain curtailed our trip to the beach.",""],["acoustic","uh-KOO-stik","adjective","Having to do with sound, or played without electric power.","He played a soft song on his acoustic guitar.","From Greek akouein, “to hear.”"],["backwater","BAK-waw-ter","noun","A quiet place where little changes or happens.","The village was a sleepy backwater until the new road came.",""],["ultimatum","uhl-tuh-MAY-tuhm","noun","A final demand, with a result if it is not met.","Mom gave an ultimatum: clean your room or no park.",""],["dynamic","dy-NAM-ik","adjective","Full of energy and change.","The dynamic teacher kept every class exciting.","From Greek dynamis, “power.”"],["onerous","ON-er-uhs","adjective","Heavy, hard and tiring to do.","Moving the piano was an onerous task.","From Latin onus, “burden.”"],["aplomb","uh-PLOM","noun","Calm confidence, especially in a hard moment.","She handled the broken microphone with great aplomb.","From French à plomb, “straight down, like a plumb line.”"],["decipher","dih-SY-fer","verb","To figure out the meaning of something hard to read.","Can you decipher Grandma’s old handwriting?",""],["ovation","oh-VAY-shuhn","noun","Loud, long clapping to show praise.","The choir got a standing ovation.","From Latin ovare, “to rejoice.”"],["culpable","KUHL-puh-buhl","adjective","Deserving blame.","The cat was clearly culpable for the broken vase.","From Latin culpa, “fault.”"],["allegory","AL-uh-gor-ee","noun","A story with a hidden meaning or lesson.","The tale of the tortoise and the hare is an allegory about patience.","From Greek allegoria, “speaking otherwise.”"],["pensive","PEN-siv","adjective","Quietly deep in thought.","He sat pensive by the window, watching the snow.","From French penser, “to think.”"],["flâneur","flah-NUR","noun","Someone who strolls around a city just to enjoy it.","On Sundays I play the flâneur, wandering the old streets.","From French flâner, “to stroll.”"],["grotto","GROT-oh","noun","A small cave, often a pretty one.","We found a grotto behind the waterfall.","From Italian grotta, “cave.”"],["brash","BRASH","adjective","Bold and loud in a way that can seem rude.","The brash young rooster crowed at everyone.",""],["truism","TROO-iz-uhm","noun","A statement so obviously true it hardly needs saying.","It’s a truism that kids grow up fast.",""],["liminal","LIM-uh-nuhl","adjective","In between two stages or places.","Dawn is a liminal time, not quite night or day.","From Latin limen, “threshold.”"],["nondescript","non-dih-SKRIPT","adjective","Plain and hard to describe.","The best tacos came from a nondescript little shop.",""],["lilt","LILT","noun","A light, happy rise and fall in a voice or song.","Her voice had a gentle lilt.",""],["vindicate","VIN-di-kayt","verb","To show that someone was right after all.","The sunny weather vindicated our choice to picnic.","From Latin vindicare, “to claim, set free.”"],["precocious","prih-KOH-shuhs","adjective","Showing skills much earlier than usual.","The precocious girl was reading at age three.","From Latin praecox, “ripening early.”"],["indefatigable","in-di-FAT-i-guh-buhl","adjective","Never seeming to get tired.","Our indefatigable coach ran with us every lap.","From Latin indefatigabilis, “untiring.”"],["jaded","JAY-did","adjective","Tired and bored from having too much of something.","Even my jaded teenager loved the fireworks.",""],["hone","HOHN","verb","To sharpen or improve a skill.","She honed her piano skills every evening.",""],["dappled","DAP-uhld","adjective","Marked with spots of light and shade or color.","We picnicked in the dappled shade of an oak.",""],["unabashed","uhn-uh-BASHT","adjective","Not embarrassed or shy at all.","She sang along with unabashed joy.",""],["alabaster","AL-uh-bas-ter","noun","A smooth white stone; also used to mean very pale and smooth.","A small alabaster vase sat on the windowsill.",""],["append","uh-PEND","verb","To add something to the end.","She appended a smiley face to her note.","From Latin appendere, “to hang on.”"],["cardinal","KAR-dn-l","adjective","Most important; main.","The cardinal rule at the pool is no running.","From Latin cardo, “hinge.”"],["afoot","uh-FOOT","adjective","Happening or being planned, often secretly.","The giggling in the next room told me a surprise was afoot.",""],["ingrained","in-GRAYND","adjective","Deeply fixed and hard to change.","Saying please is ingrained in our family.",""],["diorama","dy-uh-RAM-uh","noun","A small 3D model of a scene.","He built a diorama of a rainforest in a shoebox.",""],["bandy","BAN-dee","verb","To toss words or ideas back and forth.","We bandied about names for the new puppy.",""],["aesthetic","es-THET-ik","adjective","Having to do with beauty and what looks pleasing.","She chose the blue curtains for aesthetic reasons.","From Greek aisthetikos, “of the senses.”"],["kiln","KILN","noun","A very hot oven for baking clay or pottery.","Our clay pots came out of the kiln shiny and hard.","From Latin culina, “kitchen.”"],["manifold","MAN-uh-fohld","adjective","Many and of different kinds.","The joys of having a garden are manifold.",""],["snazzy","SNAZ-ee","adjective","Stylish and eye-catching.","He wore snazzy red sneakers to the dance.",""],["charlatan","SHAR-luh-tuhn","noun","A person who falsely claims to have special skills.","The so-called wizard at the fair was a charming charlatan.",""],["prosaic","proh-ZAY-ik","adjective","Plain and lacking excitement.","He gave the prosaic answer that he ate toast.","From Latin prosa, “prose.”"],["jaunt","JAWNT","noun","A short trip for fun.","We took a jaunt to the beach on Saturday.",""],["kindred","KIN-drid","adjective","Similar or closely related.","The two friends were kindred spirits.",""],["blissful","BLIS-fuhl","adjective","Full of great joy and calm.","We spent a blissful afternoon by the lake.",""],["smattering","SMAT-er-ing","noun","A small amount of something.","She speaks a smattering of French.",""],["penultimate","pih-NUL-tuh-mit","adjective","Second to last.","The penultimate chapter is my favorite.","From Latin paene, “almost,” and ultimus, “last.”"],["obsidian","uhb-SID-ee-uhn","noun","A shiny black glass made by volcanoes.","The museum had a smooth piece of obsidian you could touch.",""],["paragon","PAIR-uh-gon","noun","A perfect example of something.","Our coach is a paragon of patience.",""],["vivacious","vi-VAY-shuhs","adjective","Lively and full of fun.","Our vivacious neighbor always has a funny story.","From Latin vivax, “lively.”"],["droll","DROHL","adjective","Funny in an odd or dry way.","Her droll remarks kept the dinner lively.","From French drôle, “funny.”"],["hibernate","HY-ber-nayt","verb","To spend the winter in a deep sleep.","Bears hibernate in snug dens.","From Latin hibernare, “to spend the winter.”"],["rebuke","ri-BYOOK","verb","To scold someone sharply.","The coach gently rebuked the players for being late.",""],["partake","par-TAYK","verb","To join in or take a share.","Everyone partook of the birthday cake.",""],["obsolete","ob-suh-LEET","adjective","No longer used because something newer came along.","Our old cassette player is obsolete, but we still love it.","From Latin obsolescere, “to grow old.”"],["bumptious","BUHMP-shuhs","adjective","Too sure of yourself in an annoying way.","The bumptious new player told the coach how to run practice.",""],["disconcert","dis-kuhn-SURT","verb","To unsettle or confuse someone.","The sudden silence disconcerted the speaker.",""],["incisive","in-SY-siv","adjective","Sharp and clear in thinking.","Her incisive question got right to the point.","From Latin incidere, “to cut into.”"],["knickknack","NIK-nak","noun","A small decorative object.","Her shelves are full of knickknacks from her travels.",""],["stoic","STOH-ik","adjective","Calm and patient, not showing upset feelings.","She stayed stoic while the doctor gave her a shot.","From Greek stoa, “porch,” where early thinkers taught."],["incandescent","in-kuhn-DES-uhnt","adjective","Glowing with heat, or shining brightly.","Her incandescent smile lit up the room.","From Latin incandescere, “to glow.”"],["morsel","MOR-suhl","noun","A small bite of food.","The bird took a morsel of bread from her hand.","From Old French morsel, “little bite.”"],["endeavor","en-DEV-er","noun","A serious try at doing something.","Building the treehouse was a family endeavor.",""],["aloft","uh-LAWFT","adverb","Up in the air.","The kite stayed aloft all afternoon.",""],["kelp","KELP","noun","A large brown seaweed.","Otters wrap themselves in kelp to sleep.",""],["quench","KWENCH","verb","To end your thirst by drinking.","A cold glass of lemonade quenched my thirst after the hike.","From Old English cwencan, “to put out (a fire).”"],["vestige","VES-tij","noun","A small trace of something that is mostly gone.","A vestige of snow still lay in the shady corner.","From Latin vestigium, “footprint.”"],["boorish","BOOR-ish","adjective","Rude and rough in manners.","His boorish habit of talking with his mouth full annoyed everyone.",""],["fey","FAY","adjective","Strange and dreamy, with a touch of magic.","The fey little cottage looked like it came from a fairy tale.",""],["camaraderie","kah-muh-RAH-duh-ree","noun","A warm feeling of friendship among people in a group.","The team’s camaraderie made every practice fun.","From French camarade, “comrade.”"],["dissipate","DIS-uh-payt","verb","To fade away or scatter.","The morning fog dissipated by noon.",""],["pundit","PUN-dit","noun","An expert who gives opinions to the public.","The sports pundit guessed the winner correctly.","From Hindi pandit, “learned man.”"],["quixotic","kwik-SOT-ik","adjective","Full of big, noble dreams that are hard to make real.","His quixotic plan was to plant a tree in every yard in town.","From Don Quixote, the dreamy hero of a Spanish novel."],["incorrigible","in-KOR-i-juh-buhl","adjective","Not able to be changed or corrected.","Our incorrigible puppy still chews slippers.",""],["akin","uh-KIN","adjective","Similar to or like something.","Learning a new language is akin to learning a new song.",""],["platitude","PLAT-ih-tood","noun","A saying used so much it has lost its meaning.","“It is what it is” is a common platitude.","From French plat, “flat.”"],["oxymoron","ok-see-MOR-on","noun","Two words with opposite meanings used together, like jumbo shrimp.","“Pretty ugly” is a funny oxymoron.","From Greek oxys, “sharp,” and moros, “dull.”"],["aquamarine","ak-wuh-muh-REEN","noun","A light blue-green color, like clear sea water.","The bay sparkled aquamarine in the morning sun.","From Latin aqua marina, “sea water.”"],["variegated","VAIR-ee-uh-gay-tid","adjective","Having patches or streaks of different colors.","The variegated leaves were green and cream.","From Latin variegare, “to make varied.”"],["flair","FLAIR","noun","A natural talent or a stylish way of doing things.","He has a flair for telling jokes.",""],["rueful","ROO-fuhl","adjective","Showing a little regret, often with a gentle smile.","He gave a rueful grin after dropping the ice cream.",""],["insouciant","in-SOO-see-uhnt","adjective","Calm and carefree.","He gave an insouciant shrug and kept fishing.","From French insouciant, “not caring.”"],["poise","POYZ","noun","Calm and graceful control.","She spoke with poise in front of the whole school.",""],["bucolic","byoo-KOL-ik","adjective","Having to do with peaceful country life.","We rented a cabin in a bucolic valley full of cows.","From Greek boukolos, “a cowherd.”"],["symbiosis","sim-bee-OH-sis","noun","A partnership where both sides help each other.","Bees and flowers live in a lovely symbiosis.","From Greek symbiōsis, “living together.”"],["dignity","DIG-ni-tee","noun","A calm sense of self-respect.","She handled the loss with grace and dignity.","From Latin dignus, “worthy.”"],["dilettante","DIL-i-tahnt","noun","Someone who dabbles in an interest without going deep.","He’s a dilettante who has tried ten hobbies this year.","From Italian dilettare, “to delight.”"],["benighted","bih-NY-tid","adjective","Lacking knowledge or understanding.","He joked that he was benighted about anything to do with phones.",""],["crux","KRUHKS","noun","The most important part of a problem.","The crux of the matter is who will walk the dog.","From Latin crux, “cross.”"],["bellow","BEL-oh","verb","To shout in a deep, loud voice.","The coach bellowed instructions across the field.",""],["idyllic","eye-DIL-ik","adjective","Peaceful and perfect, like a pretty picture.","We spent an idyllic week in the mountains.","From Greek eidyllion, “little picture.”"],["cadence","KAY-duhns","noun","The rise and fall of a voice or the beat of a sound.","She loved the gentle cadence of her grandfather’s stories.","From Latin cadere, “to fall.”"],["ersatz","ER-zahts","adjective","Fake, used in place of the real thing.","The ersatz coffee tasted like burnt toast.","From German Ersatz, “replacement.”"],["ineffable","in-EF-uh-buhl","adjective","Too great or beautiful to put into words.","The view from the mountaintop was ineffable.","From Latin ineffabilis, “unutterable.”"],["murky","MUR-kee","adjective","Dark, cloudy or unclear.","We could not see the fish in the murky pond.",""],["memoir","MEM-wahr","noun","A true story someone writes about their own life.","Grandma is writing a memoir about growing up on a farm.","From French mémoire, “memory.”"],["aptitude","AP-ti-tood","noun","A natural ability to do or learn something.","He shows an aptitude for music.","From Latin aptus, “fitted.”"],["doggerel","DAW-ger-uhl","noun","Silly, clumsy verse.","He wrote doggerel for Mom’s birthday card.",""],["quip","KWIP","noun","A quick, clever, funny remark.","Dad made a quip about the rain that made everyone laugh.",""],["brackish","BRAK-ish","adjective","Slightly salty, like where a river meets the sea.","Crabs live in the brackish water of the marsh.",""],["oodles","OO-dlz","noun","A lot of something.","We have oodles of zucchini from the garden.",""],["conscientious","kon-shee-EN-shuhs","adjective","Careful to do things well and right.","A conscientious student, she checks every answer twice.",""],["chortle","CHOR-tl","verb","To laugh in a happy, breathy way.","Grandpa chortled at the baby’s silly faces.",""],["nostalgia","no-STAL-juh","noun","A warm longing for the past.","Old songs fill my mom with nostalgia.","From Greek nostos, “return home,” and algos, “pain.”"],["leitmotif","LYT-moh-teef","noun","A theme that keeps coming back.","Kindness is the leitmotif of all her stories.","From German Leitmotiv, “leading motive.”"],["extol","ik-STOHL","verb","To praise something highly.","She loves to extol the joys of gardening.","From Latin extollere, “to lift up.”"],["spindly","SPIND-lee","adjective","Long, thin and weak looking.","The newborn foal stood up on spindly legs.",""],["chutzpah","HOOT-spuh","noun","Bold nerve or daring.","It took chutzpah to ask the band to play her song.","From Yiddish khutspe, “boldness.”"],["thrifty","THRIF-tee","adjective","Careful with money and not wasteful.","My thrifty aunt turns old jars into flower vases.",""],["presage","PRES-ij","verb","To be a sign of something to come.","Dark clouds presaged a stormy night.",""],["nourish","NUR-ish","verb","To feed and help grow.","Good soup nourishes body and spirit.","From Latin nutrire, “to feed.”"],["contemplate","KON-tuhm-playt","verb","To think about something slowly and deeply.","She sat by the lake to contemplate her next step.",""],["ameliorate","uh-MEEL-yuh-rayt","verb","To make something bad better.","Planting trees helped ameliorate the heat on our street.","From Latin melior, “better.”"],["undaunted","uhn-DAWN-tid","adjective","Not scared off by difficulty.","Undaunted by the rain, we finished our hike.",""],["dissuade","dih-SWAYD","verb","To talk someone out of doing something.","We dissuaded him from swimming in the cold lake.","From Latin dissuadere, “to advise against.”"],["sesquipedalian","ses-kwi-puh-DAY-lee-uhn","adjective","Using very long words.","The professor’s sesquipedalian speech made us reach for a dictionary.","From Latin sesquipedalis, “a foot and a half long.”"],["accord","uh-KORD","noun","Agreement, or a deal that settles a disagreement.","The neighbors reached an accord about where to put the fence.",""],["yammer","YAM-er","verb","To talk loudly and on and on.","The kids yammered all the way home from camp.",""],["breakneck","BRAYK-nek","adjective","Very fast, often too fast.","The kids ran down the hill at breakneck speed.",""],["hyperbole","hy-PUR-buh-lee","noun","Big exaggeration, not meant to be taken literally.","“I've told you a million times” is a classic hyperbole.","From Greek hyperbole, “a throwing beyond.”"],["reconcile","REK-uhn-syl","verb","To become friends again after a fight.","The two sisters reconciled and shared a long hug.","From Latin reconciliare, “to bring together again.”"],["equanimity","ee-kwuh-NIM-i-tee","noun","Staying calm and steady, even when things go wrong.","She handled the flat tire with equanimity.","From Latin aequus, “even,” and animus, “mind.”"],["helix","HEE-liks","noun","A spiral shape, like a spring.","The vine grew in a neat helix around the pole.","From Greek helix, “spiral.”"],["tantalize","TAN-tl-yz","verb","To tease someone with something they want but cannot have yet.","The smell of baking bread tantalized us all afternoon.","From Tantalus, a figure in Greek myth who could never reach his food."],["succor","SUK-er","noun","Help and comfort in a hard time.","Neighbors brought succor to the family after the storm.","From Latin succurrere, “to run to help.”"],["dispense","dih-SPENS","verb","To hand out.","Grandpa dispenses advice along with candy.",""],["denote","dih-NOHT","verb","To be a sign of something.","A star on the map denotes our campsite.",""],["kerfuffle","ker-FUF-uhl","noun","A fuss or commotion.","There was a kerfuffle when the hamster escaped.",""],["evocative","ih-VOK-uh-tiv","adjective","Bringing strong memories or feelings to mind.","The smell of pine is evocative of winter holidays.","From Latin evocare, “to call out.”"],["dovetail","DUHV-tayl","verb","To fit together neatly.","Her plans dovetailed with ours perfectly.",""],["transcend","tran-SEND","verb","To go beyond the usual limits.","Music can transcend language and bring people together.","From Latin transcendere, “to climb over.”"],["vim","VIM","noun","Energy and enthusiasm.","She tackled the garden with vim and vigor.",""],["ornithology","or-nuh-THOL-uh-jee","noun","The study of birds.","Her love of ornithology began with a bird feeder.","From Greek ornis, “bird.”"],["baroque","buh-ROHK","adjective","Very fancy and full of decoration and detail.","The theater had baroque gold carvings on every wall.","From French baroque, “irregular in shape.”"],["wallflower","WAWL-flow-er","noun","A shy person who stays on the side at parties.","The wallflower turned out to be a wonderful dancer.",""],["cryptic","KRIP-tik","adjective","Mysterious and hard to understand.","Grandpa left a cryptic note about hidden treasure.","From Greek kryptos, “hidden.”"],["dally","DAL-ee","verb","To move slowly or waste time.","Don’t dally, or we’ll miss the start of the movie.",""],["orchard","OR-cherd","noun","A field of fruit trees.","We picked apples at the orchard on Saturday.",""],["axiom","AK-see-uhm","noun","A statement accepted as true without needing proof.","It is an axiom in our house that dessert comes after vegetables.","From Greek axioma, “something worthy.”"],["mesmerize","MEZ-muh-ryz","verb","To hold someone's full attention like a spell.","The dancing fire mesmerized the children.",""],["enamored","ih-NAM-erd","adjective","Filled with love or delight for something.","We were enamored with the little seaside town.","From Old French enamourer, “to fill with love.”"],["haughty","HAW-tee","adjective","Acting like you are better than others.","The haughty cat ignored everyone at the party.",""],["tendril","TEN-dril","noun","A thin, curling stem that a plant uses to climb.","The pea plant wrapped its tendrils around the fence.",""],["keel","KEEL","noun","The long beam along the bottom of a boat.","After the move, our family was back on an even keel.",""],["perplex","per-PLEKS","verb","To confuse or puzzle.","The new remote control perplexed Grandpa.",""],["lodestar","LOHD-star","noun","A star used to guide travelers, or a guiding idea.","Kindness is her lodestar.",""],["hoard","HORD","verb","To collect and hide away lots of something.","Squirrels hoard acorns for winter.",""],["umami","oo-MAH-mee","noun","A rich, savory taste, like in broth or mushrooms.","The soup had a deep umami flavor.","From Japanese umami, “delicious taste.”"],["connoisseur","kon-uh-SUR","noun","An expert who knows and enjoys fine things.","Grandma is a connoisseur of homemade jam.","From old French conoistre, “to know.”"],["intrinsic","in-TRIN-sik","adjective","Belonging to the basic nature of something.","Kindness is intrinsic to who she is.",""],["churlish","CHUR-lish","adjective","Rude and bad-mannered.","It would be churlish to refuse such a kind gift.",""],["quiescent","kwee-ES-uhnt","adjective","Quiet and still, at least for now.","The old volcano has been quiescent for hundreds of years.","From Latin quiescere, “to rest.”"],["crestfallen","KREST-faw-luhn","adjective","Sad and let down.","He was crestfallen when the rain canceled the game.",""],["alight","uh-LYT","verb","To land gently, or to step down from a vehicle.","A butterfly alighted on the rim of my glass.",""],["dulcet","DUHL-sit","adjective","Sweet and soothing to hear.","We woke to the dulcet sound of birdsong.","From Latin dulcis, “sweet.”"],["serrated","SER-ay-tid","adjective","Having a jagged edge like a saw.","Use the serrated knife to slice the bread.","From Latin serra, “saw.”"],["pinnacle","PIN-uh-kuhl","noun","The highest point.","Winning the spelling bee was the pinnacle of her year.",""],["timorous","TIM-er-uhs","adjective","Shy and easily frightened.","The timorous rabbit peeked out from under the bush.","From Latin timor, “fear.”"],["grueling","GROO-uh-ling","adjective","Very tiring and hard.","The hike up the hill was grueling but worth it.",""],["exemplary","ig-ZEM-pluh-ree","adjective","So good it is worth copying.","His exemplary manners impressed everyone at dinner.","From Latin exemplum, “example.”"],["blunder","BLUHN-der","noun","A careless, silly mistake.","Putting salt in the cake instead of sugar was quite a blunder.",""],["apocryphal","uh-POK-ruh-fuhl","adjective","Widely told but probably not true.","The story that the founder lived in a tree is likely apocryphal.",""],["marginalia","mar-juh-NAY-lee-uh","noun","Notes written in the edges of a book page.","I love reading the marginalia in old library books.","From Latin margo, “edge.”"],["unequivocal","uhn-i-KWIV-uh-kuhl","adjective","Totally clear, with no doubt.","Her answer was an unequivocal yes.",""],["raconteur","rak-on-TUR","noun","A person who tells stories in a lively, fun way.","Uncle Sam is a born raconteur at every family dinner.","From French raconter, “to tell.”"],["terse","TURS","adjective","Using few words, sometimes in a short, sharp way.","Her terse reply was simply, “Got it.”","From Latin tersus, “wiped clean.”"],["crepuscular","kri-PUHS-kyuh-ler","adjective","Having to do with twilight; active at dusk or dawn.","Rabbits are crepuscular, so we see them at sunset.","From Latin crepusculum, “twilight.”"],["staunch","STAWNCH","adjective","Loyal and firm in support.","She has always been my staunch friend.",""],["peripatetic","pair-uh-puh-TET-ik","adjective","Traveling from place to place.","The peripatetic musician played in a new town each week.","From Greek peripatein, “to walk around.”"],["equivocate","ih-KWIV-uh-kayt","verb","To answer in a vague way to avoid saying what you mean.","When asked who ate the cake, my brother began to equivocate.","From Latin aequus, “equal,” and vocare, “to call.”"],["condone","kuhn-DOHN","verb","To accept or allow behavior that is wrong.","Our family does not condone cheating at cards.",""],["revere","ri-VEER","verb","To deeply respect and admire someone.","The whole town revered the kind old doctor.","From Latin revereri, “to stand in awe of.”"],["levity","LEV-i-tee","noun","Light humor at a serious time.","His joke added some levity to the long meeting.","From Latin levis, “light.”"],["vouchsafe","vowch-SAYF","verb","To kindly give or grant something.","The shy cat finally vouchsafed a purr.",""],["magnanimous","mag-NAN-uh-muhs","adjective","Generous and kind, even to someone who has wronged you.","She was magnanimous and shared the prize with the runner-up.","From Latin magnus, “great,” and animus, “soul.”"],["doughty","DOU-tee","adjective","Brave and determined.","The doughty little tugboat pulled the big ship.",""],["wistful","WIST-fuhl","adjective","Gently sad and longing for something.","She looked at her old photos with a wistful smile.",""],["yen","YEN","noun","A strong wish or craving.","I have a sudden yen for chocolate chip cookies.",""],["squander","SKWON-der","verb","To waste something, like money or time.","Don’t squander a sunny day by staying inside.",""],["deplore","dih-PLOR","verb","To strongly dislike or disapprove of.","We deplore litter in the park.",""],["skittish","SKIT-ish","adjective","Easily scared or nervous.","The skittish horse jumped at every sound.",""],["opus","OH-puhs","noun","A piece of work, especially music.","The band called their new album their greatest opus.","From Latin opus, “work.”"],["linchpin","LINCH-pin","noun","The most important part that holds things together.","Our coach is the linchpin of the team.",""],["picayune","pik-ee-YOON","adjective","Small and not important.","Let's not argue about picayune details.",""],["jigsaw","JIG-saw","noun","A puzzle of pieces that fit together.","We spent the rainy day on a thousand-piece jigsaw.",""],["censure","SEN-sher","noun","Strong, formal disapproval.","The club’s censure reminded everyone to follow the rules.",""],["coherent","koh-HEER-uhnt","adjective","Clear and making sense as a whole.","After a good sleep, her thoughts were coherent again.","From Latin cohaerere, “to stick together.”"],["lyrical","LIR-i-kuhl","adjective","Expressing feeling in a beautiful, song-like way.","She wrote a lyrical letter about her garden.","From Greek lyra, “lyre.”"],["masquerade","mas-kuh-RAYD","noun","A party where people wear masks, or a false show.","The school held a masquerade with paper masks and music.",""],["lackadaisical","lak-uh-DAY-zi-kuhl","adjective","Lazy and without much care.","The cat took a lackadaisical stroll across the yard.",""],["desultory","DES-uhl-tor-ee","adjective","Aimless and jumping from one thing to another.","We had a desultory chat while waiting for the bus.","From Latin desultor, “a leaper.”"],["perturb","per-TURB","verb","To worry or upset someone.","The loud thunder did not perturb the sleeping baby.","From Latin perturbare, “to throw into confusion.”"],["officious","uh-FISH-uhs","adjective","Too eager to give orders or help when not wanted.","The officious guard told us where to stand three times.",""],["divvy","DIV-ee","verb","To share out among people.","Let’s divvy up the cookies fairly.",""],["bandwidth","BAND-width","noun","The time and energy someone has for a task.","I don't have the bandwidth to bake tonight, so let's buy bread.",""],["gauntlet","GAWNT-lit","noun","A challenge, or a heavy glove.","She threw down the gauntlet and challenged me to a race.",""],["aplenty","uh-PLEN-tee","adjective","In large amounts; more than enough.","There were snacks aplenty at the family reunion.",""],["rustic","RUS-tik","adjective","Simple and charming, like life in the country.","We ate at a rustic wooden table in the barn.","From Latin rusticus, “of the countryside.”"],["rambunctious","ram-BUNGK-shuhs","adjective","Wild, noisy and full of energy.","The rambunctious puppies tumbled all over the living room.",""],["garrulous","GAR-uh-luhs","adjective","Very talkative, often about small things.","The garrulous barber told us stories the whole time.","From Latin garrulus, “chattering.”"],["lambent","LAM-buhnt","adjective","Glowing softly or flickering.","Lambent candlelight filled the room.","From Latin lambere, “to lick.”"],["chagrin","shuh-GRIN","noun","Embarrassment from failing or being let down.","To his chagrin, the cake fell flat just as guests arrived.","From French chagrin, “sorrow.”"],["surreptitious","sur-uhp-TISH-uhs","adjective","Done secretly so no one notices.","He took a surreptitious bite of the frosting.",""],["ulterior","uhl-TEER-ee-er","adjective","Hidden on purpose, beyond what is shown.","His ulterior motive for helping was a slice of cake.","From Latin ulterior, “farther.”"],["vogue","VOHG","noun","What is popular or in fashion right now.","Board games are in vogue again.","From French vogue, “fashion.”"],["gumption","GUMP-shuhn","noun","Courage, common sense and get-up-and-go.","It took gumption to start her own bakery.",""],["yearn","YURN","verb","To want something very much, often with longing.","On cold days, I yearn for summer at the lake.","From Old English giernan, “to desire.”"],["debacle","day-BAH-kuhl","noun","A sudden, total failure.","The cake was a debacle, but we laughed and ate it anyway.","From French débâcler, “to unbar.”"],["blather","BLATH-er","verb","To talk on and on about silly things.","He blathered about his fantasy team all through dinner.",""],["moot","MOOT","adjective","No longer worth talking about, or open to debate.","The picnic question was moot once it began to rain.",""],["octogenarian","ok-tuh-juh-NAIR-ee-uhn","noun","A person in their eighties.","The octogenarian runner finished the race with a grin.","From Latin octogenarius, “of eighty.”"],["panache","puh-NASH","noun","Bold, stylish flair.","She served the pancakes with real panache.",""],["ancillary","AN-suh-ler-ee","adjective","Helping or supporting something more important.","The library has ancillary rooms for meetings and crafts.","From Latin ancilla, “a maidservant.”"],["palatial","puh-LAY-shuhl","adjective","Grand and large, like a palace.","The library has a palatial reading room.",""],["aphorism","AF-uh-riz-uhm","noun","A short, wise saying.","Her favorite aphorism is that slow and steady wins the race.","From Greek aphorismos, “a definition.”"],["brogue","BROHG","noun","A sturdy leather shoe with small holes in a pattern.","Dad polished his brown brogues for the wedding.",""],["gingerly","JIN-jer-lee","adverb","Very carefully and gently.","She gingerly picked up the baby bird.",""],["novel","NOV-uhl","adjective","New and different in an interesting way.","Using a sock as a puppet was a novel idea.","From Latin novus, “new.”"],["bedazzle","bih-DAZ-uhl","verb","To amaze someone with brightness or cleverness.","The fireworks bedazzled the crowd.",""],["credence","KREED-ns","noun","Belief that something is true.","Nobody gave credence to his tale of a talking parrot.","From Latin credere, “to believe.”"],["allude","uh-LOOD","verb","To mention something in an indirect way.","Dad alluded to a surprise but would not say more.","From Latin alludere, “to play with.”"],["oeuvre","OO-vruh","noun","All the works made by an artist or writer.","The museum showed her whole oeuvre, from sketches to murals.","From French oeuvre, “work.”"],["rancor","RANG-ker","noun","Bitter, lasting anger or ill will.","The two friends settled their quarrel without any rancor.","From Latin rancor, “rankness, a grudge.”"],["bumbling","BUHM-bling","adjective","Clumsy and confused in a likable way.","The bumbling detective in the film still solved the case.",""],["glimmer","GLIM-er","noun","A faint, wavering light.","We saw a glimmer of light from the cabin window.",""],["clandestine","klan-DES-tin","adjective","Done in secret.","The kids held a clandestine meeting to plan Mom’s party.","From Latin clandestinus, “secret.”"],["wunderkind","VOON-der-kint","noun","A young person who is amazingly talented.","The chess wunderkind beat players three times her age.","From German Wunderkind, “wonder child.”"],["comeuppance","kuhm-UHP-uhns","noun","A fair result someone gets for bad behavior.","The sneaky fox in the story got his comeuppance.",""],["comport","kuhm-PORT","verb","To behave in a certain way.","The children comported themselves well at the wedding.","From Latin comportare, “to carry together.”"],["knoll","NOHL","noun","A small, round hill.","We flew kites on the grassy knoll.",""],["craven","KRAY-vuhn","adjective","Lacking courage.","The craven villain ran away at the first sign of trouble.",""],["contemporary","kuhn-TEM-puh-rer-ee","adjective","Of the present time; modern.","The museum has a room of contemporary art.","From Latin tempus, “time.”"],["esoteric","es-uh-TER-ik","adjective","Understood by only a small group of people.","The club talked about esoteric rules of old card games.","From Greek esoterikos, “inner.”"],["junket","JUNG-kit","noun","A pleasure trip, often paid for by someone else.","The office junket took everyone to the coast.",""],["albeit","awl-BEE-it","adverb","Although; even though.","It was a good trip, albeit a short one.",""],["fortitude","FOR-ti-tood","noun","Courage and strength when things are hard.","She showed real fortitude while training for the long race.","From Latin fortis, “strong.”"],["jocund","JOK-uhnd","adjective","Cheerful and merry.","The jocund crowd sang along.","From Latin jucundus, “pleasant.”"],["clarion","KLAIR-ee-uhn","adjective","Loud and clear, like a call to act.","Her speech was a clarion call to help the shelter.",""],["hubbub","HUB-ub","noun","A loud, busy noise of many people.","The hubbub of the market woke us up.",""],["disdain","dis-DAYN","noun","A feeling that something is not worth respect.","The cat looked at its new food with disdain.",""],["gloaming","GLOH-ming","noun","The soft light of dusk.","Fireflies blinked in the gloaming.","From Old English glomung, “twilight.”"],["antithesis","an-TITH-uh-sis","noun","The exact opposite of something.","Her calm voice was the antithesis of his loud shouting.","From Greek antithesis, “a setting against.”"],["tenterhooks","TEN-ter-hooks","noun","A state of nervous waiting.","We were on tenterhooks waiting for the puppy to be born.",""],["juncture","JUNGK-cher","noun","A key point in time.","At this juncture, we should decide where to eat.","From Latin junctura, “a joining.”"],["aviary","AY-vee-er-ee","noun","A large cage or building for keeping birds.","The zoo's aviary was full of bright parrots.","From Latin avis, “bird.”"],["brawn","BRAWN","noun","Physical strength and muscle.","Moving the piano took brains and brawn.",""],["muddle","MUD-l","noun","A state of confusion or mess.","My notes were in a muddle before the test.",""],["proverbial","pruh-VUR-bee-uhl","adjective","Well known, as in a common saying.","We found the proverbial needle in a haystack.",""],["cyclical","SIK-li-kuhl","adjective","Happening in a repeating cycle.","The seasons are cyclical, and spring always returns.","From Greek kyklos, “circle.”"],["outwit","out-WIT","verb","To beat someone by being clever.","The fox outwitted the farmer's dog.",""],["transient","TRAN-shuhnt","adjective","Lasting only a short time.","The rainbow was transient, gone in a minute.","From Latin transire, “to go across.”"],["curate","KYOOR-ayt","verb","To carefully pick and arrange things to share.","She curated a playlist for the road trip.",""],["concur","kuhn-KUR","verb","To agree.","I concur that pancakes are the best breakfast.","From Latin concurrere, “to run together.”"],["staccato","stuh-KAH-toh","adjective","Made of short, sharp, separate sounds.","The rain made staccato taps on the tin roof.","From Italian staccato, “detached.”"],["abridge","uh-BRIJ","verb","To make a book or speech shorter while keeping its main ideas.","The teacher read us an abridged version of the long novel.",""],["hoopla","HOOP-lah","noun","Excited fuss or noise.","After all the hoopla, the parade was short and sweet.",""],["nimble","NIM-buhl","adjective","Quick and light in moving or thinking.","The nimble squirrel leaped from branch to branch.",""],["timbre","TAM-ber","noun","The special quality of a sound or voice.","I love the warm timbre of my grandmother’s voice.","From French timbre, “bell, tone.”"],["caricature","KAR-i-kuh-cher","noun","A funny drawing that stretches someone’s features.","The artist drew a caricature of Dad with a giant smile.","From Italian caricare, “to load, exaggerate.”"],["array","uh-RAY","noun","A large, orderly group or display of things.","The bakery had a dazzling array of cakes.",""],["propensity","pruh-PEN-sih-tee","noun","A natural habit or tendency.","My brother has a propensity for losing his keys.",""],["swashbuckling","SWOSH-buk-ling","adjective","Bold and adventurous, like a movie hero.","We read a swashbuckling tale about pirates at sea.",""],["ebullient","ih-BUL-yuhnt","adjective","Full of cheer and bubbly energy.","Our ebullient neighbor waves at every car that passes.","From Latin ebullire, “to boil over.”"],["niche","NICH","noun","A spot or role that suits you perfectly.","She found her niche teaching art to kids.","From French niche."],["criterion","kry-TEER-ee-uhn","noun","A standard used to judge something.","Taste was the only criterion for the pie contest.","From Greek kriterion, “means of judging.”"],["capitulate","kuh-PICH-uh-layt","verb","To give in after holding out.","After an hour of pleading, Mom capitulated and let us stay up.",""],["muffle","MUF-uhl","verb","To make a sound softer.","The snow muffled every sound in the street.",""],["deflect","dih-FLEKT","verb","To turn something aside.","She deflected the compliment with a shy laugh.","From Latin flectere, “to bend.”"],["natty","NAT-ee","adjective","Neat and stylish in dress.","Grandpa looked natty in his bow tie.",""],["visceral","VIS-er-uhl","adjective","Felt deep in your gut, not just thought.","I had a visceral thrill on the roller coaster.","From Latin viscera, “inner organs.”"],["sprightly","SPRYT-lee","adjective","Lively and full of energy.","The sprightly old man walked five miles every day.",""],["auburn","AW-bern","adjective","Reddish-brown in color, usually of hair.","Her auburn hair shone in the autumn light.",""],["avow","uh-VOW","verb","To say something openly and boldly.","He avowed his love of pineapple on pizza.",""],["voracious","vaw-RAY-shuhs","adjective","Wanting a great amount of something.","She is a voracious reader who finishes a book a day.","From Latin vorare, “to swallow up.”"],["askew","uh-SKYOO","adjective","Not straight; tilted to one side.","The picture on the wall hung askew after the door slammed.",""],["dwindle","DWIN-dl","verb","To slowly get smaller.","Our supply of marshmallows dwindled by the campfire.",""],["exonerate","ig-ZON-uh-rayt","verb","To show that someone did nothing wrong.","The muddy paw prints exonerated my son, since the dog made the mess.","From Latin exonerare, “to unburden.”"],["provenance","PROV-uh-nuhns","noun","Where something came from.","The antique dealer told us the provenance of the clock.","From French provenir, “to come from.”"],["jamboree","jam-buh-REE","noun","A big, lively party or gathering.","The town held a summer jamboree with music and games.",""],["anew","uh-NOO","adverb","Again, in a new or fresh way.","After the rain, the garden seemed to bloom anew.",""],["dissemble","dih-SEM-buhl","verb","To hide your true feelings or reasons.","He dissembled, pretending he didn’t want the last slice.",""],["bewitch","bih-WICH","verb","To charm or delight someone very much.","The violin music bewitched the whole room.",""],["destiny","DES-tuh-nee","noun","What is meant to happen in the future.","She felt it was her destiny to become a teacher.",""],["butte","BYOOT","noun","A steep, flat-topped hill standing alone.","The sun set behind a red rock butte.","From French butte, “a mound.”"],["luster","LUS-ter","noun","A soft shine.","The pearl had a lovely luster.",""],["itinerant","eye-TIN-er-uhnt","adjective","Traveling from place to place.","An itinerant musician played at the market.","From Latin iter, “journey.”"],["kumquat","KUM-kwot","noun","A tiny orange fruit you eat with the skin on.","The kumquat was sweet outside and sour inside.","From Cantonese kam kwat, “golden orange.”"],["nebula","NEB-yuh-luh","noun","A huge cloud of gas and dust in space.","The telescope showed a glowing nebula far away.","From Latin nebula, “mist.”"],["agile","AJ-uhl","adjective","Able to move quickly and easily.","The agile squirrel leaped from branch to branch.","From Latin agilis, “nimble.”"],["reclusive","ri-KLOO-siv","adjective","Liking to live alone, away from other people.","The reclusive painter lived in a cabin deep in the woods.",""],["diminutive","dih-MIN-yuh-tiv","adjective","Very small.","A diminutive bird perched on the fence.",""],["oblong","OB-long","adjective","Longer than it is wide.","We bought an oblong table for family dinners.",""],["granular","GRAN-yuh-ler","adjective","Made of small grains, or very detailed.","The sand was granular and sparkly.","From Latin granum, “grain.”"],["opalescent","oh-puh-LES-uhnt","adjective","Shining with soft, shifting colors like an opal.","The inside of the shell was opalescent pink and blue.",""],["disgruntled","dis-GRUHN-tld","adjective","Annoyed and unhappy.","The disgruntled cat glared at the rain.",""],["splendor","SPLEN-der","noun","Great and shining beauty.","We gazed at the splendor of the fall leaves.","From Latin splendere, “to shine.”"],["obelisk","OB-uh-lisk","noun","A tall, thin stone pillar with a pointed top.","An old obelisk stands in the middle of the town square.","From Greek obeliskos, “small spit.”"],["omnivore","OM-nuh-vor","noun","An animal that eats both plants and meat.","Bears are omnivores that love berries and fish.","From Latin omnis, “all,” and vorare, “to eat.”"],["pastoral","PAS-ter-uhl","adjective","Having to do with peaceful country life.","The painting showed a pastoral scene with sheep and hills.","From Latin pastor, “shepherd.”"],["limerick","LIM-er-ik","noun","A funny five-line poem.","My son wrote a limerick about our cat.",""],["vaunted","VAWN-tid","adjective","Praised or boasted about a lot.","We finally tried the vaunted lemon pie, and it was great.",""],["erstwhile","ERST-wyl","adjective","Former; from an earlier time.","My erstwhile roommate is now my neighbor.",""],["debonair","deb-uh-NAIR","adjective","Charming, confident and well-dressed.","The debonair host greeted every guest by name.","From French de bon air, “of good manner.”"],["mull","MUHL","verb","To think about something slowly and carefully.","She mulled over the job offer for a week.",""],["idiom","ID-ee-uhm","noun","A phrase whose meaning is not clear from its words alone.","“Raining cats and dogs” is a funny idiom.","From Greek idioma, “a special phrasing.”"],["rapport","ra-POR","noun","A warm, easy connection between people.","The new teacher quickly built a rapport with her students.","From French rapporter, “to bring back.”"],["hullabaloo","hul-uh-buh-LOO","noun","A noisy fuss.","What is all this hullabaloo about a lost sock?",""],["contingency","kuhn-TIN-juhn-see","noun","Something that might happen and needs a backup plan.","We packed umbrellas as a contingency for rain.",""],["shimmer","SHIM-er","verb","To shine with a soft, wavering light.","The pond shimmered in the setting sun.",""],["arbitrary","AR-bi-trer-ee","adjective","Chosen by chance or whim, not for a good reason.","The order of the names was arbitrary.",""],["celerity","suh-LER-i-tee","noun","Swiftness; speed.","The waiter cleared the table with great celerity.","From Latin celer, “swift.”"],["ostensible","o-STEN-suh-buhl","adjective","Seeming true on the surface, but maybe not really.","The ostensible reason for the visit was to borrow sugar.","From Latin ostendere, “to show.”"],["juxtapose","JUK-stuh-pohz","verb","To place things side by side to compare them.","The photo juxtaposes a tiny kitten and a huge dog.","From Latin juxta, “next to.”"],["brainchild","BRAYN-chyld","noun","An idea or plan that someone thought up.","The community garden was my mom's brainchild.",""],["genteel","jen-TEEL","adjective","Polite and refined, sometimes a bit fussy.","We had a genteel tea party with tiny sandwiches.",""],["cerulean","suh-ROO-lee-uhn","adjective","Deep sky blue.","We swam in the cerulean water of the bay.","From Latin caeruleus, “sky blue.”"],["bewilder","bih-WIL-der","verb","To confuse someone completely.","The maze of hallways bewildered the new students.",""],["byword","BY-wurd","noun","A word or name that stands for a certain quality.","In our town, that bakery is a byword for good bread.",""],["conciliatory","kuhn-SIL-ee-uh-tor-ee","adjective","Meant to make peace or calm someone.","She made a conciliatory offer to split the chores.",""],["evanescent","ev-uh-NES-uhnt","adjective","Fading away quickly, like mist.","The evanescent scent of lilacs drifted by.","From Latin evanescere, “to vanish.”"],["benevolent","buh-NEV-uh-luhnt","adjective","Kind and wanting to do good.","The benevolent baker gave leftover bread to the shelter.","From Latin bene, “well,” and volens, “wishing.”"],["smorgasbord","SMOR-guhs-bord","noun","A big spread of many foods, or a wide mix of things.","The library has a smorgasbord of summer activities.","From Swedish smörgåsbord, “sandwich table.”"],["zeitgeist","TSYT-gyst","noun","The general mood and ideas of a time.","The song captured the hopeful zeitgeist of that summer.","From German Zeitgeist, “spirit of the time.”"],["ornery","OR-nuh-ree","adjective","Grumpy and hard to deal with.","The ornery goat butted the gate every morning.",""],["iconoclast","eye-KON-uh-klast","noun","A person who challenges popular ideas.","The young chef was an iconoclast who put fruit on pizza.","From Greek eikon, “image,” and klastes, “breaker.”"],["barnstorm","BARN-storm","verb","To travel from town to town giving shows or speeches.","The little circus barnstormed across the country each summer.",""],["gambit","GAM-bit","noun","A clever move made to gain an advantage.","Offering to wash the car was her gambit for a later bedtime.","From Italian gambetto, “a tripping up.”"],["circumvent","sur-kuhm-VENT","verb","To find a way around a problem.","We circumvented the traffic jam by taking the back roads.","From Latin circumvenire, “to come around.”"],["mottled","MOT-ld","adjective","Marked with spots or patches of color.","The mottled leaves glowed red and gold.",""],["brunt","BRUHNT","noun","The main force or worst part of something.","The front porch took the brunt of the storm.",""],["verisimilitude","ver-uh-si-MIL-i-tood","noun","The look or feel of being real or true.","The tiny model town had amazing verisimilitude.","From Latin verisimilis, “like the truth.”"],["nifty","NIF-tee","adjective","Clever and handy.","He showed me a nifty way to fold a map.",""],["revel","REV-uhl","verb","To enjoy something with great delight.","The children reveled in the first snow of winter.",""],["magpie","MAG-py","noun","A person who collects all sorts of small things.","My aunt is a magpie who saves every pretty button she finds.",""],["minutiae","mih-NOO-shee-ee","noun","Tiny, small details.","Dad loves the minutiae of planning a road trip.","From Latin minutia, “smallness.”"],["welkin","WEL-kin","noun","The sky, or the heavens above.","Their happy shouts made the welkin ring.","From Old English wolcen, “cloud.”"],["doleful","DOHL-fuhl","adjective","Sad and gloomy.","The puppy gave us a doleful look at the door.",""],["mitigate","MIT-uh-gayt","verb","To make something less bad.","Planting trees can mitigate the summer heat.","From Latin mitigare, “to soften.”"],["discourse","DIS-kors","noun","Serious talk or discussion.","The book club enjoys lively discourse each month.",""],["ambience","AM-bee-uhns","noun","The feeling or mood of a place.","The candles gave the room a warm ambience.",""],["bravado","bruh-VAH-doh","noun","A show of boldness to hide fear.","With a little bravado, he jumped into the cold lake.","From Spanish bravada, “a boast.”"],["shenanigans","shuh-NAN-i-guhnz","noun","Silly or mischievous tricks.","The cousins got up to shenanigans at the sleepover.",""],["devoid","dih-VOID","adjective","Completely without something.","The soup was devoid of salt.",""],["enthrall","en-THRAWL","verb","To hold someone's full attention with delight.","The magician enthralled the whole crowd.",""],["dicey","DY-see","adjective","Risky and uncertain.","Crossing the icy bridge looked dicey.",""],["scuttlebutt","SKUT-l-but","noun","Rumor or gossip.","The scuttlebutt was that a new park was coming.","From a sailors’ word for a water cask where crews swapped gossip."],["twaddle","TWOD-l","noun","Silly or foolish talk.","Grandpa said the rumor was pure twaddle.",""],["glower","GLOU-er","verb","To stare angrily.","The cat glowered at its empty food bowl.",""],["forage","FOR-ij","verb","To search for food or supplies.","We foraged for blackberries along the trail.",""],["hinterland","HIN-ter-land","noun","The quiet land far from towns or coasts.","They drove into the hinterland to see the stars.","From German Hinterland, “land behind.”"],["congenial","kuhn-JEEN-yuhl","adjective","Friendly and pleasant to be around.","Our congenial hosts made us feel at home.",""],["threadbare","THRED-bair","adjective","Worn so thin you can see the threads.","He still loves his threadbare old teddy bear.",""],["outskirts","OUT-skurts","noun","The outer edges of a town or city.","They live on the outskirts, near the farms.",""],["spate","SPAYT","noun","A sudden rush of many things at once.","We got a spate of birthday cards this week.",""],["cusp","KUHSP","noun","A point where one thing is about to change into another.","She is on the cusp of learning to ride a bike.","From Latin cuspis, “point.”"],["bricolage","bree-koh-LAHZH","noun","Something made from whatever odds and ends are at hand.","The birdhouse was a bricolage of old wood and bottle caps.","From French bricoler, “to tinker.”"],["coruscate","KOR-uh-skayt","verb","To sparkle and flash.","Sunlight coruscated on the rippling lake.","From Latin coruscare, “to glitter.”"],["simpatico","sim-PAH-ti-koh","adjective","Easy to get along with; on the same wavelength.","The two new neighbors were instantly simpatico.",""],["numismatist","noo-MIZ-muh-tist","noun","A person who studies or collects coins.","My uncle is a numismatist with coins from fifty countries.","From Greek nomisma, “coin.”"],["bailiwick","BAY-luh-wik","noun","A person's area of skill or interest.","Fixing computers is my brother's bailiwick.",""],["opaque","oh-PAYK","adjective","Not see-through, or hard to understand.","We hung opaque curtains to keep the room dark.","From Latin opacus, “shaded.”"],["dispassionate","dis-PASH-uh-nit","adjective","Calm and fair, not swayed by feelings.","A dispassionate judge picked the best pie.",""],["cobble","KOB-uhl","verb","To put something together quickly from what you have.","We cobbled together a fort from blankets and chairs.",""],["decorum","dih-KOR-uhm","noun","Proper and polite behavior.","The children showed great decorum at the concert.","From Latin decorus, “fitting.”"],["debut","day-BYOO","noun","A first public appearance.","Her piano debut was at the school concert.","From French début, “a beginning.”"],["obfuscate","OB-fuh-skayt","verb","To make something confusing on purpose.","Long words can obfuscate a simple idea.","From Latin obfuscare, “to darken.”"],["mellifluous","muh-LIF-loo-uhs","adjective","Sweet and smooth to hear.","The singer had a mellifluous voice that calmed the baby.","From Latin mel, “honey,” and fluere, “to flow.”"],["zeal","ZEEL","noun","Great energy and eagerness for something.","She cleaned the garage with surprising zeal.","From Greek zēlos, “eagerness.”"],["dither","DITH-er","verb","To be unable to make up your mind.","She dithered over which puppy to adopt.",""],["imbue","im-BYOO","verb","To fill with a feeling or quality.","Her stories are imbued with humor.",""],["kudos","KOO-dohs","noun","Praise for something done well.","Kudos to the cooks for a great dinner.","From Greek kydos, “glory.”"],["posterity","po-STAIR-ih-tee","noun","All the people who will live in the future.","We saved Grandma's recipes for posterity.","From Latin posterus, “coming after.”"],["nefarious","nih-FAIR-ee-uhs","adjective","Wicked or up to no good.","The cat had a nefarious plan to steal the fish.","From Latin nefas, “wrong.”"],["dexterity","dek-STER-i-tee","noun","Skill with the hands or the mind.","Knitting takes patience and dexterity.","From Latin dexter, “right-handed, skillful.”"],["betwixt","bih-TWIKST","adverb","An old word for between.","The cat sat betwixt the two sleeping dogs.",""],["quorum","KWOR-uhm","noun","The smallest number of members needed for a meeting to make decisions.","The book club had a quorum, so we picked next month’s book.","From Latin quorum, “of whom.”"],["monochrome","MON-uh-krohm","adjective","Using just one color or shades of one color.","She painted a monochrome picture in shades of blue.","From Greek monos, “one,” and khroma, “color.”"],["trite","TRYT","adjective","Used so often that it is dull.","The card had a trite message, but it was sweet.","From Latin tritus, “worn down.”"],["pare","PAIR","verb","To trim or cut away the outer part.","She pared the apple in one long curl.","From Latin parare, “to prepare.”"],["avant-garde","ah-vahnt-GARD","adjective","New, bold and ahead of its time, especially in art.","The museum showed avant-garde paintings that puzzled us.","From French avant-garde, “front guard.”"],["dusky","DUHS-kee","adjective","Dim, like the light at dusk.","We walked home under a dusky pink sky.",""],["bombast","BOM-bast","noun","Fancy, puffed-up talk with little meaning.","The speech was full of bombast but short on facts.",""],["plaudit","PLAW-dit","noun","Praise or applause.","The young chef earned plaudits for her soup.","From Latin plaudite, “applaud!”"],["offing","OF-ing","noun","The near future; if something is in the offing, it is coming soon.","With clouds rolling in, rain is in the offing.",""],["composure","kuhm-POH-zher","noun","A calm and steady state of mind.","She kept her composure when the lights went out.",""],["amity","AM-i-tee","noun","Friendship and good will between people or groups.","The two towns have lived in amity for a hundred years.",""],["empathy","EM-puh-thee","noun","The ability to feel and understand what someone else feels.","Her empathy made her a wonderful nurse.","From Greek em-, “in,” and pathos, “feeling.”"],["bashful","BASH-fuhl","adjective","Shy and easily embarrassed.","The bashful toddler hid behind his mom's legs.",""],["hearken","HAR-kuhn","verb","To listen, or to call back to an earlier time.","The old song hearkens back to my childhood.",""],["amalgam","uh-MAL-guhm","noun","A mix of different things blended together.","The band's music is an amalgam of folk and jazz.",""],["satiate","SAY-shee-ayt","verb","To fill up all the way, so you want no more.","The big holiday meal satiated everyone at the table.","From Latin satis, “enough.”"],["quintessential","kwin-tuh-SEN-shuhl","adjective","Being the perfect example of something.","Hot cocoa by the fire is the quintessential winter treat.","From Latin quinta essentia, “fifth essence.”"],["kitsch","KICH","noun","Showy, silly things that are fun because they are tacky.","Grandma's flamingo lamp is pure kitsch.","From German Kitsch."],["arbor","AR-ber","noun","A shady garden shelter with plants growing over it.","Roses climbed all over the arbor in the backyard.",""],["belated","bih-LAY-tid","adjective","Coming late.","I sent my friend a belated birthday card.",""],["anthology","an-THOL-uh-jee","noun","A collection of poems, stories or songs in one book.","We read a poem from an anthology of nature writing.","From Greek anthologia, “a gathering of flowers.”"],["maxim","MAK-sim","noun","A short saying that gives a rule for living.","Her favorite maxim is “measure twice, cut once.”","From Latin maxima, “greatest.”"],["permeate","PUR-mee-ayt","verb","To spread through every part.","The smell of fresh bread permeated the house.","From Latin permeare, “to pass through.”"],["sublime","suh-BLYM","adjective","So beautiful or great it fills you with wonder.","The sunset over the ocean was sublime.","From Latin sublimis, “lofty, raised up.”"],["abstruse","ab-STROOS","adjective","Hard to understand.","The instructions for the new printer were so abstruse that we gave up.","From Latin abstrusus, “hidden.”"],["attest","uh-TEST","verb","To show or prove that something is true.","Her medals attest to years of hard training.","From Latin testis, “a witness.”"],["sylvan","SIL-vuhn","adjective","Having to do with woods and forests.","We picnicked in a quiet sylvan glade.","From Latin silva, “forest.”"],["dire","DYR","adjective","Very serious or urgent.","We were in dire need of coffee.","From Latin dirus, “fearful.”"],["aver","uh-VUR","verb","To say firmly that something is true.","She avers that her soup is the best in town.",""],["nettle","NET-l","verb","To annoy or bother someone.","Loud chewing nettles my brother.",""],["foliage","FOH-lee-ij","noun","The leaves of plants or trees.","We drove north to see the autumn foliage.","From Latin folium, “leaf.”"],["apportion","uh-POR-shuhn","verb","To divide and share out.","Dad apportioned the chores fairly among us.",""],["lark","LARK","noun","Something done just for fun.","We drove to the beach at dawn, just for a lark.",""],["broach","BROHCH","verb","To bring up a subject for talking about.","She waited until dessert to broach the idea of a puppy.",""],["pastiche","pa-STEESH","noun","A work that copies or mixes styles from others.","The play was a pastiche of old fairy tales.","From Italian pasticcio, “a pie, a mix.”"],["jetsam","JET-suhm","noun","Things thrown off a ship that wash ashore.","We found a glass float among the jetsam on the beach.",""],["enclave","EN-klayv","noun","A small area that is different from the area around it.","The garden was a quiet enclave in the busy city.","From French enclaver, “to enclose.”"],["divulge","dih-VUHLJ","verb","To reveal a secret.","She refused to divulge the secret recipe.",""],["klutz","KLUTS","noun","A clumsy person.","I'm such a klutz, I tripped over my own shoes.","From Yiddish klots, “block of wood.”"],["euphony","YOO-fuh-nee","noun","A pleasing, sweet sound, especially of words.","I love the euphony of the word “willow.”","From Greek euphonia, “good sound.”"],["contiguous","kuhn-TIG-yoo-uhs","adjective","Touching or sharing a border.","Our two gardens are contiguous, so we share tomatoes.",""],["denounce","dih-NOUNS","verb","To publicly say something is wrong.","The neighbors denounced the plan to cut down the old trees.",""],["colloquial","kuh-LOH-kwee-uhl","adjective","Used in everyday talk, not formal writing.","“Gonna” is a colloquial way of saying “going to.”","From Latin colloquium, “conversation.”"],["obtuse","uhb-TOOS","adjective","Slow to understand, or an angle wider than a right angle.","I was a bit obtuse and missed the joke at first.","From Latin obtusus, “blunt.”"],["dismay","dis-MAY","noun","Sudden worry or disappointment.","To our dismay, the store was closed.",""],["reverie","REV-uh-ree","noun","A pleasant daydream.","The ringing phone broke her happy reverie.","From French rêverie, “daydreaming.”"],["svelte","SVELT","adjective","Slim and graceful.","The svelte cat slipped easily through the fence.","From Italian svelto, “slender, quick.”"],["quibble","KWIB-uhl","verb","To argue about a tiny, unimportant detail.","Let’s not quibble over who gets the bigger slice.",""],["beset","bih-SET","verb","To trouble from all sides.","The trip was beset by flat tires and rain.",""],["dumbfound","duhm-FOUND","verb","To shock and amaze someone so they can’t speak.","The magic trick dumbfounded the whole class.",""],["dystopia","dis-TOH-pee-uh","noun","An imagined world where life is very bad.","The novel is set in a gloomy dystopia.",""],["nemesis","NEM-uh-sis","noun","A rival or enemy you cannot seem to beat.","The crossword puzzle on Sundays is my nemesis.",""],["meager","MEE-ger","adjective","Small and not enough.","Our garden gave a meager crop of three tomatoes.",""],["compunction","kuhm-PUNGK-shuhn","noun","A small feeling of guilt about doing something.","She had no compunction about taking a nap.","From Latin compungere, “to prick sharply.”"],["prattle","PRAT-l","verb","To talk on and on about silly things.","The toddler prattled happily in the back seat.",""],["galvanize","GAL-vuh-nyz","verb","To shock or excite someone into action.","The storm galvanized the neighbors to help each other.",""],["dowdy","DOU-dee","adjective","Plain and out of style.","She turned a dowdy old coat into something chic.",""],["jabber","JAB-er","verb","To talk fast in a way that is hard to follow.","The kids jabbered excitedly about the zoo.",""],["insipid","in-SIP-id","adjective","Dull and without flavor.","The soup was insipid until we added salt.","From Latin insipidus, “tasteless.”"],["sophistry","SOF-uh-stree","noun","Clever-sounding arguments that are really false.","Don’t be fooled by sophistry; ask for the facts.",""],["hiatus","hy-AY-tuhs","noun","A break or pause.","The band took a hiatus for the summer.","From Latin hiatus, “an opening.”"],["bamboozle","bam-BOO-zuhl","verb","To trick or fool someone.","My little sister bamboozled me into doing her chores.",""],["nonplussed","non-PLUST","adjective","So surprised you don't know what to say.","He was nonplussed when the parrot said his name.","From Latin non plus, “no more.”"],["spry","SPRY","adjective","Lively and active, especially for an older person.","At ninety, Grandma is still spry enough to dance.",""],["zigzag","ZIG-zag","verb","To move in a line with sharp turns from side to side.","The rabbit zigzagged across the field.",""],["augur","AW-ger","verb","To be a sign of what will happen.","Blue skies augur well for our picnic.","From Latin augur, a Roman reader of signs."],["sedulous","SEJ-uh-luhs","adjective","Hard-working and careful over a long time.","The sedulous gardener pulled weeds every single morning.","From Latin sedulus, “busy, careful.”"],["dispel","dih-SPEL","verb","To make a worry or idea go away.","Her smile dispelled all my nerves.","From Latin dispellere, “to drive apart.”"],["purloin","per-LOYN","verb","To take something that isn't yours, often sneakily.","The dog purloined a sock from the laundry.",""],["mosaic","moh-ZAY-ik","noun","A picture made of many small pieces.","The children made a mosaic from broken tiles.",""],["alfresco","al-FRES-koh","adverb","Outdoors, especially when eating.","On warm nights we like to eat alfresco in the backyard.","From Italian al fresco, “in the fresh air.”"],["ubiquitous","yoo-BIK-wi-tuhs","adjective","Found everywhere.","In spring, dandelions are ubiquitous in our yard.","From Latin ubique, “everywhere.”"],["whippersnapper","WIP-er-snap-er","noun","A young person who acts too bold or sure of themselves.","“Listen here, you little whippersnapper,” Grandpa teased.",""],["zany","ZAY-nee","adjective","Wildly silly and funny.","Our zany uncle wore a chicken hat to the picnic.","From Italian zanni, a clown in old comic plays."],["outlandish","out-LAN-dish","adjective","Very strange or unusual.","He wore an outlandish hat with feathers and bells.",""],["succinct","suhk-SINGKT","adjective","Short and clear, with no extra words.","Her succinct note said just, “Back at five. Love you.”","From Latin succinctus, “tucked up.”"],["lollygag","LOL-ee-gag","verb","To waste time doing nothing much.","Stop lollygagging and put on your shoes!",""],["resilient","ri-ZIL-yuhnt","adjective","Able to bounce back after something hard.","Kids are resilient and often adjust fast to a new school.","From Latin resilire, “to leap back.”"],["bask","BASK","verb","To lie in and enjoy warmth or attention.","The lizard basked on a sunny rock.",""],["gibberish","JIB-er-ish","noun","Speech or writing that makes no sense.","The baby babbled happy gibberish.",""],["plummet","PLUM-it","verb","To fall fast and far.","The temperature plummeted after sunset.",""],["badger","BAJ-er","verb","To keep asking someone again and again.","The kids badgered Dad to take them to the pool.",""],["gist","JIST","noun","The main point of something.","I missed the start, but I got the gist of the movie.",""],["cranny","KRAN-ee","noun","A small, narrow opening or corner.","We searched every nook and cranny for the lost ring.",""],["vex","VEKS","verb","To annoy or puzzle someone.","The missing sock vexed me all morning.","From Latin vexare, “to shake, disturb.”"],["rapacious","ruh-PAY-shuhs","adjective","Greedy and grabbing for more and more.","The rapacious seagulls snatched every last fry.","From Latin rapax, “grasping.”"],["ember","EM-ber","noun","A small glowing piece of wood or coal in a dying fire.","We roasted marshmallows over the last embers.",""],["yeoman","YOH-muhn","adjective","Steady, hard-working and useful.","She did yeoman work organizing the school fair.",""],["liaison","lee-AY-zon","noun","A person who links two groups.","She acts as liaison between the parents and the school.","From French liaison, “a binding.”"],["nuance","NOO-ahns","noun","A small, fine difference in meaning or feeling.","Good actors show every nuance of a feeling.","From French nuance, “shade of color.”"],["tapestry","TAP-uh-stree","noun","A heavy cloth with pictures woven in, or a rich mix of things.","Our town is a tapestry of many cultures and foods.",""],["beckon","BEK-uhn","verb","To signal someone to come closer.","Grandma beckoned us into the warm kitchen.",""],["thrum","THRUM","verb","To make a steady humming or strumming sound.","Rain thrummed on the tent all night.",""],["veracity","vuh-RAS-i-tee","noun","Truthfulness.","No one doubted the veracity of Grandma’s fish story.","From Latin verax, “truthful.”"],["lore","LOR","noun","Stories and knowledge passed down over time.","Grandpa knows all the local fishing lore.",""],["ken","KEN","noun","The range of what someone knows.","Fixing cars is beyond my ken.",""],["coddle","KOD-l","verb","To treat someone too gently or protect them too much.","Grandma coddles the dog with treats all day.",""],["migratory","MY-gruh-tor-ee","adjective","Moving from place to place with the seasons.","Migratory geese fly over our house each fall.","From Latin migrare, “to move.”"],["prescient","PRESH-uhnt","adjective","Seeming to know what will happen before it does.","Packing umbrellas turned out to be prescient.","From Latin praescire, “to know beforehand.”"],["moonlight","MOON-lyt","verb","To work a second job, often at night.","He moonlights as a piano teacher on weekends.",""],["temerity","tuh-MER-i-tee","noun","Bold daring that might be a bit too much.","The squirrel had the temerity to steal from our picnic.","From Latin temere, “rashly.”"],["abyss","uh-BIS","noun","A very deep hole or gap that seems to have no bottom.","We peered over the rail into the dark abyss of the canyon.","From Greek abyssos, “bottomless.”"],["vapid","VAP-id","adjective","Dull and lacking in interest or ideas.","The movie was pretty but vapid.","From Latin vapidus, “flat, gone stale.”"],["parlance","PAR-luhns","noun","A way of speaking used by a certain group.","In sailing parlance, the left side is “port.”","From French parler, “to speak.”"],["sagacious","suh-GAY-shuhs","adjective","Wise and good at judging things.","The sagacious old farmer could tell when rain was coming.","From Latin sagax, “of keen sense.”"],["malaise","ma-LAYZ","noun","A vague feeling that something is not quite right.","A gray week left the whole office with a mild malaise.","From French malaise, “ill ease.”"],["obstreperous","uhb-STREP-er-uhs","adjective","Noisy and hard to control.","The obstreperous puppies tumbled across the yard.","From Latin obstrepere, “to make noise against.”"],["anomaly","uh-NOM-uh-lee","noun","Something that is different from what is normal or expected.","A warm day in January is an anomaly here.","From Greek anomalia, “unevenness.”"],["relinquish","ri-LING-kwish","verb","To let go of something or give it up.","The cat finally relinquished the sunny spot on the couch.","From Latin relinquere, “to leave behind.”"],["expedite","EK-spi-dyt","verb","To make something happen faster.","We paid extra to expedite the gift's delivery.","From Latin expedire, “to free the feet.”"],["trinket","TRING-kit","noun","A small, cheap ornament or toy.","Her shelf was full of trinkets from family trips.",""],["vortex","VOR-teks","noun","A whirling mass of water or air.","The draining bathwater made a little vortex.","From Latin vortex, “whirlpool.”"],["legerdemain","lej-er-duh-MAYN","noun","Clever tricks with the hands, like magic.","The magician's legerdemain amazed the kids.","From French léger de main, “light of hand.”"],["cultivate","KUHL-tuh-vayt","verb","To grow or develop something with care.","She cultivates both roses and friendships.",""],["credulous","KREJ-uh-luhs","adjective","Too quick to believe things.","The credulous boy believed the moon was made of cheese.","From Latin credere, “to believe.”"],["bistro","BEE-stroh","noun","A small, cozy restaurant.","We shared soup at a little bistro on the corner.","From French bistro."],["diverge","dih-VURJ","verb","To split off in different directions.","The path diverged at the old oak tree.",""],["beget","bih-GET","verb","To cause or bring about.","Kindness tends to beget more kindness.",""],["nascent","NAY-suhnt","adjective","Just starting to grow or form.","Their nascent garden has tiny green sprouts.","From Latin nasci, “to be born.”"],["arbiter","AR-bi-ter","noun","A person who settles arguments or decides what is right.","Grandma is the family arbiter when we can't agree on a game.","From Latin arbiter, “a judge.”"],["callow","KAL-oh","adjective","Young and not yet experienced.","The callow new player soon learned the rules of the game.","From Old English calu, “bald.”"],["encomium","en-KOH-mee-uhm","noun","A speech or piece of writing full of high praise.","At the party, her friends gave a warm encomium to her years of service.","From Greek enkomion, “praise.”"],["nonpareil","non-puh-REL","adjective","Having no equal; the very best.","Her apple pie is nonpareil.","From French non, “not,” and pareil, “equal.”"],["nonchalant","non-shuh-LAHNT","adjective","Calm and relaxed, not worried.","She was nonchalant about the spider on the wall.","From French nonchalant, “not caring.”"],["cadenza","kuh-DEN-zuh","noun","A showy solo part near the end of a piece of music.","The violinist dazzled us with her cadenza.","From Italian cadenza, “cadence.”"],["orchestrate","OR-kuh-strayt","verb","To plan and arrange the parts of something.","Mom orchestrated a surprise party without anyone guessing.",""],["volatile","VOL-uh-tl","adjective","Likely to change suddenly.","Spring weather here is volatile, so bring a coat.","From Latin volare, “to fly.”"],["besmirch","bih-SMURCH","verb","To harm someone's good name.","He would never besmirch his friend's good name.",""],["deadpan","DED-pan","adjective","Showing no feeling while being funny.","His deadpan jokes make everyone giggle.",""],["aspire","uh-SPYR","verb","To hope and work hard to reach a goal.","She aspires to be a pilot one day.","From Latin aspirare, “to breathe upon.”"],["overt","oh-VURT","adjective","Done openly, not hidden.","His overt joy at the news made us all smile.","From Old French overt, “open.”"],["contentment","kuhn-TENT-muhnt","noun","A calm feeling of being happy with what you have.","A warm bath and a good book bring pure contentment.",""],["perspicacious","pur-spih-KAY-shuhs","adjective","Able to see and understand things clearly.","The perspicacious detective noticed the muddy boots.","From Latin perspicax, “sharp-sighted.”"],["lissome","LIS-uhm","adjective","Slim and graceful.","The lissome dancer leapt across the stage.",""],["slapdash","SLAP-dash","adjective","Done quickly and carelessly.","His slapdash paint job left drips on the floor.",""],["elusive","ih-LOO-siv","adjective","Hard to find, catch or remember.","The elusive fox only came out at dusk.","From Latin eludere, “to escape by tricks.”"],["adversity","ad-VUR-suh-tee","noun","Hard times or bad luck.","The team showed courage in the face of adversity.",""],["conflagration","kon-fluh-GRAY-shuhn","noun","A very large fire.","The old film showed a conflagration in a forest far away.","From Latin conflagrare, “to burn up.”"],["sashay","sa-SHAY","verb","To walk in a showy, swinging way.","She sashayed across the room in her new dress.",""],["beseech","bih-SEECH","verb","To beg someone urgently.","I beseech you to try just one bite of my soup.",""],["testy","TES-tee","adjective","Easily annoyed.","He gets a bit testy before his morning coffee.",""],["reverberate","ri-VUR-buh-rayt","verb","To echo again and again.","Laughter reverberated through the big empty hall.","From Latin reverberare, “to beat back.”"],["stratagem","STRAT-uh-juhm","noun","A clever plan to get what you want.","Her stratagem to get the kids to bed was a bedtime story.",""],["lugubrious","luh-GOO-bree-uhs","adjective","Sad and gloomy, often too much so.","The basset hound has a lugubrious face.","From Latin lugere, “to mourn.”"],["serendipity","ser-uhn-DIP-i-tee","noun","Finding something good by happy accident.","By pure serendipity, we met our new best friends at the bus stop.","Coined in 1754 by the writer Horace Walpole, from a fairy tale."],["solace","SOL-is","noun","Comfort in a sad or hard time.","She found solace in long walks with her dog.","From Latin solacium, “comfort.”"],["blandishment","BLAN-dish-muhnt","noun","Sweet talk or flattery used to persuade.","No blandishments could get the cat off the warm laptop.",""],["predilection","pred-l-EK-shuhn","noun","A special liking for something.","He has a predilection for old jazz records.",""],["arduous","AR-joo-uhs","adjective","Very hard and tiring.","The climb was arduous, but the view was worth it.","From Latin arduus, “steep.”"],["fiasco","fee-AS-koh","noun","A total and often funny failure.","Our first try at pancakes was a sticky fiasco.","From Italian fiasco, “flask.”"],["oxbow","OKS-boh","noun","A U-shaped bend in a river.","We paddled our canoe around the oxbow.",""],["grandeur","GRAN-jer","noun","Great beauty and size that fills you with awe.","We stood quietly before the mountain's grandeur.","From French grand, “great.”"],["nugatory","NOO-guh-tor-ee","adjective","Of no value or importance.","The tiny scratch on the table is nugatory.","From Latin nugae, “trifles.”"],["rejuvenate","ri-JOO-vuh-nayt","verb","To make someone feel young and fresh again.","A week at the lake rejuvenated the whole family.","From Latin re-, “again,” and juvenis, “young.”"],["misnomer","mis-NOH-mer","noun","A name that does not fit the thing.","“Quick lunch” was a misnomer, since it took two hours.",""],["ethereal","ih-THEER-ee-uhl","adjective","Light, delicate and almost too lovely to be real.","Morning mist gave the garden an ethereal glow.","From Greek aither, “upper air.”"],["artifice","AR-tuh-fis","noun","Clever tricks or skill used to fool or impress.","The magician's artifice kept us guessing.",""],["blueprint","BLOO-print","noun","A detailed plan for building or doing something.","The garden plan was a blueprint for our summer project.",""],["petrichor","PET-rih-kor","noun","The lovely earthy smell after rain falls on dry ground.","We stepped outside to breathe in the petrichor.","From Greek petra, “stone.”"],["cartography","kar-TOG-ruh-fee","noun","The art and science of making maps.","His love of cartography began with treasure maps.","From French carte, “map,” and Greek graphein, “to write.”"],["nectar","NEK-ter","noun","The sweet liquid in flowers, or any delicious drink.","Bees sip nectar from the lavender.",""],["iota","eye-OH-tuh","noun","A very small amount.","There is not one iota of cake left.","From Greek iota, the smallest Greek letter."],["fecund","FEE-kuhnd","adjective","Able to produce a lot; very fruitful.","The fecund garden gave us more tomatoes than we could eat.","From Latin fecundus, “fruitful.”"],["bivouac","BIV-oo-ak","noun","A simple camp with little or no shelter.","The hikers made a bivouac under the stars.",""],["boon","BOON","noun","A helpful gift or blessing.","The new bike path has been a boon to our town.",""],["hardy","HAR-dee","adjective","Strong and able to survive hard conditions.","These hardy plants bloom even in the cold.",""],["osmosis","oz-MOH-sis","noun","Learning something slowly just by being around it.","He learned to cook by osmosis, watching his dad.",""],["incessant","in-SES-uhnt","adjective","Never stopping.","The incessant rain kept us inside all day.",""],["cache","KASH","noun","A hidden store of things.","The squirrel kept a cache of acorns under the porch.","From French cacher, “to hide.”"],["monsoon","mon-SOON","noun","A season of strong winds and heavy rain.","The monsoon brought cool air and green fields.",""],["cherish","CHER-ish","verb","To love and care for something deeply.","She cherishes the quilt her mother made.","From French cher, “dear.”"],["wonderment","WUHN-der-muhnt","noun","A feeling of happy amazement.","The toddler stared at the snow in wonderment.",""],["incipient","in-SIP-ee-uhnt","adjective","Just beginning.","We noticed an incipient friendship between the two puppies.","From Latin incipere, “to begin.”"],["copious","KOH-pee-uhs","adjective","In large amounts.","She took copious notes in her first art class.","From Latin copia, “plenty.”"],["whet","WET","verb","To sharpen, or to make someone more eager.","The smell of popcorn whetted our appetite for the movie.","From Old English hwettan, “to sharpen.”"],["betoken","bih-TOH-kuhn","verb","To be a sign of something.","Dark clouds betokened a storm.",""],["memento","muh-MEN-toh","noun","A small thing kept to help you remember.","She kept a seashell as a memento of the trip.","From Latin memento, “remember!”"],["ascetic","uh-SET-ik","adjective","Living very simply and giving up comforts.","He lives an ascetic life with very few belongings.","From Greek asketes, “one who trains.”"],["overture","OH-ver-cher","noun","The music at the start of a show, or a first friendly move.","The new neighbors made an overture with a plate of cookies.","From Old French overture, “opening.”"],["confidant","KON-fi-dant","noun","A trusted friend you share secrets with.","Her older sister is her closest confidant.",""],["concise","kuhn-SYS","adjective","Saying a lot in few words.","His concise note said just what we needed to know.","From Latin concidere, “to cut up.”"],["cosmopolitan","koz-muh-POL-i-tn","adjective","Familiar with many countries and cultures.","The city has a cosmopolitan mix of food and music.","From Greek kosmopolites, “citizen of the world.”"],["boreal","BOR-ee-uhl","adjective","Having to do with the cold north, or its forests.","Moose wander through the boreal forest.","From Greek Boreas, the north wind."],["superfluous","soo-PUR-floo-uhs","adjective","More than is needed; extra.","The extra sugar in the recipe was superfluous.","From Latin superfluere, “to overflow.”"],["cavalier","kav-uh-LEER","adjective","Careless about things that matter.","Don’t be cavalier about locking the front door.","From Italian cavaliere, “horseman.”"],["promenade","prom-uh-NAYD","noun","A slow walk for pleasure, or a path for one.","We took an evening promenade along the beach.","From French promener, “to take for a walk.”"],["concord","KON-kord","noun","Peace and agreement.","The neighbors lived in happy concord for years.","From Latin concors, “of one heart.”"],["bonanza","buh-NAN-zuh","noun","A sudden source of good luck or plenty.","The garage sale was a bonanza of old comic books.","From Spanish bonanza, “fair weather.”"],["bespectacled","bih-SPEK-tuh-kuhld","adjective","Wearing glasses.","A bespectacled owl looked out from the book cover.",""],["ephemeral","ih-FEM-er-uhl","adjective","Lasting only a very short time.","The rainbow was ephemeral, gone in a minute.","From Greek ephemeros, “lasting a day.”"],["yore","YOR","noun","Long ago; the old days.","Grandma told tales of the days of yore.","From Old English geāra, “long ago.”"],["mellow","MEL-oh","adjective","Soft, calm and relaxed.","The evening was mellow, with tea and slow music.",""],["bluster","BLUHS-ter","noun","Loud, boastful talk that means little; also strong gusty wind.","Behind all his bluster, he is a gentle soul.",""],["abiding","uh-BY-ding","adjective","Lasting a long time and not changing.","She has an abiding love of old maps.",""],["ascend","uh-SEND","verb","To go up or climb.","The balloon ascended slowly into the blue sky.","From Latin ascendere, “to climb up.”"],["crucible","KROO-suh-buhl","noun","A hard test that changes someone.","The tough season was a crucible that made the team strong.",""],["calamity","kuh-LAM-i-tee","noun","A great disaster or trouble.","Losing the cake on the way was a minor calamity.","From Latin calamitas, “disaster.”"],["onus","OH-nuhs","noun","A duty or responsibility.","The onus is on me to bring snacks this week.","From Latin onus, “burden.”"],["lurk","LURK","verb","To wait quietly, out of sight.","A frog lurked under the lily pad.",""],["nuzzle","NUZ-uhl","verb","To rub gently with the nose.","The pony nuzzled my hand looking for apples.",""],["perfunctory","per-FUNK-tuh-ree","adjective","Done quickly, just to get it over with.","He gave the dishes a perfunctory rinse.",""],["handiwork","HAN-dee-wurk","noun","Something made by a person's own hands.","The birdhouse is Grandpa's handiwork.",""],["pliable","PLY-uh-buhl","adjective","Easy to bend, or easy to influence.","Soak the willow sticks to make them pliable.",""],["mollify","MOL-uh-fy","verb","To calm someone who is upset.","A warm cookie mollified the tired toddler.","From Latin mollis, “soft.”"],["decant","dih-KANT","verb","To pour liquid gently from one container into another.","She decanted the lemonade into a glass pitcher.",""],["isthmus","IS-muhs","noun","A narrow strip of land joining two larger lands.","A road runs along the sandy isthmus.","From Greek isthmos, “neck.”"],["addendum","uh-DEN-duhm","noun","Something added to the end of a book or document.","The recipe had an addendum with tips for baking at high altitude.","From Latin addendum, “a thing to be added.”"],["solstice","SOL-stis","noun","The longest or shortest day of the year.","We watched the sunset on the summer solstice.","From Latin sol, “sun,” and sistere, “to stand still.”"],["vignette","vin-YET","noun","A short, vivid scene or story.","Her book is full of sweet vignettes about family life.","From French vignette, “little vine.”"],["quaff","KWAF","verb","To drink something in big, happy gulps.","After the soccer game, the kids quaffed cold water.",""],["versatile","VUR-suh-tl","adjective","Able to do many different things well.","A versatile cook, he can make soup, bread and pie.","From Latin versatilis, “turning easily.”"],["subterfuge","SUB-ter-fyooj","noun","A sneaky trick used to hide something.","We used a little subterfuge to plan Dad’s surprise party.",""],["haven","HAY-vuhn","noun","A safe, peaceful place.","The library is my haven on busy days.",""],["avarice","AV-er-is","noun","Too much desire for money or things.","In the fable, the king's avarice left him lonely.","From Latin avarus, “greedy.”"],["naive","nah-EEV","adjective","Trusting too easily because you lack experience.","I was naive to think the puppy would not chew my shoes.","From French naïf, “natural.”"],["civility","si-VIL-i-tee","noun","Polite and respectful behavior.","Even when they disagree, they speak with civility.",""],["bicker","BIK-er","verb","To argue about small things.","The twins bickered over who got the window seat.",""],["yawp","YAWP","noun","A loud, wild cry.","He let out a happy yawp when he jumped into the lake.",""],["pantomime","PAN-tuh-mym","noun","Acting out a story with only movements, no words.","The kids used pantomime to guess the animal.",""],["obstinate","OB-stuh-nit","adjective","Stubborn and not willing to change your mind.","The obstinate toddler wore rain boots on a sunny day.","From Latin obstinatus, “determined.”"],["dote","DOHT","verb","To show great love, often a lot.","Grandma dotes on her new grandson.",""],["upshot","UHP-shot","noun","The final result of something.","The upshot of our talk was a family game night every Friday.",""],["confluence","KON-floo-uhns","noun","A place where things flow or come together.","The town grew at the confluence of two rivers.","From Latin confluere, “to flow together.”"],["talisman","TAL-is-muhn","noun","An object believed to bring good luck.","Her grandfather’s old coin was her talisman on test days.",""],["absurd","ab-SURD","adjective","Silly in a way that makes no sense.","The idea of a cat driving a bus is absurd, but it made us laugh.","From Latin absurdus, “out of tune.”"],["mawkish","MAW-kish","adjective","Sweet and sad in a way that feels fake.","The card was a little mawkish, but it still made her smile.",""],["olfactory","ol-FAK-tuh-ree","adjective","Having to do with the sense of smell.","The bakery was an olfactory delight.","From Latin olfacere, “to smell.”"],["facile","FAS-uhl","adjective","Too simple; done easily but without much thought.","She gave a facile answer to a hard question.","From Latin facilis, “easy.”"],["redolent","RED-uh-luhnt","adjective","Full of a strong, pleasant smell, or bringing back memories.","The kitchen was redolent of cinnamon and fresh bread.","From Latin redolere, “to give off a smell.”"],["petulant","PECH-uh-luhnt","adjective","Cranky and sulky like a spoiled child.","The petulant puppy whined until it got a treat.",""],["effulgent","ih-FUL-juhnt","adjective","Shining brightly.","The effulgent sunset turned the lake gold.","From Latin effulgere, “to shine out.”"],["lexicon","LEK-si-kon","noun","All the words a person or group uses.","“Hygge” has entered our family lexicon.","From Greek lexikon, “of words.”"],["momentous","moh-MEN-tuhs","adjective","Very important.","Moving to a new country was a momentous choice.",""],["vitriol","VIT-ree-uhl","noun","Bitter, harsh words or feelings.","Let’s keep our debate kind and free of vitriol.",""],["portmanteau","port-MAN-toh","noun","A word made by blending two words, like brunch from breakfast and lunch.","“Smog” is a portmanteau of smoke and fog.","From French porter, “to carry,” and manteau, “cloak.”"],["afterglow","AF-ter-gloh","noun","The light in the sky after sunset, or a warm feeling after a happy event.","We sat in the afterglow of the birthday party, full and happy.",""],["corporeal","kor-POR-ee-uhl","adjective","Having a body you can touch; physical.","The ghost in the play had no corporeal form.","From Latin corpus, “body.”"],["ballad","BAL-uhd","noun","A song or poem that tells a story.","Grandpa sang an old ballad about a sailor.",""],["ensconce","en-SKONS","verb","To settle in a safe, cozy spot.","The kids were ensconced in blankets watching a movie.",""],["minimalism","MIN-uh-muh-liz-uhm","noun","A style that uses very few, simple things.","Her minimalism means one plant, one chair and lots of light.",""],["detritus","dih-TRY-tuhs","noun","Bits of waste or debris left behind.","We swept up the detritus after the party.",""],["anecdote","AN-ik-doht","noun","A short, interesting story about a real event.","Grandpa told a funny anecdote about his first car.","From Greek anekdota, “things unpublished.”"],["gargantuan","gar-GAN-choo-uhn","adjective","Huge.","He ate a gargantuan stack of pancakes.",""],["bespoke","bih-SPOHK","adjective","Made to order for one person.","He wore a bespoke suit to his daughter's wedding.",""],["otherworldly","uh-ther-WURLD-lee","adjective","Strange and dreamy, as if from another world.","The northern lights looked otherworldly.",""],["corroborate","kuh-ROB-uh-rayt","verb","To back up a story or idea with proof.","Her photos corroborated our tale of the giant fish.","From Latin robur, “strength.”"],["decibel","DES-uh-bel","noun","A unit for measuring how loud a sound is.","The cheering hit a very high decibel level.",""],["repartee","rep-er-TEE","noun","Quick, witty back-and-forth talk.","Their friendly repartee kept the whole table laughing.","From French repartie, “a quick reply.”"],["austere","aw-STEER","adjective","Very plain and simple, without comfort or decoration.","The cabin was austere, with just a bed and a stove.","From Greek austeros, “harsh.”"],["balmy","BAH-mee","adjective","Pleasantly warm and gentle, used for weather.","We sat outside on a balmy summer evening.",""],["alleviate","uh-LEE-vee-ayt","verb","To make something hard or painful easier to bear.","A cool cloth helped alleviate the summer heat.","From Latin levis, “light.”"],["deleterious","del-i-TEER-ee-uhs","adjective","Harmful.","Too much sugar can be deleterious to your teeth.","From Greek deleterios, “harmful.”"],["impish","IM-pish","adjective","Playfully naughty.","He gave an impish grin before the prank.",""],["dwell","DWEL","verb","To live somewhere, or to keep thinking about something.","Try not to dwell on small mistakes.",""],["tortuous","TOR-choo-uhs","adjective","Full of twists and turns.","We drove up a tortuous mountain road.","From Latin tortus, “twisted.”"],["berth","BURTH","noun","A place to sleep on a ship or train; also a safe distance.","We gave the grumpy goose a wide berth.",""],["quagmire","KWAG-myr","noun","A soggy bog, or a messy problem that is hard to get out of.","The garden turned into a quagmire after three days of rain.",""],["sardonic","sar-DON-ik","adjective","Dryly mocking, with a crooked kind of humor.","He gave a sardonic smile when the bus was late again.",""],["beleaguered","bih-LEE-gerd","adjective","Having lots of troubles or pressure.","The beleaguered waiter smiled through the busy lunch rush.",""],["glib","GLIB","adjective","Smooth and quick in speech, but not sincere.","His glib excuse did not fool his mom.",""],["egress","EE-gres","noun","A way out, or the act of going out.","The garden gate is our egress to the park.","From Latin egredi, “to go out.”"],["hoary","HOR-ee","adjective","Gray or white with age; very old.","A hoary old oak stood by the gate.",""],["acrid","AK-rid","adjective","Sharp and bitter to smell or taste.","The acrid smell of burnt toast filled the kitchen.","From Latin acer, “sharp.”"],["mainstay","MAYN-stay","noun","The main thing or person that holds something up.","Soup has been the mainstay of our winter dinners.",""],["origami","or-ih-GAH-mee","noun","The art of folding paper into shapes.","She made an origami crane for each guest.","From Japanese ori, “folding,” and kami, “paper.”"],["tarry","TAIR-ee","verb","To stay longer than planned, or to be slow to leave.","We tarried at the beach until the sun went down.",""],["barren","BAIR-uhn","adjective","Bare and empty, unable to grow plants.","The barren hillside turned green after the spring rains.",""],["dollop","DOL-uhp","noun","A soft lump of something, like whipped cream.","Add a dollop of cream to your pie.",""],["dauntless","DAWNT-lis","adjective","Brave and not easily scared.","The dauntless climber reached the top at dawn.",""],["epiphany","ih-PIF-uh-nee","noun","A sudden moment when you understand something.","While washing dishes, I had an epiphany about the puzzle.","From Greek epiphaneia, “appearance.”"],["teem","TEEM","verb","To be full of moving things.","The pond teemed with tiny tadpoles.",""],["balk","BAWK","verb","To stop and refuse to go on.","The pony balked at crossing the stream.",""],["brouhaha","BROO-hah-hah","noun","A noisy fuss or stir over something.","There was a big brouhaha over who got the last cupcake.","From French brouhaha."],["circuitous","ser-KYOO-i-tuhs","adjective","Taking a long, winding way instead of a direct one.","We took a circuitous path to enjoy the autumn leaves.",""],["implore","im-PLOR","verb","To beg someone eagerly.","The kids implored us for five more minutes at the park.","From Latin implorare, “to beg with tears.”"],["boutique","boo-TEEK","noun","A small shop that sells special or stylish items.","We found the scarf at a little boutique downtown.","From French boutique, “a shop.”"],["potable","POH-tuh-buhl","adjective","Safe to drink.","The spring water was cold and potable.","From Latin potare, “to drink.”"],["braggadocio","brag-uh-DOH-shee-oh","noun","Empty, boastful talk.","His braggadocio about his fishing skills made us laugh.",""],["mulish","MYOO-lish","adjective","Stubborn, like a mule.","He was mulish about wearing a coat until he felt the cold.",""],["penchant","PEN-chuhnt","noun","A strong liking for something.","She has a penchant for spicy food.","From French pencher, “to lean.”"],["luxuriate","lug-ZHOOR-ee-ayt","verb","To relax and enjoy something fully.","I luxuriated in a warm bath.","From Latin luxuria, “excess.”"],["bedeck","bih-DEK","verb","To decorate in a showy way.","The street was bedecked with lights for the festival.",""],["odyssey","OD-uh-see","noun","A long, adventurous journey.","Our trip to the beach became an odyssey of detours.",""],["rendezvous","RAHN-day-voo","noun","A planned meeting at a set time and place.","Our rendezvous point was the big oak tree in the park.","From French rendez-vous, “present yourselves.”"],["consummate","KON-suh-mit","adjective","Showing great skill; complete in every way.","He is a consummate host who remembers every name.",""],["mentor","MEN-tor","noun","A wise person who guides someone with less experience.","My first boss became my mentor for life.",""],["ilk","ILK","noun","A type or kind.","My uncle loves jazz, blues and music of that ilk.",""],["slake","SLAYK","verb","To satisfy a thirst or a strong wish.","A cold drink from the well slaked our thirst.",""],["plethora","PLETH-er-uh","noun","Much more than you need.","The buffet had a plethora of desserts.","From Greek plethore, “fullness.”"],["steadfast","STED-fast","adjective","Firm, loyal and not changing.","The old dog was steadfast by the boy’s side.","From Old English stedefæst, “firm in place.”"],["dossier","DOS-ee-ay","noun","A file of papers about a person or topic.","She kept a dossier of ideas for her garden.","From French dossier, “bundle of papers.”"],["dint","DINT","noun","Means or effort, used in the phrase “by dint of” something.","By dint of hard work, she finished the quilt.",""],["brevity","BREV-i-tee","noun","Being short or brief.","The speaker's brevity was welcome on such a hot day.","From Latin brevis, “short.”"],["atoll","AT-awl","noun","A ring-shaped coral island around a lagoon.","The plane flew over a tiny atoll in the blue ocean.","From Maldivian atolu."],["nub","NUHB","noun","The main point, or a small lump.","The nub of the problem is that we need more chairs.",""],["inundate","IN-uhn-dayt","verb","To flood or overwhelm.","After the bake sale, we were inundated with thank-you notes.","From Latin unda, “wave.”"],["docent","DOH-suhnt","noun","A guide who teaches visitors at a museum.","The docent told us the story behind each painting.","From Latin docere, “to teach.”"],["byway","BY-way","noun","A small side road; also a less-known area of a subject.","We took a quiet byway through the farmland.",""],["aegis","EE-jis","noun","The protection or support of someone.","The fair was held under the aegis of the local library.","From Greek aigis, the shield of Zeus."],["amble","AM-buhl","verb","To walk in a slow, relaxed way.","We ambled along the beach after dinner.","From Latin ambulare, “to walk.”"],["traipse","TRAYPS","verb","To walk around in a tired or aimless way.","We traipsed through three stores looking for the right shoes.",""],["curmudgeon","ker-MUHJ-uhn","noun","A grumpy, stubborn person, often older.","The town curmudgeon secretly fed all the stray cats.",""],["multifarious","mul-tuh-FAIR-ee-uhs","adjective","Of many different kinds.","Her multifarious hobbies include knitting, chess and kayaking.",""],["convalesce","kon-vuh-LES","verb","To rest and recover after being sick.","He convalesced on the couch with soup and movies.","From Latin convalescere, “to grow strong.”"],["parody","PAIR-uh-dee","noun","A funny copy of something that pokes fun at it.","They wrote a parody of a famous song about their cat.",""],["appraise","uh-PRAYZ","verb","To judge the value or quality of something.","The jeweler appraised Grandma's old ring.",""],["pedantic","puh-DAN-tik","adjective","Too fussy about small rules and details.","He was pedantic about the right way to load the dishwasher.",""],["jubilant","JOO-buh-luhnt","adjective","Very happy, especially after a win.","The jubilant team danced on the field.","From Latin jubilare, “to shout with joy.”"],["avert","uh-VURT","verb","To turn away, or to stop something bad from happening.","Quick thinking averted a kitchen disaster.","From Latin avertere, “to turn away.”"],["flummox","FLUM-uhks","verb","To confuse someone completely.","The new TV remote flummoxed Grandma.",""],["opprobrium","uh-PROH-bree-uhm","noun","Strong public blame or shame.","The team faced opprobrium for leaving trash in the park.","From Latin opprobrium, “reproach.”"],["congregate","KONG-gri-gayt","verb","To gather together in a group.","Ducks congregate by the pond when we bring bread.","From Latin grex, “flock.”"],["unflappable","uhn-FLAP-uh-buhl","adjective","Calm, even when things go wrong.","The unflappable bus driver handled the snow with ease.",""],["contour","KON-toor","noun","The outline or shape of something.","We traced the contour of the hills on paper.",""],["overweening","oh-ver-WEE-ning","adjective","Too proud or too sure of yourself.","His overweening pride made him skip the practice.",""],["mountebank","MOUN-tuh-bank","noun","A person who tricks people to get their money.","The mountebank sold “magic” water at the fair.","From Italian montambanco, “one who climbs on a bench.”"],["somnolent","SOM-nuh-luhnt","adjective","Sleepy or drowsy.","The warm afternoon made the whole class somnolent.","From Latin somnus, “sleep.”"],["nosegay","NOHZ-gay","noun","A small bunch of flowers.","The child gave her teacher a nosegay of daisies.",""],["unfettered","uhn-FET-erd","adjective","Free from limits or restraints.","The kids had unfettered fun on the last day of school.",""],["anagram","AN-uh-gram","noun","A word made by mixing up the letters of another word.","Listen is an anagram of silent.",""],["glut","GLUT","noun","Too much of something.","There is a glut of zucchini in our garden this year.",""],["unbridled","uhn-BRY-dld","adjective","Free and not held back.","The kids ran to the ocean with unbridled excitement.",""],["maroon","muh-ROON","verb","To leave someone stuck in a lonely place.","The snowstorm marooned us at the cabin for two cozy days.",""],["folly","FOL-ee","noun","A foolish act or idea.","Wearing sandals in the snow was pure folly.","From French folie, “madness.”"],["munificent","myoo-NIF-uh-suhnt","adjective","Very generous with gifts.","A munificent neighbor paid for the new park benches.","From Latin munus, “gift.”"],["kith","KITH","noun","Your friends and neighbors.","All our kith and kin came to the reunion.",""],["labyrinth","LAB-uh-rinth","noun","A maze of winding paths.","We got lost in the corn labyrinth.","From Greek labyrinthos."],["coalesce","koh-uh-LES","verb","To come together into one whole.","Our ideas coalesced into one great plan.","From Latin coalescere, “to grow together.”"],["protean","PROH-tee-uhn","adjective","Able to change shape or do many different things.","The protean actor played a king, a dog and a tree.",""],["kooky","KOO-kee","adjective","Odd in a fun way.","My aunt wears kooky hats to every party.",""],["antiquarian","an-ti-KWAIR-ee-uhn","adjective","Having to do with old and rare objects or books.","We browsed the antiquarian bookshop for an hour.",""],["discrepancy","dih-SKREP-uhn-see","noun","A difference between things that should match.","There was a discrepancy between the bill and the menu.",""],["artless","ART-lis","adjective","Simple, honest and natural, without trying to impress.","The child's artless drawing made everyone smile.",""],["effervescent","ef-er-VES-uhnt","adjective","Bubbly, like a fizzy drink, or lively and cheerful.","Her effervescent laugh filled the kitchen.","From Latin effervescere, “to boil up.”"],["devious","DEE-vee-uhs","adjective","Sneaky and not straightforward.","The cat had a devious plan to steal the ham.",""],["catalyst","KAT-uh-list","noun","Something that makes a change happen faster.","Her kind note was the catalyst for a lifelong friendship.","From Greek katalysis, “a dissolving.”"],["hodgepodge","HOJ-poj","noun","A messy mix of things.","Our soup was a tasty hodgepodge of leftovers.",""],["exult","ig-ZULT","verb","To feel or show great joy.","The team exulted after the last goal.","From Latin exsultare, “to leap up.”"],["wisp","WISP","noun","A thin, small piece of something, like hair or smoke.","A wisp of steam rose from my tea.",""],["boulevard","BUL-uh-vard","noun","A wide city street, often lined with trees.","We strolled down the shady boulevard.","From French boulevard."],["obliging","uh-BLY-jing","adjective","Happy and willing to help.","The obliging clerk carried our bags to the car.",""],["flotsam","FLOT-suhm","noun","Bits of wreckage or junk floating on the water.","We found flotsam and driftwood along the beach.",""],["zugzwang","TSOOK-tsvahng","noun","A spot where any move you make will hurt you, as in chess.","I was in zugzwang: either answer would spoil the surprise.","From German Zugzwang, “compulsion to move.”"],["hygge","HOO-guh","noun","A cozy feeling of comfort and togetherness.","Candles, cocoa and blankets filled the room with hygge.","From Danish hygge."],["harbinger","HAR-bin-jer","noun","A sign that something is coming.","The first robin is a harbinger of spring.",""],["compatriot","kuhm-PAY-tree-uht","noun","A person from your own country.","Far from home, she met a compatriot at the market.",""],["tantamount","TAN-tuh-mownt","adjective","Equal to, or as good as.","Skipping practice was tantamount to giving up the spot.",""],["bootstrap","BOOT-strap","verb","To start something using only what you already have.","She bootstrapped her bakery from her home kitchen.",""],["buttress","BUH-tris","verb","To support or strengthen.","She buttressed her argument with a few good facts.",""],["abstemious","ab-STEE-mee-uhs","adjective","Careful not to eat or drink too much.","He is abstemious at parties and always takes just one cookie.",""],["diffuse","dih-FYOOZ","verb","To spread out over a wide area.","The lamp diffused a soft glow across the room.","From Latin diffundere, “to pour out.”"],["wane","WAYN","verb","To slowly get smaller or weaker.","The moon wanes after it is full.","From Old English wanian, “to lessen.”"],["accrue","uh-KROO","verb","To build up slowly over time.","The coins in the jar accrued until we had enough for a picnic.",""],["jargon","JAR-guhn","noun","Special words used by one group that others may not understand.","The doctor explained everything without any jargon.",""],["gesticulate","je-STIK-yuh-layt","verb","To wave your hands while you talk.","My uncle gesticulates wildly when he tells a story.",""],["flabbergast","FLAB-er-gast","verb","To amaze someone completely.","The surprise party flabbergasted my mom.",""],["novice","NOV-is","noun","A person who is new at something.","The novice skater held the wall the whole time.","From Latin novus, “new.”"],["oblique","oh-BLEEK","adjective","Slanting, or not said in a direct way.","She made an oblique hint about her birthday.","From Latin obliquus, “slanting.”"],["balderdash","BAWL-der-dash","noun","Silly talk or nonsense.","He said the moon was made of cheese, which was pure balderdash.",""],["renaissance","REN-uh-sahns","noun","A rebirth or fresh burst of interest in something.","Board games are having a renaissance in our house.","From French renaissance, “rebirth.”"],["bauble","BAW-buhl","noun","A small, cheap, shiny decoration or trinket.","The tree was hung with glittering baubles.",""],["disarray","dis-uh-RAY","noun","A messy, untidy state.","After the sleepover, the room was in total disarray.",""],["untoward","uhn-TORD","adjective","Unexpected and not wanted or proper.","The trip went smoothly with nothing untoward.",""],["nimbus","NIM-buhs","noun","A rain cloud, or a glow around something.","A soft nimbus of light circled the street lamp in the fog.","From Latin nimbus, “cloud.”"],["eddy","ED-ee","noun","A small swirl of water or air.","Leaves spun in a little eddy by the creek.",""],["beguile","bih-GYL","verb","To charm or delight, sometimes in a tricky way.","The puppy beguiled us with his big brown eyes.",""],["catharsis","kuh-THAR-sis","noun","A feeling of relief after letting out strong emotions.","Writing in her journal gave her a sense of catharsis.","From Greek katharsis, “cleansing.”"],["conduit","KON-doo-it","noun","A channel through which something flows.","The library became a conduit for new ideas in town.",""],["boondoggle","BOON-dog-uhl","noun","A project that wastes time and money.","The fancy fountain that never worked was a real boondoggle.",""],["jinx","JINGKS","noun","Something thought to bring bad luck.","Don't say we'll win, or you'll put a jinx on it!",""],["adroit","uh-DROYT","adjective","Clever and skillful, especially with hands or words.","The adroit baker shaped the dough into perfect knots.","From French à droit, “rightly.”"],["breezy","BREE-zee","adjective","Windy and fresh; also light and relaxed in manner.","She waved with a breezy smile.",""],["fresco","FRES-koh","noun","A painting made on wet plaster on a wall.","The old villa had a fresco of lemon trees.","From Italian fresco, “fresh.”"],["brandish","BRAN-dish","verb","To wave something about in a showy way.","Grandma brandished her wooden spoon and called us to dinner.",""],["vociferous","voh-SIF-er-uhs","adjective","Loud and forceful in speaking out.","The fans were vociferous in their cheering.","From Latin vox, “voice,” and ferre, “to carry.”"],["trove","TROHV","noun","A collection of valuable or delightful things.","The attic was a trove of old photos and letters.",""],["obviate","OB-vee-ayt","verb","To remove the need for something.","A good map obviates the need to ask for directions.",""],["lithe","LYTH","adjective","Bending easily and gracefully.","The lithe cat leapt onto the fence.",""],["ratify","RAT-uh-fy","verb","To give official approval to something.","The club members voted to ratify the new rules.","From Latin ratus, “fixed, settled.”"],["convivial","kuhn-VIV-ee-uhl","adjective","Friendly, lively and fun to be with.","The convivial dinner went late into the night.","From Latin convivium, “a feast.”"],["tranquil","TRANG-kwil","adjective","Calm, quiet and peaceful.","We spent a tranquil afternoon by the pond.","From Latin tranquillus, “calm.”"],["deluge","DEL-yooj","noun","A great flood, or a huge amount of something.","After the post, we got a deluge of kind messages.",""],["distraught","dih-STRAWT","adjective","Very upset and worried.","The distraught boy found his kite in a tree.",""],["dishearten","dis-HAR-tn","verb","To make someone lose hope or courage.","Don’t let one bad grade dishearten you.",""],["dawdle","DAW-dl","verb","To be slow and take your time.","The kids dawdled on the way home from school.",""],["raucous","RAW-kuhs","adjective","Loud and rough in a noisy way.","Raucous cheers filled the gym when the team won.","From Latin raucus, “hoarse.”"],["conjecture","kuhn-JEK-cher","noun","A guess made without full proof.","Where the cat goes at night is pure conjecture.",""],["tenet","TEN-it","noun","A main belief or rule that a group holds.","A key tenet of our family is to always say thank you.","From Latin tenet, “he holds.”"],["medley","MED-lee","noun","A mix of different things, like songs.","The band played a medley of old favorites.",""],["amiss","uh-MIS","adjective","Wrong or not as it should be.","She sensed something was amiss when the dog did not bark.",""],["largesse","lar-ZHES","noun","Generosity in giving.","Thanks to her largesse, every child got a book.","From French largesse, “generosity.”"],["harangue","huh-RANG","noun","A long, loud speech scolding someone.","Grandma gave a harangue about muddy boots.",""],["dialect","DY-uh-lekt","noun","A way of speaking a language in one area.","Grandma’s dialect has words we’ve never heard.","From Greek dialektos, “way of speaking.”"],["gloat","GLOHT","verb","To show off about your own success.","My sister gloated after beating me at checkers.",""],["glisten","GLIS-uhn","verb","To shine softly, like something wet.","Dew glistened on the grass.",""],["decrepit","dih-KREP-it","adjective","Old and worn out.","The decrepit fence leaned in the wind.","From Latin decrepitus, “very old.”"],["bequeath","bih-KWEETH","verb","To leave something to someone, often in a will; to pass on.","Grandpa bequeathed his fishing rod to me.",""],["forlorn","for-LORN","adjective","Sad and lonely.","A forlorn teddy bear sat in the rain until we brought it inside.",""],["gambol","GAM-buhl","verb","To run and jump playfully.","Puppies gamboled in the fresh snow.",""],["monolith","MON-uh-lith","noun","A single huge block of stone.","The hikers rested in the shade of a tall monolith.","From Greek monos, “one,” and lithos, “stone.”"],["ominous","OM-uh-nuhs","adjective","Seeming to warn that something bad is coming.","Ominous clouds gathered before the storm.","From Latin omen, “sign.”"],["obtrusive","uhb-TROO-siv","adjective","Too noticeable in an unwelcome way.","The bright sign was obtrusive on the quiet street.",""],["regale","ri-GAYL","verb","To entertain someone with stories or good food.","Grandpa regaled us with tales of his first car.","From French régaler, “to treat to a feast.”"],["knack","NAK","noun","A natural skill.","He has a knack for fixing bikes.",""],["devise","dih-VYZ","verb","To come up with a plan or idea.","The kids devised a game with only a ball and a box.",""],["disparage","dih-SPAR-ij","verb","To speak badly of someone or something.","Never disparage someone for trying their best.",""],["usurp","yoo-SURP","verb","To take someone’s place or power without the right to.","The new kitten usurped the old cat’s favorite chair.","From Latin usurpare, “to seize for use.”"],["ostracize","OS-truh-syz","verb","To leave someone out of a group on purpose.","Our class agreed never to ostracize the new kid.","From Greek ostrakon, “piece of pottery.”"],["mimic","MIM-ik","verb","To copy how someone acts or sounds.","The parrot can mimic the doorbell perfectly.","From Greek mimos, “actor.”"],["prevaricate","prih-VAIR-ih-kayt","verb","To avoid telling the whole truth.","Don't prevaricate, just tell me who ate the cookies.","From Latin praevaricari, “to walk crookedly.”"],["cavalcade","KAV-uhl-kayd","noun","A long parade or line of riders or cars.","A cavalcade of decorated bikes rolled down Main Street.",""],["limber","LIM-ber","adjective","Able to bend and move easily.","Yoga keeps Grandma limber.",""],["loam","LOHM","noun","Rich, crumbly soil.","Carrots grow well in soft loam.",""],["plausible","PLAW-zuh-buhl","adjective","Seeming likely to be true.","“The wind blew it away” was a plausible excuse.",""],["nonagenarian","non-uh-juh-NAIR-ee-uhn","noun","A person in their nineties.","The nonagenarian at the party danced with everyone.","From Latin nonageni, “ninety each.”"],["detour","DEE-toor","noun","A longer way taken to avoid something.","The detour led us to a lovely bakery.","From French détour, “a turning aside.”"],["ossify","OS-uh-fy","verb","To become hard and unable to change.","Without new ideas, old habits can ossify.","From Latin os, “bone.”"],["frolic","FROL-ik","verb","To play and run around happily.","Lambs frolicked in the spring meadow.","From Dutch vrolijk, “cheerful.”"],["utilitarian","yoo-til-i-TAIR-ee-uhn","adjective","Made to be useful rather than pretty.","Her kitchen is utilitarian, with just what she needs.","From Latin utilis, “useful.”"],["cynical","SIN-i-kuhl","adjective","Believing people act only for selfish reasons.","Her kind neighbors made her less cynical.",""],["translucent","trans-LOO-suhnt","adjective","Letting some light through, but not fully clear.","The translucent curtains glowed in the morning sun.","From Latin trans, “through,” and lucere, “to shine.”"],["assiduous","uh-SIJ-oo-uhs","adjective","Working with steady care and effort.","His assiduous practice made him a great piano player.","From Latin assiduus, “sitting down to.”"],["deem","DEEM","verb","To judge or consider something in a certain way.","The cook deemed the soup ready.",""],["plucky","PLUK-ee","adjective","Brave and full of spirit.","The plucky little team never gave up.",""],["immaculate","ih-MAK-yuh-lit","adjective","Perfectly clean and neat.","Her kitchen is always immaculate.","From Latin immaculatus, “unstained.”"],["portent","POR-tent","noun","A sign of something about to happen.","The first robin is a portent of spring.",""],["potluck","POT-luk","noun","A meal where each guest brings a dish to share.","The neighborhood potluck had twelve kinds of salad.",""],["nexus","NEK-suhs","noun","A central link or meeting point.","The library is the nexus of our small town.","From Latin nexus, “a binding.”"],["hindsight","HYND-syt","noun","Understanding something only after it happens.","In hindsight, we should have packed more snacks.",""],["trellis","TREL-is","noun","A frame of crossed strips for plants to climb on.","Roses climbed the white trellis by the gate.",""],["feckless","FEK-lis","adjective","Lacking skill or energy; not able to get things done.","The feckless scarecrow didn't scare a single crow.",""],["brimming","BRIM-ing","adjective","Full to the top.","Her eyes were brimming with happy tears.",""],["behemoth","bih-HEE-muhth","noun","Something huge and powerful.","The new truck was a behemoth that barely fit in the garage.",""],["acme","AK-mee","noun","The highest point of something.","Winning the spelling bee was the acme of her school year.","From Greek akme, “the highest point.”"],["exquisite","ek-SKWIZ-it","adjective","Very beautiful and delicate.","The lace on the old dress was exquisite.","From Latin exquisitus, “sought out.”"],["undulate","UHN-juh-layt","verb","To move in smooth waves.","The tall grass undulated in the breeze.","From Latin unda, “wave.”"],["burgeon","BUR-juhn","verb","To grow or spread quickly.","Her small garden has burgeoned into a jungle of tomatoes.",""],["gauche","GOHSH","adjective","Awkward and clumsy in social settings.","I felt gauche at my first fancy dinner.","From French gauche, “left.”"],["cornucopia","kor-nuh-KOH-pee-uh","noun","A large, rich supply of good things.","The farm stand was a cornucopia of fruit.","From Latin cornu copiae, “horn of plenty.”"],["denouement","day-noo-MAHN","noun","The final part of a story where things are wrapped up.","The denouement tied up every loose end.","From French dénouer, “to untie.”"],["demeanor","dih-MEE-ner","noun","The way a person looks and acts.","Her calm demeanor made the kids feel safe.",""],["hurtle","HUR-tl","verb","To move very fast, often out of control.","The sled hurtled down the snowy hill.",""],["holistic","hoh-LIS-tik","adjective","Looking at the whole thing, not just the parts.","The coach takes a holistic view of each player.","From Greek holos, “whole.”"],["pervasive","per-VAY-siv","adjective","Spread everywhere.","The pervasive scent of pine filled the cabin.","From Latin pervadere, “to go through.”"],["burble","BUR-buhl","verb","To make a soft bubbling sound, or to talk on happily.","The coffee pot burbled on the stove.",""],["mystify","MIS-tuh-fy","verb","To puzzle someone completely.","The magic trick mystified the whole family.",""],["bedrock","BED-rok","noun","The solid rock under soil; also the strong base of something.","Trust is the bedrock of any good friendship.",""],["mercurial","mer-KYOOR-ee-uhl","adjective","Changing mood quickly and often.","The mercurial weather went from sun to rain in an hour.",""],["charisma","kuh-RIZ-muh","noun","A special charm that draws people to someone.","Our coach has the charisma to fire up the whole team.","From Greek charisma, “gift of grace.”"],["camouflage","KAM-uh-flahzh","noun","Colors or covers that help something blend in.","The moth’s camouflage made it look like tree bark.","From French camoufler, “to disguise.”"],["coy","KOY","adjective","Shy in a playful way.","She gave a coy smile when asked about the surprise.",""],["autumnal","aw-TUHM-nuhl","adjective","Having to do with autumn, or like autumn.","The kitchen smelled autumnal with cinnamon and apples.",""],["imminent","IM-uh-nuhnt","adjective","About to happen.","Dark clouds meant rain was imminent.","From Latin imminere, “to hang over.”"],["deter","dih-TUR","verb","To discourage someone from doing something.","The fence deters deer from eating the lettuce.","From Latin deterrere, “to frighten off.”"],["aura","AWR-uh","noun","A special feeling or quality that seems to surround a person or place.","The old library has an aura of calm.","From Greek aura, “a breeze.”"],["birdsong","BURD-sawng","noun","The musical sounds birds make.","We woke to birdsong outside the cabin.",""],["tutelage","TOOT-l-ij","noun","Teaching and guidance from someone.","Under her aunt’s tutelage, she learned to bake bread.","From Latin tutela, “protection.”"],["doyen","DOY-uhn","noun","The most respected or senior person in a group.","She is the doyen of the town’s gardening club.","From French doyen, “dean.”"],["facsimile","fak-SIM-uh-lee","noun","An exact copy.","The museum sells a facsimile of the old map.","From Latin fac simile, “make similar.”"],["bravura","bruh-VYOOR-uh","noun","Great skill and flair, especially in a performance.","The pianist played with dazzling bravura.","From Italian bravura, “bravery.”"],["quizzical","KWIZ-i-kuhl","adjective","Showing that you are puzzled or curious.","The puppy gave me a quizzical look when I sneezed.",""],["bide","BYD","verb","To wait patiently, as in “bide your time” before acting.","She bided her time until the cookies cooled.",""],["canopy","KAN-uh-pee","noun","A cover overhead, like treetops forming a roof.","We walked under a canopy of green leaves.",""],["notoriety","noh-tuh-RY-ih-tee","noun","Being well known, often for something bad.","The goat gained notoriety for eating the mayor's hat.",""],["palaver","puh-LAV-er","noun","A lot of fuss and talk over nothing much.","There was a big palaver about who sits where.","From Portuguese palavra, “word.”"],["bloviate","BLOH-vee-ayt","verb","To talk a lot in a puffed-up, empty way.","Uncle Joe tends to bloviate about his golf game.",""],["purview","PUR-vyoo","noun","The area that someone is in charge of.","Weekend pancakes are in Dad's purview.",""],["wherewithal","WAIR-with-awl","noun","The money, means or skill needed to do something.","We finally had the wherewithal to build a treehouse.",""],["communal","kuh-MYOON-l","adjective","Shared by a whole group.","Our street has a communal garden for everyone.",""],["doppelganger","DOP-uhl-gang-er","noun","Someone who looks exactly like another person.","I met my doppelganger at the grocery store.","From German Doppelgänger, “double-goer.”"],["consternation","kon-ster-NAY-shuhn","noun","Worry and alarm, often sudden.","To our consternation, the dog ate the birthday cake.",""],["omen","OH-muhn","noun","A sign that something good or bad will happen.","A rainbow on moving day felt like a good omen.","From Latin omen."],["swelter","SWEL-ter","verb","To feel uncomfortably hot and sweaty.","We sweltered in the summer heat until the fan came on.",""],["stupendous","stoo-PEN-duhs","adjective","Amazingly great or large.","The view from the mountain top was stupendous.","From Latin stupere, “to be amazed.”"],["joust","JOWST","verb","To fight on horseback with long poles, or to compete playfully.","The two friends jousted with pool noodles.",""],["chivalry","SHIV-uhl-ree","noun","Polite, kind and brave behavior.","He showed chivalry by holding the door for everyone.","From French chevalier, “knight.”"],["surfeit","SUR-fit","noun","Too much of something.","After the party, we had a surfeit of cupcakes.",""],["interlude","IN-ter-lood","noun","A short break between parts of something.","We had a quiet interlude between the two games.","From Latin inter, “between,” and ludus, “play.”"],["pristine","pris-TEEN","adjective","Clean, fresh and like new.","The new snow was pristine and sparkling.","From Latin pristinus, “former.”"],["recompense","REK-uhm-pens","noun","Payment or reward for work or for a loss.","As recompense for raking leaves, we got hot apple pie.",""],["pernicious","per-NISH-uhs","adjective","Harmful in a slow, quiet way.","Weeds can have a pernicious effect on a garden.",""],["qualm","KWAHM","noun","A small, uneasy feeling of doubt.","I had no qualms about lending my neighbor my ladder.",""],["nebulous","NEB-yuh-luhs","adjective","Vague and not clear.","Our weekend plans are still nebulous.","From Latin nebula, “mist.”"],["resplendent","ri-SPLEN-duhnt","adjective","Shining and splendid to look at.","The bride looked resplendent in her golden dress.","From Latin resplendere, “to shine brightly.”"],["zenith","ZEE-nith","noun","The highest point of something.","At its zenith, the sun was right above our heads.",""],["gusto","GUS-toh","noun","Great enjoyment and energy.","The kids sang with gusto.","From Italian gusto, “taste.”"],["nitpick","NIT-pik","verb","To fuss about tiny, unimportant faults.","Please don't nitpick my drawing, I'm still learning.",""],["amenity","uh-MEN-i-tee","noun","Something that makes a place comfortable or pleasant.","The campsite's best amenity was a hot shower.","From Latin amoenus, “pleasant.”"],["ingenious","in-JEEN-yuhs","adjective","Very clever and inventive.","She had an ingenious idea for storing her yarn.","From Latin ingenium, “talent.”"],["segue","SEG-way","noun","A smooth move from one topic or part to the next.","Talking about pie made a nice segue into dessert.","From Italian segue, “it follows.”"],["rhapsody","RAP-suh-dee","noun","A burst of joyful feeling, or a free and emotional piece of music.","Her letter was a rhapsody about the beauty of the mountains.","From Greek rhapsōidia, from rhaptein, “to stitch,” and ōidē, “song.”"],["inimitable","ih-NIM-i-tuh-buhl","adjective","So special it cannot be copied.","Grandpa told jokes in his inimitable way.",""],["aficionado","uh-fish-ee-uh-NAH-doh","noun","A person who knows a lot about and loves a hobby or subject.","My aunt is a tea aficionado with forty kinds in her cupboard.","From Spanish aficionado, “fond of.”"],["dabble","DAB-uhl","verb","To try something a little, without going deep.","She dabbles in painting on lazy Sundays.",""],["rollicking","ROL-i-king","adjective","Full of lively, noisy fun.","We had a rollicking time at the family picnic.",""],["feral","FEER-uhl","adjective","Wild, especially an animal that was once tame.","A feral cat lives under the old barn.","From Latin fera, “wild animal.”"],["palindrome","PAL-in-drohm","noun","A word or phrase that reads the same backward and forward.","“Racecar” is a palindrome.","From Greek palin, “again,” and dromos, “running.”"],["dismantle","dis-MAN-tl","verb","To take something apart piece by piece.","We dismantled the tent after the trip.",""],["wayfarer","WAY-fair-er","noun","A person who travels on foot.","The inn welcomed weary wayfarers with warm soup.",""],["wont","WAWNT","noun","A habit or usual way of doing things.","As is his wont, Dad hummed while cooking.",""],["carousel","kar-uh-SEL","noun","A merry-go-round.","Grandpa rode the carousel horse right beside her.",""],["bristle","BRIS-uhl","verb","To show sudden anger or offense; also to stand up stiffly, like hair.","The cat's fur bristled when it saw the dog.",""],["unwieldy","uhn-WEEL-dee","adjective","Too big or awkward to carry or handle easily.","The unwieldy couch would not fit through the door.",""],["chimera","ky-MEER-uh","noun","A wild dream or idea that can never come true.","A house with no chores is a lovely chimera.","From Greek chimaira, a mythical monster."],["arcane","ar-KAYN","adjective","Known or understood by only a few people.","He loves learning arcane facts about old clocks.","From Latin arcanus, “secret.”"],["unfathomable","uhn-FATH-uh-muh-buhl","adjective","Too deep or strange to understand.","The number of stars in the sky is unfathomable.",""],["ululate","UHL-yuh-layt","verb","To make a long, high, wavering cry.","At the wedding, the aunties ululated with joy.","From Latin ululare, “to howl.”"],["castigate","KAS-ti-gayt","verb","To criticize someone harshly.","The editor castigated the writer for missing the deadline.","From Latin castigare, “to correct, punish.”"],["profound","pruh-FOUND","adjective","Very deep in meaning or feeling.","Her kind words had a profound effect on me.","From Latin profundus, “deep.”"],["venerable","VEN-er-uh-buhl","adjective","Respected because of age and wisdom.","The venerable oak tree shaded the whole yard.","From Latin venerari, “to honor.”"],["retrospect","RET-ruh-spekt","noun","A look back at what has already happened.","In retrospect, leaving early was a wise choice.","From Latin retro, “back,” and specere, “to look.”"],["mores","MOR-ayz","noun","The customs and manners of a group.","Every family has its own mores at the dinner table.","From Latin mores, “customs.”"],["squelch","SKWELCH","verb","To make a wet, sucking sound, or to stop something.","Our boots squelched in the muddy field.",""],["ocher","OH-ker","noun","A warm earthy yellow or orange-brown color.","The hills glowed ocher in the evening light.","From Greek okhros, “pale yellow.”"],["curio","KYOOR-ee-oh","noun","A small, unusual object people collect.","Her shelf is full of curios from her travels.",""],["ungainly","uhn-GAYN-lee","adjective","Awkward and clumsy in how you move.","The baby giraffe took a few ungainly steps.",""],["hue","HYOO","noun","A color or shade.","The sky turned a pink hue at sunset.",""],["maladroit","mal-uh-DROYT","adjective","Clumsy or awkward in how you act.","His maladroit joke made the room go quiet, but he laughed it off.","From French mal, “badly,” and adroit, “skillful.”"],["archetype","AR-ki-typ","noun","A perfect or typical example of something.","Our neighbor is the archetype of a friendly gardener.","From Greek archetypon, “a pattern.”"],["apiary","AY-pee-er-ee","noun","A place where bees are kept.","Our neighbor's apiary gives us honey every fall.","From Latin apis, “bee.”"],["bygone","BY-gawn","adjective","Belonging to the past.","The old diner reminds Grandpa of a bygone era.",""],["dilapidated","dih-LAP-i-day-tid","adjective","Old and falling apart.","They fixed up the dilapidated barn together.",""],["ostentatious","os-ten-TAY-shuhs","adjective","Showy in a way meant to impress.","The ostentatious car had gold wheels.","From Latin ostentare, “to display.”"],["deference","DEF-er-uhns","noun","Polite respect for someone’s wishes.","In deference to the baby, we spoke softly.",""],["amulet","AM-yuh-lit","noun","A small charm worn for good luck.","She wore a little stone amulet her grandmother gave her.",""],["waggish","WAG-ish","adjective","Playful and joking.","Our waggish mail carrier always has a pun ready.",""],["patter","PAT-er","noun","Quick, light sounds, or fast smooth talk.","We fell asleep to the patter of rain.",""],["paramount","PAIR-uh-mount","adjective","More important than anything else.","Safety is paramount when we go camping.",""],["domicile","DOM-uh-syl","noun","A home.","Their cozy domicile sat at the end of the lane.","From Latin domus, “house.”"],["canny","KAN-ee","adjective","Smart and careful, especially with money or plans.","The canny shopper waited for the big sale.",""],["eloquent","EL-uh-kwuhnt","adjective","Able to speak or write in a clear, moving way.","The student gave an eloquent speech at graduation.","From Latin eloqui, “to speak out.”"],["impetus","IM-pi-tuhs","noun","A push or reason that makes something happen.","The new park gave us the impetus to walk more.","From Latin impetus, “attack, force.”"],["orotund","OR-uh-tund","adjective","Full and rich in sound, sometimes too grand.","The announcer had an orotund voice.","From Latin ore rotundo, “with round mouth.”"],["bittersweet","BIT-er-sweet","adjective","Happy and sad at the same time.","Graduation day was bittersweet for the whole family.",""],["rigmarole","RIG-muh-rohl","noun","A long, fussy, confusing process.","Getting a new library card was quite a rigmarole.",""],["operetta","op-uh-RET-uh","noun","A short, light, funny opera.","The school put on a cheerful operetta in the spring.","From Italian operetta, “little work.”"],["cogitate","KOJ-i-tayt","verb","To think deeply about something.","He sat on the porch to cogitate over the puzzle.","From Latin cogitare, “to think.”"],["peruse","puh-ROOZ","verb","To read or look over, often slowly.","I like to peruse the cookbook on lazy Sundays.",""],["blarney","BLAR-nee","noun","Charming talk that flatters or stretches the truth.","Don't believe his blarney about catching a fish this big.",""],["prodigy","PROD-ih-jee","noun","A young person with amazing talent.","The piano prodigy played for the whole town.",""],["vulpine","VUL-pyn","adjective","Like a fox, sly and clever.","The cat had a vulpine grin after stealing the ham.","From Latin vulpes, “fox.”"],["riposte","ri-POHST","noun","A quick, clever reply.","Her friendly riposte made even the teacher laugh.","From Italian risposta, “an answer.”"],["keystone","KEE-stohn","noun","The top stone of an arch that holds it together, or the key part of something.","Mom is the keystone of our family.",""],["reticent","RET-uh-suhnt","adjective","Quiet and slow to share your thoughts.","He was reticent at first but opened up over lunch.","From Latin reticere, “to keep silent.”"],["pittance","PIT-ns","noun","A very small amount of money.","He worked for a pittance but loved the job.",""],["dregs","DREGZ","noun","The last bits left at the bottom of a drink.","He drank the coffee down to the dregs.",""],["consensus","kuhn-SEN-suhs","noun","An agreement shared by most of a group.","The family reached a consensus: pizza on Friday.","From Latin consentire, “to agree.”"],["bower","BOW-er","noun","A shady, leafy spot in a garden.","We read under a bower of climbing roses.",""],["gamut","GAM-uht","noun","The whole range of something.","The movie ran the gamut from tears to laughter.",""],["gestalt","guh-SHTAHLT","noun","A whole that is more than the sum of its parts.","The quilt's gestalt was lovelier than any single square.","From German Gestalt, “shape, form.”"],["tousled","TOW-zuhld","adjective","Messy and rumpled, like hair after sleep.","He came to breakfast with tousled hair and a big yawn.",""],["tenuous","TEN-yoo-uhs","adjective","Very thin or weak.","We had only a tenuous phone signal in the mountains.","From Latin tenuis, “thin.”"],["boisterous","BOY-ster-uhs","adjective","Loud, lively and full of energy.","The boisterous kids raced around the yard.",""],["constellation","kon-stuh-LAY-shuhn","noun","A group of stars that forms a shape.","We found a constellation that looked like a kite.","From Latin stella, “star.”"],["clarity","KLAIR-i-tee","noun","The quality of being clear and easy to understand.","A walk outside gave her clarity about the choice.","From Latin clarus, “clear.”"],["bode","BOHD","verb","To be a sign of what will happen.","Clear skies bode well for the parade.",""],["procrastinate","proh-KRAS-tuh-nayt","verb","To put off doing something until later.","I procrastinated on my taxes, then did them in one night.","From Latin crastinus, “of tomorrow.”"],["erudite","ER-yoo-dyt","adjective","Having a lot of knowledge from reading and study.","Our erudite librarian can answer almost any question.","From Latin erudire, “to teach.”"],["sinuous","SIN-yoo-uhs","adjective","Curving and twisting gracefully.","The sinuous river wound through the green valley.","From Latin sinus, “a curve.”"],["countenance","KOUN-tn-uhns","noun","A person’s face or expression.","Her countenance brightened when she saw the puppy.",""],["intuition","in-too-ISH-uhn","noun","Knowing something without reasoning it out.","My intuition told me to bring a jacket.","From Latin intueri, “to look at.”"],["gossamer","GOS-uh-mer","adjective","Very light, thin and delicate.","Gossamer curtains let in the morning light.","From Middle English gossomer, “goose summer.”"],["arable","AIR-uh-buhl","adjective","Good for growing crops.","The valley has rich, arable soil.","From Latin arare, “to plow.”"],["hapless","HAP-lis","adjective","Unlucky.","The hapless picnic got rained out twice.","From Old Norse happ, “luck.”"],["acquiesce","ak-wee-ES","verb","To accept or agree quietly without arguing.","I wanted pizza, but I acquiesced when everyone else chose tacos.","From Latin acquiescere, “to rest.”"],["balm","BAHM","noun","Something that soothes, heals or comforts.","Her kind words were a balm after a long day.",""],["drowsy","DROU-zee","adjective","Sleepy.","The warm fire made everyone drowsy.",""],["amber","AM-ber","noun","A warm golden-orange color; also a fossil tree resin.","The setting sun turned the field to amber.","From Arabic anbar."],["whirligig","WUR-li-gig","noun","A toy or object that spins around.","A wooden whirligig spun in the wind on the fence post.",""],["laudable","LAW-duh-buhl","adjective","Worthy of praise.","Cleaning up the park was a laudable effort.","From Latin laudare, “to praise.”"],["approbation","ap-ruh-BAY-shuhn","noun","Approval or praise.","The chef nodded in approbation after tasting the sauce.","From Latin approbare, “to approve.”"],["despondent","dih-SPON-duhnt","adjective","Very sad and without hope.","He was despondent until his lost dog came home.",""],["ramble","RAM-buhl","verb","To walk with no set path, or to talk on and on.","We rambled through the meadow looking for wildflowers.",""],["unwitting","uhn-WIT-ing","adjective","Not knowing or aware.","The dog was an unwitting star in our home video.",""],["nocturne","NOK-turn","noun","A gentle, dreamy piece of music suited to night.","She played a soft nocturne before bedtime.","From French nocturne, “of the night.”"],["draconian","dray-KOH-nee-uhn","adjective","Very harsh or strict.","No dessert for a week seemed a bit draconian.",""],["diatribe","DY-uh-tryb","noun","A long, angry speech against something.","Uncle’s diatribe against cold coffee made us laugh.",""],["locale","loh-KAL","noun","A place where something happens.","The beach was the perfect locale for the party.",""],["bemused","bih-MYOOZD","adjective","Puzzled and a little confused.","She gave a bemused smile at the odd question.",""],["dogged","DAW-gid","adjective","Stubbornly determined.","Her dogged practice paid off at the recital.",""],["nook","NOOK","noun","A small, cozy corner.","I read in a sunny nook by the window.",""],["conviction","kuhn-VIK-shuhn","noun","A strong belief.","She spoke with conviction about saving the old tree.",""],["lagniappe","LAN-yap","noun","A small extra gift, like a bonus.","The baker added a cookie as lagniappe.","From Louisiana French, from Spanish la ñapa, “the gift.”"],["replete","ri-PLEET","adjective","Full, or well supplied with something.","The garden was replete with ripe red tomatoes.","From Latin repletus, “filled up.”"],["cumbersome","KUHM-ber-suhm","adjective","Large, heavy and hard to carry or use.","The cumbersome box would not fit through the door.",""],["xenophile","ZEN-uh-fyl","noun","A person who loves foreign people, cultures and food.","As a true xenophile, she tries a new world recipe every week.","From Greek xenos, “stranger,” and philos, “loving.”"],["abreast","uh-BREST","adverb","Side by side; also, up to date with news.","We walked three abreast down the quiet country lane.",""],["canter","KAN-ter","verb","To move at a smooth, easy speed, like a horse.","The pony cantered across the field.",""],["ballyhoo","BAL-ee-hoo","noun","Noisy fuss and excitement to get attention.","After all the ballyhoo, the new store was rather small.",""],["mien","MEEN","noun","The way a person looks or carries themselves.","The teacher had a calm and kindly mien.",""],["philately","fih-LAT-l-ee","noun","The hobby of collecting stamps.","Grandpa's philately began with one stamp from his pen pal.",""],["cavernous","KAV-er-nuhs","adjective","Huge and hollow, like a cave.","Our voices echoed in the cavernous barn.",""],["adjourn","uh-JURN","verb","To stop a meeting and plan to meet again later.","The book club adjourned for lemonade on the patio.","From Old French ajorner, “to set a day.”"],["bioluminescence","by-oh-loo-muh-NES-uhns","noun","Light made by living things, like fireflies.","We watched the bioluminescence glow blue in the waves.","From Greek bios, “life,” and Latin lumen, “light.”"],["reminisce","rem-uh-NIS","verb","To talk or think about happy past times.","The old friends reminisced about their school days.","From Latin reminisci, “to remember.”"],["causeway","KAWZ-way","noun","A raised road across water or wet ground.","We drove the causeway to the island at low tide.",""],["disquiet","dis-KWY-it","noun","A feeling of worry or unease.","A quiet disquiet grew as the storm drew near.",""],["innocuous","ih-NOK-yoo-uhs","adjective","Harmless.","The little snake in the garden was innocuous.","From Latin innocuus, “harmless.”"],["chicanery","shi-KAY-nuh-ree","noun","Sneaky tricks used to fool people.","The board game ended in giggles over his playful chicanery.",""],["oscillate","OS-uh-layt","verb","To swing back and forth.","The fan oscillates to cool the whole room.","From Latin oscillare, “to swing.”"],["synchronicity","sing-kruh-NIS-i-tee","noun","Two things happening together by chance in a meaningful way.","By synchronicity, my friend called just as I picked up the phone.",""],["sumptuous","SUMP-choo-uhs","adjective","Rich, grand and costly looking.","The wedding had a sumptuous feast of many dishes.",""],["ruminate","ROO-muh-nayt","verb","To think about something deeply for a long time.","She ruminated on the question during her evening walk.","From Latin ruminari, “to chew the cud.”"],["callous","KAL-uhs","adjective","Not caring about others’ feelings.","It was callous to laugh when he tripped.",""],["ambiguous","am-BIG-yoo-uhs","adjective","Having more than one possible meaning; unclear.","Her answer was ambiguous, so I asked again.","From Latin ambiguus, “doubtful.”"],["emulate","EM-yuh-layt","verb","To copy someone you admire.","My son tries to emulate his big cousin's soccer moves.","From Latin aemulari, “to rival.”"],["sporadic","spuh-RAD-ik","adjective","Happening now and then, not on a regular plan.","We heard sporadic bird calls in the quiet forest.","From Greek sporadikos, “scattered.”"],["motley","MOT-lee","adjective","Made of many different, mismatched kinds.","A motley crew of neighbors helped paint the fence.",""],["behoove","bih-HOOV","verb","To be right or wise for someone to do.","It behooves us to leave early to beat the traffic.",""],["elixir","ih-LIK-ser","noun","A magic drink thought to cure anything, or a perfect remedy.","A cup of hot tea is my elixir on a cold morning.","From Arabic al-iksir."],["diligent","DIL-i-juhnt","adjective","Careful and hardworking.","The diligent gardener weeds every morning.","From Latin diligere, “to value, love.”"],["dissonance","DIS-uh-nuhns","noun","A clash of sounds or ideas.","The band tuned up until the dissonance became music.","From Latin dissonare, “to sound apart.”"],["ascertain","as-er-TAYN","verb","To find out for sure.","We called ahead to ascertain that the museum was open.",""],["sonorous","SON-er-uhs","adjective","Deep, full and rich in sound.","The church bell rang out in sonorous tones.","From Latin sonor, “sound.”"],["penumbra","pih-NUM-bruh","noun","The soft, partly shaded edge around a shadow.","We sat in the penumbra of the big oak tree.","From Latin paene, “almost,” and umbra, “shadow.”"],["heirloom","AIR-loom","noun","A treasured object passed down in a family.","This quilt is a family heirloom.",""],["diadem","DY-uh-dem","noun","A jeweled crown or headband.","The queen in the play wore a sparkling diadem.","From Greek diadema, “band.”"],["vagary","VAY-guh-ree","noun","An odd, unexpected change.","We packed for the vagaries of mountain weather.","From Latin vagari, “to wander.”"],["cantankerous","kan-TANG-ker-uhs","adjective","Grumpy and quick to argue.","The cantankerous old cat hissed at everyone but Grandma.",""],["rapscallion","rap-SKAL-yuhn","noun","A playful little rascal.","That little rapscallion hid my slippers again.",""],["blight","BLYT","noun","Something that spoils or damages; also a plant disease.","Litter is a blight on our lovely park.",""],["galore","guh-LOR","adjective","In large amounts.","There were cookies galore at the party.","From Irish go leor, “to sufficiency.”"],["amenable","uh-MEE-nuh-buhl","adjective","Willing to agree or go along with something.","The kids were amenable to a hike if snacks were included.",""],["ballast","BAL-uhst","noun","Heavy material that keeps a ship steady; also anything that gives balance.","Her calm presence was the ballast of the busy family.",""],["tableau","ta-BLOH","noun","A striking scene, like a picture.","The family on the porch made a sweet tableau.","From French tableau, “picture.”"],["gaggle","GAG-uhl","noun","A group of geese, or a noisy group of people.","A gaggle of kids ran to the ice cream truck.",""],["augment","awg-MENT","verb","To make bigger or add to.","He augments his income by tutoring on weekends.","From Latin augere, “to increase.”"],["prolix","proh-LIKS","adjective","Using too many words.","The prolix speech made everyone yawn.","From Latin prolixus, “extended.”"],["soporific","sop-uh-RIF-ik","adjective","Making you feel sleepy.","The soft hum of the fan was soporific.","From Latin sopor, “deep sleep.”"],["lumbering","LUM-ber-ing","adjective","Moving in a slow, heavy, clumsy way.","A lumbering bear crossed the road.",""],["arpeggio","ar-PEJ-ee-oh","noun","The notes of a chord played one after another.","She warmed up on the piano with a few arpeggios.","From Italian arpeggiare, “to play on a harp.”"],["agrarian","uh-GRAIR-ee-uhn","adjective","Having to do with farms and farming land.","Our town began as a small agrarian village.","From Latin ager, “a field.”"],["tactile","TAK-tl","adjective","Having to do with touch.","Babies love tactile toys that are soft or bumpy.","From Latin tangere, “to touch.”"],["guile","GYL","noun","Clever, sly tricks.","The fox used guile to get the grapes.",""],["lucrative","LOO-kruh-tiv","adjective","Making a lot of money.","Her lemonade stand was surprisingly lucrative.","From Latin lucrum, “profit.”"],["admonish","ad-MON-ish","verb","To warn or scold someone gently but firmly.","The librarian admonished us to keep our voices low.",""],["bathos","BAY-thos","noun","A sudden drop from serious to silly, often by accident.","The grand speech ended in bathos when he tripped over the cord.","From Greek bathos, “depth.”"],["sycophant","SIK-uh-fuhnt","noun","Someone who flatters others too much to get ahead.","The king was surrounded by sycophants who always agreed.",""],["windfall","WIND-fawl","noun","A sudden bit of good luck, often money.","Finding twenty dollars in my coat was a nice windfall.",""],["absolve","ab-ZOLV","verb","To free someone from blame or a duty.","The coach absolved him of blame for the lost game.","From Latin absolvere, “to set free.”"],["tremulous","TREM-yuh-luhs","adjective","Shaking a little, often from nerves.","She gave her speech in a tremulous but brave voice.","From Latin tremulus, “trembling.”"],["debunk","dee-BUHNGK","verb","To show that a claim is false.","Our science teacher debunked the myth about goldfish memory.",""],["aurora","uh-ROR-uh","noun","Bright bands of colored light in the night sky near the poles.","We stayed up late to watch the green aurora dance.","From Latin aurora, “dawn.”"],["brusque","BRUHSK","adjective","Short and blunt in speech, in a way that can seem rude.","The busy clerk gave a brusque reply, then smiled an apology.","From French brusque, “sharp.”"],["precipice","PRES-uh-pis","noun","A very steep cliff, or the edge of something big.","We stood well back from the precipice to take photos.","From Latin praeceps, “headlong.”"],["sidle","SY-dl","verb","To move sideways or slyly, as if shy.","The puppy sidled up to me for a treat.",""],["clamber","KLAM-ber","verb","To climb awkwardly using hands and feet.","The kids clambered up the big rocks.",""],["complacent","kuhm-PLAY-suhnt","adjective","Too pleased with yourself to keep trying.","Winning once made the team complacent.","From Latin complacere, “to please.”"],["discreet","dih-SKREET","adjective","Careful not to draw attention or share secrets.","She was discreet about the surprise party.",""],["wizened","WIZ-uhnd","adjective","Dried up and wrinkled with age.","The wizened apple still made a fine pie.","From Old English wisnian, “to wither.”"],["peckish","PEK-ish","adjective","A little bit hungry.","I'm feeling peckish, so I'll grab an apple.",""],["bellwether","BEL-weth-er","noun","Something that shows where a trend is going.","The busy farmers market is a bellwether for a good harvest.","From the bell worn by the lead sheep, or wether, of a flock."],["reprieve","ri-PREEV","noun","A break or short relief from something hard.","The rain gave us a reprieve from mowing the lawn.",""],["aubade","oh-BAHD","noun","A song or poem about the dawn.","The birds outside sang a cheerful aubade.","From French aube, “dawn.”"],["antidote","AN-ti-doht","noun","Something that cures or fixes a bad situation.","A good laugh is the best antidote to a gloomy day.","From Greek antidoton, “given against.”"],["unrequited","uhn-ri-KWY-tid","adjective","Not returned or given back, especially love.","His love of broccoli was sadly unrequited by his kids.",""],["disrepute","dis-ri-PYOOT","noun","A state of having a bad name.","The old diner fell into disrepute, then made a comeback.",""],["bestow","bih-STOH","verb","To give something as an honor or gift.","The town bestowed a medal on the brave lifeguard.",""],["depict","dih-PIKT","verb","To show in a picture or in words.","The mural depicts our town a hundred years ago.","From Latin depingere, “to paint.”"],["archaic","ar-KAY-ik","adjective","Very old and no longer in common use.","Thou is an archaic word for you.","From Greek archaios, “ancient.”"],["nurture","NUR-cher","verb","To care for and help grow.","She nurtures her tomato plants every morning.","From Latin nutrire, “to feed.”"],["longevity","lon-JEV-i-tee","noun","Long life.","Tortoises are famous for their longevity.","From Latin longus, “long,” and aevum, “age.”"],["multitude","MUL-tih-tood","noun","A very large number of people or things.","A multitude of fireflies lit up the field.","From Latin multus, “many.”"],["tintinnabulation","tin-ti-nab-yuh-LAY-shuhn","noun","The ringing and jingling of bells.","The tintinnabulation of sleigh bells filled the snowy night.","From Latin tintinnabulum, “a little bell.”"],["dispatch","dih-SPACH","verb","To send off quickly.","She dispatched thank-you notes the next day.",""],["aqueduct","AK-wi-duhkt","noun","A long channel or bridge that carries water.","We hiked along an old stone aqueduct.","From Latin aqua, “water,” and ducere, “to lead.”"],["jolt","JOHLT","noun","A sudden jerk or shock.","The bus stopped with a jolt.",""],["scrumptious","SKRUMP-shuhs","adjective","Extremely tasty.","Grandma’s scrumptious cookies vanished in minutes.",""],["astute","uh-STOOT","adjective","Clever and quick to notice what matters.","An astute shopper, she always finds the best deals.","From Latin astutus, “crafty.”"],["doff","DOF","verb","To take off a hat or piece of clothing.","He doffed his cap to the ladies at the gate.","From Middle English do off, “to take off.”"],["tempestuous","tem-PES-choo-uhs","adjective","Stormy, or full of strong feelings.","The tempestuous sea tossed the little boat.","From Latin tempestas, “storm.”"],["accede","ak-SEED","verb","To agree to a request, often after thinking it over.","Mom finally acceded to our request for a later bedtime on Friday.",""],["appease","uh-PEEZ","verb","To calm someone by giving them what they want.","We appeased the hungry toddler with a cracker.",""],["indomitable","in-DOM-i-tuh-buhl","adjective","Impossible to defeat or discourage.","Grandma has an indomitable spirit.","From Latin indomitus, “untamed.”"],["inexorable","in-EK-ser-uh-buhl","adjective","Impossible to stop.","The inexorable tide crept up the beach.","From Latin inexorabilis, “not moved by pleading.”"],["jasmine","JAZ-min","noun","A climbing plant with sweet-smelling white flowers.","Jasmine scented the evening air.","From Persian yasaman."],["frond","FROND","noun","A large leaf of a fern or palm.","A fern frond uncurled in the shade.","From Latin frons, “leaf.”"],["paraphernalia","pair-uh-fer-NAYL-yuh","noun","All the gear and stuff for an activity.","The fishing paraphernalia filled the whole trunk.",""],["dilemma","dih-LEM-uh","noun","A hard choice between two options.","Pie or ice cream was a real dilemma.","From Greek di-, “two,” and lemma, “premise.”"],["volition","voh-LISH-uhn","noun","The power to choose for yourself.","He cleaned his room of his own volition.","From Latin volo, “I wish.”"],["tyro","TY-roh","noun","A beginner at something.","As a tyro at knitting, she made a very lumpy scarf.","From Latin tiro, “a new recruit.”"],["meritorious","mair-ih-TOR-ee-uhs","adjective","Deserving praise.","He got an award for meritorious service to the town.","From Latin meritum, “earned.”"],["babble","BAB-uhl","verb","To talk fast in a way that is hard to follow, or to make a soft bubbling sound.","The brook babbled softly beside our tent.",""],["circumspect","SUR-kuhm-spekt","adjective","Careful to think about risks before acting.","She was circumspect about sharing her new idea.","From Latin circumspicere, “to look around.”"],["apposite","AP-uh-zit","adjective","Very fitting and right for the moment.","The teacher closed with an apposite quote about kindness.",""],["hospitable","HOS-pi-tuh-buhl","adjective","Friendly and welcoming to guests.","Our hospitable neighbors invited us for dinner.","From Latin hospes, “guest, host.”"],["diaphanous","dy-AF-uh-nuhs","adjective","Light, delicate and see-through.","Diaphanous curtains fluttered in the breeze.","From Greek diaphanes, “see-through.”"],["curiosity","kyoor-ee-OS-i-tee","noun","A strong wish to know or learn something.","Curiosity led the kids to explore the old attic.","From Latin curiosus, “careful, inquisitive.”"],["chiaroscuro","kee-ar-uh-SKYOOR-oh","noun","The use of strong light and dark in a picture.","The painting’s chiaroscuro made the candle seem to glow.","From Italian chiaro, “clear,” and scuro, “dark.”"],["endemic","en-DEM-ik","adjective","Found naturally in only one place.","That bright bird is endemic to the island.","From Greek endemos, “native.”"],["fanfare","FAN-fair","noun","A short blast of trumpets, or a big showy fuss.","The new library opened with great fanfare.",""],["ajar","uh-JAR","adjective","Slightly open, used for a door or lid.","The cat slipped through the door we had left ajar.",""],["insular","IN-suh-ler","adjective","Cut off from other people or ideas.","The small town felt insular until the new café opened.","From Latin insula, “island.”"],["requite","ri-KWYT","verb","To pay back or return a kindness or feeling.","She requited his kindness with a handmade card.",""],["momentum","moh-MEN-tuhm","noun","The force that keeps something moving forward.","After the first chapter, my reading gained momentum.","From Latin momentum, “movement.”"],["benefactor","BEN-uh-fak-ter","noun","A person who gives money or help to others.","A kind benefactor paid for the new playground.","From Latin bene, “well,” and facere, “to do.”"],["gallivant","GAL-uh-vant","verb","To wander from place to place for fun.","They spent the summer gallivanting around the coast.",""],["crescendo","kruh-SHEN-doh","noun","A slow build to a loud or strong peak.","The song rose to a thrilling crescendo.","From Italian crescendo, “growing.”"],["pugnacious","pug-NAY-shuhs","adjective","Quick to argue or fight.","The pugnacious little terrier barked at every leaf.","From Latin pugnax, “fond of fighting.”"],["persnickety","per-SNIK-ih-tee","adjective","Very fussy about small things.","My cat is persnickety about her food bowl.",""],["skulduggery","skul-DUG-uh-ree","noun","Sneaky, dishonest tricks.","There was some skulduggery when someone hid all the game pieces.",""],["dainty","DAYN-tee","adjective","Small, delicate and pretty.","She served tea in dainty cups.",""],["cordial","KOR-juhl","adjective","Warm and polite.","The new neighbors gave us a cordial welcome.","From Latin cor, “heart.”"],["querulous","KWER-uh-luhs","adjective","Whiny and full of small complaints.","The tired traveler grew querulous after the long delay.","From Latin queri, “to complain.”"],["autonomy","aw-TON-uh-mee","noun","The freedom to make your own choices.","Teens enjoy the autonomy of picking their own clothes.","From Greek autonomia, “self-rule.”"],["deplete","dih-PLEET","verb","To use up a supply.","The long hike depleted our snacks.",""],["botch","BOCH","verb","To do something badly; to mess up.","I botched the pancakes, but they still tasted good.",""],["calligraphy","kuh-LIG-ruh-fee","noun","The art of beautiful handwriting.","She wrote the invitations in fancy calligraphy.","From Greek kallos, “beauty,” and graphein, “to write.”"],["histrionic","his-tree-ON-ik","adjective","Overly dramatic.","My toddler's histrionic sobs over a broken cookie made us smile.","From Latin histrio, “actor.”"],["amorphous","uh-MOR-fuhs","adjective","Having no clear shape or form.","The clouds drifted by in amorphous white puffs.","From Greek amorphos, “without shape.”"],["discern","dih-SURN","verb","To notice or understand something not obvious.","Can you discern the hint of lemon in this cake?","From Latin discernere, “to separate.”"]],"kids":[["fable","FAY-buhl","noun","A short story that teaches a lesson, often with talking animals.","In the fable, the slow turtle wins the race.","From Latin fabula, “story.”"],["prance","PRANS","verb","To move in a proud, bouncy way.","The pony pranced around the field with its tail held high.",""],["smudge","SMUJ","noun","A dirty or blurry mark.","There was a smudge of chocolate on my homework.",""],["keen","KEEN","adjective","Very sharp, or very eager.","Our dog has a keen nose and finds every treat.","From Old English cēne, “brave, bold.”"],["aloft","uh-LOFT","adverb","Up high in the air.","The wind kept my kite aloft all afternoon.",""],["pamper","PAM-per","verb","To treat someone with lots of care and comfort.","On Mom's birthday, we pampered her with breakfast in bed.",""],["mutter","MUT-er","verb","To speak quietly, often when grumpy.","Sam muttered to himself when he lost the board game.",""],["droop","DROOP","verb","To hang down because it is weak or tired.","The flowers drooped until we watered them.",""],["swirl","SWURL","verb","To spin around in circles.","Watch the milk swirl into the hot cocoa.",""],["amuse","uh-MYOOZ","verb","To make someone smile or laugh.","My little brother tried to amuse us with silly faces.",""],["assist","uh-SIST","verb","To help someone do something.","I like to assist my dad when he bakes bread.","From Latin assistere, “to stand by.”"],["babble","BAB-uhl","verb","To talk fast in a way that is hard to understand.","My baby cousin likes to babble at the dog.",""],["squint","SKWINT","verb","To look with your eyes partly closed.","I had to squint to read the sign in the bright sun.",""],["balmy","BAH-mee","adjective","Warm and pleasant, like nice weather.","We ate dinner outside on a balmy summer night.",""],["soggy","SOG-ee","adjective","Very wet and soft.","My cereal got soggy because I left it too long.",""],["tremble","TREM-buhl","verb","To shake because you are cold, scared or excited.","My hands tremble a little before I play piano on stage.","From Latin tremere, “to shake.”"],["quench","KWENCH","verb","To stop your thirst by drinking.","After soccer practice, a cold glass of water will quench your thirst.","From Old English cwencan, “to put out.”"],["blunt","BLUHNT","adjective","Not sharp, or saying things in a very plain way.","Kids use scissors with blunt tips in art class.",""],["jumble","JUM-buhl","noun","A messy mix of things.","My toy box is a jumble of blocks and cars.",""],["outwit","owt-WIT","verb","To win by being more clever than someone.","The rabbit outwitted the fox by hiding in a hollow log.",""],["echo","EK-oh","noun","A sound that bounces back so you hear it again.","We shouted in the cave and heard our echo.","From Greek ēchō, “sound.”"],["waddle","WOD-uhl","verb","To walk with short steps, rocking side to side.","The ducks waddle down to the pond every morning.",""],["oasis","oh-AY-sis","noun","A green spot with water in a dry desert.","The camels rested at the oasis under the palm trees.","From Greek oasis, a fertile spot in the desert."],["ladle","LAY-duhl","noun","A big, deep spoon for serving soup.","Dad used a ladle to fill our bowls with chili.",""],["clutter","KLUHT-er","noun","A messy pile of things.","I cleaned the clutter off my desk.",""],["stumble","STUM-buhl","verb","To trip or almost fall.","I tried not to stumble over the toys on the floor.",""],["dart","DART","verb","To move suddenly and fast.","A tiny fish darted under a rock.",""],["urge","URJ","verb","To push someone hard to do something.","Coach will urge us to drink water on hot days.","From Latin urgere, “to press.”"],["ponder","PON-der","verb","To think about something carefully.","I pondered which book to borrow from the library.","From Latin ponderare, “to weigh.”"],["dash","DASH","verb","To run very fast for a short way.","We dashed to the bus stop before it left.",""],["leap","LEEP","verb","To jump high or far.","The frog can leap from one lily pad to the next.","From Old English hlēapan, “to jump.”"],["alcove","AL-kohv","noun","A small space set back into a wall.","I read my comics in a cozy alcove by the window.","From Arabic al-qubba, “the vault.”"],["rowdy","ROW-dee","adjective","Loud and wild.","The bus got rowdy on the way home from the game.",""],["savor","SAY-ver","verb","To enjoy something slowly.","I like to savor every bite of my birthday cake.","From Latin sapor, “taste.”"],["colossal","kuh-LOS-uhl","adjective","Very, very big.","We built a colossal snowman taller than Dad.","From Greek kolossos, “giant statue.”"],["delicate","DEL-i-kuht","adjective","Easy to break or hurt, so you must be gentle.","The butterfly’s wings are very delicate.","From Latin delicatus, “dainty.”"],["clever","KLEV-er","adjective","Quick to learn and good at solving problems.","My clever sister found a way to fix the broken kite.",""],["overflow","oh-ver-FLOH","verb","To spill over the top because it is too full.","The bathtub overflowed when I forgot to turn off the water.",""],["hatch","HACH","verb","To break out of an egg.","We watched the chicks hatch in our classroom.",""],["huddle","HUD-uhl","verb","To crowd close together.","The puppies huddle together to stay warm.",""],["nudge","NUJ","verb","To push someone gently, often with your elbow.","Mia nudged me when the teacher called my name.",""],["ramble","RAM-buhl","verb","To talk a long time without a clear point.","Grandpa likes to ramble about the old days at dinner.",""],["brisk","BRISK","adjective","Quick and full of energy, or cool and fresh.","We took a brisk walk on the chilly morning.",""],["current","KUR-uhnt","noun","Water or air moving in one direction.","The river current carried our stick downstream.","From Latin currere, “to run.”"],["merry","MAIR-ee","adjective","Happy and full of fun.","We sang merry songs on the long car ride.","From Old English myrige, “pleasant.”"],["nourish","NUR-ish","verb","To give food and what is needed to grow.","Rain and sunshine nourish the plants in our garden.","From Latin nutrire, “to feed.”"],["trickle","TRIK-uhl","verb","To flow slowly in a thin stream.","Rain began to trickle down the window.",""],["nibble","NIB-uhl","verb","To eat with small, quick bites.","My hamster likes to nibble on carrot sticks.",""],["rustle","RUS-uhl","verb","To make a soft, crackling sound.","The dry leaves rustle when the squirrel runs over them.",""],["pounce","POWNS","verb","To jump on something suddenly.","My cat pounced on the toy mouse.",""],["jolt","JOHLT","noun","A sudden bump or shake.","The bus stopped with a jolt.",""],["yelp","YELP","verb","To give a short, sharp cry.","The puppy let out a yelp when I stepped on its tail by mistake.",""],["aroma","uh-ROH-muh","noun","A nice smell.","The aroma of popcorn filled the whole house.","From Greek arōma, “spice.”"],["lantern","LAN-tern","noun","A light inside a case that you can carry.","We used a lantern to find our way to the tent.","From Latin lanterna, “lamp.”"],["pliable","PLY-uh-buhl","adjective","Easy to bend without breaking.","Warm clay is pliable, so you can shape it into anything.","From French plier, “to bend.”"],["creature","KREE-cher","noun","Any living animal.","A tiny creature with lots of legs crawled across the path.","From Latin creatura, “a created thing.”"],["bicker","BIK-er","verb","To argue about small, silly things.","The twins bicker over who gets the front seat.",""],["thud","THUD","noun","A dull, heavy sound.","The book fell off the shelf with a loud thud.",""],["gallop","GAL-uhp","verb","To run fast, like a horse.","The pony started to gallop across the field.",""],["mope","MOHP","verb","To act sad and slow because you feel down.","Don't mope just because it rained on game day.",""],["yearn","YURN","verb","To want something very much.","In winter, I yearn for warm days at the beach.","From Old English giernan, “to desire.”"],["plume","PLOOM","noun","A big, fluffy feather, or something shaped like one.","A plume of steam rose from my hot cocoa.","From Latin pluma, “feather.”"],["hover","HUV-er","verb","To stay in one spot in the air.","The hummingbird can hover by the flower.",""],["beverage","BEV-er-ij","noun","Something to drink.","Lemonade is my favorite summer beverage.","From Old French bevrage, from beivre, “to drink.”"],["bog","BOG","noun","Soft, wet, muddy ground.","My boot got stuck in the bog by the lake.","From Irish bogach, from bog, “soft.”"],["journey","JUR-nee","noun","A trip from one place to another.","Our journey to Grandpa’s house took all day.","From French journée, “a day’s travel.”"],["rugged","RUG-id","adjective","Rough, strong and bumpy.","We hiked up a rugged trail full of rocks and roots.",""],["brook","BROOK","noun","A small stream of water.","Frogs sat on rocks along the brook.","From Old English brōc, “stream.”"],["ooze","OOZ","verb","To flow out slowly.","Jelly oozed out of my sandwich onto my shirt.",""],["doze","DOHZ","verb","To take a short, light sleep.","Grandpa dozed off in his chair during the movie.",""],["mound","MOWND","noun","A small hill or pile.","The ants built a big mound of dirt by the swing set.",""],["nectar","NEK-ter","noun","The sweet juice inside flowers.","Bees drink nectar from the flowers in our yard.","From Greek nektar, the drink of the gods in old myths."],["rummage","RUM-ij","verb","To dig through things to find something.","I had to rummage through my backpack to find my pencil.",""],["fetch","FECH","verb","To go and get something and bring it back.","Our puppy loves to fetch the ball.","From Old English feccan, “to bring.”"],["astray","uh-STRAY","adverb","Off the right path.","One sheep went astray and wandered into the woods.",""],["zigzag","ZIG-zag","noun","A line with sharp turns back and forth.","The lightning made a bright zigzag across the sky.",""],["radiant","RAY-dee-uhnt","adjective","Shining bright, or glowing with joy.","Mom looked radiant when she saw the card we made.","From Latin radius, “ray.”"],["antler","ANT-ler","noun","A branching horn on the head of a deer or moose.","We found a deer antler on our hike in the woods.",""],["gorgeous","GOR-juhs","adjective","Very beautiful.","The sunset over the lake was gorgeous.","From Old French gorgias, “fine, elegant.”"],["dizzy","DIZ-ee","adjective","Feeling like everything is spinning.","Spinning on the tire swing made me dizzy.",""],["agile","AJ-uhl","adjective","Able to move quickly and easily.","The agile squirrel jumped from branch to branch.","From Latin agilis, “nimble,” from agere, “to do or drive.”"],["flicker","FLIK-er","verb","To shine on and off in an unsteady way.","The candle began to flicker in the breeze.","From Old English flicorian, “to flutter.”"],["orchard","OR-cherd","noun","A field where fruit trees grow.","We picked apples at the orchard on Saturday.",""],["puzzled","PUZ-uhld","adjective","Confused and not sure what is going on.","I was puzzled when my shoes were not where I left them.",""],["sly","SLY","adjective","Sneaky and clever.","The sly fox in the story tricked the crow.",""],["dense","DENS","adjective","Packed closely together.","The dense fog hid the whole playground.","From Latin densus, “thick.”"],["anxious","ANGK-shuhs","adjective","Worried or nervous about what might happen.","I felt anxious before my first piano recital.","From Latin anxius, “troubled.”"],["nook","NUUK","noun","A small, cozy corner.","I read my comic books in the reading nook by the window.",""],["hearty","HAR-tee","adjective","Warm, big and filling.","We ate a hearty bowl of soup after sledding.",""],["gaze","GAYZ","verb","To look at something for a long time.","We lay on the grass to gaze at the stars.",""],["capture","KAP-cher","verb","To catch and hold.","I captured a firefly in a jar, then let it go.","From Latin capere, “to take.”"],["damp","DAMP","adjective","A little bit wet.","My socks were still damp after the puddle jump.",""],["perch","PURCH","verb","To sit on something high or narrow.","The robin perched on the fence and sang.","From Latin pertica, “pole.”"],["glance","GLANS","verb","To take a quick look.","I glance at the clock when recess is almost over.",""],["assemble","uh-SEM-buhl","verb","To put the parts of something together.","We had to assemble the new bookshelf with a tiny wrench.",""],["bleak","BLEEK","adjective","Cold, empty, and gloomy.","The beach looked bleak on the gray winter day.",""],["dribble","DRIB-uhl","verb","To bounce a ball over and over while you move.","She dribbled the ball down the court.",""],["drizzle","DRIZ-uhl","noun","Light rain with very small drops.","We played soccer in a gentle drizzle.",""],["noble","NOH-buhl","adjective","Good, brave and kind in a way others admire.","It was noble of you to share your lunch with the new kid.","From Latin nobilis, “well known.”"],["burrow","BUR-oh","noun","A hole in the ground that an animal digs to live in.","The rabbit hopped into its burrow under the bush.",""],["clasp","KLASP","verb","To hold something tightly.","She clasped her lunch box with both hands.",""],["enormous","ih-NOR-muhs","adjective","Very, very big.","The enormous pumpkin would not fit in the wagon.","From Latin enormis, “out of the usual shape.”"],["nifty","NIF-tee","adjective","Clever, handy or neat.","My new pencil case has a nifty secret pocket.",""],["timid","TIM-id","adjective","Shy and easily scared.","The timid kitten hid under the bed when guests came.","From Latin timidus, “fearful.”"],["appetite","AP-uh-tite","noun","The feeling of wanting to eat.","Playing outside all day gave me a big appetite.","From Latin appetitus, “desire.”"],["trudge","TRUJ","verb","To walk slowly with heavy steps.","We had to trudge through deep snow to get to school.",""],["weary","WEER-ee","adjective","Very tired.","After the long hike, we felt weary and went to bed early.",""],["collapse","kuh-LAPS","verb","To fall down or cave in suddenly.","Our sand castle collapsed when the wave hit it.","From Latin collapsus, “fallen together.”"],["mellow","MEL-oh","adjective","Calm, soft and relaxed.","After his nap, my puppy was in a mellow mood.",""],["absorb","uhb-ZORB","verb","To soak up or take in something.","The sponge will absorb the juice I spilled on the table.","From Latin absorbere, “to swallow up.”"],["gulp","GULP","verb","To swallow quickly in a big mouthful.","After soccer, I gulp down a whole bottle of water.",""],["boulder","BOHL-der","noun","A very large rock.","We climbed on top of a boulder to see the lake.",""],["orbit","OR-bit","verb","To travel in a circle around something in space.","The moon orbits the Earth about once a month.","From Latin orbita, “wheel track.”"],["roam","ROHM","verb","To walk around with no set plan.","The goats roam all over the farm in the afternoon.",""],["cackle","KAK-uhl","verb","To laugh in a loud, sharp way.","The hens cackled in the barnyard.",""],["brink","BRINGK","noun","The very edge of something.","The ball rolled to the brink of the pond and stopped.",""],["moat","MOHT","noun","A deep ditch filled with water around a castle.","We dug a moat around our sandcastle and filled it with seawater.","From Old French mote, “mound.”"],["brim","BRIM","noun","The top edge of a cup or bowl.","I filled my cup with cocoa right to the brim.",""],["bristle","BRIS-uhl","noun","A short, stiff hair, like on a brush.","One bristle fell out of my new toothbrush.",""],["crater","KRAY-ter","noun","A large, bowl-shaped hole in the ground.","We saw craters on the moon through the telescope.","From Greek krater, “mixing bowl.”"],["linger","LING-ger","verb","To stay longer than you need to.","We like to linger at the park until the sun sets.",""],["vanish","VAN-ish","verb","To disappear all at once.","The magician made the coin vanish from his hand.",""],["crafty","KRAF-tee","adjective","Clever at tricking others.","The crafty raccoon figured out how to open the trash can.",""],["vivid","VIV-id","adjective","Bright, strong and clear.","She painted the sunset in vivid orange and pink.","From Latin vividus, “full of life.”"],["crevice","KREV-is","noun","A narrow crack or opening.","A lizard hid in a crevice between two rocks.",""],["chuckle","CHUHK-uhl","verb","To laugh quietly.","Dad chuckled at the joke on the back of the cereal box.",""],["doodle","DOO-duhl","verb","To draw little pictures without thinking much.","I doodled stars all over my notebook.",""],["canopy","KAN-uh-pee","noun","A cover of leaves and branches high above the ground.","Monkeys swing through the rainforest canopy.","From Greek konopeion, “a net against mosquitoes.”"],["blend","BLEND","verb","To mix things together.","We blend bananas and berries to make a smoothie.",""],["dazzle","DAZ-uhl","verb","To amaze someone with brightness or skill.","The fireworks dazzled everyone at the park.","From the old word “daze.”"],["vibrant","VY-bruhnt","adjective","Bright and full of life.","The market was full of vibrant fruits and flowers.",""],["grumpy","GRUM-pee","adjective","In a bad, cranky mood.","My brother is grumpy until he eats breakfast.",""],["boast","BOHST","verb","To talk proudly about yourself.","It is not kind to boast when you win a game.",""],["pantry","PAN-tree","noun","A small room or closet where food is kept.","The cereal is on the top shelf of the pantry.","From Old French paneterie, “bread room.”"],["loyal","LOY-uhl","adjective","Always standing by a friend.","My dog is loyal and follows me everywhere.","From Latin legalis, “of the law.”"],["rascal","RAS-kuhl","noun","A playful kid or pet who causes small trouble.","That little rascal of a kitten hid my sock again.",""],["glossy","GLOS-ee","adjective","Smooth and shiny.","The horse had a glossy brown coat.",""],["bulge","BUHLJ","verb","To stick out in a round lump.","My pockets bulge with shells from the beach.",""],["gust","GUST","noun","A sudden, strong rush of wind.","A gust of wind blew my hat off.","From Old Norse gustr, “a blast of wind.”"],["detect","dih-TEKT","verb","To notice or find something.","My dog can detect a treat hidden in my pocket.","From Latin detegere, “to uncover.”"],["harvest","HAR-vist","noun","The time when crops are picked.","We helped with the apple harvest at the farm.","From Old English hærfest, “autumn.”"],["bouquet","boh-KAY","noun","A bunch of flowers held together.","I gave my teacher a bouquet of daisies.","From French bouquet, “a little wood or bunch.”"],["sputter","SPUT-er","verb","To make popping or spitting sounds.","The old car began to sputter and then stopped.",""],["rumble","RUM-buhl","verb","To make a deep, rolling sound.","My tummy started to rumble right before lunch.",""],["admire","ad-MYRE","verb","To like and look up to someone or something.","I admire how my sister never gives up on hard puzzles.","From Latin admirari, “to wonder at.”"],["bramble","BRAM-buhl","noun","A prickly bush, like a blackberry bush.","My sock got caught on a bramble near the trail.",""],["glide","GLYDE","verb","To move smoothly and quietly.","The swan seemed to glide across the pond.","From Old English glīdan, “to slide.”"],["journal","JUR-nuhl","noun","A book where you write about your days.","I drew a picture of my fish in my journal.","From French journal, “daily.”"],["idle","EYE-duhl","adjective","Not busy or not working.","The swings sat idle while it rained.","From Old English īdel, “empty, useless.”"],["thrifty","THRIF-tee","adjective","Careful not to waste money or things.","My thrifty brother saves half his allowance every week.",""],["ledge","LEJ","noun","A narrow shelf sticking out from a wall or rock.","A pigeon sat on the window ledge.",""],["scold","SKOHLD","verb","To speak to someone in an angry way about what they did.","Dad had to scold the puppy for chewing his slipper.",""],["hush","HUSH","verb","To make quiet.","Mom tried to hush the baby with a soft song.",""],["bough","BOW","noun","A big branch of a tree.","A bird built its nest on a low bough.","From Old English bōg, “shoulder, branch.”"],["rickety","RIK-uh-tee","adjective","Weak and shaky, like it might fall apart.","Be careful on that rickety old ladder in the barn.",""],["coil","KOYL","verb","To wind into rings or loops.","The snake coiled up on a warm rock.",""],["courage","KUR-ij","noun","Being brave when something is hard or scary.","It took courage to sing in front of the class.","From Latin cor, “heart.”"],["gloomy","GLOO-mee","adjective","Dark, or feeling sad.","It was a gloomy, rainy day, so we played board games.",""],["cozy","KOH-zee","adjective","Warm, snug and comfy.","We built a cozy fort out of blankets and pillows.",""],["blotch","BLOCH","noun","A large, messy spot or mark.","There was a blue blotch of paint on my shirt.",""],["grateful","GRAYT-fuhl","adjective","Thankful for something.","I was grateful when my friend shared her umbrella.","From Latin gratus, “pleasing, thankful.”"],["overjoyed","oh-ver-JOYD","adjective","Very, very happy.","Lily was overjoyed when her grandma came to visit.",""],["coax","KOHKS","verb","To gently get someone to do something.","I coaxed the shy kitten out from under the bed.",""],["twinkle","TWINK-uhl","verb","To shine with little flashes of light.","The stars twinkle over our tent at camp.",""],["anchor","ANG-ker","noun","A heavy metal hook that keeps a boat in place.","The sailors dropped the anchor so the boat would stay still.","From Greek ankyra, “anchor.”"],["prowl","PROWL","verb","To move around quietly, looking for something.","The cat prowled through the garden looking for bugs.",""],["gigantic","jy-GAN-tik","adjective","Huge, like a giant.","A gigantic wave splashed our sandcastle.","From Greek gigas, “giant.”"],["arrange","uh-RAYNJ","verb","To put things in a neat or useful order.","Mom helped me arrange my books by color.",""],["glimmer","GLIM-er","noun","A small, faint light.","We saw a glimmer of light from the tent.",""],["preen","PREEN","verb","To clean and smooth feathers with a beak.","The duck preened its feathers by the pond.",""],["paddle","PAD-uhl","verb","To move through water using a flat oar or your hands.","We paddled the canoe across the calm lake.",""],["oblong","OB-long","adjective","Longer than it is wide.","We set up the oblong table for the family dinner.","From Latin oblongus, “rather long.”"],["plunge","PLUNJ","verb","To jump or dive in quickly.","The kids plunged into the cool pool on the hot day.",""],["prickly","PRIK-lee","adjective","Covered with sharp little points.","Be careful, the cactus is very prickly.",""],["quarrel","KWOR-uhl","noun","An angry argument.","The twins had a quarrel over who got the top bunk.","From Latin querela, “complaint.”"],["lagoon","luh-GOON","noun","A shallow pool of water near the sea.","Bright fish swam in the calm lagoon.","From Latin lacuna, “pool, pit.”"],["cluster","KLUHS-ter","noun","A small group of things close together.","A cluster of grapes hung from the vine.","From Old English clyster."],["frantic","FRAN-tik","adjective","Wild and rushed because you are worried.","I was frantic when I could not find my homework.",""],["jagged","JAG-id","adjective","Having sharp, rough points.","The mountain had a jagged top like a saw.",""],["flutter","FLUT-er","verb","To flap quickly and lightly.","A yellow butterfly began to flutter by the window.","From Old English floterian, “to float back and forth.”"],["fond","FOND","adjective","Liking someone or something a lot.","Lily is very fond of her old stuffed bear.",""],["lively","LYVE-lee","adjective","Full of life and energy.","The class was lively on the last day of school.",""],["sprout","SPROWT","verb","To start to grow.","Our bean seeds began to sprout after three days.",""],["stroll","STROHL","verb","To walk in a slow, relaxed way.","We stroll around the park after Sunday lunch.",""],["bulky","BUHL-kee","adjective","Big and hard to carry.","My bulky winter coat barely fit in my cubby.",""],["unique","yoo-NEEK","adjective","The only one of its kind.","Every snowflake has a unique shape.","From Latin unicus, “only one.”"],["lofty","LOF-tee","adjective","Very high up.","An eagle built a nest in a lofty pine tree.","From Old Norse lopt, “air, sky.”"],["camouflage","KAM-uh-flahzh","noun","Colors or patterns that help something blend in.","The frog’s green camouflage hid it in the leaves.","From French camoufler, “to disguise.”"],["fumble","FUM-buhl","verb","To handle something in a clumsy way.","I tend to fumble with my keys when my hands are cold.",""],["brew","BROO","verb","To make a drink by soaking or boiling things in water.","Mom likes to brew mint tea after dinner.",""],["nugget","NUG-it","noun","A small lump of something.","We found a shiny gold nugget in the gift shop sandbox.",""],["alert","uh-LURT","adjective","Watching closely and ready to act.","The alert goalie stopped the ball before it went in.","From Italian all’erta, “on the watch.”"],["vow","VOW","verb","To make a serious promise.","I vow to feed the fish every single day.",""],["clatter","KLAT-er","noun","A loud rattling noise.","The pots fell off the shelf with a clatter.",""],["applaud","uh-PLAWD","verb","To clap your hands to show you liked something.","Everyone stood up to applaud the class play.","From Latin applaudere, “to clap at.”"],["pebble","PEB-uhl","noun","A small, smooth stone.","I found a shiny pebble at the bottom of the creek.",""],["predict","pri-DIKT","verb","To say what you think will happen next.","I predict it will snow tomorrow.","From Latin praedicere, “to say before.”"],["precious","PRESH-uhs","adjective","Very special and worth a lot to someone.","This old photo of my great-grandpa is precious to our family.","From Latin pretiosus, “costly.”"],["crisp","KRISP","adjective","Firm, dry and crunchy.","I love the crisp sound of a fresh apple when I bite it.","From Latin crispus, “curly.”"],["plentiful","PLEN-tih-fuhl","adjective","More than enough.","Apples were plentiful at the farm stand this fall.","From Latin plenus, “full.”"],["swift","SWIFT","adjective","Very fast.","The swift rabbit dashed across the yard.","From Old English swift, “moving quickly.”"],["drift","DRIFT","verb","To float along slowly.","Our paper boat drifted down the creek.",""],["cascade","kas-KAYD","noun","A small waterfall, or a lot of something falling at once.","A cascade of marbles rolled across the floor.","From Italian cascare, “to fall.”"],["gleam","GLEEM","verb","To shine with a soft, bright light.","My new bike seemed to gleam in the sun.","From Old English glǣm, “bright light.”"],["croak","KROHK","verb","To make a deep, rough sound like a frog.","Frogs croak in the pond every summer night.",""],["gadget","GAJ-it","noun","A small, handy tool or machine.","Uncle Ray has a gadget that peels apples in a spiral.",""],["quiver","KWIV-er","verb","To shake with small, quick moves.","The puppy’s nose began to quiver when it smelled the bacon.",""],["fizz","FIZ","verb","To make lots of tiny bubbles with a hissing sound.","The lemonade began to fizz when Dad added soda water.",""],["beacon","BEE-kuhn","noun","A bright light that guides or warns people.","The lighthouse beacon helped the boats find their way.","From Old English bēacen, “sign.”"],["marsh","MARSH","noun","Soft, wet land with tall grasses.","Frogs croaked all night in the marsh.",""],["dune","DOON","noun","A hill of sand made by the wind.","We rolled down the sand dune at the beach.","From Dutch duin."],["dusk","DUHSK","noun","The time just after the sun sets, when it starts to get dark.","The fireflies came out at dusk.",""],["crave","KRAYV","verb","To want something very much.","On hot days, I crave ice-cold lemonade.",""],["jolly","JOL-ee","adjective","Happy and cheerful.","The jolly baker gave us each a free cookie.","From Old French jolif, “merry.”"],["cove","KOHV","noun","A small, curved bay along a shore.","Our rowboat rested in a quiet cove.",""],["adore","uh-DOR","verb","To love something or someone very much.","I adore the way my puppy wiggles when I come home.","From Latin adorare, “to worship, to pray to.”"],["knack","NAK","noun","A natural skill for doing something.","Ava has a knack for solving puzzles fast.",""],["hobby","HOB-ee","noun","Something you like to do for fun in your free time.","My hobby is collecting smooth rocks.",""],["daring","DAIR-ing","adjective","Brave and willing to take chances.","The daring squirrel leaped from tree to tree.",""],["wriggle","RIG-uhl","verb","To twist and turn your body.","The worm began to wriggle in my hand.",""],["whimper","WIM-per","verb","To make small, sad crying sounds.","The puppy will whimper if it is left alone too long.",""],["delight","dih-LYTE","noun","Great joy.","The kids squealed with delight at the new puppy.","From Latin delectare, “to charm.”"],["ornament","OR-nuh-muhnt","noun","A pretty thing used for decoration.","I made a clay ornament for our window.","From Latin ornare, “to decorate.”"],["astonish","uh-STON-ish","verb","To surprise someone a lot.","The magician’s card trick will astonish you.",""],["mumble","MUM-buhl","verb","To speak softly so the words are hard to hear.","My brother mumbled his answer with a mouth full of cereal.",""],["mend","MEND","verb","To fix something that is broken or torn.","Grandma mended the hole in my jeans.",""],["hazy","HAY-zee","adjective","Misty or not clear.","The hills looked hazy in the early morning.",""],["ripple","RIP-uhl","noun","A tiny wave on the top of water.","The pebble made a ripple across the quiet pond.",""],["bustle","BUHS-uhl","verb","To move around in a busy, hurried way.","Shoppers bustle through the market on Saturday morning.",""],["nuzzle","NUZ-uhl","verb","To gently rub or push with the nose.","The pony nuzzled my hand looking for apples.",""],["pluck","PLUK","verb","To pull something off quickly.","Grandpa plucked a ripe tomato from the vine.",""],["bonfire","BON-fire","noun","A big outdoor fire.","We roasted marshmallows over the bonfire at camp.","From Middle English bone fire, “bone fire.”"],["attic","AT-ik","noun","A room or space right under the roof of a house.","We found old toys in a box up in the attic.",""],["moist","MOYST","adjective","A little bit wet.","Grandma's banana bread is always soft and moist.",""],["humble","HUM-buhl","adjective","Not bragging about yourself.","Even after she won, Mia stayed humble and thanked her team.","From Latin humilis, “low, near the ground.”"],["burly","BUR-lee","adjective","Big, strong, and sturdy.","The burly mover lifted the piano with a friend.",""],["magnify","MAG-nuh-fy","verb","To make something look bigger than it is.","We used a lens to magnify the tiny ant on the sidewalk.","From Latin magnificare, “to make great.”"],["blizzard","BLIZ-erd","noun","A big snowstorm with strong winds.","School was closed because of the blizzard.",""],["icicle","EYE-sih-kuhl","noun","A hanging spike of ice.","A long icicle hung from the roof.",""],["muffle","MUF-uhl","verb","To make a sound quieter by covering it.","I put a pillow over the alarm clock to muffle the beeping.",""],["zest","ZEST","noun","Lots of energy and joy.","Grandma sings with such zest that we all join in.",""],["mischief","MIS-chif","noun","Playful behavior that causes small trouble.","The kitten got into mischief and unrolled all the yarn.","From Old French meschief, “misfortune.”"],["curious","KYUR-ee-uhs","adjective","Eager to learn or know about something.","The curious puppy sniffed every box in the garage.","From Latin curiosus, “careful, eager to know.”"],["bland","BLAND","adjective","Not having much taste or flavor.","The soup was bland until we added some salt.","From Latin blandus, “soft, smooth.”"],["marvel","MAR-vuhl","verb","To feel amazed by something.","We marveled at the giant rainbow over the park.","From Old French merveille, “a wonder.”"],["batch","BACH","noun","A group of things made at the same time.","Grandpa baked a batch of muffins for the bake sale.",""],["ruckus","RUK-uhs","noun","A noisy fuss.","The chickens made a big ruckus when the dog came by.",""],["discover","dis-KUHV-er","verb","To find something for the first time.","We discovered a bird’s nest in the hedge.",""],["avoid","uh-VOYD","verb","To stay away from something.","I walk around the puddle to avoid getting wet shoes.",""],["crumble","KRUHM-buhl","verb","To break into tiny pieces.","The dry cookie began to crumble in my hand.","From Old English, related to “crumb.”"],["gobble","GOB-uhl","verb","To eat fast and greedily.","Our dog will gobble his dinner in ten seconds.",""],["polish","POL-ish","verb","To rub something until it shines.","We polished the old trophy until it sparkled.","From Latin polire, “to make smooth.”"],["massive","MAS-iv","adjective","Very large and heavy.","A massive tree fell across the hiking trail.","From Latin massa, “lump.”"],["drench","DRENCH","verb","To make something soaking wet.","The sprinkler drenched my little brother.","From Old English drencan, “to give a drink.”"],["beckon","BEK-uhn","verb","To wave or nod to call someone over.","Grandma will beckon us to the kitchen when the cookies are ready.","From Old English bīecnan, “to make a sign.”"],["morsel","MOR-suhl","noun","A tiny piece of food.","The bird pecked up every morsel of bread we tossed.","From Latin morsus, “a bite.”"],["meek","MEEK","adjective","Quiet, gentle and shy.","The meek little mouse peeked out of its hole.",""],["wander","WON-der","verb","To walk around slowly with no set path.","We like to wander through the garden after dinner.",""],["aisle","ILE","noun","A path between rows of seats or shelves.","The cereal is in the third aisle of the store.",""],["snug","SNUG","adjective","Warm, cozy and comfy.","The dog curled up snug in its blanket by the fire.",""],["heap","HEEP","noun","A big, messy pile.","I jumped into a heap of autumn leaves.","From Old English hēap, “a pile.”"],["aware","uh-WAIR","adjective","Knowing about something.","I was not aware that the cat was sleeping in my backpack.","From Old English gewær, “watchful.”"],["crouch","KROWCH","verb","To bend your knees and get low to the ground.","The cat crouched in the grass, ready to pounce.",""],["banquet","BANG-kwit","noun","A big, fancy meal for many people.","Our team had a banquet at the end of the soccer season.","From French banquet, “a little bench.”"],["plush","PLUSH","adjective","Soft, thick and fluffy.","My plush pillow feels like a cloud.",""],["dodge","DOJ","verb","To move quickly out of the way.","I dodged the ball and stayed in the game.",""],["slither","SLITH-er","verb","To slide along the ground like a snake.","We watched the garden snake slither under a rock.",""],["cooperate","koh-OP-uh-rayt","verb","To work together to get something done.","We cooperated to carry the big box of books.","From Latin co-, “together,” and operari, “to work.”"],["nimble","NIM-buhl","adjective","Quick and light in the way you move.","The nimble squirrel leaped from branch to branch.",""],["soar","SOR","verb","To fly high in the air.","The eagle can soar above the treetops for hours.",""],["pester","PES-ter","verb","To keep bothering someone.","My little sister pestered me to play tag all afternoon.",""],["buoy","BOO-ee","noun","A floating marker in the water.","We swam out to the red buoy and back.",""],["bundle","BUHN-duhl","noun","A group of things tied or wrapped together.","Dad carried a bundle of sticks for the campfire.",""],["bumble","BUHM-buhl","verb","To move or act in a clumsy way.","The puppy will bumble around the yard chasing bugs.",""],["shimmer","SHIM-er","verb","To shine with a soft, shaky light.","The lake seemed to shimmer under the moon.",""],["mammoth","MAM-uhth","adjective","Very, very big.","We built a mammoth snowman taller than Dad.","From Russian mamont, the name of the giant ice age animal."],["drowsy","DROW-zee","adjective","Sleepy and tired.","The warm car ride home made me drowsy.",""],["disguise","dis-GYZE","noun","Clothes or makeup that hide who you are.","I wore a fake mustache as a disguise in the school play.",""],["feast","FEEST","noun","A big, special meal with lots of food.","Grandma made a feast for the whole family.","From Latin festa, “holidays.”"],["cinder","SIN-der","noun","A small piece of burned wood or coal.","We watched the cinders glow in the campfire.","From Old English sinder."],["mural","MYUR-uhl","noun","A big painting made right on a wall.","Our class painted a mural of the ocean in the hallway.","From Latin murus, “wall.”"],["fragile","FRAJ-uhl","adjective","Easy to break.","Hold the bird’s egg gently because it is fragile.","From Latin fragilis, “easily broken.”"],["zany","ZAY-nee","adjective","Silly and wild in a funny way.","Our class made up a zany dance for the talent show.",""],["clamber","KLAM-ber","verb","To climb using your hands and feet.","We clambered up the big rocks at the park.",""],["igloo","IG-loo","noun","A round house made of snow blocks.","We built a tiny igloo in the backyard.","From Inuktitut iglu, “house.”"],["expert","EK-spurt","noun","A person who knows a lot about something.","My sister is an expert at building paper planes.","From Latin expertus, “tried, experienced.”"],["portion","POR-shuhn","noun","A part or share of something.","Each of us got a portion of the pizza.","From Latin portio, “share.”"],["blaze","BLAYZ","noun","A big, bright fire.","The campfire grew into a cheerful blaze.",""],["vast","VAST","adjective","Very, very large.","The ocean looked vast from the top of the cliff.","From Latin vastus, “huge, empty.”"],["peer","PEER","verb","To look closely, as if it is hard to see.","We peered into the dark cave with our flashlights.",""],["blossom","BLOS-uhm","noun","A flower on a tree or plant.","A pink blossom fell from the cherry tree onto my hat.","From Old English blōstm, “flower.”"],["frisky","FRIS-kee","adjective","Playful and full of energy.","The frisky kitten chased its own tail.",""],["crinkle","KRING-kuhl","verb","To wrinkle and make a crackly sound.","The snack wrapper crinkled in my hand.",""],["fierce","FEERS","adjective","Very strong and wild.","A fierce wind blew our kite high into the sky.","From Latin ferus, “wild.”"],["crest","KREST","noun","The top of a hill or wave.","We stopped at the crest of the hill to see the lake.","From Latin crista, “tuft, plume.”"],["plod","PLOD","verb","To walk slowly with heavy steps.","We plodded home through the deep snow.",""],["invent","in-VENT","verb","To make something new that no one made before.","Jay wants to invent a robot that folds laundry.","From Latin invenire, “to come upon, find.”"],["scamper","SKAM-per","verb","To run quickly and lightly, like a small animal.","The chipmunks scamper up the tree when we get close.",""],["latch","LACH","noun","A small bar that holds a door or gate shut.","Close the latch so the goats stay in the pen.",""],["quirky","KWUR-kee","adjective","A little strange in a fun way.","My aunt has a quirky habit of naming every houseplant.",""],["amble","AM-buhl","verb","To walk slowly and in a relaxed way.","We like to amble through the park after lunch.","From Latin ambulare, “to walk.”"],["tattered","TAT-erd","adjective","Old and torn into rags.","My favorite teddy bear has a tattered ear.",""],["hollow","HOL-oh","adjective","Empty inside.","An owl lives in the hollow tree by our house.","From Old English holh, “a hole.”"],["dappled","DAP-uhld","adjective","Covered with spots of color or of light and shade.","The pony had a dappled gray coat.",""],["depart","dih-PART","verb","To leave.","The train will depart at noon.",""],["creak","KREEK","verb","To make a long, squeaky sound.","The old stairs creak when I sneak down for a snack.",""],["tangle","TANG-guhl","noun","A messy knot of things twisted together.","The kite string was one big tangle.",""],["bashful","BASH-fuhl","adjective","Shy and easily embarrassed.","The bashful kitten hid behind the couch.",""],["awning","AW-ning","noun","A cloth roof over a window or door to give shade.","We waited for the rain to stop under the shop’s awning.",""],["ancient","AYN-shuhnt","adjective","Very, very old.","We saw an ancient tree that was hundreds of years old.",""],["bellow","BEL-oh","verb","To shout in a loud, deep voice.","The coach had to bellow so we could hear him across the field.",""],["pollen","POL-uhn","noun","Yellow powder made by flowers.","The bee's legs were covered in pollen.","From Latin pollen, “fine flour.”"],["scurry","SKUR-ee","verb","To run with quick, short steps.","The mice scurry away when the cat walks in.",""],["bold","BOHLD","adjective","Brave and not afraid to take chances.","The bold kid raised her hand first to answer.","From Old English bald, “brave.”"],["chirp","CHURP","verb","To make a short, high sound like a small bird.","The baby birds chirp when their mother brings food.",""],["instant","IN-stuhnt","noun","A very short moment.","The bubble popped in an instant.","From Latin instans, “being near, pressing.”"],["tidbit","TID-bit","noun","A small, tasty bit of food or news.","I gave my dog a tidbit of cheese for sitting nicely.",""],["wilt","WILT","verb","To droop because of no water or too much heat.","The flowers will wilt if you forget to water them.",""],["observe","uhb-ZURV","verb","To watch something carefully.","We observed the caterpillar every day until it made a cocoon.","From Latin observare, “to watch over.”"],["swoop","SWOOP","verb","To dive down fast through the air.","The owl will swoop down to catch a mouse.",""],["speck","SPEK","noun","A very tiny spot or bit.","There is a speck of paint on your nose.",""],["awkward","AWK-werd","adjective","Clumsy or a little uncomfortable.","It felt awkward to dance when nobody else was dancing.",""],["splendid","SPLEN-did","adjective","Very good or very grand.","We had a splendid time at the class picnic.","From Latin splendidus, “shining.”"],["cocoon","kuh-KOON","noun","A silky case a caterpillar makes before it changes.","We watched a moth come out of its cocoon.","From French cocon."],["acrobat","AK-ruh-bat","noun","A person who does flips, jumps, and balancing tricks.","The acrobat walked on a rope high above the crowd.","From Greek akrobatēs, “one who walks on tiptoe.”"],["scrawny","SKRAW-nee","adjective","Very thin and bony.","The scrawny stray cat got fat and happy at our house.",""],["kennel","KEN-uhl","noun","A small house or shelter for a dog.","Our dog sleeps in a kennel on rainy nights.","From Latin canis, “dog.”"],["snoop","SNOOP","verb","To look around secretly where you should not.","My little sister likes to snoop in my diary.","From Dutch snoepen, “to eat sweets on the sly.”"],["chomp","CHOMP","verb","To bite or chew noisily.","The horse chomped on a crunchy carrot.",""],["sturdy","STUR-dee","adjective","Strong and hard to break.","We built a sturdy fort out of logs and boards.",""],["wobble","WOB-uhl","verb","To move from side to side in a shaky way.","My bike would wobble until I learned to pedal faster.",""],["brittle","BRIT-uhl","adjective","Hard but easy to break or snap.","The dry leaves were brittle and crunched under my boots.",""],["drab","DRAB","adjective","Dull and not colorful.","We painted the drab fence bright yellow.",""],["notch","NOCH","noun","A small cut shaped like a V.","Dad cut a notch in the stick to hold the string.",""],["clumsy","KLUHM-zee","adjective","Likely to trip, drop or bump into things.","The clumsy puppy tripped over its own big paws.",""],["grove","GROHV","noun","A small group of trees.","We had a picnic in the shade of an orange grove.","From Old English grāf, “small wood.”"],["knapsack","NAP-sak","noun","A bag you carry on your back.","I packed snacks and a map in my knapsack.","From German Knappsack, “food bag.”"],["crimson","KRIM-zuhn","adjective","Deep red.","The maple leaves turned crimson in the fall.",""],["bolt","BOHLT","verb","To run away very fast.","The cat will bolt under the bed when the doorbell rings.",""],["descend","dih-SEND","verb","To go down.","We descended the hill on our sleds.","From Latin descendere, “to climb down.”"],["dangle","DANG-guhl","verb","To hang and swing loosely.","My legs dangle off the edge of the dock.",""],["confident","KON-fi-duhnt","adjective","Sure that you can do something.","After lots of practice, I felt confident about my spelling test.","From Latin confidere, “to trust fully.”"],["juggle","JUG-uhl","verb","To toss and catch several things, keeping them in the air.","The clown can juggle four oranges at once.","From Latin joculari, “to joke.”"],["dainty","DAYN-tee","adjective","Small, pretty and delicate.","The doll had dainty little shoes.","From Latin dignitas, “worth.”"],["compass","KUHM-puhs","noun","A tool with a needle that always points north.","We used a compass to find our way on the hike.",""],["blurt","BLURT","verb","To say something suddenly without thinking.","Try not to blurt out the answer before the teacher calls on you.",""],["dawdle","DAW-duhl","verb","To move slowly and waste time.","Don’t dawdle, or we’ll be late for school!",""],["plump","PLUMP","adjective","Nicely round and full.","We picked plump strawberries from the garden.",""],["avalanche","AV-uh-lanch","noun","A huge amount of snow sliding fast down a mountain.","An avalanche of snow slid off the roof of the shed.","From French avalanche."],["yonder","YON-der","adverb","Over there, a little way off.","The barn is just yonder, past the apple trees.",""],["tuft","TUFT","noun","A small bunch of hair, grass or feathers.","The baby bird had a funny tuft of feathers on its head.",""],["jingle","JING-guhl","verb","To make a light, ringing sound.","The bells on the cat’s collar jingle when she runs.",""],["murky","MUR-kee","adjective","Dark and hard to see through.","We could not see the fish in the murky pond.",""],["budge","BUHJ","verb","To move just a little bit.","The stuck window would not budge.","From French bouger, “to stir.”"],["nestle","NES-uhl","verb","To settle into a warm, cozy spot.","The puppy nestled into the blanket on the couch.","From Old English nestlian, “to make a nest.”"],["nocturnal","nok-TUR-nuhl","adjective","Awake and active at night.","Owls are nocturnal, so they hunt while we sleep.","From Latin nocturnus, “of the night.”"],["lumpy","LUM-pee","adjective","Full of bumps or lumps.","The oatmeal was lumpy, but it tasted fine.",""],["mingle","MING-guhl","verb","To mix with others, often at a party.","At the class picnic, the parents mingled by the snack table.","From Old English mengan, “to mix.”"],["wisp","WISP","noun","A thin, light bit of something.","A wisp of smoke rose from the campfire.",""],["shabby","SHAB-ee","adjective","Old and worn out.","Our shabby old couch is still the comfiest seat in the house.",""],["explore","ik-SPLOR","verb","To look around a new place to learn about it.","We put on boots to explore the creek behind school.","From Latin explorare, “to search out.”"],["meadow","MED-oh","noun","A wide field of grass and wildflowers.","The bunnies hopped across the sunny meadow.","From Old English mǣd, “a grassy field.”"],["cling","KLING","verb","To hold on tight.","The baby koala clings to its mother’s back.","From Old English clingan."],["eager","EE-ger","adjective","Wanting to do something very much.","Max was eager to open his birthday presents.","From Old French aigre, “sharp, keen.”"],["mimic","MIM-ik","verb","To copy the way someone talks or moves.","My parrot can mimic the sound of the doorbell.","From Greek mimos, “actor.”"],["abrupt","uh-BRUHPT","adjective","Very sudden and unexpected.","The game came to an abrupt stop when it started to rain.","From Latin abruptus, “broken off.”"],["contagious","kuhn-TAY-juhs","adjective","Easily spread from one person to another.","Her giggle was so contagious that we all started laughing.","From Latin contingere, “to touch.”"],["cringe","KRINJ","verb","To pull back or make a face because something is awkward or gross.","I cringed when my baby brother tried to eat a worm.",""],["feeble","FEE-buhl","adjective","Weak and without much strength.","The baby bird gave a feeble chirp.","From Latin flebilis, “to be wept over.”"],["outrageous","owt-RAY-juhs","adjective","Very surprising and over the top.","My uncle told an outrageous story about a talking goat.",""],["barter","BAR-ter","verb","To trade things without using money.","We barter stickers for trading cards at lunch.",""],["elated","ih-LAY-tid","adjective","Very happy and excited.","Sam was elated when his team won the spelling bee.","From Latin elatus, “lifted up.”"],["antique","an-TEEK","noun","An old object that is valuable because of its age.","Grandma’s rocking chair is an antique from long ago.","From Latin antiquus, “old.”"],["fascinate","FAS-uh-nayt","verb","To hold someone’s interest very strongly.","Sea creatures fascinate my cousin.","From Latin fascinare, “to cast a spell on.”"],["investigate","in-VES-tih-gayt","verb","To look into something to find out the truth.","We will investigate who ate the last cookie.","From Latin vestigium, “footprint.”"],["reveal","rih-VEEL","verb","To show something that was hidden.","Lift the cup to reveal the hidden marble.","From Latin revelare, “to unveil.”"],["billow","BIL-oh","verb","To puff up and swell out, like a sail in the wind.","The curtains billow when the window is open.","From Old Norse bylgja, “wave.”"],["obvious","OB-vee-uhs","adjective","Easy to see or understand.","It was obvious the dog ate the cookies, because crumbs were on his nose.","From Latin obvius, “in the way.”"],["blemish","BLEM-ish","noun","A small mark or spot that spoils how something looks.","The apple was perfect except for one small blemish.",""],["blustery","BLUHS-ter-ee","adjective","Very windy.","On blustery days, my hat flies right off my head.",""],["tolerate","TOL-uh-rayt","verb","To put up with something you don’t like.","I can tolerate the cold, but I don’t like it.","From Latin tolerare, “to bear.”"],["aspire","uh-SPIRE","verb","To hope and work to become something.","I aspire to be a great chess player one day.","From Latin aspirare, “to breathe upon.”"],["dedicate","DED-i-kayt","verb","To give your time and effort to something.","She dedicated her Saturday to cleaning up the park.",""],["convince","kuhn-VINS","verb","To get someone to believe or agree with something.","I convinced my parents to let me get a hamster.",""],["vessel","VES-uhl","noun","A ship or a container that holds liquid.","The fishing vessel came back to the dock at noon.",""],["lanky","LANG-kee","adjective","Tall and thin, with long arms and legs.","The lanky colt wobbled on its long legs.",""],["exhausted","ig-ZAWS-tid","adjective","Very, very tired.","After the field trip, I was exhausted and fell asleep in the car.","From Latin exhaurire, “to draw out, drain.”"],["edible","ED-uh-buhl","adjective","Safe to eat.","The flowers on the cake were edible.","From Latin edere, “to eat.”"],["limber","LIM-ber","adjective","Able to bend and move easily.","We stretch to stay limber before dance class.",""],["gradual","GRAJ-oo-uhl","adjective","Happening slowly, a little at a time.","The gradual rise of the sun lit up the hills.","From Latin gradus, “a step.”"],["budget","BUHJ-it","noun","A plan for how to spend money.","I made a budget so I could save for a new skateboard.","From Old French bougette, “a little bag.”"],["bargain","BAR-gin","noun","Something you buy for less than it is worth.","The used bike at the yard sale was a real bargain.",""],["recite","rih-SYT","verb","To say something out loud from memory.","Each of us had to recite a short poem in class.","From Latin recitare, “to read aloud.”"],["preserve","prih-ZURV","verb","To keep something safe from harm or change.","We pressed flowers in a book to preserve them.","From Latin praeservare, “to guard beforehand.”"],["assume","uh-SOOM","verb","To think something is true without checking.","Don’t assume the test is easy just because it is short.","From Latin assumere, “to take up.”"],["plummet","PLUM-it","verb","To fall fast and far.","The paper airplane plummeted to the ground.","From Old French plommet, “lead weight.”"],["ajar","uh-JAR","adjective","Slightly open.","The door was ajar, so the cat slipped inside.",""],["evaporate","ih-VAP-uh-rayt","verb","To change from water into a gas and disappear into the air.","The puddles began to evaporate in the hot sun.","From Latin vapor, “steam.”"],["lunar","LOO-ner","adjective","Having to do with the moon.","The lunar rover drove across the moon’s dusty ground.","From Latin luna, “moon.”"],["expand","ik-SPAND","verb","To get bigger.","The balloon will expand as you blow air into it.","From Latin expandere, “to spread out.”"],["solitary","SOL-ih-tair-ee","adjective","Alone, or living alone.","A solitary owl sat on the fence post.","From Latin solus, “alone.”"],["assure","uh-SHOOR","verb","To tell someone something to take away their worry.","I assure you the dog is friendly.",""],["persevere","pur-suh-VEER","verb","To keep trying even when it is hard.","I persevered and finally learned to ride my bike.","From Latin perseverare, “to persist.”"],["bulletin","BUL-ih-tin","noun","A short news report or notice.","The school bulletin said the book fair starts Monday.",""],["sparse","SPARS","adjective","Thinly spread out, not much of it.","The grass was sparse under the big oak tree.",""],["identical","eye-DEN-tih-kuhl","adjective","Exactly the same.","The twins wore identical red sweaters.","From Latin idem, “the same.”"],["dismay","dis-MAY","noun","A sad, worried feeling when something goes wrong.","To my dismay, my ice cream fell off the cone.",""],["typical","TIP-ih-kuhl","adjective","Normal or usual.","On a typical Saturday, we go to the farmers market.",""],["volunteer","vol-uhn-TEER","verb","To offer to help without being asked or paid.","I volunteer to feed the class hamster on Fridays.",""],["cower","KOW-er","verb","To crouch down in fear.","The puppy cowered under the table during the thunderstorm.",""],["obedient","oh-BEE-dee-uhnt","adjective","Doing what you are told.","Our obedient dog sits as soon as we say so.","From Latin oboedire, “to obey.”"],["nomad","NOH-mad","noun","A person who moves from place to place instead of living in one home.","Long ago, many nomads followed their herds across the land.","From Greek nomas, “roaming to find pasture.”"],["novel","NOV-uhl","adjective","New and different.","Using a paper plate as a frisbee was a novel idea.","From Latin novus, “new.”"],["hinder","HIN-der","verb","To get in the way or slow something down.","The muddy path will hinder our bike ride.",""],["sincere","sin-SEER","adjective","Honest and real.","She gave me a sincere thank-you for helping her.","From Latin sincerus, “pure, whole.”"],["urgent","UR-juhnt","adjective","Needing to be done right away.","The vet said the sick puppy needed urgent care.",""],["utensil","yoo-TEN-suhl","noun","A tool used for cooking or eating.","A spatula is my favorite kitchen utensil.","From Latin utensilia, “useful things.”"],["swivel","SWIV-uhl","verb","To turn around on one spot.","My desk chair can swivel all the way around.",""],["sympathy","SIM-puh-thee","noun","Feeling sorry for someone who is sad or hurt.","I felt sympathy for my friend when her goldfish died.","From Greek sympatheia, “feeling with.”"],["pursue","per-SOO","verb","To chase or follow something you want.","My sister wants to pursue her dream of being a vet.","From Old French poursuir, “to follow.”"],["probable","PROB-uh-buhl","adjective","Likely to happen.","Rain is probable today, so bring a jacket.","From Latin probabilis, “provable.”"],["mobile","MOH-buhl","adjective","Able to move or be moved easily.","The library has a mobile book cart that visits each class.","From Latin mobilis, “movable.”"],["monitor","MON-ih-ter","verb","To watch or check on something over time.","We monitor the tadpoles in our class tank every morning.","From Latin monere, “to warn.”"],["determined","dih-TUR-mind","adjective","Not giving up until you reach your goal.","He was determined to learn to ride his bike.",""],["zoologist","zoh-OL-uh-jist","noun","A scientist who studies animals.","The zoologist showed us how to tell a frog from a toad.","From Greek zoion, “animal.”"],["disrupt","dis-RUHPT","verb","To interrupt or break up something.","The fire drill disrupted our spelling test.","From Latin disrumpere, “to break apart.”"],["minimum","MIN-uh-muhm","noun","The least or the smallest amount allowed.","You need a minimum of four players for this game.","From Latin minimus, “smallest.”"],["fertile","FUR-tuhl","adjective","Good for growing lots of plants.","The farmer’s fertile soil grew huge tomatoes.","From Latin fertilis, “bearing fruit.”"],["fiction","FIK-shuhn","noun","Stories that are made up.","My favorite fiction book is about a dragon who bakes pies.","From Latin fingere, “to shape, make up.”"],["jubilant","JOO-buh-luhnt","adjective","Full of joy, like after a big win.","The jubilant team danced on the field.","From Latin jubilare, “to shout for joy.”"],["deserve","dih-ZURV","verb","To earn something because of what you did.","After all that practice, you deserve a rest.",""],["prosper","PROS-per","verb","To do well and grow strong.","Our lemonade stand prospered on the hot day.","From Latin prosperare, “to make happy.”"],["resourceful","rih-SORS-fuhl","adjective","Good at finding smart ways to solve problems.","The resourceful scouts built a shelter out of branches.",""],["remedy","REM-uh-dee","noun","Something that fixes a problem or helps you heal.","Warm soup is Mom’s favorite remedy for a cold.","From Latin remedium, “cure.”"],["hurdle","HUR-duhl","noun","A bar to jump over in a race, or a problem to get past.","Jen cleared the last hurdle and won the race.",""],["foliage","FOH-lee-ij","noun","The leaves of plants and trees.","The fall foliage turned red and gold.","From Latin folium, “leaf.”"],["attain","uh-TAYN","verb","To reach or get something after effort.","She trained all year to attain her swimming badge.","From Latin attingere, “to touch, reach.”"],["inspect","in-SPEKT","verb","To look at something closely and carefully.","The coach will inspect our bikes before the ride.","From Latin inspicere, “to look into.”"],["confine","kuhn-FYNE","verb","To keep inside a small space.","We confined the puppy to the kitchen while we were out.",""],["durable","DUR-uh-buhl","adjective","Strong and able to last a long time.","These durable boots lasted through a whole muddy year.","From Latin durare, “to last.”"],["complicated","KOM-pli-kay-tid","adjective","Hard to understand because it has many parts.","The instructions for the toy robot were complicated.",""],["boisterous","BOY-ster-uhs","adjective","Loud, lively, and full of energy.","The boisterous kids cheered at the birthday party.",""],["cultivate","KUHL-tuh-vayt","verb","To grow and care for plants.","We cultivate tomatoes in our backyard garden.","From Latin colere, “to till the soil.”"],["clamor","KLAM-er","noun","A loud, steady noise of many voices.","The clamor of the lunchroom made it hard to hear.","From Latin clamare, “to cry out.”"],["horizon","huh-RY-zuhn","noun","The line where the sky seems to meet the land or sea.","We watched the boat sail toward the horizon.","From Greek horizon, “bounding circle.”"],["mascot","MAS-kot","noun","An animal, person or thing that brings a team good luck.","Our team mascot is a fuzzy blue owl.","From French mascotte, “lucky charm.”"],["compliment","KOM-pluh-muhnt","noun","Something nice you say about someone.","My friend gave me a compliment on my drawing.",""],["landmark","LAND-mark","noun","A building or place that is easy to see and helps you know where you are.","The old clock tower is a landmark in our town.",""],["barrier","BAIR-ee-er","noun","Something that blocks the way.","A fence acts as a barrier to keep the goats in the field.",""],["vary","VAIR-ee","verb","To change or be different.","The colors of the leaves vary from red to gold.",""],["strategy","STRAT-uh-jee","noun","A plan to reach a goal.","Our strategy in tag was to hide behind the slide.","From Greek strategos, “army leader.”"],["trivial","TRIV-ee-uhl","adjective","Small and not very important.","Don’t fight over something so trivial as a blue crayon.",""],["befriend","bih-FREND","verb","To become a friend to someone.","I tried to befriend the new girl in my class.",""],["misplace","mis-PLAYS","verb","To put something somewhere and forget where.","I misplaced my library card, so I checked under my bed.",""],["query","KWEER-ee","noun","A question you ask to find something out.","The librarian answered my query about dinosaur books.","From Latin quaerere, “to ask.”"],["erupt","ih-RUPT","verb","To burst out suddenly.","Our baking soda volcano began to erupt with foam.","From Latin erumpere, “to break out.”"],["compact","kuhm-PAKT","adjective","Small and packed tightly.","My compact tent fits in my backpack.",""],["scheme","SKEEM","noun","A clever plan.","We came up with a scheme to surprise Mom on her birthday.","From Greek skhema, “form, shape.”"],["interrupt","in-tuh-RUPT","verb","To stop someone while they are talking or doing something.","Please do not interrupt while your friend is reading.","From Latin interrumpere, “to break apart.”"],["ambition","am-BISH-uhn","noun","A strong wish to do or become something.","Her ambition is to become a vet and help animals.","From Latin ambitio, “a going around.”"],["pledge","PLEJ","noun","A serious promise.","We made a pledge to keep the playground clean.",""],["estimate","ES-tuh-mayt","verb","To make a careful guess about an amount.","Can you estimate how many beans are in the jar?","From Latin aestimare, “to value.”"],["genuine","JEN-yoo-in","adjective","Real and true, not fake.","Her smile was genuine when she saw the surprise.","From Latin genuinus, “natural, real.”"],["lush","LUSH","adjective","Thick, green and full of plants.","The garden was lush after a week of rain.",""],["accomplish","uh-KOM-plish","verb","To finish something you set out to do.","I want to accomplish my goal of reading ten books this summer.","From Old French acompliss-, “to complete.”"],["monotonous","muh-NOT-uh-nuhs","adjective","Boring because it never changes.","Sorting socks for an hour was monotonous.","From Greek monotonos, “of one tone.”"],["summit","SUM-it","noun","The very top of a mountain.","We ate sandwiches when we reached the summit.",""],["dependable","dih-PEN-duh-buhl","adjective","Able to be trusted to do what you said.","Our dependable neighbor feeds our fish every summer.",""],["destination","des-tuh-NAY-shuhn","noun","The place you are going to.","Our destination for the field trip was the aquarium.",""],["diligent","DIL-i-juhnt","adjective","Hard-working and careful.","The diligent student checked every math answer twice.","From Latin diligere, “to value.”"],["colony","KOL-uh-nee","noun","A group of animals of one kind that live together.","An ant colony lives under our sidewalk.",""],["witty","WIT-ee","adjective","Clever and funny with words.","My witty friend always makes the class laugh.",""],["nuisance","NOO-suhns","noun","Someone or something that is annoying.","The buzzing fly was a nuisance during dinner.","From Old French nuisance, “harm.”"],["nominate","NOM-uh-nayt","verb","To suggest someone for a job or prize.","I nominated my best friend for class helper.","From Latin nominare, “to name.”"],["reliable","rih-LY-uh-buhl","adjective","Able to be trusted every time.","My reliable alarm clock wakes me up for school.",""],["ancestor","AN-ses-ter","noun","A family member who lived long before you.","One of my ancestors was a sailor who crossed the ocean.","From Latin antecessor, “one who goes before.”"],["dwell","DWEL","verb","To live in a place.","Owls dwell in hollow trees.",""],["notion","NOH-shuhn","noun","An idea or belief.","My little brother has a notion that carrots help you see in the dark.","From Latin notio, “an idea.”"],["duplicate","DOO-pli-kayt","verb","To make an exact copy.","Dad duplicated the house key for me.","From Latin duplex, “double.”"],["conceal","kuhn-SEEL","verb","To hide.","I concealed the birthday gift under my bed.","From Latin celare, “to hide.”"],["glum","GLUM","adjective","Sad and quiet.","Ben looked glum when the game was rained out.",""],["brief","BREEF","adjective","Short, not lasting long.","The teacher gave a brief talk before recess.","From Latin brevis, “short.”"],["recede","rih-SEED","verb","To move back or away.","We watched the waves recede from the sand.","From Latin recedere, “to go back.”"],["considerate","kuhn-SID-er-it","adjective","Thoughtful about other people’s feelings.","It was considerate of you to share your umbrella.",""],["dread","DRED","verb","To feel worried about something that is coming.","I dread cleaning my room on Saturdays.",""],["devour","dih-VOWR","verb","To eat something quickly and hungrily.","The kids devoured the whole pizza.","From Latin devorare, “to swallow down.”"],["cunning","KUHN-ing","adjective","Clever in a sneaky way.","The cunning fox found a way into the chicken yard.",""],["awe","AW","noun","A feeling of wonder and amazement.","We stared in awe at the giant whale skeleton at the museum.",""],["graze","GRAYZ","verb","To eat grass in a field.","The cows graze in the meadow all morning.","From Old English grasian, from græs, “grass.”"],["flimsy","FLIM-zee","adjective","Thin and weak, easy to break or tear.","The flimsy paper plate bent under my pizza.",""],["monument","MON-yuh-muhnt","noun","A statue or building made to remember someone or something.","We visited a stone monument in the town square.","From Latin monumentum, “a reminder.”"],["previous","PREE-vee-uhs","adjective","Coming just before.","I liked the previous book in the series even more.","From Latin praevius, “going before.”"],["bystander","BY-stan-der","noun","A person who is nearby but not taking part.","A bystander saw the ball roll away and threw it back to us.",""],["wince","WINS","verb","To make a quick face because of pain.","I wince when I pull off a bandage.",""],["nautical","NAW-tih-kuhl","adjective","Having to do with ships and sailing.","My room has a nautical theme with anchors and boats.","From Greek nautes, “sailor.”"],["eclipse","ih-KLIPS","noun","When the moon or earth blocks the light of the sun or moon.","Our class wore special glasses to watch the eclipse.","From Greek ekleipsis, “a leaving out, failing.”"],["neutral","NOO-truhl","adjective","Not taking either side.","When my sisters argued, Dad stayed neutral.","From Latin neuter, “neither.”"],["scarce","SKAIRS","adjective","Hard to find because there is not much.","Water is scarce in the desert.",""],["triumph","TRY-umf","noun","A big win or success.","Finishing the puzzle was a triumph for the whole family.",""],["distract","dih-STRAKT","verb","To pull someone’s attention away.","A squirrel outside the window distracted me from my reading.","From Latin distrahere, “to pull apart.”"],["appreciate","uh-PREE-shee-ayt","verb","To be thankful for something or someone.","I appreciate my friend sharing her colored pencils.","From Latin pretium, “price.”"],["vibrate","VY-brayt","verb","To shake back and forth very fast.","The drum began to vibrate when I hit it.","From Latin vibrare, “to shake.”"],["marine","muh-REEN","adjective","Having to do with the sea.","We learned about marine animals like octopuses and seals.","From Latin mare, “sea.”"],["vague","VAYG","adjective","Not clear.","He gave a vague answer about where my cookies went.",""],["adapt","uh-DAPT","verb","To change to fit a new place or situation.","Our new puppy had to adapt to living with two cats.","From Latin adaptare, “to fit to.”"],["desperate","DES-per-it","adjective","Needing something very badly.","The thirsty dog was desperate for a drink.","From Latin desperare, “to lose hope.”"],["prompt","PROMPT","adjective","On time, without delay.","Please be prompt for the bus at 7:30.","From Latin promptus, “ready.”"],["restless","REST-lis","adjective","Not able to stay still or calm.","The dog gets restless when it hasn’t had a walk.",""],["blunder","BLUHN-der","noun","A careless or silly mistake.","Forgetting my lunch on field trip day was a big blunder.",""],["temporary","TEM-puh-rair-ee","adjective","Lasting only a short time.","The tattoo from the fair was only temporary.","From Latin tempus, “time.”"],["pastime","PAS-tym","noun","Something you do for fun.","Bird watching is my grandma's favorite pastime.",""],["acquire","uh-KWIRE","verb","To get or gain something.","I hope to acquire a few new stamps for my collection.","From Latin acquirere, “to get more.”"],["tedious","TEE-dee-uhs","adjective","Long, slow and boring.","Sorting all the buttons by color was tedious.",""],["occasion","uh-KAY-zhuhn","noun","A special time or event.","We wear our nice clothes for a big occasion like a wedding.","From Latin occasio, “opportunity.”"],["constant","KON-stuhnt","adjective","Happening all the time without stopping.","The constant drip of the faucet kept me awake.",""],["unruly","un-ROO-lee","adjective","Hard to control.","My unruly hair sticks up every morning.",""],["debris","duh-BREE","noun","Scattered pieces of something broken or left behind.","After the storm, we picked up debris in the yard.","From French débris, “broken pieces.”"],["precise","prih-SYS","adjective","Exact and careful.","Baking needs precise measuring, or the cake may flop.","From Latin praecisus, “cut short.”"],["bedraggled","bih-DRAG-uhld","adjective","Wet, messy, and dirty.","The bedraggled dog came in from the rain covered in mud.",""],["decay","dih-KAY","verb","To slowly rot or break down.","The fallen leaves decay and feed the soil.",""],["modest","MOD-ist","adjective","Not bragging about yourself.","Even after scoring three goals, Ava stayed modest.","From Latin modestus, “keeping within measure.”"],["patrol","puh-TROHL","verb","To walk around an area to keep it safe.","Crossing guards patrol the street near our school.",""],["ally","AL-eye","noun","A friend who helps you and is on your side.","My best friend is my ally when we play tag.",""],["apparent","uh-PAIR-uhnt","adjective","Easy to see or understand.","It was apparent the dog ate the cake from the crumbs on his nose.","From Latin apparere, “to appear.”"],["dismal","DIZ-muhl","adjective","Gloomy and sad.","The dismal weather kept us inside all day.","From Latin dies mali, “bad days.”"],["parallel","PAIR-uh-lel","adjective","Side by side and always the same distance apart.","Train tracks are two parallel lines.","From Greek parallelos, “beside one another.”"],["occupy","OK-yuh-py","verb","To fill a space or time.","Puzzles occupy my grandpa for hours.","From Latin occupare, “to seize.”"],["thrive","THRYV","verb","To grow strong and healthy.","Ferns thrive in shady, damp spots.",""],["maximum","MAK-suh-muhm","noun","The most or the highest amount allowed.","The elevator holds a maximum of ten people.","From Latin maximus, “greatest.”"],["forecast","FOR-kast","noun","A guess about what will happen, like the weather.","The forecast says it will snow on Saturday.",""],["tension","TEN-shuhn","noun","A tight, uneasy feeling.","You could feel the tension before the last penalty kick.",""],["overcome","oh-ver-KUM","verb","To get past a problem or fear.","I overcame my fear of the high dive this summer.",""],["intense","in-TENS","adjective","Very strong.","The heat from the oven was intense.","From Latin intensus, “stretched tight.”"],["cram","KRAM","verb","To stuff too much into a small space.","I crammed all my toys into one box.",""],["proceed","proh-SEED","verb","To go on or keep going.","After the fire drill, we proceeded with our math lesson.","From Latin procedere, “to go forward.”"],["clench","KLENCH","verb","To close or squeeze tightly.","I clenched my fists as the roller coaster climbed.",""],["detour","DEE-toor","noun","A different, longer way around.","We took a detour because the road was closed.","From French détour, “a turning aside.”"],["capable","KAY-puh-buhl","adjective","Able to do something well.","My little brother is capable of tying his own shoes now.",""],["courteous","KUR-tee-uhs","adjective","Polite and kind.","The courteous boy held the door for everyone.",""],["murmur","MUR-mer","noun","A soft, low sound.","We heard the murmur of the stream as we fell asleep in the tent.","From Latin murmur, “a humming sound.”"],["achieve","uh-CHEEV","verb","To reach a goal by working hard.","I practiced every day to achieve my yellow belt in karate.","From Old French achever, “to finish.”"],["boggle","BOG-uhl","verb","To amaze or confuse the mind.","The size of the universe can boggle your mind.",""],["wholesome","HOHL-suhm","adjective","Good for your body or mind.","Grandma makes a wholesome soup full of vegetables.",""],["potential","puh-TEN-shuhl","noun","What someone or something could become.","Our coach says every player has the potential to improve.","From Latin potentia, “power.”"],["anticipate","an-TIS-uh-payt","verb","To expect something and get ready for it.","I anticipate a long line at the ice cream truck on hot days.","From Latin anticipare, “to take before.”"],["retreat","rih-TREET","verb","To move back or away from something.","The crab will retreat into its shell if you get too close.",""],["fortunate","FOR-chuh-nit","adjective","Lucky.","We were fortunate to find a parking spot near the zoo.","From Latin fortuna, “luck.”"],["valiant","VAL-yuhnt","adjective","Very brave.","The valiant knight in the play saved the village.",""],["dialogue","DY-uh-log","noun","The words people say to each other in a story or play.","I practiced my dialogue for the class play.","From Greek dialogos, “conversation.”"],["attentive","uh-TEN-tiv","adjective","Paying close attention.","The attentive student noticed the spelling mistake on the board.",""],["vapor","VAY-per","noun","Tiny drops of water floating in the air.","Vapor rose from my hot cocoa.",""],["practical","PRAK-tih-kuhl","adjective","Useful and sensible.","Rain boots are practical for a muddy hike.","From Greek praktikos, “fit for action.”"],["conclude","kuhn-KLOOD","verb","To come to an end.","The show concluded with a big bow from the whole cast.",""],["deflate","dih-FLAYT","verb","To let the air out of something.","The pool float deflated overnight.",""],["migrate","MY-grayt","verb","To move from one place to another, often with the seasons.","Every fall, the geese migrate south for the winter.","From Latin migrare, “to move.”"],["impressive","im-PRES-iv","adjective","So good that people notice and admire it.","Her block tower was impressive, almost as tall as me.",""],["rigid","RIJ-id","adjective","Stiff and hard to bend.","The frozen towel was rigid as a board.","From Latin rigidus, “stiff.”"],["endure","en-DOOR","verb","To keep going through something hard.","We had to endure a long, hot hike to see the waterfall.","From Latin indurare, “to make hard.”"],["brainstorm","BRAYN-storm","verb","To think up lots of ideas fast.","Let’s brainstorm names for our new goldfish.",""],["accompany","uh-KUHM-puh-nee","verb","To go somewhere with someone.","My big sister will accompany me to the park.",""],["sensible","SEN-suh-buhl","adjective","Showing good sense.","Wearing boots in the mud is a sensible choice.",""],["method","METH-uhd","noun","A way of doing something.","My method for cleaning my room is to start with the floor.","From Greek methodos, “a way of going after.”"],["expedition","ek-spih-DISH-uhn","noun","A trip taken for a special purpose, like exploring.","We went on an expedition to find frogs at the pond.","From Latin expedire, “to free the feet.”"],["adjust","uh-JUHST","verb","To change something a little so it works better.","I had to adjust my bike seat because I grew taller.",""],["dormant","DOR-muhnt","adjective","Resting or not active for a while.","The tulip bulbs stay dormant under the snow.","From Latin dormire, “to sleep.”"],["alter","AWL-ter","verb","To change something.","Grandma will alter my dress so it fits just right.","From Latin alter, “other.”"],["conserve","kuhn-SURV","verb","To save something so it is not wasted.","We turn off the lights to conserve energy.","From Latin conservare, “to keep safe.”"],["navigate","NAV-ih-gayt","verb","To find your way from one place to another.","We used a map to navigate the trail.","From Latin navigare, “to sail.”"],["bewildered","bih-WIL-derd","adjective","Very confused.","The bewildered puppy did not know which way the ball went.",""],["kin","KIN","noun","Your family and relatives.","All my kin came to the summer picnic.","From Old English cyn, “family.”"],["dreary","DREER-ee","adjective","Gray, dull and gloomy.","We played board games on the dreary, rainy day.",""],["irritate","IR-ih-tayt","verb","To bother or annoy.","Loud chewing can irritate my sister.","From Latin irritare, “to stir up.”"],["bask","BASK","verb","To lie in warm sunshine and enjoy it.","Turtles bask on logs in the pond.",""],["flinch","FLINCH","verb","To pull back quickly because of surprise or pain.","I did not flinch when the nurse gave me my shot.",""],["suspend","suh-SPEND","verb","To hang something, or to stop it for a while.","We suspend the bird feeder from a high branch.","From Latin suspendere, “to hang up.”"],["permanent","PUR-muh-nuhnt","adjective","Lasting forever or for a very long time.","Use a pencil, because markers are permanent.","From Latin permanere, “to remain.”"],["contribute","kuhn-TRIB-yoot","verb","To give or add something to help.","Everyone contributed a snack to the class party.",""],["hibernate","HY-ber-nayt","verb","To sleep through the winter.","Bears hibernate in caves when it gets cold.","From Latin hibernus, “wintry.”"],["boost","BOOST","verb","To lift up or make stronger.","A good breakfast will boost your energy.",""],["swarm","SWORM","noun","A big, busy group of insects or people.","A swarm of bees buzzed around the flowers.",""],["vital","VY-tuhl","adjective","Very important and needed.","Water is vital for every living thing.","From Latin vita, “life.”"],["cautious","KAW-shuhs","adjective","Careful to stay safe.","Be cautious when you walk on the icy sidewalk.","From Latin cavere, “to take care.”"],["exaggerate","ig-ZAJ-uh-rayt","verb","To make something sound bigger or better than it really is.","My friend likes to exaggerate how big his fish was.","From Latin exaggerare, “to heap up.”"],["motto","MOT-oh","noun","A short saying that shows what someone believes.","Our class motto is “Be kind, work hard.”","From Italian motto, “word.”"],["bluff","BLUHF","verb","To pretend you know something or can do something.","He tried to bluff that he had a good card in the game.",""],["vacant","VAY-kuhnt","adjective","Empty, with no one in it.","We played ball in the vacant lot next door.","From Latin vacare, “to be empty.”"],["merge","MURJ","verb","To join together into one.","The two small streams merge to make a river.","From Latin mergere, “to dip.”"],["abode","uh-BOHD","noun","The place where someone lives.","The hamster’s cage is his cozy little abode.",""],["eavesdrop","EEVZ-drop","verb","To secretly listen to other people talking.","My little brother tried to eavesdrop on my phone call.","From eavesdrop, the ground where rain drips off a roof’s edge."],["avid","AV-id","adjective","Very eager and interested.","My cousin is an avid reader who finishes a book every week.","From Latin avidus, “eager.”"],["compassion","kuhm-PASH-uhn","noun","Caring about others who are hurting and wanting to help.","She showed compassion by sitting with the new kid at lunch.","From Latin compati, “to suffer with.”"],["collide","kuh-LYDE","verb","To crash into each other.","Two bumper cars collided, and we both laughed.","From Latin collidere, “to strike together.”"],["terrain","tuh-RAYN","noun","The kind of land in an area.","The bike trail went over rocky terrain.","From Latin terra, “earth.”"],["surplus","SUR-plus","noun","More than you need.","We had a surplus of zucchini, so we gave some to neighbors.",""],["confess","kuhn-FES","verb","To admit you did something.","I confessed that I ate the last cookie.",""],["dwindle","DWIN-duhl","verb","To get smaller little by little.","Our pile of snacks dwindled during the movie.",""],["ignite","ig-NYTE","verb","To catch fire or start burning.","Dad used a match to ignite the campfire.","From Latin ignis, “fire.”"],["authentic","aw-THEN-tik","adjective","Real and true, not fake.","The museum showed us an authentic dinosaur bone.","From Greek authentikos, “original.”"],["commute","kuh-MYOOT","verb","To travel back and forth, like to school or work.","We commute to school by bike.",""],["meander","mee-AN-der","verb","To wander slowly with no set path.","The creek meanders through the woods behind our school.","From Greek Maiandros, a river famous for its twists and turns."],["imitate","IM-ih-tayt","verb","To copy the way someone acts or sounds.","My parrot can imitate the doorbell.","From Latin imitari, “to copy.”"],["fluent","FLOO-uhnt","adjective","Able to speak a language easily and well.","Rosa is fluent in English and Spanish.","From Latin fluere, “to flow.”"],["knead","NEED","verb","To press and fold dough with your hands.","We knead the bread dough before it rises.",""],["calculate","KAL-kyuh-layt","verb","To work out an answer using math.","We calculated how many cookies each friend gets.","From Latin calculus, “small pebble.”"],["tranquil","TRANG-kwil","adjective","Quiet and peaceful.","The garden felt tranquil after everyone went home.","From Latin tranquillus, “calm.”"],["absurd","ab-SURD","adjective","Silly and not making any sense.","Wearing flippers to the grocery store would be absurd.","From Latin absurdus, “out of tune.”"],["remote","rih-MOHT","adjective","Far away from towns and people.","We camped on a remote island with no stores at all.","From Latin remotus, “moved back.”"],["befuddled","bih-FUHD-uhld","adjective","Mixed up and unable to think clearly.","The new board game rules left me befuddled.",""],["gravity","GRAV-ih-tee","noun","The force that pulls things down toward the earth.","Gravity makes the ball fall back down.","From Latin gravis, “heavy.”"],["brood","BROOD","verb","To keep thinking about something that makes you unhappy.","Don’t brood about losing the game; there is always next week.",""],["guardian","GAR-dee-uhn","noun","A person who protects or takes care of someone.","My guardian signed my field trip form.",""],["accustomed","uh-KUHS-tuhmd","adjective","Used to something.","I am accustomed to waking up early for swim practice.",""],["motivate","MOH-tih-vayt","verb","To give someone a reason to want to do something.","A sticker chart helped motivate me to practice piano.","From Latin motivus, “moving.”"],["beneath","bih-NEETH","adverb","Under or below something.","The cat sleeps on the rug beneath the table.",""],["capsize","KAP-syze","verb","To tip over in the water.","Our canoe capsized, and we swam to shore laughing.",""],["glacier","GLAY-sher","noun","A huge sheet of ice that moves very slowly.","We saw a blue glacier on our trip north.","From Latin glacies, “ice.”"],["pioneer","py-uh-NEER","noun","One of the first people to do or explore something.","The pioneers crossed the plains in covered wagons.","From Old French peonier, “foot soldier.”"],["hesitate","HEZ-ih-tayt","verb","To stop for a moment before doing something.","I hesitate before I jump into the cold pool.","From Latin haesitare, “to get stuck.”"],["omit","oh-MIT","verb","To leave something out.","Please don't omit your name from the top of your test.","From Latin omittere, “to let go.”"],["hoist","HOYST","verb","To lift something up, often with ropes.","We hoist the flag up the pole each morning.",""],["uneasy","un-EE-zee","adjective","Worried or not comfortable.","I felt uneasy walking into the new class.",""],["contrast","KON-trast","noun","A big difference between two things.","The white snow made a sharp contrast with the dark trees.",""],["refuge","REF-yooj","noun","A safe place to go.","The birds found refuge in the barn during the storm.","From Latin refugium, “a place to flee to.”"],["frequent","FREE-kwuhnt","adjective","Happening often.","We make frequent trips to the library.","From Latin frequens, “crowded, often.”"],["dejected","dih-JEK-tid","adjective","Sad and let down.","He looked dejected when the game got rained out.","From Latin deicere, “to throw down.”"],["furious","FYUR-ee-uhs","adjective","Very angry.","The cat was furious when the dog took her bed.","From Latin furia, “rage.”"],["chaos","KAY-os","noun","Total mess and confusion.","When the class hamster got loose, the room was in chaos.","From Greek khaos, “empty space.”"],["crucial","KROO-shuhl","adjective","Very, very important.","Water is crucial for plants to grow.","From Latin crux, “cross.”"],["orderly","OR-der-lee","adjective","Neat and in good order.","The kids walked to lunch in an orderly line.",""],["amateur","AM-uh-cher","noun","Someone who does something for fun, not as a job.","My uncle is an amateur bird watcher.","From French amateur, “lover,” from Latin amare, “to love.”"],["annual","AN-yoo-uhl","adjective","Happening once every year.","Our annual family picnic is in June.","From Latin annus, “year.”"],["cherish","CHAIR-ish","verb","To love and care for something a lot.","I cherish the bracelet my grandma made me.","From French cher, “dear.”"],["seldom","SEL-duhm","adverb","Not often.","It seldom snows where my cousins live.",""],["fossil","FOS-uhl","noun","The hardened remains or print of a plant or animal from long ago.","Jada found a fossil of a seashell in a rock.","From Latin fossilis, “dug up.”"],["approximate","uh-PROK-suh-mit","adjective","Close to the exact amount, but not exact.","The approximate number of jellybeans in the jar was 200.","From Latin proximus, “nearest.”"],["legend","LEJ-uhnd","noun","An old story that many people tell, which may not be fully true.","The legend says a giant fish lives in the lake.","From Latin legenda, “things to be read.”"],["mature","muh-CHUR","adjective","Acting grown up and sensible.","It was mature of you to say sorry first.","From Latin maturus, “ripe.”"],["benefit","BEN-uh-fit","noun","Something good that helps you.","One benefit of walking to school is getting fresh air.","From Latin benefactum, “a good deed.”"],["commotion","kuh-MOH-shuhn","noun","Noisy, busy confusion.","The loose goat caused a commotion at the fair.",""],["bungle","BUHNG-guhl","verb","To do something badly or clumsily.","I didn’t want to bungle my lines in the school play.",""],["robust","roh-BUST","adjective","Strong and healthy.","The robust tomato plants grew taller than me.","From Latin robustus, “strong as oak.”"],["boundary","BOWN-dree","noun","A line that marks the edge of an area.","The fence marks the boundary of our backyard.",""],["affection","uh-FEK-shuhn","noun","A warm feeling of love or liking.","My dog shows affection by licking my nose.",""],["venture","VEN-cher","verb","To go somewhere new that might be risky.","We will venture into the cave with flashlights.",""],["portable","POR-tuh-buhl","adjective","Easy to carry.","We took a portable chair to the soccer game.","From Latin portare, “to carry.”"],["concentrate","KON-suhn-trayt","verb","To focus all your attention on one thing.","I concentrate best when the room is quiet.",""],["gnaw","NAW","verb","To keep biting or chewing on something.","The beaver will gnaw on the log all day.","From Old English gnagan, “to chew.”"],["serene","suh-REEN","adjective","Calm and peaceful.","The lake was serene at sunrise.","From Latin serenus, “clear, calm.”"],["transform","trans-FORM","verb","To change completely.","A caterpillar will transform into a butterfly.",""],["embark","em-BARK","verb","To get on a ship or start something new.","We will embark on our ferry ride at noon.","From French embarquer, “to put on a boat.”"],["clarify","KLAIR-uh-fy","verb","To make something easier to understand.","The teacher clarified the rules of the game.","From Latin clarus, “clear.”"],["pivot","PIV-uht","verb","To turn on one point.","The basketball player pivoted on one foot.",""],["emerge","ih-MURJ","verb","To come out into view.","A turtle began to emerge from its shell.","From Latin emergere, “to rise out.”"],["optimist","OP-tuh-mist","noun","Someone who expects good things to happen.","Even in the rain, Leo the optimist said the sun would come out.","From Latin optimus, “best.”"],["advise","ad-VIZE","verb","To give someone ideas about what they should do.","The librarian can advise you on a good mystery book.",""],["decline","dih-KLYNE","verb","To politely say no.","I declined a second slice of cake because I was full.",""],["humid","HYOO-mid","adjective","Warm and damp, with lots of water in the air.","It was so humid that my hair puffed up.","From Latin humidus, “moist.”"],["accurate","AK-yer-it","adjective","Exactly right, with no mistakes.","My map of the playground was accurate down to the swings.","From Latin accuratus, “done with care.”"],["energetic","en-er-JET-ik","adjective","Full of energy and moving a lot.","The energetic puppy ran circles around the yard.","From Greek energeia, “activity.”"],["brawny","BRAW-nee","adjective","Big and strong, with lots of muscles.","The brawny farmer carried two hay bales at once.",""],["elegant","EL-uh-guhnt","adjective","Graceful and stylish.","The swan looked elegant as it swam.","From Latin elegans, “choosy, fine.”"],["routine","roo-TEEN","noun","The usual way you do things each day.","Brushing my teeth is part of my bedtime routine.","From French route, “road.”"],["amend","uh-MEND","verb","To change something to make it better or right.","We had to amend our club rules so everyone could join.","From Latin emendare, “to free from fault.”"],["overwhelm","oh-ver-WELM","verb","To be too much for someone to handle.","So much homework at once can overwhelm anyone.",""],["peculiar","pih-KYOOL-yer","adjective","Strange or unusual.","There was a peculiar smell coming from my brother's backpack.","From Latin peculiaris, “one's own.”"],["possess","puh-ZES","verb","To own or have something.","My cousin possesses a huge rock collection.","From Latin possidere, “to own.”"],["demolish","dih-MOL-ish","verb","To tear down completely.","Workers demolished the old shed to make room for a playground.",""],["grimace","GRIM-is","noun","A twisted face that shows you dislike something.","I made a grimace when I tasted the sour lemon.",""],["enthusiastic","en-thoo-zee-AS-tik","adjective","Very excited and interested.","Our class was enthusiastic about the science fair.",""],["wary","WAIR-ee","adjective","Careful because something might go wrong.","The deer was wary of the barking dog.",""],["criticize","KRIT-uh-syze","verb","To say what you think is wrong with something.","Our coach never criticizes us without showing us how to fix it.","From Greek kritikos, “able to judge.”"],["wilderness","WIL-der-nis","noun","Wild land where few people live.","We saw a moose on our trip to the wilderness.",""],["analyze","AN-uh-lize","verb","To study something closely to understand it.","We will analyze the leaves to find out what kind of tree it is.","From Greek analysis, “a breaking up.”"],["companion","kuhm-PAN-yuhn","noun","A friend who spends time with you.","My dog is my best hiking companion.","From Latin com-, “with,” and panis, “bread.”"],["resemble","rih-ZEM-buhl","verb","To look like someone or something.","My baby brother starts to resemble Dad more each month.",""],["mystify","MIS-tuh-fy","verb","To confuse someone completely.","The magic trick mystified everyone at the party.",""],["haven","HAY-vuhn","noun","A safe, peaceful place.","The tree house is my haven on busy days.","From Old English hæfen, “harbor.”"],["pact","PAKT","noun","A promise or deal between people.","My friends and I made a pact to read one book a week.","From Latin pactum, “agreement.”"],["obtain","uhb-TAYN","verb","To get something.","You need to obtain a permission slip before the field trip.","From Latin obtinere, “to hold.”"],["outspoken","owt-SPOH-kuhn","adjective","Saying what you think in a clear, bold way.","Maya is outspoken about keeping the park clean.",""],["reckless","REK-lis","adjective","Not careful about danger.","Riding your bike without a helmet is reckless.",""],["generous","JEN-er-uhs","adjective","Happy to share and give.","Leo was generous and shared his crayons with everyone.","From Latin generosus, “of noble birth.”"],["locate","LOH-kayt","verb","To find where something is.","Can you locate our town on the map?","From Latin locus, “place.”"],["dabble","DAB-uhl","verb","To try something a little, just for fun.","I like to dabble in painting on weekends.",""],["ascend","uh-SEND","verb","To go up or climb.","We watched the hot air balloon ascend into the sky.","From Latin ascendere, “to climb up.”"],["abandon","uh-BAN-duhn","verb","To leave something behind and not come back for it.","We had to abandon our sandcastle when the tide came in.","From Old French abandoner, “to give up.”"],["construct","kuhn-STRUHKT","verb","To build.","We constructed a birdhouse out of wood.","From Latin construere, “to pile up.”"],["habitat","HAB-ih-tat","noun","The natural home of a plant or animal.","The pond is a habitat for frogs and ducks.","From Latin habitat, “it lives.”"],["curfew","KUR-fyoo","noun","A time you must be home or in bed.","My curfew at sleepovers is ten o’clock.","From French couvre-feu, “cover the fire.”"],["reluctant","rih-LUK-tuhnt","adjective","Not wanting to do something.","I was reluctant to jump into the cold pool.","From Latin reluctari, “to struggle against.”"],["consequence","KON-si-kwens","noun","Something that happens because of something else.","One consequence of staying up late is feeling grumpy.",""],["appeal","uh-PEEL","verb","To be interesting or pleasing to someone.","Stories about dragons really appeal to my brother.",""],["fidget","FIJ-it","verb","To move around because you cannot sit still.","I fidget in my chair when I am waiting for lunch.",""],["scavenge","SKAV-inj","verb","To search for useful things others threw away.","Raccoons scavenge for snacks in the trash cans.",""],["obstacle","OB-stuh-kuhl","noun","Something that blocks your way.","We climbed over every obstacle in the backyard course.","From Latin obstaculum, “a hindrance.”"],["opponent","uh-POH-nuhnt","noun","The person or team you play against.","My opponent in chess was my clever cousin.","From Latin opponere, “to set against.”"],["immense","ih-MENS","adjective","Huge and very large.","The whale was immense next to our little boat.","From Latin immensus, “not measured.”"],["bountiful","BOWN-tih-fuhl","adjective","Plenty of something, more than enough.","Our garden gave us a bountiful crop of tomatoes.",""],["perplexed","per-PLEKST","adjective","Very confused.","I was perplexed by the tricky riddle.","From Latin perplexus, “tangled.”"],["spectacle","SPEK-tuh-kuhl","noun","An amazing thing to see.","The fireworks show was a real spectacle.","From Latin spectare, “to watch.”"],["drastic","DRAS-tik","adjective","Big and sudden.","Cutting my long hair short was a drastic change.",""],["rival","RY-vuhl","noun","Someone you compete against.","Our team’s rival won the spelling bee last year.","From Latin rivalis, “one who shares a stream.”"],["stern","STURN","adjective","Strict and serious.","The coach gave us a stern look when we were late.",""],["chide","CHYDE","verb","To gently scold.","Mom chided me for leaving my shoes on the stairs.",""],["burden","BUR-duhn","noun","A heavy load to carry.","My overstuffed backpack felt like a burden on the way home.",""],["numerous","NOO-mer-uhs","adjective","Many; a lot.","There were numerous shells on the beach after the storm.","From Latin numerus, “number.”"],["yield","YEELD","verb","To give way, or to produce something.","Our little apple tree will yield a whole basket this fall.",""],["arid","AIR-id","adjective","Very dry, with little rain.","Cactuses grow well in arid places.","From Latin aridus, “dry.”"],["haul","HAWL","verb","To pull or carry something heavy.","We had to haul the wagon full of pumpkins up the hill.",""],["persuade","per-SWAYD","verb","To get someone to agree with you.","I persuaded Mom to let us have pancakes for dinner.","From Latin persuadere, “to urge.”"],["dispute","dih-SPYOOT","noun","An argument or disagreement.","We settled our dispute over the swing by taking turns.",""],["majestic","muh-JES-tik","adjective","Grand and beautiful in a way that makes you feel small.","The majestic mountains were covered in snow.","From Latin majestas, “greatness.”"],["browse","BROWZ","verb","To look through things in a relaxed way.","I like to browse the shelves at the library.",""],["extinct","ik-STINGKT","adjective","No longer living anywhere on Earth.","Dinosaurs have been extinct for millions of years.","From Latin exstinguere, “to put out.”"],["realm","RELM","noun","A kingdom, or an area of something.","In our game, the dragon guards the snowy realm.",""],["outskirts","OWT-skurts","noun","The edges of a town.","Our farm is on the outskirts of the city.",""],["flexible","FLEK-suh-buhl","adjective","Able to bend easily, or able to change plans.","A gymnast has to be very flexible.","From Latin flectere, “to bend.”"],["thorough","THUR-oh","adjective","Careful and complete.","Dad did a thorough job cleaning the fish tank.",""],["devise","dih-VYZE","verb","To think up a plan or idea.","We devised a plan to surprise Mom on her birthday.",""],["muster","MUS-ter","verb","To gather up, like courage or strength.","I mustered the courage to sing in the talent show.","From Latin monstrare, “to show.”"],["plead","PLEED","verb","To beg for something.","The puppy's eyes seemed to plead for a treat.",""],["bleary","BLEER-ee","adjective","Tired and blurry, like sleepy eyes.","My bleary eyes could barely see the clock in the morning.",""],["visible","VIZ-uh-buhl","adjective","Able to be seen.","The moon was visible even in the afternoon.","From Latin videre, “to see.”"],["baffle","BAF-uhl","verb","To confuse someone completely.","This riddle will baffle even the grown-ups.",""],["quaint","KWAYNT","adjective","Old-fashioned in a charming way.","We stayed in a quaint cottage with a red door.",""],["aloof","uh-LOOF","adjective","Not friendly, keeping to yourself.","Our new cat stayed aloof for the first few days.",""],["wisdom","WIZ-duhm","noun","Good sense that comes from knowing a lot.","My grandpa shares his wisdom while we fish.",""],["prior","PRY-er","adjective","Coming before.","I had a prior plan, so I couldn't go to the movie.","From Latin prior, “earlier.”"],["neglect","nih-GLEKT","verb","To not take care of something.","If you neglect your plant, it will droop and turn brown.","From Latin neglegere, “to not pick up.”"],["banter","BAN-ter","noun","Friendly, joking talk.","The banter between my parents makes car rides fun.",""],["improvise","IM-pruh-vyze","verb","To make something up on the spot.","When the drum broke, we had to improvise with a bucket.","From Latin improvisus, “not seen ahead.”"],["pedestrian","puh-DES-tree-uhn","noun","A person walking, not riding.","Drivers must stop for pedestrians at the crosswalk.","From Latin pedester, “on foot.”"],["cuisine","kwi-ZEEN","noun","A style of cooking.","Our class tasted foods from many cuisines at the culture fair.","From French cuisine, “kitchen.”"],["paraphrase","PAIR-uh-frayz","verb","To say something again in your own words.","Can you paraphrase the story for the class?","From Greek paraphrasis, “telling in other words.”"],["segment","SEG-muhnt","noun","One part of something.","I gave my friend a segment of my orange.","From Latin segmentum, “a piece cut off.”"],["noteworthy","NOHT-wur-thee","adjective","Important enough to notice.","The science fair had a few noteworthy projects.",""],["mythical","MITH-ih-kuhl","adjective","Found only in old stories, not real life.","The unicorn is a mythical creature.","From Greek mythos, “story.”"],["dissolve","dih-ZOLV","verb","To mix into a liquid and disappear.","Sugar dissolves quickly in hot cocoa.","From Latin dissolvere, “to loosen apart.”"],["coarse","KORS","adjective","Rough and bumpy to touch.","The coarse sand scratched my bare feet.",""],["abridge","uh-BRIJ","verb","To make a book or story shorter.","The publisher chose to abridge the long novel for young readers.",""],["valid","VAL-id","adjective","True, fair or acceptable.","You made a valid point about sharing the swing.","From Latin validus, “strong.”"],["labyrinth","LAB-uh-rinth","noun","A maze with many winding paths.","We got lost in the corn labyrinth at the farm.","From Greek labyrinthos, “maze.”"],["pristine","pris-TEEN","adjective","Perfectly clean, like new.","The fresh snow was pristine until the dog ran through it.","From Latin pristinus, “former.”"],["prevail","prih-VAYL","verb","To win or succeed in the end.","Our team prevailed in the tug of war.","From Latin praevalere, “to be stronger.”"],["distort","dih-STORT","verb","To twist something out of its normal shape.","The funhouse mirror distorted my face.","From Latin distorquere, “to twist apart.”"],["plausible","PLAW-zuh-buhl","adjective","Possible and easy to believe.","His excuse for being late sounded plausible.","From Latin plausibilis, “worthy of applause.”"],["adorn","uh-DORN","verb","To decorate with pretty things.","We adorn the tree with paper stars every winter.","From Latin adornare, “to decorate.”"],["stagnant","STAG-nuhnt","adjective","Not moving or flowing, and often smelly.","Mosquitoes love stagnant puddles.","From Latin stagnum, “pool.”"],["tactic","TAK-tik","noun","A move or method used to reach a goal.","Passing to the open player is a smart tactic.","From Greek taktikos, “of arranging.”"],["ovation","oh-VAY-shuhn","noun","Loud clapping from a crowd.","The choir got a standing ovation.","From Latin ovatio, “rejoicing.”"],["gauge","GAYJ","verb","To measure or judge something.","We tried to gauge how deep the creek was with a stick.",""],["evade","ih-VAYD","verb","To get away from or avoid.","The rabbit tried to evade the dog by zigzagging.","From Latin evadere, “to get away.”"],["detach","dih-TACH","verb","To separate or unhook.","I detached the trailer from my toy truck.",""],["contrary","KON-trer-ee","adjective","Completely opposite.","Contrary to what I expected, the test was easy.","From Latin contra, “against.”"],["buffer","BUHF-er","noun","Something that protects by coming between two things.","The bushes act as a buffer between our yard and the road.",""],["colleague","KOL-eeg","noun","A person you work with.","Mom had lunch with a colleague from her office.",""],["restore","rih-STOR","verb","To bring something back to how it was.","Dad worked all summer to restore the old bike.","From Latin restaurare, “to rebuild.”"],["metamorphosis","met-uh-MOR-fuh-sis","noun","A big change in form, like a caterpillar becoming a butterfly.","We watched the metamorphosis of our tadpoles into frogs.","From Greek metamorphosis, “change of shape.”"],["mirage","mih-RAHZH","noun","Something you think you see that is not really there.","On the hot road, the shiny puddle was only a mirage.","From French mirer, “to look at.”"],["amenity","uh-MEN-ih-tee","noun","Something that makes a place more pleasant or comfy.","The hotel’s best amenity was the pool with a slide.","From Latin amoenus, “pleasant.”"],["legible","LEJ-uh-buhl","adjective","Clear enough to read.","Please make your handwriting legible.","From Latin legere, “to read.”"],["orient","OR-ee-ent","verb","To figure out where you are or which way to go.","We used the sun to orient ourselves on the hike.","From Latin oriens, “rising,” as in the rising sun in the east."],["flourish","FLUR-ish","verb","To grow strong and healthy.","The tomato plants flourish in the sunny window.","From Latin florere, “to bloom.”"],["bestow","bih-STOH","verb","To give something as an honor or gift.","The principal will bestow a medal on the spelling bee winner.",""],["distinct","dih-STINGKT","adjective","Clearly different or easy to notice.","Each zebra has a distinct pattern of stripes.",""],["defiant","dih-FY-uhnt","adjective","Boldly refusing to obey.","The defiant cat would not get off the kitchen table.",""],["deft","DEFT","adjective","Quick and skillful with your hands.","With deft fingers, she folded a paper crane.",""],["annex","AN-eks","noun","An extra building added on or nearby.","Art class is held in the school annex.","From Latin annectere, “to tie to.”"],["oblivious","uh-BLIV-ee-uhs","adjective","Not noticing what is going on around you.","Reading her book, Zoe was oblivious to the noise.","From Latin oblivisci, “to forget.”"],["dubious","DOO-bee-uhs","adjective","Unsure or doubtful.","I was dubious about the green smoothie, but it was tasty.","From Latin dubius, “doubtful.”"],["calamity","kuh-LAM-i-tee","noun","A sudden disaster or terrible event.","Dropping the birthday cake felt like a calamity.",""],["gourmet","goor-MAY","adjective","Fancy and made with great care, often about food.","Dad made gourmet pancakes with berries and whipped cream.","From French gourmet, “wine taster.”"],["inquire","in-KWYRE","verb","To ask about something.","Mom called to inquire about swim lessons.","From Latin inquirere, “to seek into.”"],["debate","dih-BAYT","noun","A formal talk where people argue different sides.","Our class held a debate about whether recess should be longer.",""],["dispatch","dih-SPACH","verb","To send off quickly.","The coach dispatched a runner to get the extra balls.",""],["apparel","uh-PAIR-uhl","noun","Clothing.","The store sells sports apparel like jerseys and socks.",""],["comprehend","kom-pri-HEND","verb","To understand.","I read the page twice to comprehend it.","From Latin comprehendere, “to grasp.”"],["mediocre","mee-dee-OH-ker","adjective","Just okay; not very good.","The pizza was mediocre, but the company was great.","From Latin mediocris, “middling.”"],["sufficient","suh-FISH-uhnt","adjective","Enough.","Two sandwiches are sufficient for our hike.",""],["obsolete","ob-suh-LEET","adjective","No longer used because something better came along.","Dad says his old music player is obsolete.","From Latin obsoletus, “worn out.”"],["diminish","dih-MIN-ish","verb","To become smaller or less.","The puddle diminished in the hot sun.",""],["mandatory","MAN-duh-tor-ee","adjective","Something you must do; not a choice.","Wearing a helmet is mandatory at the skate park.","From Latin mandare, “to order.”"],["feasible","FEE-zuh-buhl","adjective","Possible to do.","Is it feasible to build a sled from a cardboard box?","From French faisable, “doable.”"],["exceed","ik-SEED","verb","To go beyond a limit or amount.","Our bake sale will exceed its goal if we sell ten more muffins.","From Latin excedere, “to go beyond.”"],["gullible","GUL-uh-buhl","adjective","Easy to fool.","My gullible brother believed the moon was made of cheese.","From gull, an old word meaning “to trick.”"],["deter","dih-TUR","verb","To stop someone from doing something by making them worry.","The scarecrow deters birds from eating the corn.","From Latin deterrere, “to frighten off.”"],["kinetic","kih-NET-ik","adjective","Having to do with motion.","A rolling ball has kinetic energy.","From Greek kinein, “to move.”"],["partial","PAR-shuhl","adjective","Only part, not the whole.","We saw a partial eclipse of the sun.","From Latin pars, “part.”"],["abstain","ab-STAYN","verb","To choose not to do or have something.","I will abstain from candy until after dinner.","From Latin abstinere, “to hold back.”"],["anecdote","AN-ik-doht","noun","A short, interesting story about something that happened.","Grandpa told an anecdote about his first bike.","From Greek anekdota, “things not published.”"],["quell","KWEL","verb","To calm or stop something.","Mom told a funny story to quell my fear of the dark.",""],["prominent","PROM-uh-nuhnt","adjective","Easy to see or well known.","The tall clock tower is prominent in our town.","From Latin prominere, “to stick out.”"],["spontaneous","spon-TAY-nee-uhs","adjective","Done all of a sudden, without a plan.","We had a spontaneous dance party in the kitchen.","From Latin sponte, “of one’s own free will.”"],["insight","IN-syte","noun","A clear, deep understanding.","Grandpa had a great insight about why the bread did not rise.",""],["frugal","FROO-guhl","adjective","Careful not to waste money or things.","Being frugal, Grandpa saves every rubber band.","From Latin frugalis, “thrifty.”"],["advocate","AD-vuh-kuht","noun","A person who speaks up for someone or something.","My aunt is an advocate for animal shelters.","From Latin advocatus, “one called to help.”"],["coincide","koh-in-SYDE","verb","To happen at the same time.","This year my birthday coincides with the first day of spring.",""],["barren","BAIR-uhn","adjective","Empty, with few or no plants.","The barren hill had only rocks and dirt.",""],["elaborate","ih-LAB-er-it","adjective","Having lots of careful parts and details.","Mia built an elaborate fort with tunnels and flags.","From Latin elaborare, “to work out.”"],["whim","WIM","noun","A sudden wish or idea.","On a whim, we painted the doghouse purple.",""],["resilient","rih-ZIL-yuhnt","adjective","Able to bounce back after something hard.","Our resilient team kept playing after losing the first game.","From Latin resilire, “to spring back.”"],["belittle","bih-LIT-uhl","verb","To make someone or something seem unimportant.","Good teammates never belittle each other’s mistakes.",""],["terminate","TUR-muh-nayt","verb","To bring something to an end.","The bus line will terminate at the last stop by the zoo.","From Latin terminus, “end, boundary.”"],["profound","pruh-FOWND","adjective","Very deep or strong in meaning.","The book had a profound effect on how I treat animals.","From Latin profundus, “deep.”"],["superb","soo-PURB","adjective","Excellent, of the best kind.","The pizza at the fair was superb.","From Latin superbus, “proud, grand.”"],["vulnerable","VUL-ner-uh-buhl","adjective","Easy to hurt or harm.","Baby turtles are vulnerable on their way to the sea.","From Latin vulnus, “wound.”"],["prohibit","proh-HIB-it","verb","To not allow something by a rule.","The pool rules prohibit running on the deck.","From Latin prohibere, “to hold back.”"],["erode","ih-ROHD","verb","To wear away slowly.","Waves erode the sand on the beach a little every day.","From Latin erodere, “to gnaw away.”"],["narrate","NAIR-ayt","verb","To tell a story out loud.","Grandma narrated the story while we acted it out.","From Latin narrare, “to tell.”"],["abyss","uh-BIS","noun","A very deep hole or gap that seems to have no bottom.","The cave looked like a dark abyss.","From Greek abyssos, “bottomless.”"],["rebuke","rih-BYOOK","verb","To tell someone sharply that they did wrong.","The ref had to rebuke a player for pushing.",""],["astute","uh-STOOT","adjective","Smart and quick to notice things.","The astute detective in my book spotted the tiny clue.","From Latin astutus, “crafty.”"],["acquaint","uh-KWAYNT","verb","To make yourself or someone familiar with something.","The tour will acquaint new students with the school.",""],["accumulate","uh-KYOO-myuh-layt","verb","To gather or pile up over time.","Dust will accumulate under the bed if we don’t sweep.","From Latin cumulus, “heap.”"],["loiter","LOY-ter","verb","To stand around without a real reason.","Kids loiter by the ice cream truck, hoping for a treat.",""],["infinite","IN-fuh-nit","adjective","Without any end.","The number of stars seems infinite.","From Latin infinitus, “without end.”"],["pinnacle","PIN-uh-kuhl","noun","The highest point.","Winning the spelling bee was the pinnacle of my year.","From Latin pinnaculum, “little peak.”"],["parody","PAIR-uh-dee","noun","A funny copy of something to make people laugh.","We wrote a parody of a nursery rhyme about our teacher's cat.","From Greek parodia, “a mocking song.”"],["diagnose","DY-uhg-nohs","verb","To find out what is causing a problem.","The vet diagnosed my cat’s sore paw.",""],["tangible","TAN-juh-buhl","adjective","Real enough to touch or see.","Our garden gave us tangible proof that hard work pays off.","From Latin tangere, “to touch.”"],["propel","pruh-PEL","verb","To push something forward.","The wind propelled our little sailboat across the pond.","From Latin propellere, “to drive forward.”"],["plight","PLYT","noun","A hard or sad situation.","The class raised money to help with the plight of the shelter dogs.",""],["blight","BLITE","noun","A disease that makes plants dry up and die.","A blight ruined the tomato plants in our garden.",""],["deduce","dih-DOOS","verb","To figure out from clues.","I deduced that the dog ate my sandwich from the crumbs on his nose.","From Latin deducere, “to lead down.”"],["unkempt","un-KEMPT","adjective","Messy and not cared for.","The unkempt garden was full of weeds.",""],["aspect","AS-pekt","noun","One part or side of something.","My favorite aspect of camp is swimming in the lake.","From Latin aspicere, “to look at.”"],["secluded","sih-KLOO-did","adjective","Hidden away from other people.","We found a secluded spot by the creek for our picnic.",""],["suppress","suh-PRES","verb","To hold something back.","I tried to suppress a giggle during the quiet test.","From Latin supprimere, “to press down.”"],["adjacent","uh-JAY-suhnt","adjective","Right next to something.","The library is adjacent to the gym.","From Latin adiacere, “to lie near.”"],["proximity","prok-SIM-ih-tee","noun","Being close to something.","Our house is in close proximity to the park.","From Latin proximus, “nearest.”"],["eccentric","ik-SEN-trik","adjective","Odd or unusual in a fun way.","Our eccentric neighbor walks his cat on a leash.","From Greek ekkentros, “out of the center.”"],["amass","uh-MAS","verb","To collect a large amount of something.","Over the years, she managed to amass a huge rock collection.",""],["grueling","GROO-uh-ling","adjective","Very hard and tiring.","The grueling hike up the hill took two hours.",""],["culprit","KUHL-prit","noun","The one who did something wrong.","The culprit who ate the cupcakes had frosting on his whiskers.",""],["adversary","AD-ver-sair-ee","noun","Someone you compete against.","My chess adversary was my best friend.",""],["prodigy","PROD-uh-jee","noun","A young person with amazing talent.","The chess prodigy beat her coach at age nine.","From Latin prodigium, “a marvel.”"],["naive","ny-EEV","adjective","Trusting too easily, without much experience.","It was naive to think the cat would leave the fish alone.","From French naïf, “natural.”"],["berate","bih-RAYT","verb","To scold someone loudly and angrily.","The coach did not berate us for losing; he told us to keep trying.",""],["pseudonym","SOO-duh-nim","noun","A made-up name a writer uses.","The author wrote her mystery books under a pseudonym.","From Greek pseudonymos, “falsely named.”"],["bizarre","bih-ZAR","adjective","Very strange or odd.","My dog has a bizarre habit of sleeping in the bathtub.",""],["strenuous","STREN-yoo-uhs","adjective","Needing lots of hard work or effort.","Moving all the books was a strenuous job.",""],["amiable","AY-mee-uh-buhl","adjective","Friendly and pleasant.","The amiable bus driver waves to every kid.","From Latin amicabilis, “friendly.”"],["malfunction","mal-FUNGK-shuhn","noun","A problem that stops a machine from working right.","A malfunction in the printer jammed all our art pages.",""],["avert","uh-VURT","verb","To turn away or to stop something bad from happening.","Quick thinking helped us avert a spill when the cup tipped.","From Latin avertere, “to turn away.”"],["perspective","per-SPEK-tiv","noun","A way of seeing or thinking about something.","From my little brother's perspective, bedtime is way too early.","From Latin perspicere, “to look through.”"],["conspicuous","kuhn-SPIK-yoo-uhs","adjective","Easy to see or notice.","My bright orange hat was conspicuous in the crowd.","From Latin conspicere, “to look at.”"],["miniature","MIN-ee-uh-cher","adjective","Very small; a tiny copy of something bigger.","My grandpa built a miniature train set in the basement.","From Italian miniatura, a small painting in an old book."],["chronic","KRON-ik","adjective","Lasting a long time or happening again and again.","My chronic habit of forgetting my lunch is a family joke.","From Greek khronos, “time.”"],["lenient","LEE-nee-uhnt","adjective","Not strict, more forgiving.","The lenient librarian let us keep the book an extra week.","From Latin lenis, “soft, gentle.”"],["abundant","uh-BUHN-duhnt","adjective","More than enough; plenty.","Blackberries were abundant along the trail, so we filled two buckets.","From Latin abundare, “to overflow.”"],["zeal","ZEEL","noun","Great eagerness for something.","She cleaned her room with surprising zeal.","From Greek zelos, “eager rivalry.”"],["assert","uh-SURT","verb","To say something firmly and with confidence.","She asserted that her paper airplane would fly the farthest.","From Latin asserere, “to claim.”"],["retrieve","rih-TREEV","verb","To go get something and bring it back.","Our dog loves to retrieve sticks from the lake.",""],["rotate","ROH-tayt","verb","To turn around a center point.","The Earth takes one day to rotate once.","From Latin rota, “wheel.”"],["mesmerize","MEZ-muh-ryz","verb","To hold someone's attention so they can't look away.","The fireflies mesmerized us on the summer night.",""],["pertinent","PUR-tuh-nuhnt","adjective","Having to do with the subject at hand.","Please ask questions that are pertinent to the lesson.","From Latin pertinere, “to relate to.”"],["apprehensive","ap-rih-HEN-siv","adjective","Worried that something bad might happen.","I felt apprehensive about my first day at a new school.",""],["idiom","ID-ee-uhm","noun","A phrase that means something different from its words.","“It’s raining cats and dogs” is an idiom.","From Greek idioma, “a special way of speaking.”"],["designate","DEZ-ig-nayt","verb","To choose someone or something for a job.","The teacher designated me as line leader.",""],["commence","kuh-MENS","verb","To begin.","The race will commence when the whistle blows.",""],["onset","ON-set","noun","The beginning of something.","With the onset of winter, the birds flew south.",""],["cumbersome","KUHM-ber-suhm","adjective","Big, heavy and hard to carry.","The cumbersome cello case barely fit in the car.",""],["diverse","dih-VURS","adjective","Made up of many different kinds.","The reef is home to a diverse group of fish.",""],["acknowledge","ak-NOL-ij","verb","To admit or show that you notice something.","She waved to acknowledge her friends in the crowd.",""],["taut","TAWT","adjective","Pulled tight.","Keep the kite string taut so it stays up.",""],["lavish","LAV-ish","adjective","Rich, fancy and generous.","The wedding had a lavish dessert table.",""],["balk","BAWK","verb","To stop and refuse to go on.","My horse will balk at jumping over the puddle.",""],["proficient","pruh-FISH-uhnt","adjective","Very good at something from practice.","After a year of lessons, I'm proficient at the guitar.","From Latin proficere, “to make progress.”"],["deceive","dih-SEEV","verb","To trick someone into believing something false.","The stick bug deceives birds by looking like a twig.","From Latin decipere, “to catch, trick.”"],["punctual","PUNGK-choo-uhl","adjective","Always on time.","Our bus driver is so punctual you could set a clock by her.","From Latin punctum, “point.”"],["quota","KWOH-tuh","noun","A set amount you must reach or can’t go over.","My reading quota is twenty pages a night.","From Latin quota pars, “how great a part.”"],["loathe","LOHTH","verb","To dislike something very much.","I loathe wet socks.","From Old English lāthian, “to hate.”"],["intricate","IN-trih-kit","adjective","Having many small parts that fit together.","The spider spun an intricate web.","From Latin intricare, “to tangle.”"],["competent","KOM-pi-tuhnt","adjective","Having the skill to do something well.","She is a competent swimmer, so she can go in the deep end.",""],["convey","kuhn-VAY","verb","To share or get an idea across.","Her big smile conveyed how happy she was.",""],["burnish","BUR-nish","verb","To rub something until it is smooth and shiny.","We burnish the old coins with a soft cloth.",""],["elusive","ih-LOO-siv","adjective","Hard to find or catch.","The elusive fox only came out at dusk.","From Latin eludere, “to escape by tricks.”"],["bias","BY-uhs","noun","Unfairly favoring one side over another.","The judge of the bake-off tried hard to have no bias.",""],["discard","dih-SKARD","verb","To throw away.","We discarded the broken crayons.",""],["maneuver","muh-NOO-ver","verb","To move skillfully around things.","She maneuvered her scooter around the puddles.","From French manœuvre, “handwork.”"],["aquatic","uh-KWAT-ik","adjective","Living or growing in water.","Frogs, fish, and turtles are aquatic animals.","From Latin aqua, “water.”"],["decipher","dih-SY-fer","verb","To figure out something hard to read.","We deciphered the secret code in the treasure hunt.",""],["wane","WAYN","verb","To get smaller or weaker little by little.","My interest in the game began to wane after an hour.",""],["depict","dih-PIKT","verb","To show in a picture or in words.","The mural depicts animals of the rainforest.","From Latin depingere, “to paint.”"],["excavate","EK-skuh-vayt","verb","To dig out and uncover.","Scientists excavate old bones from the desert.","From Latin excavare, “to hollow out.”"],["modify","MOD-uh-fy","verb","To change something a little.","We modified the recipe to use less sugar.","From Latin modificare, “to limit.”"],["pandemonium","pan-duh-MOH-nee-uhm","noun","Wild noise and confusion.","When the class hamster escaped, there was pandemonium.",""],["antagonist","an-TAG-uh-nist","noun","The character who works against the hero in a story.","The antagonist in the movie was a sneaky fox.","From Greek antagōnistēs, “opponent.”"],["skeptical","SKEP-tih-kuhl","adjective","Not quick to believe something.","I was skeptical when my brother said he saw a unicorn.","From Greek skeptikos, “thoughtful, inquiring.”"],["morale","muh-RAL","noun","How hopeful and cheerful a group feels.","Team morale went up after our first win.","From French moral, “spirit.”"],["proclaim","proh-KLAYM","verb","To announce something loudly and proudly.","My sister proclaimed herself the queen of board games.","From Latin proclamare, “to cry out.”"],["solemn","SOL-uhm","adjective","Very serious and quiet.","The class was solemn as we said goodbye to our teacher.",""],["altitude","AL-tih-tood","noun","How high something is above the ground or sea.","The plane flew at a very high altitude.","From Latin altus, “high.”"],["abrasive","uh-BRAY-siv","adjective","Rough enough to scrape, or harsh in manner.","Sandpaper is abrasive, so it smooths the wood.","From Latin abradere, “to scrape off.”"],["tamper","TAM-per","verb","To mess with something you should not touch.","Please don’t tamper with the thermostat.",""],["surmount","ser-MOWNT","verb","To get past a problem.","She worked hard to surmount her fear of swimming.",""],["finicky","FIN-ih-kee","adjective","Very fussy about what you like.","Our finicky cat only eats fish on Fridays.",""],["drought","DROWT","noun","A long time with little or no rain.","During the drought, we saved bathwater for the plants.",""],["relish","REL-ish","verb","To enjoy something a lot.","I relish the first snow day of winter.",""],["credible","KRED-uh-buhl","adjective","Able to be believed or trusted.","We used credible websites for our science report.","From Latin credere, “to believe.”"],["swindle","SWIN-duhl","verb","To cheat someone out of money or things.","The fox in the fable tried to swindle the hen out of her eggs.",""],["contaminate","kuhn-TAM-uh-nayt","verb","To make something dirty or unsafe.","Oil from the street can contaminate the creek.",""],["arduous","AR-joo-uhs","adjective","Very hard and tiring.","Climbing the steep hill was an arduous task.","From Latin arduus, “steep.”"],["accessible","ak-SES-uh-buhl","adjective","Easy to reach, get, or use.","The new ramp makes the playground accessible to everyone.",""],["contemplate","KON-tuhm-playt","verb","To think deeply about something.","I contemplated which book to read next.",""],["interval","IN-ter-vuhl","noun","The time or space between two things.","The bus comes at ten-minute intervals.","From Latin intervallum, “space between walls.”"],["component","kuhm-POH-nuhnt","noun","One part of a bigger thing.","A battery is a key component of my remote control car.","From Latin componere, “to put together.”"],["vex","VEKS","verb","To bother or annoy.","Buzzing flies always vex our cat.","From Latin vexare, “to shake, trouble.”"],["wield","WEELD","verb","To hold and use a tool well.","The chef can wield a knife with great skill.",""],["opaque","oh-PAYK","adjective","Not letting light through.","The bathroom window is opaque so no one can see in.","From Latin opacus, “shaded.”"],["animated","AN-uh-may-tid","adjective","Lively and full of energy.","The kids had an animated chat about their favorite games.","From Latin anima, “breath, life.”"],["hypothesis","hy-POTH-uh-sis","noun","A guess you can test in an experiment.","My hypothesis is that plants grow faster with music.","From Greek hypothesis, “a base, supposition.”"],["gallant","GAL-uhnt","adjective","Brave and polite.","In a gallant move, Theo gave his seat to the older lady.",""],["collaborate","kuh-LAB-uh-rayt","verb","To work with others on a project.","We collaborated on a poster about recycling.","From Latin com-, “with,” and laborare, “to work.”"],["mishap","MIS-hap","noun","A small accident.","We had a little mishap and spilled paint on the rug.",""],["camaraderie","kah-muh-RAH-duh-ree","noun","A friendly feeling of trust among a group.","The team’s camaraderie grew during the long season.","From French camarade, “comrade.”"],["heritage","HAIR-ih-tij","noun","Traditions and things passed down from family or the past.","Our family heritage includes Grandma’s soup recipe.","From Latin heres, “heir.”"],["articulate","ar-TIK-yuh-lit","adjective","Able to say things clearly and well.","The articulate student explained the science project to the judges.",""],["domestic","duh-MES-tik","adjective","Kept by people at home, not wild.","Dogs and cats are domestic animals.","From Latin domus, “house.”"],["compromise","KOM-pruh-myze","noun","An agreement where each side gives up a little.","Our compromise was pizza tonight and tacos tomorrow.",""],["attribute","AT-ruh-byoot","noun","A quality or trait that someone or something has.","Kindness is my grandma’s best attribute.",""],["conscience","KON-shuhns","noun","The inner sense that tells you right from wrong.","My conscience told me to return the extra change.","From Latin conscientia, “knowledge within oneself.”"],["overt","oh-VURT","adjective","Done openly, not hidden.","He made an overt effort to be nice to the new student.","From Old French overt, “open.”"],["ailment","AYL-muhnt","noun","A small illness.","A cold is a common winter ailment.",""],["multitude","MUL-tih-tood","noun","A very large number of things or people.","A multitude of stars filled the sky at camp.","From Latin multitudo, “a great number.”"],["incentive","in-SEN-tiv","noun","Something that makes you want to try harder.","A pizza party is a great incentive to read more books.","From Latin incentivus, “setting the tune.”"],["sustain","suh-STAYN","verb","To keep something going.","A good breakfast will sustain you until lunch.","From Latin sustinere, “to hold up.”"],["innovate","IN-uh-vayt","verb","To come up with new ideas or ways of doing things.","Our class tried to innovate a better lunch line.","From Latin novus, “new.”"],["empathy","EM-puh-thee","noun","Understanding and sharing how another person feels.","Nia showed empathy when she sat with the new kid at lunch.","From Greek pathos, “feeling.”"],["mutual","MYOO-choo-uhl","adjective","Shared by two or more people.","Jay and I became friends because of our mutual love of dinosaurs.","From Latin mutuus, “exchanged.”"],["simulate","SIM-yuh-layt","verb","To copy how something real looks or works.","The app can simulate flying a plane.",""],["integrity","in-TEG-rih-tee","noun","Being honest and doing the right thing.","Ali showed integrity when he returned the lost wallet.","From Latin integer, “whole.”"],["amplify","AM-pluh-fy","verb","To make something louder or stronger.","A microphone will amplify your voice at the assembly.","From Latin amplus, “large.”"],["bolster","BOHL-ster","verb","To support or make stronger.","Practicing every day will bolster your confidence.","From Old English bolster, “a long pillow.”"],["glimpse","GLIMPS","noun","A quick look.","I caught a glimpse of a shooting star.",""],["perceive","per-SEEV","verb","To notice or understand something.","Dogs can perceive sounds we can't hear.","From Latin percipere, “to seize wholly.”"],["epic","EP-ik","adjective","Very big, long or impressive.","We had an epic snowball fight that lasted all afternoon.","From Greek epos, “word, story.”"],["endeavor","en-DEV-er","noun","A serious try at doing something.","Building a robot was our biggest endeavor this year.",""],["boon","BOON","noun","Something helpful or a blessing.","The new bike lane is a boon for kids who ride to school.","From Old Norse bón, “prayer, request.”"],["dynamic","dy-NAM-ik","adjective","Full of energy and always changing.","Our dynamic coach makes every practice fun.","From Greek dynamis, “power.”"],["awry","uh-RY","adverb","Wrong, or not the way it was planned.","Our science project went awry when the volcano would not erupt.",""],["casual","KAZH-oo-uhl","adjective","Relaxed and not fancy.","Friday is casual day, so I wore my comfy hoodie.",""],["broach","BROHCH","verb","To bring up a topic to talk about.","I waited until dinner to broach the idea of getting a puppy.",""],["encounter","en-KOWN-ter","noun","A meeting, often by surprise.","We had a close encounter with a deer on our hike.",""],["gesture","JES-cher","noun","A movement of the hands or body that shows a meaning.","A wave is a friendly gesture.","From Latin gerere, “to carry, act.”"],["assess","uh-SES","verb","To judge or figure out how good or big something is.","The teacher will assess our reading at the end of the month.",""],["vigorous","VIG-er-uhs","adjective","Strong and full of energy.","We did vigorous jumping jacks in gym class.",""],["prolong","pruh-LONG","verb","To make something last longer.","We prolonged our beach day by staying for the sunset.","From Latin prolongare, “to lengthen.”"],["utilize","YOO-tuh-lyz","verb","To use something in a helpful way.","We utilize old jars to store our crayons.",""],["deplete","dih-PLEET","verb","To use up.","We depleted our supply of glue sticks by Friday.",""],["compile","kuhm-PYLE","verb","To gather things into one list or collection.","We compiled our best recipes into a class cookbook.",""],["latitude","LAT-ih-tood","noun","How far north or south a place is from the middle of the earth.","We found our town’s latitude on the globe.","From Latin latitudo, “width.”"],["blatant","BLAY-tuhnt","adjective","Very obvious, done openly.","Peeking at the cards was a blatant way to cheat at the game.",""],["array","uh-RAY","noun","A large, neat group of things.","The bakery had a colorful array of cupcakes.",""],["correspond","kor-uh-SPOND","verb","To write letters to each other.","I correspond with a pen pal who lives across the ocean.",""],["virtual","VUR-choo-uhl","adjective","Made by a computer, not real.","We went on a virtual tour of the museum.",""],["delve","DELV","verb","To dig deep into a subject.","We delved into books about volcanoes.",""],["disperse","dih-SPURS","verb","To spread out in different directions.","The crowd dispersed after the parade.","From Latin dispergere, “to scatter.”"],["steadfast","STED-fast","adjective","Loyal and not changing.","My dog is a steadfast friend who waits by the door.",""],["justify","JUS-tuh-fy","verb","To give a good reason for something.","Can you justify why we need a second hamster?","From Latin justus, “fair, right.”"],["versatile","VUR-suh-tuhl","adjective","Able to do many different things.","A versatile player can play any position on the team.",""],["discreet","dih-SKREET","adjective","Careful not to draw attention or share secrets.","Be discreet about the surprise party plans.",""],["upheaval","up-HEE-vuhl","noun","A big, sudden change.","Moving to a new town was an upheaval for our family.",""],["prototype","PROH-tuh-typ","noun","The first model of something new.","Our team built a prototype of our robot out of cardboard.","From Greek prototypos, “first form.”"],["compensate","KOM-puhn-sayt","verb","To make up for something.","I compensated for my late start by running faster.",""],["circumstance","SUR-kuhm-stans","noun","A fact or event that affects what happens.","Under the circumstances, we moved the picnic indoors.","From Latin circumstare, “to stand around.”"],["curtail","ker-TAYL","verb","To cut short or limit.","Rain curtailed our soccer game.",""],["bonanza","buh-NAN-zuh","noun","A source of great luck or plenty.","The yard sale was a bonanza of cheap comic books.","From Spanish bonanza, “fair weather.”"],["agenda","uh-JEN-duh","noun","A list of things to do or talk about.","The first item on the club’s agenda was picking a name.","From Latin agenda, “things to be done.”"],["uphold","up-HOHLD","verb","To support or keep something going.","Our class promises to uphold the rules of the game.",""],["immerse","ih-MURS","verb","To put fully into something, like water or a task.","I immerse myself in a good book on rainy days.","From Latin immergere, “to dip in.”"],["presume","prih-ZOOM","verb","To think something is true without being sure.","I presume you want ketchup with your fries.","From Latin praesumere, “to take beforehand.”"],["illuminate","ih-LOO-mih-nayt","verb","To light up.","Fireflies illuminate the backyard at night.","From Latin lumen, “light.”"],["transparent","trans-PAIR-uhnt","adjective","Clear enough to see through.","The jellyfish was almost transparent.",""],["adhere","ad-HEER","verb","To stick to something, or to follow a rule closely.","The stickers adhere well to my notebook cover.","From Latin adhaerere, “to stick to.”"],["appease","uh-PEEZ","verb","To calm someone by giving them what they want.","We gave the barking puppy a toy to appease him.","From Old French apaisier, “to bring to peace.”"],["jostle","JOS-uhl","verb","To bump and push in a crowd.","Fans jostle each other to get a better view.",""],["orator","OR-uh-ter","noun","A skilled public speaker.","Our class president is a great orator.","From Latin orator, “speaker.”"],["candid","KAN-did","adjective","Honest and open about what you think.","My friend gave me a candid answer about my new haircut.","From Latin candidus, “white, pure.”"],["meager","MEE-ger","adjective","Too small in amount; not enough.","My meager allowance was not enough for the new game.","From Latin macer, “thin.”"],["perimeter","puh-RIM-ih-ter","noun","The distance around the edge of a shape.","We measured the perimeter of the garden to buy a fence.","From Greek perimetros, “measure around.”"],["throng","THRONG","noun","A big crowd of people.","A throng of fans waited outside the gym.",""],["thwart","THWORT","verb","To stop someone from doing something.","A fence will thwart the rabbits from eating our lettuce.",""],["vintage","VIN-tij","adjective","Old but of good quality.","Grandpa has a vintage toy train from when he was small.",""],["evident","EV-ih-duhnt","adjective","Easy to see or understand.","It was evident that the puppy had found the mud.","From Latin evidens, “clear to see.”"],["embellish","em-BEL-ish","verb","To decorate, or to add extra details to a story.","We embellish our notebooks with stickers and glitter.","From Old French embellir, “to make beautiful.”"],["devote","dih-VOHT","verb","To give lots of time or love to something.","He devotes every recess to practicing his kickflips.",""],["acute","uh-KYOOT","adjective","Sharp or very strong.","Owls have an acute sense of hearing.","From Latin acutus, “sharpened.”"],["eloquent","EL-uh-kwuhnt","adjective","Able to speak or write in a clear, moving way.","Jamal gave an eloquent speech about saving the park.","From Latin eloqui, “to speak out.”"],["accord","uh-KORD","noun","Agreement.","The two teams were in accord about the rules.","From Latin cor, “heart.”"],["exhilarate","ig-ZIL-uh-rayt","verb","To make someone feel very happy and excited.","Riding the roller coaster will exhilarate you.","From Latin hilaris, “cheerful.”"],["anonymous","uh-NON-uh-muhs","adjective","Having a name that is not known.","An anonymous person left flowers on the teacher’s desk.","From Greek anōnymos, “nameless.”"],["enigma","ih-NIG-muh","noun","A puzzle or mystery that is hard to figure out.","Where my left socks go is an enigma.","From Greek ainigma, “riddle.”"],["adamant","AD-uh-muhnt","adjective","Firm and not willing to change your mind.","My brother was adamant that pizza is a breakfast food.",""],["fathom","FATH-uhm","verb","To understand something hard.","I cannot fathom how ants carry such big crumbs.","From Old English fæthm, “outstretched arms.”"],["prospect","PROS-pekt","noun","Something that might happen in the future.","The prospect of a snow day made us cheer.","From Latin prospectus, “view.”"],["cartographer","kar-TOG-ruh-fer","noun","A person who makes maps.","The cartographer drew a map of our town’s hiking trails.",""],["niche","NICH","noun","A place or job that fits someone just right.","Lena found her niche in the robotics club.","From French niche, “a nook in a wall.”"],["significant","sig-NIF-ih-kuhnt","adjective","Important or large enough to notice.","There was a significant jump in my reading score.",""],["renowned","rih-NOWND","adjective","Famous and admired.","A renowned chef visited our school kitchen.",""],["recount","rih-KOWNT","verb","To tell the story of what happened.","Grandma likes to recount the day she met Grandpa.",""],["preliminary","prih-LIM-uh-nair-ee","adjective","Coming first, to get ready for the main thing.","We ran preliminary races before the big final.","From Latin limen, “threshold.”"],["initiative","ih-NISH-uh-tiv","noun","The will to start something without being told.","Ella took the initiative and cleaned up the art table.","From Latin initium, “a beginning.”"],["contradict","kon-truh-DIKT","verb","To say the opposite of what someone else said.","My sister contradicted me about whose turn it was.","From Latin contra, “against,” and dicere, “to say.”"],["affable","AF-uh-buhl","adjective","Friendly and easy to talk to.","The affable librarian always helps us find good books.","From Latin affabilis, “easy to speak to.”"],["toxic","TOK-sik","adjective","Poisonous and harmful.","Some plants are toxic to cats, so we keep them away.",""],["reinforce","ree-in-FORS","verb","To make something stronger.","We used tape to reinforce the corners of the box.",""],["enhance","en-HANS","verb","To make something better.","A little cinnamon will enhance the taste of the apples.",""],["alleviate","uh-LEE-vee-ayt","verb","To make something less painful or hard.","A cold cloth can alleviate the itch of a bug bite.","From Latin levis, “light.”"],["mentor","MEN-tor","noun","A wise person who helps and guides you.","My swim coach is also my mentor.","From Greek Mentor, a wise teacher in an old Greek story."],["barometer","buh-ROM-ih-ter","noun","A tool that measures air pressure to help predict weather.","The barometer showed a storm was coming.","From Greek baros, “weight.”"],["vocal","VOH-kuhl","adjective","Speaking up loudly and often.","My little sister is very vocal about wanting a pet.","From Latin vox, “voice.”"],["jovial","JOH-vee-uhl","adjective","Cheerful and friendly.","The jovial bus driver sang to us every morning.",""],["stamina","STAM-uh-nuh","noun","The energy to keep going a long time.","Running every day built up my stamina.",""],["jargon","JAR-guhn","noun","Special words used by one group that others may not understand.","The pilot’s jargon was hard for us to follow.","From Old French jargon, “chatter of birds.”"],["predicament","prih-DIK-uh-muhnt","noun","A tricky problem that is hard to get out of.","The cat was in a predicament, stuck on the roof.",""],["tentative","TEN-tuh-tiv","adjective","Not sure or not final yet.","We made tentative plans for a beach day on Saturday.",""],["undermine","un-der-MYN","verb","To weaken something bit by bit.","Teasing can undermine a person’s confidence.",""],["hoard","HORD","verb","To collect and hide a large supply of something.","Squirrels hoard acorns for the winter.","From Old English hord, “treasure.”"],["ultimate","UL-tuh-mit","adjective","The greatest or the last.","Winning the science fair is my ultimate goal.","From Latin ultimus, “last.”"],["confront","kuhn-FRUHNT","verb","To face something hard head-on.","I confronted my fear and jumped off the high dive.",""],["obscure","uhb-SKYUR","adjective","Not well known or hard to see.","We found an obscure trail that few hikers use.","From Latin obscurus, “dark.”"],["essential","ih-SEN-shuhl","adjective","Very much needed.","Water is essential for a long bike ride.","From Latin essentia, “being.”"],["phenomenon","fih-NOM-uh-non","noun","Something that happens that people can see and study.","A rainbow is a phenomenon caused by sunlight and rain.","From Greek phainomenon, “thing seen.”"],["outlook","OWT-luk","noun","The way you see things or what you expect.","Her bright outlook makes rainy days better.",""],["formidable","FOR-mih-duh-buhl","adjective","Very strong and hard to beat.","The other chess team was formidable.","From Latin formido, “fear.”"],["adequate","AD-ih-kwit","adjective","Good enough for what is needed.","Two sandwiches were adequate for our short hike.","From Latin adaequare, “to make equal.”"],["momentum","moh-MEN-tuhm","noun","The force that keeps something moving.","The sled gained momentum as it raced down the hill.","From Latin momentum, “movement.”"],["convenient","kuhn-VEEN-yuhnt","adjective","Easy and handy to use or reach.","The library is convenient because it is right next to our school.",""],["obstinate","OB-stuh-nit","adjective","Stubborn; refusing to change your mind.","The obstinate goat would not budge from the path.","From Latin obstinatus, “determined.”"],["indignant","in-DIG-nuhnt","adjective","Upset because something seems unfair.","Kai was indignant when he was blamed for the spill.","From Latin indignari, “to think unworthy.”"],["verdict","VUR-dikt","noun","A final decision.","The verdict from the judges was that our cake won first prize.","From Latin vere dictum, “truly said.”"],["trait","TRAYT","noun","A quality that makes someone who they are.","Kindness is my best friend’s best trait.",""],["brazen","BRAY-zuhn","adjective","Bold in a rude way, without shame.","The brazen seagull grabbed a fry right off my plate.","From Old English bræsen, “made of brass.”"],["novice","NOV-is","noun","A beginner.","As a novice skater, I held on to the wall.","From Latin novicius, “new.”"],["symmetry","SIM-ih-tree","noun","When two halves match like a mirror.","A butterfly’s wings show perfect symmetry.","From Greek symmetria, “due proportion.”"],["deliberate","dih-LIB-er-it","adjective","Done on purpose and with care.","She took slow, deliberate steps across the log bridge.",""],["detest","dih-TEST","verb","To dislike very much.","I detest the sound of chalk squeaking on the board.",""],["capacity","kuh-PAS-i-tee","noun","The most that something can hold.","The bus has a capacity of forty kids.","From Latin capax, “able to hold.”"],["waver","WAY-ver","verb","To be unsure between choices.","I waver between chocolate and strawberry every time.",""],["extravagant","ik-STRAV-uh-guhnt","adjective","Spending or using much more than needed.","The cat’s extravagant birthday party had three cakes.","From Latin extra, “outside,” and vagari, “to wander.”"],["outlandish","owt-LAN-dish","adjective","Very strange or odd.","My aunt wore an outlandish hat with feathers and a bird.",""],["refine","rih-FYN","verb","To make something better with small changes.","We worked to refine our science fair poster.",""],["compel","kuhm-PEL","verb","To force or push someone to do something.","The cold rain compelled us to go inside.","From Latin compellere, “to drive together.”"],["cease","SEES","verb","To stop.","The rain finally ceased, and we ran outside.","From Latin cessare, “to stop.”"],["fatigue","fuh-TEEG","noun","A feeling of being very tired.","After the long swim meet, fatigue set in.","From Latin fatigare, “to tire out.”"],["usher","USH-er","verb","To lead someone to a place.","The teacher will usher us to our seats for the play.",""],["haphazard","hap-HAZ-erd","adjective","Done without a plan, in a messy way.","My haphazard packing left my socks at home.","From hap, “luck,” and hazard, “chance.”"],["impartial","im-PAR-shuhl","adjective","Fair to everyone, not taking sides.","The referee must be impartial during the game.",""],["falter","FAWL-ter","verb","To stumble or lose strength.","Her voice did not falter when she sang the solo.",""],["affluent","AF-loo-uhnt","adjective","Having a lot of money.","The affluent family gave money to build a new park.","From Latin affluere, “to flow toward.”"],["subtle","SUT-uhl","adjective","Small and hard to notice.","There is a subtle hint of mint in this lemonade.",""],["prudent","PROO-duhnt","adjective","Careful and wise about the future.","It is prudent to save some of your birthday money.","From Latin prudens, “wise.”"],["audible","AW-duh-buhl","adjective","Loud enough to be heard.","The whisper was barely audible from the back of the room.","From Latin audire, “to hear.”"],["oversight","OH-ver-syt","noun","A mistake made by not noticing something.","Forgetting the napkins was an oversight.",""],["banish","BAN-ish","verb","To send someone or something away for good.","Mom said she would banish the noisy toy to the closet.",""],["jeopardy","JEP-er-dee","noun","Danger of losing something.","Our picnic was in jeopardy when dark clouds rolled in.","From Old French jeu parti, “a split game.”"],["dilemma","dih-LEM-uh","noun","A hard choice between two things.","My dilemma was choosing between the zoo and the water park.",""],["futile","FYOO-tuhl","adjective","Having no chance of working.","Trying to keep the cat off the couch was futile.","From Latin futilis, “leaky.”"],["curator","kyoo-RAY-ter","noun","A person in charge of a museum collection.","The curator showed us the dinosaur bones.","From Latin curare, “to take care of.”"],["concise","kuhn-SYSE","adjective","Short and clear, with no extra words.","Her concise answer fit on one line.","From Latin concisus, “cut up.”"],["procrastinate","proh-KRAS-tuh-nayt","verb","To put off doing something.","I procrastinated on my report and had to rush.","From Latin crastinus, “of tomorrow.”"],["irate","eye-RAYT","adjective","Very angry.","The irate goose chased us away from its nest.","From Latin ira, “anger.”"],["replenish","rih-PLEN-ish","verb","To fill something up again.","We replenish the bird feeder every Sunday.","From Old French replenir, “to fill again.”"],["ardent","AR-duhnt","adjective","Full of strong feeling; very eager.","He is an ardent fan of his local soccer team.","From Latin ardere, “to burn.”"],["literal","LIT-er-uhl","adjective","Meaning exactly what the words say.","My little sister took “break a leg” in a literal way and looked worried.","From Latin littera, “letter.”"],["savvy","SAV-ee","adjective","Smart and knowing a lot about something.","My savvy sister knows every shortcut on the computer.",""],["voyage","VOY-ij","noun","A long trip, often by sea.","The sailors went on a voyage across the ocean.",""],["derive","dih-RYVE","verb","To get something from a source.","Many English words are derived from Latin.","From Latin derivare, “to draw off water.”"],["rigorous","RIG-er-uhs","adjective","Very strict and careful.","The swim team has a rigorous training plan.",""],["impulse","IM-puls","noun","A sudden wish to do something.","On an impulse, I hugged my teacher.","From Latin impellere, “to push on.”"],["fabricate","FAB-rih-kayt","verb","To make something, or to make up a false story.","Do not fabricate an excuse about the dog eating your homework.","From Latin fabrica, “workshop.”"],["abolish","uh-BOL-ish","verb","To end a rule or practice for good.","Our class voted to abolish homework on birthdays.","From Latin abolere, “to destroy.”"],["remnant","REM-nuhnt","noun","A small piece left over.","Mom sewed a pillow from a remnant of old fabric.",""],["dismantle","dis-MAN-tuhl","verb","To take apart piece by piece.","We dismantled the tent after our camping trip.",""],["sluggish","SLUG-ish","adjective","Slow and low on energy.","I feel sluggish if I stay up too late.",""],["allure","uh-LOOR","noun","The power to attract or tempt.","The allure of the ice cream truck made everyone run outside.",""],["conifer","KON-uh-fer","noun","A tree that has cones and needle-like leaves.","The conifers stay green all winter long.","From Latin conifer, “cone-bearing.”"],["monologue","MON-uh-log","noun","A long speech by one person.","In the school play, I gave a funny monologue about my cat.","From Greek monologos, “speaking alone.”"],["docile","DOS-uhl","adjective","Calm and easy to handle.","The docile pony let every kid pet it.","From Latin docilis, “easy to teach.”"],["persistent","per-SIS-tuhnt","adjective","Not giving up; keeping on.","The persistent woodpecker tapped all morning.","From Latin persistere, “to continue steadily.”"],["exasperate","ig-ZAS-puh-rayt","verb","To annoy someone a lot.","The broken zipper started to exasperate me.","From Latin exasperare, “to make rough.”"],["almanac","AWL-muh-nak","noun","A yearly book of facts, dates, and weather.","We checked the almanac to see when the full moon would rise.",""],["allocate","AL-uh-kayt","verb","To give out a share for a certain use.","We allocate ten minutes of class time for silent reading.","From Latin locus, “place.”"],["zenith","ZEE-nith","noun","The highest point.","At noon, the sun is near its zenith.",""],["shrewd","SHROOD","adjective","Clever at making good choices.","The shrewd shopper waited for the sale.",""],["uncanny","un-KAN-ee","adjective","Strange in a way that is hard to explain.","My twin and I have an uncanny way of saying the same thing at once.",""],["adept","uh-DEPT","adjective","Very good at doing something.","My sister is adept at solving puzzle cubes.","From Latin adeptus, “having reached.”"],["placid","PLAS-id","adjective","Calm and peaceful.","The lake was placid in the early morning.","From Latin placidus, “gentle.”"],["turmoil","TUR-moyl","noun","A state of great confusion or upset.","The kitchen was in turmoil when the dog stole the turkey.",""],["ordeal","or-DEEL","noun","A hard or painful experience.","Getting lost at the fair was quite an ordeal.",""],["misconception","mis-kuhn-SEP-shuhn","noun","A wrong idea about something.","It's a misconception that goldfish only remember for three seconds.",""],["accommodate","uh-KOM-uh-dayt","verb","To make room for or fit someone’s needs.","The van can accommodate our whole soccer team.",""],["consistent","kuhn-SIS-tuhnt","adjective","Always acting or happening the same way.","Her consistent practice made her a great piano player.",""],["emphasize","EM-fuh-syze","verb","To show that something is very important.","The coach likes to emphasize teamwork.","From Greek emphasis, “a showing.”"],["feign","FAYN","verb","To pretend.","My cat will feign sleep, then pounce on my toes.","From Latin fingere, “to shape, pretend.”"],["garble","GAR-buhl","verb","To mix up words so they are hard to understand.","The bad phone signal would garble every word.",""],["repercussion","ree-per-KUSH-uhn","noun","An effect that comes later from an action.","Staying up late had a repercussion: I was tired all day.",""],["levity","LEV-ih-tee","noun","Lightness and humor in a serious moment.","His joke brought some levity to the long test day.","From Latin levis, “light.”"],["heed","HEED","verb","To pay attention to advice or a warning.","Heed the sign and stay on the trail.","From Old English hēdan, “to guard.”"],["callous","KAL-uhs","adjective","Not caring about other people’s feelings.","Laughing when he fell was a callous thing to do.",""],["agrarian","uh-GRAIR-ee-uhn","adjective","Having to do with farms and farming.","Long ago, most towns had an agrarian way of life.","From Latin ager, “field.”"],["melancholy","MEL-uhn-kol-ee","adjective","Quietly sad in a thoughtful way.","The rainy Sunday put me in a melancholy mood.","From Greek melankholia, “black bile,” once thought to cause sadness."],["delineate","dih-LIN-ee-ayt","verb","To describe or mark out clearly.","Chalk lines delineate the edges of the field.","From Latin linea, “line.”"],["palatable","PAL-uh-tuh-buhl","adjective","Pleasant to taste, or okay enough to accept.","Adding cheese made the broccoli more palatable to my brother.","From Latin palatum, “roof of the mouth.”"],["reconcile","REK-uhn-syl","verb","To become friends again after a fight.","The two friends were able to reconcile after a long talk.","From Latin reconciliare, “to bring together again.”"],["fortify","FOR-tuh-fy","verb","To make something stronger.","We used extra snow to fortify our snow fort.","From Latin fortis, “strong.”"],["wistful","WIST-fuhl","adjective","Softly sad and wishing for something.","She took a wistful look at the beach on our last day.",""],["exert","ig-ZURT","verb","To use strength or effort.","You have to exert a lot of force to open this jar.","From Latin exserere, “to put forth.”"],["resolute","REZ-uh-loot","adjective","Firm and set on a goal.","She was resolute about finishing the marathon.",""],["opulent","OP-yuh-luhnt","adjective","Rich and fancy.","The hotel lobby was opulent, with gold lamps and velvet chairs.","From Latin opulentus, “wealthy.”"],["forfeit","FOR-fit","verb","To lose or give up something, often as a penalty.","The team had to forfeit the game when only four players came.",""],["stupendous","stoo-PEN-duhs","adjective","Amazing and huge.","The view from the top of the mountain was stupendous.","From Latin stupere, “to be amazed.”"],["commodity","kuh-MOD-i-tee","noun","Something that is bought and sold.","On the old farm, wheat was the main commodity.",""],["latent","LAY-tuhnt","adjective","Hidden but able to come out later.","She had a latent talent for drawing.","From Latin latere, “to lie hidden.”"],["benevolent","buh-NEV-uh-luhnt","adjective","Kind and wanting to help others.","The benevolent neighbor fixed every kid’s bike for free.","From Latin bene, “well,” and volens, “wishing.”"],["sheepish","SHEE-pish","adjective","A bit embarrassed about a mistake.","He gave a sheepish grin after tripping on stage.",""],["rapport","ra-POR","noun","A friendly, easy connection with someone.","Our new coach built a quick rapport with the team.","From French rapporter, “to bring back.”"],["apathy","AP-uh-thee","noun","Not caring or feeling interested.","The class’s apathy about the dull movie was easy to see.","From Greek apatheia, “without feeling.”"],["prolific","pruh-LIF-ik","adjective","Making a lot of something.","Our prolific apple tree gave us ten baskets this year.",""],["accrue","uh-KROO","verb","To build up little by little over time.","Interest will accrue in my savings account every month.","From Latin accrescere, “to grow.”"],["nebulous","NEB-yuh-luhs","adjective","Fuzzy and unclear.","Our plans for the weekend are still nebulous.","From Latin nebula, “mist.”"],["contemporary","kuhn-TEM-puh-rer-ee","adjective","Modern, or living at the same time.","The museum has a room full of contemporary art.","From Latin com-, “with,” and tempus, “time.”"],["flamboyant","flam-BOY-uhnt","adjective","Bold, bright and showy.","The parrot had flamboyant red and green feathers.","From French flamboyer, “to flame.”"],["eradicate","ih-RAD-ih-kayt","verb","To get rid of something completely.","We worked hard to eradicate the weeds from the garden.","From Latin radix, “root.”"],["admonish","ad-MON-ish","verb","To warn or scold someone gently.","The librarian had to admonish us for giggling too loudly.","From Latin admonere, “to remind.”"],["trite","TRYT","adjective","Used so often it is no longer fresh.","“It was all a dream” is a trite way to end a story.",""],["deteriorate","dih-TEER-ee-uh-rayt","verb","To get worse over time.","The old treehouse began to deteriorate in the rain.","From Latin deterior, “worse.”"],["stoic","STOH-ik","adjective","Calm and not showing feelings, even when things are hard.","He stayed stoic while the nurse gave him a shot.",""],["genre","ZHAHN-ruh","noun","A kind or type of book, movie or music.","Mystery is my favorite book genre.","From French genre, “kind.”"],["laud","LAWD","verb","To praise highly.","The teachers laud the students who clean up the park.","From Latin laus, “praise.”"],["altruism","AL-troo-iz-uhm","noun","Caring about others and helping them without wanting a reward.","Shoveling the neighbor’s driveway for free was an act of altruism.","From French altruisme, from Latin alter, “other.”"],["subdue","suhb-DOO","verb","To bring under control or make quieter.","Mom dimmed the lights to subdue the noisy party.",""],["adulation","aj-uh-LAY-shuhn","noun","Very great praise or admiration.","The young singer enjoyed the adulation of the crowd.",""],["acclimate","AK-luh-mayt","verb","To get used to a new place or climate.","It took a few days to acclimate to the mountain air.",""],["paltry","PAWL-tree","adjective","Very small and not worth much.","Ten cents is a paltry price for a book at the yard sale.",""],["pompous","POM-puhs","adjective","Acting too important and proud.","The pompous rooster strutted around the farmyard.","From Latin pompa, “parade.”"],["languid","LANG-gwid","adjective","Slow and relaxed, with little energy.","The cat gave a languid stretch in the sun.","From Latin languere, “to be faint.”"],["emulate","EM-yuh-layt","verb","To copy someone because you admire them.","Young players emulate the moves of older kids.","From Latin aemulari, “to try to equal.”"],["disseminate","dih-SEM-uh-nayt","verb","To spread information widely.","We disseminated flyers about the bake sale.","From Latin semen, “seed.”"],["precarious","prih-KAIR-ee-uhs","adjective","Shaky and likely to fall or fail.","The tower of blocks looked precarious.","From Latin precarius, “obtained by asking.”"],["rejuvenate","rih-JOO-vuh-nayt","verb","To make someone feel young and fresh again.","A weekend at the lake will rejuvenate the whole family.","From Latin juvenis, “young.”"],["omnipresent","om-nih-PREZ-uhnt","adjective","Seeming to be everywhere at once.","In the fall, pumpkin treats are omnipresent.","From Latin omnis, “all,” and praesens, “present.”"],["debilitate","dih-BIL-i-tayt","verb","To make weak.","The flu debilitated me for a whole week.","From Latin debilis, “weak.”"],["irony","EYE-ruh-nee","noun","When what happens is the opposite of what you expect.","The irony was that the fire station’s cake caught fire.","From Greek eirōneia, “pretend ignorance.”"],["solace","SOL-is","noun","Comfort when you are sad.","My cat gave me solace after a rough day.","From Latin solacium, “comfort.”"],["bewitch","bih-WICH","verb","To charm or delight someone completely.","The snowy forest seemed to bewitch everyone on the hike.",""],["append","uh-PEND","verb","To add something to the end.","Please append your name to the bottom of the list.","From Latin appendere, “to hang on.”"],["nuance","NOO-ahns","noun","A small, subtle difference.","A good singer notices every nuance in a song.","From French nuance, “shade of color.”"],["haughty","HAW-tee","adjective","Acting like you are better than others.","The haughty cat ignored everyone at the party.","From Old French haut, “high.”"],["tenacious","tuh-NAY-shuhs","adjective","Holding on tight and not giving up.","The tenacious puppy would not let go of the rope toy.","From Latin tenax, “holding fast.”"],["succinct","suhk-SINGKT","adjective","Short and clear.","Her book report was succinct but full of good ideas.",""],["bemoan","bih-MOHN","verb","To complain or feel sad about something.","There’s no use to bemoan the rain; let’s play a board game.",""],["contrive","kuhn-TRYVE","verb","To cleverly plan or invent something.","We contrived a way to reach the kite stuck in the tree.",""],["mediate","MEE-dee-ayt","verb","To help two sides settle a disagreement.","Our teacher mediated when two teams wanted the same field.","From Latin mediare, “to be in the middle.”"],["affirm","uh-FURM","verb","To say firmly that something is true.","The coach will affirm that practice starts at four.","From Latin affirmare, “to make firm.”"],["propensity","pruh-PEN-sih-tee","noun","A natural habit or leaning toward something.","My cat has a propensity for napping in sunbeams.","From Latin propensus, “inclined.”"],["convoluted","KON-vuh-loo-tid","adjective","Very twisty and hard to follow.","The game had convoluted rules nobody understood.",""],["contour","KON-toor","noun","The outline or shape of something.","I traced the contour of my hand on paper.",""],["superfluous","soo-PUR-floo-uhs","adjective","More than is needed.","The extra glitter on my poster was superfluous.","From Latin superfluus, “overflowing.”"],["circumvent","sur-kuhm-VENT","verb","To find a way around a problem.","We circumvented the traffic by taking a back road.","From Latin circumvenire, “to come around.”"],["sullen","SUL-uhn","adjective","Quiet and grumpy.","He sat in sullen silence after losing the game.",""],["meticulous","muh-TIK-yuh-luhs","adjective","Very careful about every small detail.","Nora was meticulous about labeling every rock in her collection.",""],["nostalgia","no-STAL-juh","noun","A warm, wistful feeling about the past.","Looking at baby photos filled Mom with nostalgia.","From Greek nostos, “return home,” and algos, “pain.”"],["coherent","koh-HEER-uhnt","adjective","Clear and making sense.","Her coherent plan won over the whole team.","From Latin cohaerere, “to stick together.”"],["transient","TRAN-zee-uhnt","adjective","Lasting only a short time.","The rainbow was transient and gone in a minute.","From Latin transire, “to go across.”"],["conjecture","kuhn-JEK-cher","noun","A guess made without full proof.","My conjecture is that the missing sock is behind the dryer.",""],["adage","AD-ij","noun","An old saying that many people believe is true.","My grandpa’s favorite adage is “practice makes perfect.”",""],["ubiquitous","yoo-BIK-wih-tuhs","adjective","Found everywhere.","Pigeons are ubiquitous in the city park.","From Latin ubique, “everywhere.”"],["permeate","PUR-mee-ayt","verb","To spread through every part of something.","The smell of popcorn permeated the whole house.","From Latin permeare, “to pass through.”"],["prowess","PROW-is","noun","Great skill.","Her prowess at the piano amazed the audience.","From Old French proesse, “bravery.”"],["plethora","PLETH-er-uh","noun","Far more than enough.","The buffet had a plethora of desserts.","From Greek plethore, “fullness.”"],["rectify","REK-tuh-fy","verb","To fix something that is wrong.","I erased my mistake to rectify the math problem.","From Latin rectus, “right, straight.”"],["deluge","DEL-yooj","noun","A huge flood or rush of something.","After the bake sale flyer, we got a deluge of cookie orders.",""],["mortified","MOR-tuh-fyd","adjective","Very embarrassed.","I was mortified when I tripped on stage at the concert.",""],["aplomb","uh-PLOM","noun","Calm confidence, even when things are hard.","She handled the tricky question with aplomb.","From French à plomb, “straight down, like a plumb line.”"],["elicit","ih-LIS-it","verb","To draw out a reaction or answer.","The clown’s silly hat would elicit giggles from every kid.","From Latin elicere, “to draw out.”"],["confound","kuhn-FOWND","verb","To confuse or puzzle.","The magic trick confounded everyone at the party.",""],["denounce","dih-NOWNS","verb","To say out loud that something is wrong.","Our class denounced littering with a poster campaign.",""],["calibrate","KAL-uh-brayt","verb","To adjust a tool so it measures correctly.","We calibrated the scale before weighing our pumpkins.",""],["substantial","suhb-STAN-shuhl","adjective","Large in size or amount.","We raised a substantial amount of money at the bake sale.",""],["akin","uh-KIN","adjective","Similar or like something.","Learning to skate is akin to learning to ride a bike.",""],["voracious","vaw-RAY-shuhs","adjective","Wanting a lot of something, especially food or books.","My voracious reader friend finishes a book a day.","From Latin vorare, “to swallow up.”"],["animosity","an-uh-MOS-ih-tee","noun","Strong dislike between people.","After the game, there was no animosity between the two teams.",""],["peruse","puh-ROOZ","verb","To read or look through something carefully.","I perused the menu before choosing the pasta.",""],["maverick","MAV-er-ik","noun","Someone who thinks and acts in their own way.","Our art teacher is a maverick who paints with sponges and forks.","From Samuel Maverick, a rancher who did not brand his cattle."],["wry","RY","adjective","Dry and a little funny in a quiet way.","Dad gave a wry smile when the dog ate his sandwich.",""],["aesthetic","es-THET-ik","adjective","Having to do with beauty and how things look.","She arranged her shelf for aesthetic reasons, not just to store books.","From Greek aisthētikos, “perceptive.”"],["profuse","pruh-FYOOS","adjective","Pouring out in large amounts.","She gave profuse thanks for the birthday surprise.","From Latin profusus, “poured forth.”"],["obstruct","uhb-STRUKT","verb","To block the way.","A fallen branch obstructed the bike path.","From Latin obstruere, “to build against.”"],["endorse","en-DORS","verb","To publicly support or approve something.","The student council will endorse the idea of a garden club.","From Latin dorsum, “back,” as in signing the back of a paper."],["allay","uh-LAY","verb","To calm or ease a fear or worry.","The vet tried to allay my worry about my sick hamster.",""],["deficient","dih-FISH-uhnt","adjective","Not having enough of something needed.","Plants deficient in sunlight turn pale.",""],["abhor","ab-HOR","verb","To hate something very much.","I abhor the sound of chalk squeaking on a board.","From Latin abhorrere, “to shrink back from.”"],["boorish","BOOR-ish","adjective","Rude and having bad manners.","Talking loudly during the movie was boorish.",""],["chagrin","shuh-GRIN","noun","Embarrassment or annoyance.","To my chagrin, I wore two different shoes to school.","From French chagrin, “sorrow.”"],["accentuate","ak-SEN-choo-ayt","verb","To make something stand out more.","The bright frame will accentuate the colors in my painting.",""],["beguile","bih-GILE","verb","To charm or trick someone.","The cat’s purring can beguile you into giving it extra treats.",""],["facilitate","fuh-SIL-ih-tayt","verb","To make something easier to do.","A map will facilitate our treasure hunt.","From Latin facilis, “easy.”"],["pragmatic","prag-MAT-ik","adjective","Practical and focused on what works.","Bringing an extra pencil was a pragmatic choice.","From Greek pragma, “deed.”"],["prosaic","proh-ZAY-ik","adjective","Plain and ordinary, not exciting.","The story had a prosaic ending, with everyone just going home.","From Latin prosa, “prose.”"],["intact","in-TAKT","adjective","Whole and not damaged.","The egg stayed intact after our egg-drop test.","From Latin intactus, “untouched.”"],["brusque","BRUHSK","adjective","Short and rude in how you speak.","The busy clerk gave a brusque answer and turned away.",""],["benchmark","BENCH-mark","noun","A standard used to measure or compare things.","My best time last year is the benchmark I want to beat.",""],["impeccable","im-PEK-uh-buhl","adjective","Perfect, with no mistakes.","Her room was impeccable before the guests arrived.",""],["pervasive","per-VAY-siv","adjective","Spread everywhere.","The smell of pine was pervasive in the forest.","From Latin pervadere, “to go through.”"],["inherent","in-HAIR-uhnt","adjective","Being a natural, built-in part of something.","There is an inherent risk of getting wet when you canoe.","From Latin inhaerere, “to stick in.”"],["antithesis","an-TITH-uh-sis","noun","The exact opposite of something.","My messy room is the antithesis of my sister’s neat one.","From Greek antithesis, “a setting against.”"],["incessant","in-SES-uhnt","adjective","Never stopping.","The puppy’s incessant barking kept us awake.","From Latin incessans, “not stopping.”"],["lull","LUL","noun","A short time of quiet or calm.","In a lull in the storm, we ran to the car.",""],["cursory","KUR-suh-ree","adjective","Quick and not careful.","A cursory look at my homework missed three mistakes.",""],["supplement","SUP-luh-muhnt","noun","Something added to make a thing complete.","The teacher gave us a reading supplement for extra practice.",""],["impede","im-PEED","verb","To block or slow progress.","Fallen branches can impede the path.","From Latin impedire, “to shackle the feet.”"],["torrent","TOR-uhnt","noun","A fast, strong rush of water or something else.","A torrent of rain poured off the roof.",""],["abstract","AB-strakt","adjective","Based on ideas, not on real things you can touch.","Fairness is an abstract idea, but we can still see it in action.","From Latin abstractus, “drawn away.”"],["disparity","dih-SPAIR-i-tee","noun","A big difference.","There was a big disparity between the two teams’ heights.",""],["intermittent","in-ter-MIT-uhnt","adjective","Stopping and starting again.","Intermittent rain made the picnic a soggy one.","From Latin intermittere, “to leave off for a while.”"],["euphoria","yoo-FOR-ee-uh","noun","A feeling of great happiness.","The team felt pure euphoria after the last-second goal.","From Greek euphoros, “bearing well.”"],["digress","dy-GRES","verb","To wander off the main topic.","Grandpa often digresses into stories about his old dog.","From Latin digredi, “to step away.”"],["refute","rih-FYOOT","verb","To prove that something is wrong.","She used facts to refute the idea that bats are blind.","From Latin refutare, “to drive back.”"],["incognito","in-kog-NEE-toh","adverb","In disguise so no one knows who you are.","Dad went to the costume party incognito as a giant banana.","From Italian incognito, “unknown.”"],["deplore","dih-PLOR","verb","To strongly dislike or disapprove of.","I deplore soggy cereal.",""],["banal","buh-NAL","adjective","Boring and ordinary, with nothing new.","The story had a banal ending that we all guessed.",""],["resonate","REZ-uh-nayt","verb","To ring out with sound, or to feel meaningful.","The bell’s sound seemed to resonate through the whole hall.","From Latin resonare, “to sound again.”"],["corroborate","kuh-ROB-uh-rayt","verb","To back up a story with proof.","My friend corroborated my story about the giant fish.",""],["complacent","kuhm-PLAY-suhnt","adjective","Too pleased with yourself to keep trying hard.","After winning twice, the team got complacent and lost.",""],["trepidation","trep-ih-DAY-shuhn","noun","A feeling of fear about what might happen.","I walked onto the stage with trepidation.","From Latin trepidare, “to tremble, hurry.”"],["engross","en-GROHS","verb","To hold all of someone’s attention.","A good mystery can engross me for hours.",""],["malleable","MAL-ee-uh-buhl","adjective","Easy to shape or change.","Warm wax is malleable, so we molded it into candles.","From Latin malleus, “hammer.”"],["discern","dih-SURN","verb","To notice or tell the difference.","Can you discern the two different bird calls?",""],["comply","kuhm-PLY","verb","To follow a rule or request.","Every swimmer must comply with the lifeguard’s rules.",""],["stringent","STRIN-juhnt","adjective","Very strict.","The library has stringent rules about late books.","From Latin stringere, “to draw tight.”"],["negate","nih-GAYT","verb","To cancel the effect of something.","Eating three donuts can negate the good of a long run.","From Latin negare, “to deny.”"],["vacillate","VAS-uh-layt","verb","To keep changing your mind.","I vacillate between soccer and art club every year.","From Latin vacillare, “to sway.”"],["intrepid","in-TREP-id","adjective","Very brave and bold.","The intrepid hikers crossed the rope bridge.","From Latin intrepidus, “not alarmed.”"],["vicinity","vih-SIN-ih-tee","noun","The area nearby.","Is there a library in the vicinity of your house?","From Latin vicinus, “neighbor.”"],["adroit","uh-DROYT","adjective","Clever and skillful, especially with your hands.","The adroit juggler kept five balls in the air.","From French à droit, “rightly.”"],["reiterate","ree-IT-uh-rayt","verb","To say something again to make it clear.","The coach will reiterate the rules before every game.","From Latin iterum, “again.”"],["arable","AIR-uh-buhl","adjective","Good for growing crops.","The arable land by the river is perfect for corn.","From Latin arare, “to plow.”"],["entice","en-TYSE","verb","To tempt someone with something good.","The smell of popcorn will entice everyone into the kitchen.",""],["nonchalant","non-shuh-LAHNT","adjective","Calm and relaxed, as if you don't care.","He acted nonchalant, but he was nervous about the test.","From French nonchalant, “not caring.”"],["capitulate","kuh-PICH-uh-layt","verb","To give in after holding out.","After an hour of pleading, Dad capitulated and made pancakes.",""],["caustic","KAW-stik","adjective","Harsh and stinging, in words or in chemicals.","The coach asked for helpful notes, not caustic remarks.","From Greek kaustikos, “burning.”"],["fickle","FIK-uhl","adjective","Changing your mind often.","The fickle weather went from sunny to rainy in an hour.","From Old English ficol, “tricky.”"],["mundane","mun-DAYN","adjective","Ordinary and a bit dull.","Folding laundry is a mundane chore, so I play music while I do it.","From Latin mundanus, “of the world.”"],["connoisseur","kon-uh-SUR","noun","An expert who knows a lot about something fine.","My uncle is a connoisseur of hot sauces.","From old French conoistre, “to know.”"],["condone","kuhn-DOHN","verb","To allow or accept something wrong.","Our teacher will not condone cheating.",""],["threshold","THRESH-hohld","noun","A doorway, or the point where something begins.","The cat sat on the threshold, not sure whether to come in.",""],["frivolous","FRIV-uh-luhs","adjective","Silly and not important.","Buying a hat for the goldfish was a frivolous idea.","From Latin frivolus, “silly, worthless.”"],["analogy","uh-NAL-uh-jee","noun","A comparison that explains one thing by showing how it is like another.","Our teacher used an analogy: the heart is like a pump.","From Greek analogia, “proportion.”"],["audacious","aw-DAY-shuhs","adjective","Very bold and daring.","She made an audacious plan to read 100 books in a year.","From Latin audax, “bold.”"],["ingenious","in-JEEN-yuhs","adjective","Very clever and inventive.","Leo had an ingenious plan to reach the top shelf.","From Latin ingenium, “natural talent.”"],["incorporate","in-KOR-puh-rayt","verb","To include something as part of a whole.","We will incorporate photos into our class report.","From Latin corpus, “body.”"],["wily","WY-lee","adjective","Clever and tricky.","The wily raccoon figured out how to open the cooler.",""],["decree","dih-KREE","noun","An official order.","By royal decree, the queen in our class play gave everyone a holiday.",""],["affinity","uh-FIN-ih-tee","noun","A natural liking for something.","My cousin has an affinity for drawing animals.","From Latin affinis, “bordering on.”"],["pretentious","prih-TEN-shuhs","adjective","Trying to seem more important or smart than you are.","He used big, pretentious words to sound clever.",""],["infuse","in-FYOOZ","verb","To fill something with a quality or flavor.","Mom likes to infuse her tea with fresh mint.","From Latin infundere, “to pour in.”"],["burgeon","BUR-juhn","verb","To grow or spread quickly.","Our class garden began to burgeon in the spring.","From Old French borjon, “bud.”"],["deride","dih-RYDE","verb","To make fun of in a mean way.","Some great artists were derided before people loved their work.","From Latin deridere, “to laugh at.”"],["abate","uh-BAYT","verb","To become less strong.","We waited for the wind to abate before flying our kite.",""],["remorse","rih-MORS","noun","A deep feeling of being sorry for doing wrong.","He felt remorse after breaking his sister’s sandcastle.","From Latin remordere, “to bite again.”"],["minuscule","MIN-uh-skyool","adjective","Extremely tiny.","There was a minuscule crack in my phone screen.","From Latin minusculus, “rather small.”"],["haggle","HAG-uhl","verb","To argue about the price of something.","We watched Dad haggle over the price of a used bike.",""],["apex","AY-peks","noun","The highest point of something.","We stood at the apex of the hill and saw the whole town.","From Latin apex, “peak.”"],["overbearing","oh-ver-BAIR-ing","adjective","Bossy in a way that is hard to be around.","The overbearing team captain told everyone exactly where to stand.",""],["salient","SAY-lee-uhnt","adjective","Most important or easy to notice.","The salient point of the lesson was to check your work.","From Latin salire, “to leap.”"],["reminisce","rem-uh-NIS","verb","To talk or think about happy past times.","We love to reminisce about our trip to the lake.",""],["erratic","ih-RAT-ik","adjective","Not steady or regular, hard to predict.","The fly’s erratic path made it hard to catch.","From Latin errare, “to wander.”"],["palpable","PAL-puh-buhl","adjective","So strong you can almost touch it.","The excitement before the final game was palpable.","From Latin palpare, “to touch gently.”"],["culminate","KUHL-muh-nayt","verb","To reach the highest point or final moment.","The week of practice culminated in our big concert.","From Latin culmen, “top.”"],["verve","VURV","noun","Energy and style.","The band played with so much verve that everyone danced.",""],["gist","JIST","noun","The main point of something.","I missed part of the movie, but I got the gist.","From Old French gist, “it lies,” meaning the main point."],["vehement","VEE-uh-muhnt","adjective","Showing very strong feelings.","She was vehement that pineapple does not belong on pizza.",""],["oblique","oh-BLEEK","adjective","Slanted, or not said directly.","She made an oblique hint about what she wanted for her birthday.","From Latin obliquus, “slanting.”"],["commend","kuh-MEND","verb","To praise in public.","The principal commended our class for its kindness.",""],["embody","em-BOD-ee","verb","To be a perfect example of an idea or quality.","Our team captain seems to embody good sportsmanship.",""],["ascertain","as-er-TAYN","verb","To find out for sure.","We checked the map to ascertain which trail led to the lake.",""],["lethargic","luh-THAR-jik","adjective","Very sleepy and slow.","I feel lethargic after a big holiday lunch.","From Greek lēthargos, “forgetful.”"],["converge","kuhn-VURJ","verb","To come together at one point.","The two trails converge at the waterfall.",""],["explicit","ik-SPLIS-it","adjective","Stated very clearly, with nothing left out.","The teacher gave explicit steps for the experiment.","From Latin explicitus, “unfolded.”"],["cajole","kuh-JOHL","verb","To gently talk someone into something with sweet words.","I cajoled my brother into playing my favorite game.",""],["dissuade","dih-SWAYD","verb","To talk someone out of doing something.","My friend dissuaded me from eating a whole bag of candy.","From Latin dissuadere, “to advise against.”"],["disdain","dis-DAYN","noun","A feeling that something is not worth your respect.","The cat looked at the cheap toy with disdain.",""],["qualm","KWAHM","noun","A small worry that something is not right.","I had no qualms about giving my old bike to my cousin.",""],["vestige","VES-tij","noun","A small trace of something that is gone.","A vestige of the old treehouse still hangs in the oak.","From Latin vestigium, “footprint.”"],["destitute","DES-ti-toot","adjective","Very poor, without basic things.","Our food drive helps destitute families in town.",""],["copious","KOH-pee-uhs","adjective","Large in amount; plenty.","I took copious notes during the museum tour.","From Latin copia, “plenty.”"],["demean","dih-MEEN","verb","To make someone feel less important.","Good teammates never demean each other.",""],["bode","BOHD","verb","To be a sign of what will happen.","Dark clouds bode badly for our picnic.",""],["unscathed","un-SKAYTHD","adjective","Not hurt at all.","The vase fell off the shelf but landed unscathed on the rug.",""],["peripheral","puh-RIF-er-uhl","adjective","At the edge, not the main part.","I saw the ball coming out of my peripheral vision.","From Greek periphereia, “circumference.”"],["terse","TURS","adjective","Using very few words, sometimes in a rude way.","His terse reply was just “No.”",""],["misgiving","mis-GIV-ing","noun","A feeling of doubt or worry.","I had misgivings about the shaky rope bridge.",""],["surmise","ser-MYZ","verb","To guess based on clues.","From the muddy paws, I surmise the dog went in the garden.",""],["jaunty","JAWN-tee","adjective","Cheerful and full of confidence.","He walked to school in a jaunty way, whistling.","From French gentil, “noble, nice.”"],["dearth","DURTH","noun","Not enough of something.","There was a dearth of snow, so no sledding this year.",""],["eclectic","ih-KLEK-tik","adjective","Made from many different kinds of things.","Jo has an eclectic music list, from banjo to rock.","From Greek eklektikos, “picking out.”"],["bastion","BAS-chuhn","noun","A place or group that strongly protects something.","Our library is a bastion of quiet in a noisy city.",""],["coerce","koh-URS","verb","To force someone to do something.","You can’t coerce a cat into a bath.",""],["pacify","PAS-uh-fy","verb","To calm or soothe.","A lullaby pacified the crying baby.","From Latin pax, “peace.”"],["squander","SKWON-der","verb","To waste something, like money or time.","Don’t squander your allowance on candy.",""],["misnomer","mis-NOH-mer","noun","A name that does not fit the thing.","“Peanut” is a misnomer, since peanuts are not really nuts.","From Old French mesnommer, “to misname.”"],["panacea","pan-uh-SEE-uh","noun","Something people think will fix every problem.","Mom says a good night's sleep is not a panacea, but it helps.","From Greek panakeia, “cure-all.”"],["virtuoso","vur-choo-OH-soh","noun","A person with amazing skill, often in music.","Our music teacher is a piano virtuoso.","From Italian virtuoso, “skilled.”"],["absolve","ab-ZOLV","verb","To free someone from blame.","The video absolved my brother; the cat broke the vase.","From Latin absolvere, “to set free.”"],["beseech","bih-SEECH","verb","To beg someone in an eager way.","I beseech you to let me stay up for the meteor shower.",""],["vindicate","VIN-dih-kayt","verb","To show someone was right or not to blame.","The video helped vindicate me: I did not eat the last cookie.",""],["precocious","prih-KOH-shuhs","adjective","Smart or skilled very early in life.","The precocious four-year-old could already read chapter books.","From Latin praecox, “ripe early.”"],["legacy","LEG-uh-see","noun","Something handed down or left behind for others.","The class garden is our legacy for next year’s students.",""],["infer","in-FUR","verb","To figure something out from clues.","From the muddy paw prints, I can infer the dog went outside.","From Latin inferre, “to bring in.”"],["arbitrary","AR-bih-trair-ee","adjective","Chosen by chance or whim, not for a reason.","Picking teams by shoe color felt arbitrary.","From Latin arbitrarius, “uncertain.”"],["finesse","fih-NES","noun","Skill and grace in handling something.","She iced the cupcakes with real finesse.","From French fin, “fine.”"],["superficial","soo-per-FISH-uhl","adjective","Only on the surface, not deep.","The scratch on my knee was only superficial.","From Latin superficies, “surface.”"],["rampant","RAM-puhnt","adjective","Spreading fast and out of control.","Weeds grew rampant in the empty lot.",""],["delegate","DEL-i-gayt","verb","To give part of a job to someone else.","The team captain delegated tasks to each player.",""],["vantage","VAN-tij","noun","A spot that gives a good view.","From our vantage point on the hill, we saw the whole parade.",""],["metaphor","MET-uh-for","noun","Saying one thing is another thing to compare them.","My teacher said “time is a thief” is a metaphor.","From Greek metaphora, “a carrying over.”"],["affront","uh-FRUHNT","noun","An insult that hurts someone’s pride.","Being picked last felt like an affront.",""],["anthology","an-THOL-uh-jee","noun","A book with many stories or poems by different writers.","Our class made an anthology of our best poems.","From Greek anthologia, “a gathering of flowers.”"],["zephyr","ZEF-er","noun","A soft, gentle breeze.","A warm zephyr blew through the open window.","From Greek Zephyros, “the west wind.”"],["charisma","kuh-RIZ-muh","noun","A special charm that draws people to you.","Her charisma made the whole class want to join her club.","From Greek kharisma, “gift.”"],["archaic","ar-KAY-ik","adjective","Very old and no longer used.","“Thou” is an archaic word for “you.”","From Greek arkhaios, “ancient.”"],["overture","OH-ver-cher","noun","A first step to start a friendship or a deal; also the opening music of a show.","Sharing her crayons was an overture of friendship.","From Old French overture, “opening.”"],["conform","kuhn-FORM","verb","To follow the rules or act like everyone else.","Our costumes must conform to the school’s dress code.",""],["anomaly","uh-NOM-uh-lee","noun","Something different from what is normal or expected.","A snowy day in May would be an anomaly here.","From Greek anōmalia, “unevenness.”"],["myriad","MEER-ee-uhd","adjective","Too many to count.","The reef was home to myriad colorful fish.","From Greek myrias, “ten thousand.”"],["relinquish","rih-LING-kwish","verb","To give up or let go of something.","My brother finally agreed to relinquish the remote.","From Latin relinquere, “to leave behind.”"],["lucrative","LOO-kruh-tiv","adjective","Making a lot of money.","Our lemonade stand was lucrative on the hottest day.","From Latin lucrum, “profit.”"],["contrite","kuhn-TRYTE","adjective","Truly sorry for doing something wrong.","The contrite puppy brought back the stolen sock.",""],["aggregate","AG-rih-git","noun","A total made by adding things together.","Our team’s aggregate score was the highest in the league.","From Latin aggregare, “to add to a flock.”"],["facade","fuh-SAHD","noun","The front of a building, or a false outside look.","The old shop had a bright blue facade.","From French façade, “front.”"],["scrupulous","SKROO-pyuh-luhs","adjective","Very careful to do what is right.","The scrupulous cashier gave back the extra change.",""],["mitigate","MIT-ih-gayt","verb","To make something less bad.","Planting trees can help mitigate the summer heat.","From Latin mitigare, “to soften.”"],["concede","kuhn-SEED","verb","To admit something is true, often unwillingly.","I conceded that my sister’s sandcastle was better.",""],["scintillating","SIN-tuh-lay-ting","adjective","Sparkling, or very lively and clever.","The guest speaker gave a scintillating talk about space.","From Latin scintilla, “spark.”"],["grievance","GREE-vuhns","noun","A complaint about something unfair.","The class shared their grievance about the short recess.",""],["opportune","op-er-TOON","adjective","Happening at just the right time.","Dad was in a good mood, so it was an opportune time to ask for a puppy.","From Latin opportunus, “toward the port,” as in a helpful wind."],["synthesize","SIN-thuh-syz","verb","To combine parts to make something new.","We had to synthesize facts from three books into one report.","From Greek synthesis, “putting together.”"],["exemplary","ig-ZEM-pluh-ree","adjective","So good that others should copy it.","Her exemplary science project won first prize.","From Latin exemplum, “example.”"],["counterfeit","KOWN-ter-fit","adjective","Fake and made to look real.","The counterfeit trading card had blurry printing.",""],["amenable","uh-MEE-nuh-buhl","adjective","Willing to go along with an idea.","Dad was amenable to pancakes for dinner.",""],["conundrum","kuh-NUHN-druhm","noun","A confusing problem or riddle.","Fitting the giant pizza box in the fridge was a conundrum.",""],["tenuous","TEN-yoo-uhs","adjective","Very weak or thin.","Our lead in the game was tenuous, just one point.","From Latin tenuis, “thin.”"],["canny","KAN-ee","adjective","Smart and careful, especially with money or choices.","The canny shopper saved her allowance for a month.",""],["allot","uh-LOT","verb","To give out a share of something.","Mom will allot each of us three cookies.",""],["contend","kuhn-TEND","verb","To compete or struggle.","Five teams will contend for the trophy.",""],["manifest","MAN-uh-fest","verb","To show clearly.","Her love of animals manifests in how she cares for her pets.","From Latin manifestus, “clear.”"],["gregarious","grih-GAIR-ee-uhs","adjective","Liking to be with other people.","Our gregarious dog greets everyone at the park.","From Latin grex, “flock.”"],["inundate","IN-uhn-dayt","verb","To flood, or to give too much of something.","Fans will inundate the author with letters.","From Latin unda, “wave.”"],["cynical","SIN-i-kuhl","adjective","Believing people only care about themselves.","Don’t be so cynical; most people want to help.",""],["oust","OWST","verb","To push someone out of a place or job.","The bigger bird ousted the sparrow from the feeder.",""],["hone","HOHN","verb","To sharpen or make better through practice.","She practices daily to hone her piano skills.","From Old English hān, “stone.”"],["provisional","pruh-VIZH-uh-nuhl","adjective","Set up for now, maybe changed later.","We made a provisional plan in case of rain.",""],["outmoded","owt-MOH-did","adjective","Out of date; no longer in style.","My cousin's flip phone is outmoded but still works.",""],["sporadic","spuh-RAD-ik","adjective","Happening now and then, not on a regular basis.","We heard sporadic thunder all afternoon.","From Greek sporadikos, “scattered.”"],["perpetual","per-PECH-oo-uhl","adjective","Going on forever, without stopping.","My little sister seems to be in perpetual motion.","From Latin perpetuus, “continuous.”"],["cognitive","KOG-ni-tiv","adjective","About thinking, learning and remembering.","Puzzles give your cognitive skills a workout.","From Latin cognoscere, “to get to know.”"],["annotate","AN-oh-tayt","verb","To add notes to explain something you are reading.","We annotate our poems with sticky notes in class.","From Latin nota, “mark.”"],["jaded","JAY-did","adjective","Bored or tired from having too much of something.","After ten rides, even the roller coaster made him feel jaded.",""],["moot","MOOT","adjective","No longer worth arguing about.","Whether we'd play outside was moot once the thunderstorm hit.",""],["accolade","AK-uh-layd","noun","An award or words of high praise.","Winning the science fair was the biggest accolade of her year.",""],["autonomy","aw-TON-uh-mee","noun","The freedom to make your own choices.","Getting a bus pass gave my brother more autonomy.","From Greek autonomia, “self-rule.”"],["avarice","AV-er-is","noun","Extreme greed for money or things.","In the fable, the king’s avarice made him lose everything.","From Latin avarus, “greedy.”"],["consolidate","kuhn-SOL-i-dayt","verb","To combine into one stronger thing.","We consolidated our two toy bins into one big bin.",""],["ludicrous","LOO-dih-kruhs","adjective","So silly it is funny.","A dog wearing sunglasses and a tie looks ludicrous.","From Latin ludus, “play, game.”"],["glib","GLIB","adjective","Smooth and quick in speaking, but not careful or deep.","His glib excuse did not fool the teacher.",""],["cadence","KAY-duhns","noun","The rhythm and rise and fall of sounds.","The cadence of the poem made it easy to memorize.","From Latin cadere, “to fall.”"],["hierarchy","HY-uh-rar-kee","noun","A system that ranks people or things from top to bottom.","In our chicken coop, there is a clear pecking hierarchy.",""],["advent","AD-vent","noun","The arrival or start of something important.","The advent of spring brought tulips to our yard.","From Latin adventus, “arrival.”"],["pessimist","PES-uh-mist","noun","Someone who expects things to go wrong.","The pessimist packed three umbrellas for a sunny day.","From Latin pessimus, “worst.”"],["comprise","kuhm-PRYZE","verb","To be made up of.","Our team comprises six players and a coach.",""],["volatile","VOL-uh-tuhl","adjective","Likely to change quickly, often in a wild way.","The weather in the mountains is volatile.","From Latin volare, “to fly.”"],["hiatus","hy-AY-tuhs","noun","A break or pause.","The band club took a hiatus during exams.","From Latin hiatus, “an opening, gap.”"],["redundant","rih-DUN-duhnt","adjective","Not needed because it repeats something.","Saying “free gift” is redundant, since gifts are free.","From Latin redundare, “to overflow.”"],["oscillate","OS-uh-layt","verb","To swing back and forth.","The fan oscillates so it cools the whole room.","From Latin oscillare, “to swing.”"],["bravado","bruh-VAH-doh","noun","Showing off how brave you are, often to hide fear.","With great bravado, he said he wasn’t scared of the dark.","From Spanish bravada."],["attest","uh-TEST","verb","To show or say that something is true.","Anyone who tasted it can attest that the pie was delicious.","From Latin attestari, “to bear witness.”"],["blanch","BLANCH","verb","To turn pale, often from shock.","He seemed to blanch when he saw the size of the math test.","From French blanc, “white.”"],["daunting","DAWN-ting","adjective","Seeming hard or scary to start.","The huge stack of library books looked daunting.",""],["ravenous","RAV-uh-nuhs","adjective","Very, very hungry.","After swim practice, I am always ravenous.",""],["adjourn","uh-JURN","verb","To stop a meeting and continue it later.","The student council will adjourn and meet again Friday.","From Old French ajorner, “to set a day.”"],["procure","proh-KYUR","verb","To get something, often with effort.","We procured enough cardboard boxes to build a fort.","From Latin procurare, “to take care of.”"],["abscond","ab-SKOND","verb","To leave secretly and quickly, often with something.","The puppy tried to abscond with my sock.","From Latin abscondere, “to hide away.”"],["epitome","ih-PIT-uh-mee","noun","A perfect example of something.","My grandma’s kitchen is the epitome of cozy.","From Greek epitome, “a cutting short.”"],["meddle","MED-uhl","verb","To get involved in something that is not your business.","Please don't meddle with my science project while I'm at practice.","From Old French medler, “to mix.”"],["subsequent","SUB-sih-kwuhnt","adjective","Coming after something else.","The first test was hard, but subsequent tests got easier.","From Latin subsequi, “to follow close after.”"],["indifferent","in-DIF-er-uhnt","adjective","Not caring one way or the other.","The cat was indifferent to its fancy new toy.",""],["mosaic","moh-ZAY-ik","noun","A picture made from small colored pieces.","We made a mosaic of a turtle from broken tiles.",""],["uproar","UP-ror","noun","Loud noise and confusion.","The gym was in an uproar after the winning shot.",""],["onerous","OH-ner-uhs","adjective","Heavy, hard and tiring to do.","Cleaning the whole garage was an onerous job.","From Latin onus, “burden.”"],["scrutinize","SKROO-tuh-nyz","verb","To look at something very closely.","The judges scrutinize every painting in the art show.",""],["dissent","dih-SENT","noun","Disagreement with the group.","There was some dissent when the class voted on the field trip.",""],["rudimentary","roo-duh-MEN-tuh-ree","adjective","Very basic, at the starting level.","I have a rudimentary knowledge of Spanish.","From Latin rudimentum, “first attempt.”"],["relentless","rih-LENT-lis","adjective","Not stopping or giving up.","The relentless rain kept us inside all weekend.",""],["innate","ih-NAYT","adjective","Something you are born with.","Birds have an innate sense of when to fly south.","From Latin innatus, “inborn.”"],["pensive","PEN-siv","adjective","Deep in quiet thought.","Grandpa looked pensive as he watched the sunset.","From French pensif, “thoughtful.”"],["deviate","DEE-vee-ayt","verb","To go off the usual path.","We deviated from the trail to watch a deer.","From Latin de-, “away from,” and via, “road.”"],["quandary","KWON-duh-ree","noun","A state of not knowing what to do.","I was in a quandary about which club to join.",""],["paradox","PAIR-uh-doks","noun","Something that seems to contradict itself but may still be true.","It's a paradox that the more you rest, the more tired you can feel.","From Greek paradoxos, “contrary to belief.”"],["paramount","PAIR-uh-mownt","adjective","Most important of all.","Safety is paramount when you use the stove.","From Old French par amont, “above.”"],["parched","PARCHT","adjective","Very dry or very thirsty.","After soccer practice, I was parched.",""],["unprecedented","un-PRES-ih-den-tid","adjective","Never done or seen before.","Our team had an unprecedented ten wins in a row.",""],["allege","uh-LEJ","verb","To say something is true without proof.","My sister alleges that I ate the last cookie.",""],["noxious","NOK-shuhs","adjective","Harmful or very unpleasant.","The noxious fumes from the paint made us open the windows.","From Latin noxius, “harmful.”"],["cumulative","KYOO-myuh-luh-tiv","adjective","Growing by adding up over time.","The cumulative effect of reading every night was huge.","From Latin cumulus, “heap.”"],["nullify","NUL-uh-fy","verb","To cancel out or make worthless.","The rain nullified all our chalk drawings.","From Latin nullus, “none.”"],["bevy","BEV-ee","noun","A group of people or animals.","A bevy of ducks floated across the pond.",""],["attune","uh-TOON","verb","To make someone more aware of or in tune with something.","Bird watching helps attune your ears to the sounds of the forest.",""],["placate","PLAY-kayt","verb","To make someone less angry.","I placated my sister by letting her pick the movie.","From Latin placare, “to calm.”"],["mar","MAR","verb","To spoil or damage.","A scratch marred the new table.","From Old English merran, “to hinder.”"],["imminent","IM-uh-nuhnt","adjective","About to happen very soon.","With thunder rumbling, rain was imminent.","From Latin imminere, “to hang over.”"],["imperative","im-PAIR-uh-tiv","adjective","Very important and needing to be done.","It is imperative that we feed the fish before the trip.","From Latin imperare, “to command.”"],["marginal","MAR-juh-nuhl","adjective","Small and not very important.","Adding one more ice cube made only a marginal difference.","From Latin margo, “edge.”"],["catalyst","KAT-uh-list","noun","Something that causes a change to happen.","The science fair was the catalyst for my love of robots.",""],["desolate","DES-uh-lit","adjective","Empty and lonely.","The beach looked desolate in the winter.","From Latin desolare, “to leave alone.”"],["fallacy","FAL-uh-see","noun","A false idea that many people believe.","It is a fallacy that goldfish only remember things for three seconds.","From Latin fallere, “to deceive.”"],["constrain","kuhn-STRAYN","verb","To hold back or limit.","Our small yard constrains how far we can kick the ball.",""],["antidote","AN-tih-doht","noun","A cure or a fix for something bad.","Laughing with friends is the best antidote to a bad day.","From Greek antidoton, “given against.”"],["blasé","blah-ZAY","adjective","Not impressed or excited because you have seen it before.","My older brother acts blasé about roller coasters now.","From French blasé, “worn out with pleasure.”"],["corrode","kuh-ROHD","verb","To slowly wear away, like metal rusting.","Salt water corroded the old bike chain.","From Latin corrodere, “to gnaw to pieces.”"],["defer","dih-FUR","verb","To put off until later.","We deferred the picnic until the rain stopped.",""],["dissipate","DIS-uh-payt","verb","To fade away or scatter.","The morning fog dissipated by lunch.",""],["bygone","BY-gon","adjective","From a time long past.","Grandma loves stories from bygone days.",""],["augment","awg-MENT","verb","To make bigger or add to.","We augment our lemonade stand money by selling cookies too.","From Latin augere, “to increase.”"],["garner","GAR-ner","verb","To gather or earn something.","Her funny video began to garner lots of laughs at school.","From Latin granarium, “granary.”"],["serendipity","ser-uhn-DIP-ih-tee","noun","Finding something good by happy chance.","By serendipity, I found my lost ring in the sandbox.",""],["tirade","TY-rayd","noun","A long, angry speech.","My brother went on a tirade about losing his video game.",""],["hamper","HAM-per","verb","To slow down or get in the way.","Thick fog can hamper the ferry’s trip.",""],["fervent","FUR-vuhnt","adjective","Full of strong, warm feeling.","He is a fervent fan of his little sister’s soccer team.","From Latin fervere, “to boil.”"],["protagonist","proh-TAG-uh-nist","noun","The main character in a story.","The protagonist of my favorite book is a brave mouse.","From Greek protagonistes, “first actor.”"],["dissect","dy-SEKT","verb","To cut apart carefully to study.","In science class we dissected a flower to see its parts.","From Latin dissecare, “to cut apart.”"],["concoct","kuhn-KOKT","verb","To mix up or make up something new.","We concocted a smoothie with every fruit in the fridge.","From Latin concoquere, “to cook together.”"],["verbose","ver-BOHS","adjective","Using more words than needed.","His verbose answer took up two whole pages.","From Latin verbum, “word.”"],["homage","OM-ij","noun","Something done to show respect or honor.","Our mural pays homage to the town’s first library.",""],["ambivalent","am-BIV-uh-luhnt","adjective","Having mixed feelings about something.","I felt ambivalent about moving: excited, but sad to leave friends.",""],["brash","BRASH","adjective","Bold and confident in a pushy way.","The brash new player bragged he would score ten goals.",""],["allude","uh-LOOD","verb","To hint at something without saying it directly.","Mom alluded to a surprise trip but would not tell us where.","From Latin alludere, “to play with.”"],["rebuttal","rih-BUT-uhl","noun","An answer that argues against what someone said.","In the class debate, Maya gave a strong rebuttal.",""],["covert","KOH-vert","adjective","Secret or hidden.","We planned a covert mission to hide Mom’s present.",""],["ebb","EB","verb","To slowly flow away or get weaker.","We waited for the tide to ebb so we could find shells.","From Old English ebba, “low tide.”"],["askew","uh-SKYOO","adjective","Crooked; not straight.","The picture on the wall was askew after the door slammed.",""],["penchant","PEN-chuhnt","noun","A strong liking for something.","My dog has a penchant for stealing socks.","From French pencher, “to lean.”"],["ornate","or-NAYT","adjective","Covered with fancy decoration.","The old library has an ornate ceiling with painted stars.","From Latin ornatus, “decorated.”"],["blithe","BLITHE","adjective","Happy and carefree.","She sang in a blithe voice as she skipped down the hall.","From Old English blīthe, “joyful.”"],["iconic","eye-KON-ik","adjective","Very well known and easy to recognize.","The red barn is an iconic sight in our town.","From Greek eikōn, “image.”"],["lackluster","LAK-lus-ter","adjective","Dull and not exciting.","The magic show was lackluster because the rabbit never appeared.",""],["plagiarize","PLAY-juh-ryz","verb","To copy someone else's work and say it is yours.","Our teacher reminded us never to plagiarize a book report.","From Latin plagiarius, “kidnapper.”"],["commemorate","kuh-MEM-uh-rayt","verb","To do something special to remember a person or event.","We planted a tree to commemorate our school’s 100th birthday.","From Latin memorare, “to remember.”"],["muse","MYOOZ","verb","To think about something in a slow, dreamy way.","On the porch swing, I mused about what to name my new kitten.",""],["riveting","RIV-it-ing","adjective","So interesting you can’t look away.","The mystery book was so riveting that I read it in one night.",""],["mollify","MOL-uh-fy","verb","To calm someone who is upset.","A warm cookie mollified my grumpy little brother.","From Latin mollis, “soft.”"],["replicate","REP-lih-kayt","verb","To copy or do something again the same way.","Scientists try to replicate an experiment to check it.",""],["dexterous","DEK-struhs","adjective","Skillful with the hands.","The dexterous juggler kept five balls in the air.","From Latin dexter, “right-handed, skillful.”"],["preposterous","prih-POS-ter-uhs","adjective","Silly and hard to believe.","The idea of a cat driving a bus is preposterous.","From Latin praeposterus, “reversed,” as in “before behind.”"],["ambiguous","am-BIG-yoo-uhs","adjective","Having more than one possible meaning; unclear.","The riddle was ambiguous, so we argued about the answer.","From Latin ambiguus, “doubtful.”"],["acclaim","uh-KLAYM","noun","Loud praise and approval.","The student film won acclaim at the town festival.","From Latin acclamare, “to shout at.”"],["auspicious","aw-SPISH-uhs","adjective","Showing signs of future success.","A sunny morning felt like an auspicious start to our camping trip.",""],["satire","SAT-yr","noun","Writing or acting that uses humor to poke fun at something.","Our class play was a satire about school lunch.","From Latin satura, “a mixed dish.”"],["escalate","ES-kuh-layt","verb","To grow bigger or more serious step by step.","A small pillow fight can quickly escalate into a giant one.","From Latin scala, “ladder.”"],["lassitude","LAS-ih-tood","noun","A tired, weak feeling.","A heavy lassitude came over us after the long beach day.","From Latin lassus, “weary.”"],["rancor","RANG-ker","noun","Bitter, long-lasting anger.","After the game, the two teams shook hands without rancor.","From Latin rancor, “rankness, grudge.”"],["abstemious","ab-STEE-mee-uhs","adjective","Careful not to eat or drink too much.","My abstemious uncle only ever takes one small piece of cake.",""],["cerebral","suh-REE-bruhl","adjective","Thinking deeply rather than going by feelings.","My cerebral friend loves chess and logic puzzles.","From Latin cerebrum, “brain.”"],["redoubtable","rih-DOW-tuh-buhl","adjective","Strong enough to earn respect, even a little fear.","The redoubtable chess champion had never lost a match.",""],["winsome","WIN-suhm","adjective","Sweet and charming.","The puppy had a winsome face that made everyone smile.",""],["strident","STRY-duhnt","adjective","Loud and harsh.","The strident alarm woke the whole house.","From Latin stridere, “to creak.”"],["peremptory","puh-REMP-tuh-ree","adjective","Bossy and expecting to be obeyed at once.","The coach gave a peremptory whistle, and everyone froze.",""],["convalesce","kon-vuh-LES","verb","To rest and get better after being sick.","I convalesced on the couch with soup and comic books.","From Latin valere, “to be strong.”"],["guile","GYLE","noun","Clever, tricky behavior.","The fox in the story used guile to get the grapes.",""],["susceptible","suh-SEP-tuh-buhl","adjective","Easily affected or harmed by something.","My little brother is susceptible to colds in winter.",""],["machination","mak-uh-NAY-shuhn","noun","A sneaky plan or scheme.","My little brother's machinations to get the last cookie never work.","From Latin machinari, “to contrive.”"],["ossify","OS-uh-fy","verb","To become hard, fixed and unable to change.","Without new ideas, the club's routine began to ossify.","From Latin os, “bone.”"],["axiom","AK-see-uhm","noun","A statement accepted as true without needing proof.","It is an axiom in our house that whoever cooks does not wash dishes.","From Greek axiōma, “what is thought fitting.”"],["desultory","DES-uhl-tor-ee","adjective","Without a plan; jumping from one thing to another.","Our desultory chat bounced from dogs to space to pancakes.",""],["insipid","in-SIP-id","adjective","Dull, without flavor or interest.","The soup was insipid until we added salt.","From Latin sapidus, “tasty,” so “not tasty.”"],["querulous","KWER-uh-luhs","adjective","Always complaining in a whiny way.","The querulous toddler fussed all through the car ride.","From Latin queri, “to complain.”"],["umbrage","UM-brij","noun","A feeling of being offended.","My cat took umbrage when I moved her bed.","From Latin umbra, “shade.”"],["magnanimous","mag-NAN-uh-muhs","adjective","Generous and forgiving, especially to someone who lost or did wrong.","The magnanimous winner shared her prize candy with every player.","From Latin magnanimus, “great-souled.”"],["germane","jer-MAYN","adjective","Closely connected to the topic.","Keep your questions germane to the science lesson.","From Latin germanus, “of the same parents.”"],["juxtapose","JUK-stuh-pohz","verb","To place things side by side to compare them.","The art teacher had us juxtapose warm and cool colors.","From Latin juxta, “next to.”"],["harangue","huh-RANG","noun","A long, loud speech that scolds.","The coach gave a harangue about leaving water bottles on the field.",""],["assay","AS-ay","noun","A test to find out what something is made of.","An assay showed the shiny rock was not real gold.",""],["ballyhoo","BAL-ee-hoo","noun","Noisy excitement or attention-getting fuss.","After all the ballyhoo, the new ride was only five seconds long.",""],["fastidious","fa-STID-ee-uhs","adjective","Very careful about details and neatness.","My fastidious cousin lines up his pencils by color.","From Latin fastidium, “disgust.”"],["obsequious","uhb-SEE-kwee-uhs","adjective","Too eager to please or obey.","The obsequious puppy followed us everywhere, wagging and bowing.","From Latin obsequi, “to comply.”"],["bonhomie","bon-uh-MEE","noun","Cheerful friendliness.","The bonhomie at the block party made everyone feel welcome.","From French bonhomie, “good nature.”"],["abeyance","uh-BAY-uhns","noun","A state of being put on hold for a while.","Our plans for the beach trip are in abeyance until the rain stops.",""],["abrogate","AB-ruh-gayt","verb","To officially end a rule or agreement.","The club voted to abrogate the old rule about secret handshakes.","From Latin abrogare, “to repeal.”"],["assonance","AS-uh-nuhns","noun","The repeating of vowel sounds in nearby words, as in poems.","“The rain in Spain” is a fun example of assonance.","From Latin assonare, “to sound in answer.”"],["bathos","BAY-thos","noun","A sudden, silly drop from a serious mood to a trivial one.","The poem ended in bathos when the hero tripped over a cat.","From Greek bathos, “depth.”"],["hubris","HYOO-bris","noun","Too much pride.","The rabbit’s hubris made him nap during the race.","From Greek hybris, “pride.”"],["efface","ih-FAYS","verb","To rub out or make hard to see.","Years of rain had begun to efface the chalk mural.","From French effacer, “to wipe out.”"],["ebullient","ih-BUL-yuhnt","adjective","Bubbling over with cheer and energy.","Our ebullient coach high-fived every player.","From Latin ebullire, “to boil over.”"],["largesse","lar-ZHES","noun","Generous giving of gifts or money.","Thanks to a neighbor’s largesse, our school got new books.","From Latin largus, “generous.”"],["eschew","es-CHOO","verb","To stay away from on purpose.","The athletes eschew sugary drinks before a race.",""],["tantamount","TAN-tuh-mownt","adjective","Equal to, in effect.","Not doing your part in a group project is tantamount to quitting.",""],["reverie","REV-uh-ree","noun","A happy daydream.","The bell snapped me out of my reverie about summer camp.","From French rêverie, “dreaming.”"],["misanthrope","MIS-uhn-throhp","noun","Someone who dislikes people in general.","The grumpy hermit in the story was a misanthrope who loved only his goats.","From Greek misanthropos, “hating people.”"],["assuage","uh-SWAYJ","verb","To ease or calm a bad feeling.","A hug from Mom helped assuage my disappointment.",""],["conciliatory","kuhn-SIL-ee-uh-tor-ee","adjective","Trying to make peace.","My conciliatory offer to share the swing ended our fight.",""],["inexorable","in-EK-ser-uh-buhl","adjective","Impossible to stop.","The inexorable tide washed away our sandcastle.","From Latin exorare, “to plead successfully.”"],["bilious","BIL-yuhs","adjective","Grumpy and bad-tempered.","After missing the bus, he was in a bilious mood all day.","From Latin bilis, “bile.”"],["disquiet","dis-KWY-it","noun","A feeling of worry.","A small disquiet grew as the bus ran later and later.",""],["mendacious","men-DAY-shuhs","adjective","Not telling the truth.","The mendacious note claimed the dog had done my homework.","From Latin mendax, “lying.”"],["crass","KRAS","adjective","Rude and without good taste.","Bragging about the prize in front of everyone was crass.",""],["acerbic","uh-SUR-bik","adjective","Sharp and biting in how you speak.","The food critic in the novel wrote acerbic reviews.","From Latin acerbus, “sour, bitter.”"],["lackadaisical","lak-uh-DAY-zih-kuhl","adjective","Lazy and not caring much.","His lackadaisical sweeping left crumbs all over the floor.",""],["nascent","NAY-suhnt","adjective","Just starting to grow or form.","Our nascent book club has only three members so far.","From Latin nasci, “to be born.”"],["consummate","KON-suh-mit","adjective","Showing great skill; complete and perfect.","The magician at the party was a consummate showman.",""],["taciturn","TAS-ih-turn","adjective","Quiet and not saying much.","My taciturn neighbor only nods hello.","From Latin tacitus, “silent.”"],["commiserate","kuh-MIZ-uh-rayt","verb","To share sympathy with someone who is sad.","We commiserated about our canceled field trip.","From Latin miser, “wretched.”"],["pellucid","puh-LOO-sid","adjective","Very clear, easy to see through or understand.","The pellucid stream showed every pebble on the bottom.","From Latin pellucidus, “transparent.”"],["trenchant","TREN-chuhnt","adjective","Sharp, clear and to the point.","Her trenchant comment ended the long argument.",""],["avow","uh-VOW","verb","To say something openly and firmly.","He avowed that he would finish the marathon.",""],["lithe","LYTHE","adjective","Thin, strong and able to bend easily.","The lithe cat slipped through the fence.","From Old English līthe, “gentle, soft.”"],["incisive","in-SY-siv","adjective","Sharp and clear in thinking.","Her incisive question got to the heart of the problem.","From Latin incidere, “to cut into.”"],["derelict","DAIR-uh-likt","adjective","Left behind and falling apart.","A derelict rowboat sat on the edge of the lake.",""],["benighted","bih-NY-tid","adjective","Lacking knowledge or understanding.","The explorers in the story thought the villagers were benighted, but they were wrong.",""],["forlorn","fer-LORN","adjective","Lonely and sad.","A forlorn mitten lay in the snow.","From Old English forloren, “lost.”"],["reprehensible","rep-rih-HEN-suh-buhl","adjective","Very wrong and deserving blame.","Cheating on the test was reprehensible.",""],["debacle","dih-BAH-kuhl","noun","A sudden, total failure.","The cake that sank in the middle was a debacle.",""],["equanimity","ee-kwuh-NIM-ih-tee","noun","Staying calm, even when things go wrong.","She met the spilled paint with equanimity and grabbed a towel.","From Latin aequus, “even,” and animus, “mind.”"],["proverbial","pruh-VUR-bee-uhl","adjective","Well known, as in a common saying.","Finding my earring in the sandbox was like the proverbial needle in a haystack.","From Latin proverbium, “a saying.”"],["provincial","pruh-VIN-shuhl","adjective","Narrow in thinking, not open to the wider world.","Traveling helped him let go of his provincial views about food.","From Latin provincia, “province.”"],["cacophony","kuh-KOF-uh-nee","noun","A harsh mix of loud, clashing sounds.","The band warming up made a cacophony of honks and squeaks.","From Greek kakos, “bad,” and phone, “sound.”"],["allegory","AL-uh-gor-ee","noun","A story with a hidden meaning or lesson.","The tale of the tortoise and the hare is an allegory about patience.","From Greek allēgoria, “speaking otherwise.”"],["opprobrium","uh-PROH-bree-uhm","noun","Harsh public criticism or shame.","The team faced opprobrium for leaving trash in the park.","From Latin opprobrium, “reproach.”"],["aphorism","AF-uh-riz-uhm","noun","A short, wise saying.","“Well begun is half done” is my coach’s favorite aphorism.","From Greek aphorismos, “definition.”"],["neophyte","NEE-uh-fyt","noun","A beginner at something.","As a neophyte at fishing, I tangled my line right away.","From Greek neophytos, “newly planted.”"],["divulge","dih-VUHLJ","verb","To share a secret.","She would not divulge the ending of the book.",""],["platitude","PLAT-ih-tood","noun","A saying used so often that it means little.","“Everything happens for a reason” felt like a platitude after the game.","From French plat, “flat.”"],["anodyne","AN-uh-dine","adjective","Harmless and unlikely to upset anyone, often a bit dull.","The speech was so anodyne that nobody remembered it.","From Greek anōdynos, “without pain.”"],["convivial","kuhn-VIV-ee-uhl","adjective","Friendly, lively and fun, like a good party.","The family reunion had a convivial mood.","From Latin convivium, “a feast.”"],["remiss","rih-MIS","adjective","Careless about doing what you should.","I would be remiss if I forgot to thank my coach.",""],["salubrious","suh-LOO-bree-uhs","adjective","Good for your health.","The fresh mountain air was salubrious.","From Latin salus, “health.”"],["propagate","PROP-uh-gayt","verb","To spread or grow more of something.","We propagated new plants from cuttings in water.","From Latin propagare, “to plant cuttings.”"],["cloying","KLOY-ing","adjective","So sweet it becomes too much.","The frosting was cloying after the second cupcake.",""],["paucity","PAW-sih-tee","noun","A small amount; not enough.","There was a paucity of snacks at the end of the party.","From Latin paucus, “few.”"],["vitriolic","vit-ree-OL-ik","adjective","Very bitter and harsh.","The book review was so vitriolic that the author felt hurt.",""],["approbation","ap-ruh-BAY-shuhn","noun","Approval or praise.","The young chef won the approbation of the whole family.","From Latin approbare, “to approve.”"],["bibliophile","BIB-lee-uh-file","noun","A person who loves books.","As a true bibliophile, she has books stacked in every room.","From Greek biblion, “book,” and philos, “loving.”"],["rapacious","ruh-PAY-shuhs","adjective","Greedy and grabbing for more.","The rapacious seagulls snatched fries right off our plates.","From Latin rapere, “to seize.”"],["scathing","SKAY-thing","adjective","Very harsh and critical.","The judge gave a scathing review of the burnt pie.",""],["agog","uh-GOG","adjective","Very eager and excited.","The kids were agog as the baby chicks hatched.",""],["intransigent","in-TRAN-sih-juhnt","adjective","Refusing to change your mind.","The intransigent toddler would only wear his rain boots.","From Spanish intransigente, “not compromising.”"],["venerable","VEN-er-uh-buhl","adjective","Respected because of age or wisdom.","The venerable oak tree has stood in the park for 300 years.",""],["alliteration","uh-lit-uh-RAY-shuhn","noun","Using the same first sound in words close together.","“Silly snakes slither slowly” is full of alliteration.","From Latin littera, “letter.”"],["besmirch","bih-SMURCH","verb","To damage someone’s good name.","Spreading rumors can besmirch a person’s reputation.",""],["impervious","im-PUR-vee-uhs","adjective","Not let in or not affected by something.","My new raincoat is impervious to water.","From Latin impervius, “not passable.”"],["bellwether","BEL-weth-er","noun","Something that shows where a trend is heading.","The first warm day is a bellwether of summer.","From Middle English, a lead sheep that wore a bell."],["maudlin","MAWD-lin","adjective","Sad or sentimental in an overdone, tearful way.","The movie's ending got maudlin, with everyone crying for ten minutes.",""],["celerity","suh-LER-i-tee","noun","Great speed.","The hummingbird moved with amazing celerity.","From Latin celer, “swift.”"],["coalesce","koh-uh-LES","verb","To come together to form one whole.","Our scattered ideas coalesced into one great science project.",""],["spurious","SPYOOR-ee-uhs","adjective","False, even if it looks real.","The ad made spurious claims about a toy that could fly.","From Latin spurius, “false.”"],["perfidious","per-FID-ee-uhs","adjective","Not loyal; breaking promises.","The perfidious fox in the fable tricked its friend the crow.","From Latin perfidia, “faithlessness.”"],["presage","PRES-ij","verb","To be a sign of what is coming.","Dark clouds presaged an afternoon storm.","From Latin praesagire, “to sense beforehand.”"],["unflappable","un-FLAP-uh-buhl","adjective","Always calm, even when things go wrong.","Our unflappable teacher stayed calm when the fire alarm rang.",""],["pernicious","per-NISH-uhs","adjective","Harmful in a slow, sneaky way.","Weeds are pernicious, quietly crowding out the flowers.","From Latin pernicies, “ruin.”"],["extol","ik-STOHL","verb","To praise very highly.","The judges extol her mural as the best in the show.","From Latin extollere, “to raise up.”"],["manifold","MAN-uh-fohld","adjective","Many and of different kinds.","The benefits of reading are manifold.","From Old English manigfeald, “many-fold.”"],["insatiable","in-SAY-shuh-buhl","adjective","Never satisfied, always wanting more.","My little brother has an insatiable hunger for dinosaur facts.","From Latin satiare, “to fill.”"],["aspersion","uh-SPUR-zhuhn","noun","An unkind remark that hurts someone’s reputation.","She would never cast aspersions on a teammate.",""],["apropos","ap-ruh-POH","adjective","Fitting for the moment.","Her joke about snow was apropos on the first day of winter.","From French à propos, “to the purpose.”"],["apoplectic","ap-uh-PLEK-tik","adjective","So angry you can barely speak.","The coach was nearly apoplectic when the bus left without the team.",""],["inane","ih-NAYN","adjective","Silly and without sense.","We laughed at the inane jokes in the comic book.","From Latin inanis, “empty.”"],["defunct","dih-FUHNGKT","adjective","No longer working or existing.","We found a defunct robot toy in the attic.",""],["exhort","ig-ZORT","verb","To strongly urge someone to do something.","The coach would exhort us to run one more lap.","From Latin exhortari, “to encourage.”"],["stolid","STOL-id","adjective","Calm and showing little feeling.","The stolid guard did not smile at our jokes.",""],["itinerant","eye-TIN-er-uhnt","adjective","Moving from place to place.","An itinerant puppet show came to our town each spring.","From Latin iter, “journey.”"],["didactic","dy-DAK-tik","adjective","Meant to teach a lesson.","The book was a little too didactic, with a moral on every page.","From Greek didaskein, “to teach.”"],["amalgamate","uh-MAL-guh-mayt","verb","To combine into one.","The two small clubs chose to amalgamate into one big club.",""],["circuitous","ser-KYOO-i-tuhs","adjective","Taking a long, winding route.","We took a circuitous path through the woods.",""],["demure","dih-MYOOR","adjective","Quiet, shy and modest.","The demure kitten hid behind its mother.",""],["evanescent","ev-uh-NES-uhnt","adjective","Fading away quickly.","The evanescent bubbles popped before we could count them.","From Latin evanescere, “to vanish.”"],["jocular","JOK-yuh-ler","adjective","Joking and playful.","Uncle Sam’s jocular stories kept us laughing.","From Latin jocus, “joke.”"],["zeitgeist","TSYT-gyst","noun","The mood and ideas of a certain time.","Those big shoulder pads were part of the zeitgeist of the 1980s.","From German Zeit, “time,” and Geist, “spirit.”"],["perturb","per-TURB","verb","To make someone worried or upset.","The strange noise in the attic perturbed my mom.","From Latin perturbare, “to throw into confusion.”"],["sonorous","SON-er-uhs","adjective","Deep, full and rich in sound.","The cello has a warm, sonorous voice.","From Latin sonor, “sound.”"],["badger","BAJ-er","verb","To keep asking someone in an annoying way.","My little sister will badger me until I play with her.",""],["nexus","NEK-suhs","noun","A connection or central link.","The library is the nexus of our town's book clubs.","From Latin nexus, “a binding.”"],["torpid","TOR-pid","adjective","Slow and sluggish, without energy.","The lizard was torpid until the sun warmed it up.","From Latin torpere, “to be numb.”"],["amorphous","uh-MOR-fuhs","adjective","Having no clear shape.","An amorphous blob of slime oozed across the table.","From Greek amorphos, “shapeless.”"],["beholden","bih-HOHL-duhn","adjective","Owing someone a favor.","I felt beholden to my neighbor for finding my lost cat.",""],["cryptic","KRIP-tik","adjective","Mysterious and hard to understand.","My brother left a cryptic note: “Look under the third step.”","From Greek kryptos, “hidden.”"],["quintessential","kwin-tuh-SEN-shuhl","adjective","The most perfect example of something.","Hot cocoa by the fire is the quintessential winter treat.","From Latin quinta essentia, “fifth essence.”"],["nadir","NAY-der","noun","The lowest point.","Losing my homework in the rain was the nadir of my week.","From Arabic nazir, “opposite.”"],["surreptitious","sur-uhp-TISH-uhs","adjective","Done in a secret, sneaky way.","I took a surreptitious bite of the cake before the party.",""],["officious","uh-FISH-uhs","adjective","Bossy in a meddling way, giving orders no one asked for.","The officious hall monitor checked our shoelaces.","From Latin officiosus, “obliging.”"],["behoove","bih-HOOV","verb","To be right or useful for someone to do.","It would behoove you to study before the spelling test.",""],["anachronism","uh-NAK-ruh-niz-uhm","noun","Something placed in the wrong time period.","A knight with a cell phone would be an anachronism.","From Greek anachronismos, “wrong timing.”"],["exacerbate","ig-ZAS-er-bayt","verb","To make a problem worse.","Scratching will only exacerbate a mosquito bite.","From Latin acerbus, “harsh, bitter.”"],["inscrutable","in-SKROO-tuh-buhl","adjective","Impossible to understand or read.","The cat stared at me with an inscrutable look.","From Latin scrutari, “to search.”"],["plaudit","PLAW-dit","noun","Praise or applause.","The young artist earned plaudits for her bright paintings.","From Latin plaudite, “applaud!”"],["deprecate","DEP-ri-kayt","verb","To show you disapprove of something.","Mom deprecates leaving dirty dishes in the sink.",""],["incandescent","in-kuhn-DES-uhnt","adjective","Glowing with heat, or full of strong feeling.","The incandescent bulb lit the whole porch.","From Latin candere, “to glow.”"],["dulcet","DUHL-sit","adjective","Sweet and pleasant to hear.","The dulcet sound of the flute filled the room.","From Latin dulcis, “sweet.”"],["sinuous","SIN-yoo-uhs","adjective","Curvy and winding.","The sinuous river wound through the valley.","From Latin sinus, “a curve.”"],["indolent","IN-duh-luhnt","adjective","Lazy and avoiding work.","The indolent cat let the mouse walk right by.","From Latin dolere, “to feel pain.”"],["evince","ih-VINS","verb","To show or reveal a feeling or quality.","His wide grin seemed to evince pure joy.","From Latin evincere, “to prove.”"],["dichotomy","dy-KOT-uh-mee","noun","A split between two opposite things.","The story shows a dichotomy between city life and farm life.","From Greek dikha, “in two,” and temnein, “to cut.”"],["effulgent","ih-FUL-juhnt","adjective","Shining brightly.","The effulgent full moon lit our walk home.","From Latin effulgere, “to shine out.”"],["inimical","ih-NIM-ih-kuhl","adjective","Harmful or working against something.","Too much screen time can be inimical to good sleep.","From Latin inimicus, “enemy.”"],["chicanery","shi-KAY-nuh-ree","noun","Clever tricks used to fool people.","The card game ended when we spotted my cousin’s chicanery.",""],["translucent","trans-LOO-suhnt","adjective","Letting some light through, but not clear.","The paper lantern was translucent and glowed softly.","From Latin translucere, “to shine through.”"],["undulate","UN-juh-layt","verb","To move in smooth waves.","The tall grass seemed to undulate in the wind.","From Latin unda, “wave.”"],["conjure","KON-jer","verb","To bring something to mind, or make it appear as if by magic.","The smell of pine conjures memories of camping.",""],["begrudge","bih-GRUHJ","verb","To feel unhappy that someone has something.","I don’t begrudge my friend her new bike; she saved for it.",""],["pithy","PITH-ee","adjective","Short but full of meaning.","Grandma's pithy advice was “Measure twice, cut once.”",""],["curmudgeon","ker-MUHJ-uhn","noun","A grumpy, cranky person.","Our neighbor acts like a curmudgeon, but he waves at us every morning.",""],["adumbrate","AD-uhm-brayt","verb","To give a rough outline or hint of something.","The first chapter adumbrates the mystery to come.","From Latin umbra, “shadow.”"],["diaphanous","dy-AF-uh-nuhs","adjective","So thin and light you can almost see through it.","The dragonfly’s diaphanous wings shimmered in the sun.",""],["cogent","KOH-juhnt","adjective","Clear and convincing.","She made a cogent case for a longer recess.",""],["innocuous","ih-NOK-yoo-uhs","adjective","Harmless.","The spider looked scary but was innocuous.","From Latin nocuus, “harmful,” so “not harmful.”"],["lexicon","LEK-sih-kon","noun","All the words used in a language or by a group.","Skateboarders have their own lexicon.","From Greek lexis, “word.”"],["insular","IN-suh-ler","adjective","Cut off from others and not open to new ideas.","The club felt insular until it invited new members.","From Latin insula, “island.”"],["resurgence","rih-SUR-juhns","noun","A rise again after a quiet time.","There has been a resurgence of board games in our family.","From Latin resurgere, “to rise again.”"],["cavalier","kav-uh-LEER","adjective","Not caring enough about something important.","His cavalier attitude toward homework hurt his grade.",""],["parsimonious","par-suh-MOH-nee-uhs","adjective","Very unwilling to spend money.","The parsimonious king in the fairy tale wouldn't buy candles.","From Latin parsimonia, “thrift.”"],["subterfuge","SUB-ter-fyooj","noun","A trick used to hide what you are doing.","We used subterfuge to plan Dad’s surprise party.",""],["enervate","EN-er-vayt","verb","To drain someone’s energy.","The muggy afternoon seemed to enervate the whole team.","From Latin nervus, “sinew, strength.”"],["whet","WET","verb","To sharpen, or to make a feeling stronger.","The smell of popcorn will whet your appetite.",""],["supercilious","soo-per-SIL-ee-uhs","adjective","Acting as if you are better than others.","The supercilious cat stared down at us from the shelf.","From Latin supercilium, “eyebrow.”"],["atrophy","AT-ruh-fee","verb","To waste away or get weaker from lack of use.","If you never practice, your piano skills will atrophy.","From Greek atrophia, “lack of food.”"],["urbane","ur-BAYN","adjective","Polite, smooth and at ease with people.","The urbane host made every guest feel welcome.","From Latin urbanus, “of the city.”"],["assiduous","uh-SIJ-oo-uhs","adjective","Working with steady care and effort.","Her assiduous practice made her the best violinist in the orchestra.","From Latin assiduus, “sitting down to, busy.”"],["baleful","BAYL-fuhl","adjective","Threatening or full of bad feeling.","The cat gave the vacuum cleaner a baleful stare.",""],["harbinger","HAR-bin-jer","noun","A sign of something that is coming.","The first robin is a harbinger of spring.",""],["feckless","FEK-lis","adjective","Lacking effort or a sense of purpose.","The feckless plan to clean the garage never got past one box.","From Scots feck, “effect, value.”"],["compunction","kuhm-PUHNGK-shuhn","noun","A feeling of guilt that stops you from doing something.","He had no compunction about eating the last slice, since it was his turn.",""],["sublime","suh-BLYM","adjective","So beautiful or great it fills you with awe.","The sunset over the canyon was sublime.","From Latin sublimis, “lofty.”"],["puerile","PYOOR-uhl","adjective","Silly and childish.","The older kids thought the whoopee cushion prank was puerile.","From Latin puer, “boy.”"],["morass","muh-RAS","noun","A messy situation that is hard to get out of.","My closet became a morass of shoes and old toys.","From Dutch moeras, “marsh.”"],["munificent","myoo-NIF-ih-suhnt","adjective","Very, very generous.","A munificent neighbor donated new books to our library.","From Latin munificus, “generous.”"],["abstruse","ab-STROOS","adjective","Very hard to understand.","The science article was so abstruse that I read it three times.","From Latin abstrusus, “hidden.”"],["deign","DAYN","verb","To do something you think is beneath you.","The cat finally deigned to come when called.",""],["jettison","JET-ih-suhn","verb","To throw away something you do not need.","We had to jettison some toys to fit the tent in the car.","From Old French getaison, “a throwing.”"],["incongruous","in-KONG-groo-uhs","adjective","Out of place or not fitting in.","A snowman looked incongruous on the sunny beach.","From Latin congruus, “fitting.”"],["staid","STAYD","adjective","Serious, proper and a bit dull.","My staid uncle surprised us by dancing at the party.",""],["ineffable","in-EF-uh-buhl","adjective","Too great to describe in words.","The view from the mountain top was ineffable.","From Latin effabilis, “able to be spoken.”"],["decorous","DEK-er-uhs","adjective","Polite and proper in behavior.","The class was decorous during the guest speaker’s talk.",""],["felicity","fih-LIS-ih-tee","noun","Great happiness, or a well-chosen way of saying something.","We felt pure felicity on the first day of summer.","From Latin felix, “happy, lucky.”"],["denizen","DEN-i-zuhn","noun","A creature or person that lives in a certain place.","Crabs are denizens of the tide pools.",""],["churlish","CHUR-lish","adjective","Rude and grumpy.","It would be churlish not to thank Grandma for the sweater.",""],["dogged","DAW-gid","adjective","Stubborn and never giving up.","Her dogged practice finally paid off at the recital.",""],["bulwark","BUL-werk","noun","A strong wall or something that protects.","Good friends are a bulwark against loneliness.",""],["malaise","ma-LAYZ","noun","A vague feeling of being unwell or uneasy.","A gray malaise settled over the class during the long, rainy week.","From French malaise, “discomfort.”"],["cantankerous","kan-TANG-ker-uhs","adjective","Grumpy and quick to argue.","Our cantankerous old goat headbutts the fence.",""],["sardonic","sar-DON-ik","adjective","Mocking in a dry, scornful way.","He gave a sardonic laugh when the bus was late again.",""],["wheedle","WEE-duhl","verb","To use sweet talk to get what you want.","My brother tried to wheedle an extra cookie out of Grandma.",""],["aegis","EE-jis","noun","Protection or support from someone.","The science fair ran under the aegis of the local library.","From Greek aigis, “goatskin shield.”"],["propitious","pruh-PISH-uhs","adjective","Showing good signs for success.","Clear skies made it a propitious day for flying kites.","From Latin propitius, “favorable.”"],["paragon","PAIR-uh-gon","noun","A perfect example of something.","Our neighbor is a paragon of patience with her twins.",""],["prodigal","PROD-ih-guhl","adjective","Spending money or things wastefully.","The prodigal squirrel buried more acorns than it could ever find.","From Latin prodigus, “wasteful.”"],["deleterious","del-i-TEER-ee-uhs","adjective","Harmful.","Too much screen time can be deleterious to good sleep.",""],["capricious","kuh-PRISH-uhs","adjective","Changing moods or plans suddenly, without reason.","The capricious spring weather went from sun to hail in an hour.",""],["ostentatious","os-ten-TAY-shuhs","adjective","Showy, trying to impress people.","His ostentatious sneakers flashed lights with every step.","From Latin ostentare, “to show off.”"],["reticent","RET-ih-suhnt","adjective","Not willing to share your thoughts or feelings.","The new student was reticent on her first day.","From Latin reticere, “to keep silent.”"],["alacrity","uh-LAK-rih-tee","noun","Cheerful eagerness and speed.","He accepted the invitation to the pool party with alacrity.","From Latin alacer, “lively.”"],["impetuous","im-PECH-oo-uhs","adjective","Acting quickly without thinking.","In an impetuous moment, he jumped in the lake with his shoes on.","From Latin impetus, “rush, attack.”"],["disconcert","dis-kuhn-SURT","verb","To unsettle or confuse.","The silent crowd disconcerted the young singer.",""],["wizened","WIZ-uhnd","adjective","Dry and wrinkled with age.","The wizened apple had been in the bowl too long.",""],["protean","PROH-tee-uhn","adjective","Able to change into many forms or do many things.","The protean actor played six roles in one play.","From Greek Proteus, a sea god in old myths who could change shape."],["ameliorate","uh-MEEL-yuh-rayt","verb","To make a bad situation better.","Planting trees helped ameliorate the heat on the playground.","From Latin melior, “better.”"],["sycophant","SIK-uh-fuhnt","noun","Someone who flatters others to get something.","The sycophant in the story praised the king to win a prize.",""],["boondoggle","BOON-dog-uhl","noun","A project that wastes time and money.","The giant robot costume became a boondoggle that we never finished.",""],["desiccate","DES-i-kayt","verb","To dry out completely.","The summer heat desiccated the garden soil.","From Latin siccus, “dry.”"],["ruminate","ROO-muh-nayt","verb","To think deeply about something for a long time.","I like to ruminate on big questions while I swing.","From Latin ruminari, “to chew the cud.”"],["mawkish","MAW-kish","adjective","Too sweet and sentimental in a way that feels fake.","The card's mawkish poem made us giggle.",""],["aggrandize","uh-GRAN-dize","verb","To make something seem bigger or more important.","He tried to aggrandize his role in the group project.","From French agrandir, “to make larger.”"],["voluble","VOL-yuh-buhl","adjective","Talking a lot, easily and fast.","My voluble cousin can chat for hours.",""],["peccadillo","pek-uh-DIL-oh","noun","A small, unimportant fault.","Leaving one sock on the floor is a peccadillo, not a crime.","From Spanish pecadillo, “little sin.”"],["aberration","ab-uh-RAY-shuhn","noun","Something that is not normal or usual.","Getting a low grade was an aberration for such a strong student.","From Latin aberrare, “to wander away.”"],["quiescent","kwee-ES-uhnt","adjective","Quiet and still, not active for now.","The volcano has been quiescent for a hundred years.","From Latin quiescere, “to rest.”"],["ignominy","IG-nuh-min-ee","noun","Public embarrassment or shame.","The team faced the ignominy of a 10 to 0 loss with good spirits.","From Latin ignominia, “loss of good name.”"],["clandestine","klan-DES-tin","adjective","Done in secret.","We held a clandestine meeting to plan Dad’s surprise party.","From Latin clam, “secretly.”"],["vicarious","vy-KAIR-ee-uhs","adjective","Felt by watching or hearing about someone else.","I got a vicarious thrill reading about her trip to the jungle.","From Latin vicarius, “substitute.”"],["veneer","vuh-NEER","noun","A thin outer layer that hides what is under it.","The table had a veneer of oak over plain wood.",""],["perennial","puh-REN-ee-uhl","adjective","Lasting a long time or coming back year after year.","Tulips are perennial flowers that bloom every spring.","From Latin perennis, “lasting through the years.”"],["gossamer","GOS-uh-mer","adjective","Very light, thin and delicate.","Dew sparkled on the gossamer threads of the web.",""],["cathartic","kuh-THAR-tik","adjective","Making you feel better by letting out strong feelings.","Writing in my journal after a rough day feels cathartic.","From Greek katharos, “pure.”"],["myopic","my-OP-ik","adjective","Only thinking about now, not the future; also nearsighted.","Spending all my savings on candy was a myopic choice.","From Greek myops, “short-sighted.”"],["chary","CHAIR-ee","adjective","Cautious and slow to trust.","The stray cat was chary of strangers.",""],["arcane","ar-KAYN","adjective","Known or understood by only a few people.","My cousin knows arcane facts about old video game glitches.","From Latin arcanus, “secret.”"],["acrimony","AK-ruh-moh-nee","noun","Bitter, angry feelings between people.","The friends settled their argument without any acrimony.","From Latin acrimonia, “sharpness.”"],["countenance","KOWN-tuh-nuhns","noun","A person’s face or expression.","Her calm countenance helped the nervous kids relax.",""],["vilify","VIL-uh-fy","verb","To say very bad, unfair things about someone.","It is unkind to vilify a player for one missed shot.","From Latin vilis, “cheap, worthless.”"],["commensurate","kuh-MEN-sher-it","adjective","Matching in size or amount.","Our reward was commensurate with how hard we worked.",""],["fatuous","FACH-oo-uhs","adjective","Silly and not thought through.","The fatuous idea to sled down the stairs was quickly dropped.","From Latin fatuus, “foolish.”"],["profligate","PROF-lih-git","adjective","Wildly wasteful.","Leaving every light on all day is profligate.",""],["recapitulate","ree-kuh-PICH-uh-layt","verb","To sum up the main points again.","Before the test, the teacher will recapitulate the whole unit.","From Latin capitulum, “chapter, heading.”"],["equivocal","ih-KWIV-uh-kuhl","adjective","Unclear, with more than one possible meaning.","His equivocal answer left us unsure if he would come.","From Latin aequus, “equal,” and vox, “voice.”"],["debase","dih-BAYS","verb","To lower the quality or value of something.","Cheating would debase our win.",""],["abjure","ab-JOOR","verb","To give up a belief or habit for good.","He decided to abjure video games during exam week.","From Latin abjurare, “to deny on oath.”"],["obfuscate","OB-fuh-skayt","verb","To make something confusing on purpose.","The tricky instructions seemed to obfuscate the rules of the game.","From Latin obfuscare, “to darken.”"],["pedantic","puh-DAN-tik","adjective","Too focused on tiny rules and details.","It's pedantic to correct every small mistake in a friend's text.",""],["avuncular","uh-VUHNG-kyuh-ler","adjective","Kind and friendly like an uncle.","The avuncular coach always had a joke for us.","From Latin avunculus, “mother’s brother.”"],["aver","uh-VUR","verb","To state something as true with confidence.","My brother will aver that he saw a shooting star.","From Latin verus, “true.”"],["milieu","meel-YOO","noun","The setting or surroundings someone is in.","Our noisy band room is the perfect milieu for new song ideas.","From French milieu, “middle.”"],["tractable","TRAK-tuh-buhl","adjective","Easy to manage or control.","The pony was gentle and tractable with new riders.","From Latin tractare, “to handle.”"],["implacable","im-PLAK-uh-buhl","adjective","Impossible to calm or change.","The baby goat was implacable until it got its bottle.","From Latin placare, “to calm.”"],["exorbitant","ig-ZOR-bih-tuhnt","adjective","Much too high in price or amount.","The snack stand charged an exorbitant price for popcorn.","From Latin exorbitare, “to go off the track.”"],["flippant","FLIP-uhnt","adjective","Not serious when you should be.","Her flippant reply made the class gasp.",""],["idyllic","eye-DIL-ik","adjective","Peaceful and perfect, like a picture.","The cabin by the lake was idyllic.","From Greek eidyllion, “little picture.”"],["garrulous","GAIR-uh-luhs","adjective","Talking a lot, often about small things.","The garrulous parrot chatted all through dinner.","From Latin garrulus, “chattering.”"],["ostensible","o-STEN-suh-buhl","adjective","Seeming true on the outside but maybe not the real reason.","The ostensible reason for the visit was to return a bowl, but she really wanted pie.","From Latin ostendere, “to show.”"],["prescient","PRESH-uhnt","adjective","Seeming to know what will happen before it does.","Bringing umbrellas turned out to be a prescient choice.","From Latin praescire, “to know beforehand.”"],["sedentary","SED-n-tair-ee","adjective","Sitting a lot and not moving much.","A sedentary day of video games made me feel stiff.","From Latin sedere, “to sit.”"],["castigate","KAS-ti-gayt","verb","To scold someone harshly.","The coach castigated us for leaving the gym a mess.",""],["repudiate","rih-PYOO-dee-ayt","verb","To refuse to accept or to reject firmly.","The scientist had to repudiate her old theory after new tests.",""],["wrought","RAWT","adjective","Made or shaped with care, often by hand.","The garden gate was made of wrought iron.","From Old English, an old past form of “work.”"],["histrionic","his-tree-ON-ik","adjective","Overly dramatic, like an actor.","My brother gave a histrionic groan when asked to set the table.","From Latin histrio, “actor.”"],["debonair","deb-uh-NAIR","adjective","Stylish, charming and confident.","My grandpa looked debonair in his bow tie.","From French de bon air, “of good manner.”"],["unfathomable","un-FATH-uh-muh-buhl","adjective","Too deep or strange to understand.","The number of stars in the sky is unfathomable.",""],["ascribe","uh-SKRIBE","verb","To say that something is caused by or belongs to someone.","We ascribe the missing cookies to the dog.","From Latin ascribere, “to write in addition.”"],["covet","KUHV-it","verb","To want something that belongs to someone else.","I covet my friend’s glow-in-the-dark sneakers.",""],["piquant","PEE-kuhnt","adjective","Pleasantly sharp in taste, or interesting.","The salsa had a piquant kick from the lime.","From French piquer, “to prick.”"],["erudite","AIR-yuh-dyte","adjective","Having a lot of knowledge from study.","The erudite tour guide knew every bird in the forest.","From Latin erudire, “to teach, polish.”"],["tumultuous","too-MUL-choo-uhs","adjective","Loud, wild and full of confusion.","The crowd gave a tumultuous cheer at the final goal.","From Latin tumultus, “uproar.”"],["maelstrom","MAYL-struhm","noun","A wild, swirling mess, like a whirlpool.","The kitchen became a maelstrom of flour on baking day.","From early Dutch maelstroom, “grinding stream.”"],["furtive","FUR-tiv","adjective","Sneaky and trying not to be noticed.","The dog cast a furtive glance at the cake on the table.","From Latin furtivus, “stolen, secret.”"],["phlegmatic","fleg-MAT-ik","adjective","Calm and hard to excite.","Our phlegmatic old dog barely blinked at the fireworks.","From Greek phlegma, “phlegm,” once thought to make people calm."],["coddle","KOD-uhl","verb","To treat someone too gently.","Grandpa coddles the dog with extra treats.",""],["esoteric","es-uh-TAIR-ik","adjective","Understood by only a small group.","The game had esoteric rules only the older kids knew.","From Greek esōterikos, “inner.”"],["brackish","BRAK-ish","adjective","Slightly salty, like water where a river meets the sea.","Some fish live in brackish water near the coast.",""],["cosset","KOS-it","verb","To pamper and protect.","We cosseted the sick puppy with soft blankets.",""],["consternation","kon-ster-NAY-shuhn","noun","Shock and worry about something unexpected.","To our consternation, the pool was closed on the hottest day.",""],["recalcitrant","rih-KAL-sih-truhnt","adjective","Stubborn and refusing to obey.","The recalcitrant mule would not cross the bridge.","From Latin recalcitrare, “to kick back.”"],["raucous","RAW-kuhs","adjective","Loud and rough-sounding.","The raucous crows woke us at dawn.","From Latin raucus, “hoarse.”"],["dour","DOOR","adjective","Stern and gloomy.","The dour museum guard finally cracked a smile.",""],["congenial","kuhn-JEEN-yuhl","adjective","Pleasant, friendly and easy to be around.","Our congenial camp counselor made everyone feel welcome.",""],["euphemism","YOO-fuh-miz-uhm","noun","A gentle word used in place of a harsh one.","“Fixer-upper” is a euphemism for a house that needs a lot of work.","From Greek euphēmismos, “speaking well.”"],["bumptious","BUHMP-shuhs","adjective","Loud and too sure of yourself in an annoying way.","The bumptious new kid told everyone how to play the game.",""],["rhetoric","RET-er-ik","noun","The skill of using words to persuade.","The debate team studies rhetoric to win arguments.","From Greek rhetor, “public speaker.”"],["redolent","RED-uh-luhnt","adjective","Full of a strong, pleasant smell, or bringing a memory to mind.","The kitchen was redolent of cinnamon and fresh bread.","From Latin redolere, “to give off a smell.”"],["byword","BY-wurd","noun","A person or thing known as the best example of something.","Our librarian is a byword for patience.",""],["astringent","uh-STRIN-juhnt","adjective","Sharp or harsh in taste or tone.","Unripe persimmons have an astringent taste.","From Latin astringere, “to bind tight.”"],["hackneyed","HAK-need","adjective","Used so often it feels stale.","“Once upon a time” felt hackneyed, so Zoe began her story another way.","From hackney, a horse anyone could rent."],["facetious","fuh-SEE-shuhs","adjective","Joking at a time that calls for being serious.","His facetious answer made the teacher sigh.","From Latin facetus, “witty.”"],["listless","LIST-lis","adjective","Having no energy or interest.","The heat made the dogs listless all afternoon.",""],["circumlocution","sur-kuhm-loh-KYOO-shuhn","noun","Using many words when a few would do.","His circumlocution made a simple yes take five minutes.","From Latin circum, “around,” and loqui, “to speak.”"],["proclivity","proh-KLIV-ih-tee","noun","A natural leaning toward doing something.","My sister has a proclivity for climbing trees.","From Latin proclivis, “sloping.”"],["circumspect","SUR-kuhm-spekt","adjective","Careful to think about risks before acting.","Be circumspect about what you post online.","From Latin circumspicere, “to look around.”"],["bombastic","bom-BAS-tik","adjective","Using big, showy words to sound important.","The villain in the play gave a bombastic speech about his plans.",""],["apposite","AP-uh-zit","adjective","Very fitting and to the point.","Her apposite comment made the whole class nod.","From Latin apponere, “to put near.”"],["perfunctory","per-FUNGK-tuh-ree","adjective","Done quickly, without care or interest.","He gave the dishes a perfunctory rinse and ran outside.","From Latin perfunctorius, “careless.”"],["abnegation","ab-nih-GAY-shuhn","noun","Giving up something you want, often for others.","Her abnegation of the last slice so her brother could have it was kind.","From Latin abnegare, “to deny.”"],["halcyon","HAL-see-uhn","adjective","Calm, happy and peaceful, often about the past.","Grandpa talks about the halcyon summers on his family’s farm.","From Greek halkyōn, “kingfisher.”"],["droll","DROHL","adjective","Funny in an odd or dry way.","Grandma’s droll jokes make us laugh at dinner.",""],["verdant","VUR-duhnt","adjective","Green with lots of plants.","The valley was verdant after the spring rains.",""],["mettle","MET-uhl","noun","Courage and strength to face something hard.","The steep climb tested our mettle.",""],["behest","bih-HEST","noun","A person’s order or request.","At my grandma’s behest, we all wore matching shirts.",""],["diatribe","DY-uh-tryb","noun","A long, angry speech against something.","My brother went on a diatribe about broccoli.",""],["vapid","VAP-id","adjective","Dull and empty of ideas.","The show was so vapid that we turned it off.","From Latin vapidus, “flat, spoiled.”"],["transcend","tran-SEND","verb","To go beyond the usual limits.","Great music can transcend language.","From Latin transcendere, “to climb over.”"],["callow","KAL-oh","adjective","Young and without much experience.","As a callow first-time camper, I forgot my flashlight.",""],["discomfit","dis-KUHM-fit","verb","To make someone feel uneasy or embarrassed.","The surprise question discomfited the quiz show host.",""],["decry","dih-KRY","verb","To speak out strongly against something.","The students decried the plan to cancel art class.",""],["sanguine","SANG-gwin","adjective","Cheerful and hopeful.","Even after the rain, she was sanguine about our picnic.","From Latin sanguis, “blood.”"],["mellifluous","muh-LIF-loo-uhs","adjective","Sweet and smooth to hear.","The cellist played a mellifluous tune at the recital.","From Latin mel, “honey,” and fluere, “to flow.”"],["acquiesce","ak-wee-ES","verb","To agree to something without arguing, even if you don’t love it.","My parents finally acquiesced and let us camp in the backyard.","From Latin acquiescere, “to rest, to be at peace.”"],["penury","PEN-yuh-ree","noun","Being very poor.","The story's hero rose from penury to run a great bakery.","From Latin penuria, “need.”"],["recondite","REK-uhn-dyt","adjective","Hard to understand and known by few people.","My uncle loves recondite facts about old clocks.","From Latin reconditus, “hidden away.”"],["ephemeral","ih-FEM-er-uhl","adjective","Lasting only a short time.","A rainbow is ephemeral, so look quickly.","From Greek ephēmeros, “lasting a day.”"],["perspicacious","pur-spih-KAY-shuhs","adjective","Quick to notice and understand things.","The perspicacious detective in the book spotted the tiny clue.","From Latin perspicax, “sharp-sighted.”"],["attenuate","uh-TEN-yoo-ayt","verb","To make thinner or weaker.","Thick curtains attenuate the noise from the street.","From Latin tenuis, “thin.”"],["engender","en-JEN-der","verb","To cause or bring about a feeling or situation.","Sharing snacks can engender friendship on a long bus ride.","From Latin generare, “to create.”"],["baroque","buh-ROHK","adjective","Very fancy and full of detail.","The cake had baroque swirls of frosting all over it.",""],["laconic","luh-KON-ik","adjective","Using very few words.","The laconic farmer just nodded and said, “Rain.”","From Greek Lakōnikos, “from Laconia,” where people spoke few words."],["apprise","uh-PRIZE","verb","To tell or inform someone about something.","Please apprise me of any changes to the practice schedule.",""],["solicitous","suh-LIS-ih-tuhs","adjective","Showing care and concern for someone.","My solicitous friend brought me soup when I was sick.",""],["dissemble","dih-SEM-buhl","verb","To hide your real feelings or thoughts.","She tried to dissemble her excitement, but she kept grinning.",""],["precipitous","prih-SIP-ih-tuhs","adjective","Very steep, or very sudden.","There was a precipitous drop at the edge of the trail.",""],["nefarious","nuh-FAIR-ee-uhs","adjective","Wicked or very bad.","In the cartoon, the nefarious raccoon tried to steal every pie in town.","From Latin nefarius, “wicked.”"],["hyperbole","hy-PUR-buh-lee","noun","A big exaggeration used for effect.","“I’m so hungry I could eat a horse” is hyperbole.","From Greek hyperbolē, “a throwing beyond.”"],["malinger","muh-LING-ger","verb","To pretend to be sick to get out of work.","The dog seemed to malinger whenever it was bath time.","From French malingre, “sickly.”"],["badinage","bad-n-AHZH","noun","Playful, witty talk.","The badinage between the two friends made the long car trip fun.","From French badinage, “joking.”"],["obdurate","OB-duh-rit","adjective","Stubborn and not willing to change.","The obdurate mule refused to cross the bridge.","From Latin obduratus, “hardened.”"],["rescind","rih-SIND","verb","To take back or cancel.","The school had to rescind the snow day when the storm missed us.","From Latin rescindere, “to cut off.”"],["stalwart","STAWL-wert","adjective","Loyal, strong and dependable.","Grandpa is a stalwart fan who never misses our games.",""],["lugubrious","luh-GOO-bree-uhs","adjective","Looking or sounding sad in a gloomy, heavy way.","The basset hound gave a lugubrious sigh when we left.","From Latin lugere, “to mourn.”"],["censure","SEN-sher","noun","Strong, formal disapproval.","The referee’s censure of the rough play quieted the field.",""],["pusillanimous","pyoo-suh-LAN-uh-muhs","adjective","Lacking courage; timid.","The pusillanimous lion in the story hid from a butterfly.","From Latin pusillus, “very small,” and animus, “spirit.”"],["disheveled","dih-SHEV-uhld","adjective","Messy and untidy.","I arrived disheveled after the windy bike ride.",""],["doldrums","DOHL-druhmz","noun","A spell of feeling bored, sad or stuck.","A rainy week put us all in the doldrums.",""],["disingenuous","dis-in-JEN-yoo-uhs","adjective","Pretending to be honest when you are not.","Saying “I didn’t see it” was disingenuous, since he was standing right there.",""],["soporific","sop-uh-RIF-ik","adjective","Making you sleepy.","The soft music had a soporific effect on the baby.","From Latin sopor, “deep sleep.”"],["panache","puh-NASH","noun","Bold, confident style.","She played the drums with great panache.","From French panache, “plume of feathers.”"],["predilection","pred-uh-LEK-shuhn","noun","A special liking for something.","My uncle has a predilection for spicy food.",""],["dilatory","DIL-uh-tor-ee","adjective","Slow and causing delay.","My dilatory start on the project meant a busy weekend.",""],["dither","DITH-er","verb","To be unable to decide.","I dithered so long over ice cream flavors that the line grew.",""],["dissonant","DIS-uh-nuhnt","adjective","Sounding harsh and not in harmony.","The two recorders played dissonant notes.","From Latin dissonare, “to sound different.”"],["dapper","DAP-er","adjective","Neat and stylish.","My dog looked dapper in his tiny bow tie.",""],["superlative","suh-PUR-luh-tiv","adjective","Of the very highest quality.","The bakery is known for its superlative croissants.",""],["proscribe","proh-SKRYB","verb","To forbid by a rule.","The library rules proscribe eating near the books.","From Latin proscribere, “to publish in writing.”"],["austere","aw-STEER","adjective","Very plain and simple, with no extras.","The cabin was austere, with just a bed, a table, and a stove.","From Greek austēros, “harsh, dry.”"],["bifurcate","BY-fer-kayt","verb","To split into two branches.","The trail will bifurcate at the big oak tree.","From Latin bifurcus, “two-forked.”"],["unctuous","UNGK-choo-uhs","adjective","Too smooth and flattering to seem honest.","The unctuous salesman in the movie smiled too much.","From Latin unctus, “oiled.”"],["palliate","PAL-ee-ayt","verb","To make something less painful or severe without curing it.","A cool cloth helped palliate my headache.","From Latin palliare, “to cloak.”"],["prevaricate","prih-VAIR-ih-kayt","verb","To avoid telling the whole truth.","When asked who broke the vase, my brother started to prevaricate.","From Latin praevaricari, “to walk crookedly.”"],["nondescript","non-dih-SKRIPT","adjective","Plain and not easy to describe or notice.","The secret clubhouse was hidden behind a nondescript door.",""],["sagacious","suh-GAY-shuhs","adjective","Wise and showing good judgment.","The sagacious old owl in the story gave the best advice.","From Latin sagax, “keen, wise.”"],["peripatetic","pair-uh-puh-TET-ik","adjective","Traveling from place to place.","Our peripatetic art teacher visits three schools a week.","From Greek peripatein, “to walk around.”"],["accoutrements","uh-KOO-truh-muhnts","noun","Extra items or gear used for something.","She packed all the accoutrements for camping: lantern, cooler, and hammock.",""],["obstreperous","uhb-STREP-er-uhs","adjective","Noisy and hard to control.","The obstreperous puppies tumbled all over the living room.","From Latin obstrepere, “to make a noise against.”"],["doleful","DOHL-fuhl","adjective","Very sad.","The puppy gave me a doleful look when I left for school.",""],["gauche","GOHSH","adjective","Awkward and clumsy in social ways.","It felt gauche to ask for seconds before everyone had eaten.","From French gauche, “left, clumsy.”"],["unassuming","un-uh-SOO-ming","adjective","Modest and not showing off.","The unassuming boy turned out to be the best singer in class.",""],["temerity","tuh-MER-ih-tee","noun","Bold daring that may be too much.","The squirrel had the temerity to steal from our picnic basket.","From Latin temeritas, “rashness.”"],["sumptuous","SUMP-choo-uhs","adjective","Rich, fancy and grand.","The holiday dinner was a sumptuous feast.","From Latin sumptus, “cost, expense.”"],["impudent","IM-pyuh-duhnt","adjective","Rude and not showing respect.","The impudent squirrel stole a chip right off my plate.","From Latin pudere, “to be ashamed.”"],["abase","uh-BAYS","verb","To make yourself seem lower or less important.","He refused to abase himself by begging for a better seat.",""],["ennui","ahn-WEE","noun","A tired feeling of boredom.","A week of rain filled the house with ennui.","From French ennui, “boredom.”"],["beleaguered","bih-LEE-gerd","adjective","Worn down by lots of problems.","The beleaguered teacher had three fire drills and a broken projector in one day.",""],["propriety","pruh-PRY-ih-tee","noun","Polite and proper behavior.","Grandma insists on propriety at the dinner table.","From Latin proprietas, “ownership, fitness.”"],["bucolic","byoo-KOL-ik","adjective","Having to do with the peaceful countryside.","The farm was a bucolic scene of cows and green hills.","From Greek boukolos, “cowherd.”"],["dilapidated","dih-LAP-i-day-tid","adjective","Old, broken and falling apart.","We fixed up the dilapidated shed and made it a clubhouse.",""],["nonplussed","non-PLUST","adjective","So surprised that you don't know what to do or say.","She was nonplussed when her shy brother sang on stage.","From Latin non plus, “no more.”"],["foible","FOY-buhl","noun","A small, harmless weakness or habit.","Dad’s foible is humming while he cooks.","From French foible, “weak.”"],["brouhaha","BROO-hah-hah","noun","A noisy fuss over something small.","There was a big brouhaha when the class hamster got loose.","From French brouhaha."],["mercurial","mer-KYUR-ee-uhl","adjective","Changing moods quickly and often.","My mercurial cat purrs one minute and swats the next.","From Latin Mercurius, the quick messenger god of Roman myths."],["bereft","bih-REFT","adjective","Lacking something or left without it.","The garden was bereft of flowers after the frost.",""],["effervescent","ef-er-VES-uhnt","adjective","Bubbly, or lively and full of fun.","Her effervescent laugh made the whole class smile.","From Latin effervescere, “to boil up.”"],["petulant","PECH-uh-luhnt","adjective","Grumpy and sulky like a spoiled child.","The petulant toddler crossed his arms and refused his peas.","From Latin petulans, “impudent.”"],["artifice","AR-tuh-fis","noun","Clever tricks used to fool people.","The magician’s artifice kept us guessing all night.","From Latin artificium, “craft.”"]]};
